    /** Header grup v4.48.1: chip toggle (pengganti CheckBox) — warna ikut pref. */
    internal fun refreshGroupChips() {
        val th = currentTheme()
        if (::groupAllChip.isInitialized) {
            val on = GroupChat.isGroupAllOn(this)
            groupAllChip.background = rounded(if (on) ACCENT else th.tileBg, 16)
            groupAllChip.setTextColor(if (on) Color.WHITE else th.text)
        }
        if (::groupExecChip.isInitialized) {
            val on = GroupChat.isGroupExecOn(this)
            groupExecChip.background = rounded(if (on) ACCENT else th.tileBg, 16)
            groupExecChip.setTextColor(if (on) Color.WHITE else th.text)
        }
    }
