    /** v4.13.0: Impor SKILL.md dari folder Download (verbatim, tanpa model).
     *  vc242 K-08 + FT-M1: pindai dulu, tampilkan pratinjau nama +
     *  deskripsi dengan centang per file, baru simpan yang dicentang
     *  (forgeUpsert: skill baru NONAKTIF, impor ulang tidak mengubah
     *  status aktif, slug sistem ditolak). */
    fun uiImportSkills() {
        Thread {
            val scan = try { SkillImport.scanFromDownload(this) } catch (e: Exception) { null }
            runOnUiThread {
                try {
                    if (scan == null || scan.candidates.isEmpty()) {
                        val skipped = if (scan != null) scan.skippedNonSkill + scan.skippedInvalid + scan.skippedOversize else 0
                        Toast.makeText(this, "Tidak ada file SKILL-*.md (atau .md ber-frontmatter skill valid) di folder Download." + if (skipped > 0) " $skipped file dilewati." else "", Toast.LENGTH_LONG).show()
                        return@runOnUiThread
                    }
                    val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(8), dp(16), dp(4)) }
                    col.addView(TextView(this).apply { text = "Pilih skill yang akan diimpor. Skill BARU tersimpan NONAKTIF (aktifkan di Settings > Skill Agen); skill yang sudah ada DIPERBARUI tanpa mengubah status aktifnya. Dilewati: ${scan.skippedNonSkill} non-skill, ${scan.skippedInvalid} isi tidak valid, ${scan.skippedOversize} melebihi 256 KB."; setTextColor(TEXT); textSize = 12f })
                    val boxes = ArrayList<Pair<CheckBox, SkillImport.Candidate>>()
                    for (c in scan.candidates) {
                        // vc262 SkillSpector: skor risiko dihitung saat
                        // pratinjau — kandidat yang diblokir tidak bisa dicentang.
                        val riskVc262 = try { SkillSpector.scan(c.name, c.descr, c.body) } catch (e: Exception) { null }
                        // vc300 BAGIAN-C: klausul peringatan "deskripsi akan
                        // dipotong ke 1000" DIHAPUS — cap descr dihapus worker A
                        // (forgeUpsert/updateSkillMeta), deskripsi kini
                        // vc301 SF-A5: addSkill DIHAPUS (dead code) —
// tidak ada lagi take(1000) pada deskripsi skill di mana pun.
                        val box = CheckBox(this).apply {
                            text = (if (c.existed) "UPDATE " else "BARU ") + c.name + " — " + c.descr.take(120) + (if (c.systemBlocked) " [DITOLAK: slug sistem dilindungi]" else "") + (if (riskVc262 != null) " [SkillSpector: skor risiko " + riskVc262.score + "/100" + (if (riskVc262.blocked) " — DIBLOKIR, tidak bisa diimpor" else if (riskVc262.findings.isNotEmpty()) " — " + riskVc262.findings.first() else "") + "]" else "") + " (" + c.fileName + ")"
                            setTextColor(TEXT); textSize = 12f
                            isChecked = !c.systemBlocked && riskVc262?.blocked != true
                            isEnabled = !c.systemBlocked && riskVc262?.blocked != true
                        }
                        boxes.add(box to c)
                        col.addView(box)
                    }
                    AlertDialog.Builder(this)
                        .setTitle("Pratinjau Impor Skill (${scan.candidates.size})")
                        .setView(ScrollView(this).apply { addView(col) })
                        .setPositiveButton("Impor yang dicentang") { _, _ ->
                            val selected = boxes.filter { it.first.isChecked }.map { it.second }
                            Thread {
                                val msg = SkillImport.importSelected(this, selected)
                                runOnUiThread { try { Toast.makeText(this, msg, Toast.LENGTH_LONG).show() } catch (e: Exception) {} }
                            }.start()
                        }
                        .setNegativeButton("Batal", null)
                        .show()
                } catch (e: Exception) {}
            }
        }.start()
    }

