    /** vc245 GELOMBANG 4 (K-10, samakan 17/30): Pulihkan Otak WAJIB lewat
     *  dialog konfirmasi yang menyebut sumber file + tanggal file +
     *  "otak aktif akan ditimpa", tombol Pulihkan bergaya bahaya, Batal
     *  di urutan pertama (default), plus ringkasan isi zip (jumlah berkas
     *  otak, ada/tidaknya settings.json dan memory-db.json) SEBELUM
     *  eksekusi. Bila file tidak ada, perilaku lama dipertahankan
     *  (pesan tidak-ditemukan dari BrainBackup.restore lewat Toast). */
    fun uiRestoreBrainWithConfirm() {
        val src = java.io.File(android.os.Environment.getExternalStoragePublicDirectory(android.os.Environment.DIRECTORY_DOWNLOADS), "harness-restore.zip")
        if (!src.exists()) { uiRestoreBrain(); return }
        val thVc245 = currentTheme()
        var summary = ""
        var stamp = ""
        try {
            stamp = java.text.SimpleDateFormat("dd/MM/yyyy HH:mm", java.util.Locale("id", "ID")).format(java.util.Date(src.lastModified()))
            val zf = java.util.zip.ZipFile(src)
            var otak = 0
            var hasSettings = false
            var hasDb = false
            val en = zf.entries()
            while (en.hasMoreElements()) {
                val n = en.nextElement().name
                if (n == "settings.json") hasSettings = true
                else if (n == "memory-db.json") hasDb = true
                else if (n.startsWith("otak/") || n.startsWith("otak-")) otak++
            }
            zf.close()
            summary = "Isi zip: $otak berkas otak" + (if (hasSettings) ", pengaturan" else ", TANPA pengaturan") + (if (hasDb) ", memori DB (fakta/skill/jadwal/aturan)" else ", TANPA memori DB (zip lama — fakta/skill tidak ikut pulih)")
        } catch (e: Exception) { summary = "Ringkasan isi zip tidak bisa dibaca (${e.message}) — lanjutkan hanya bila kamu yakin dengan file ini." }
        val msg = TextView(this).apply { text = "Sumber: Download/harness-restore.zip\nTanggal file: $stamp\n\n$summary\n\nPERINGATAN: otak aktif akan ditimpa oleh isi zip ini (file otak + pengaturan + memori DB bila ada). Tindakan ini tidak bisa dibatalkan dari UI."; textSize = 14f; setTextColor(thVc245.text) }
        thDialog("♻️ Pulihkan Otak?", msg, listOf(
            Triple("Batal", false) { d: android.app.AlertDialog -> d.dismiss() },
            Triple("Pulihkan", false) { d: android.app.AlertDialog -> d.dismiss(); uiRestoreBrain() }
        ), danger = setOf("Pulihkan"))
    }

