    // Terminal Pro (v4.1.0): sesi sh persisten — cwd & env bertahan antar perintah.
    @Volatile private var termProc: Process? = null
    @Volatile private var termIn: java.io.OutputStream? = null
    private val termBuf = StringBuilder()
    @Volatile private var termMark = 0

    private fun termEnsureShell(): Boolean {
        val alive = try { termProc?.exitValue(); false } catch (e: Exception) { termProc != null }
        if (termProc != null && alive) return true
        return try {
            val p = ProcessBuilder("sh").redirectErrorStream(true).start()
            termProc = p
            termIn = p.outputStream
            Thread {
                try {
                    val r = p.inputStream.bufferedReader()
                    val ch = CharArray(2048)
                    while (true) {
                        val n = r.read(ch)
                        if (n < 0) break
                        synchronized(termBuf) { termBuf.append(ch, 0, n) }
                    }
                } catch (e: Exception) {}
            }.start()
            true
        } catch (e: Exception) { false }
    }

    internal fun termRunPersistent(cmd: String): String {
        if (!termEnsureShell()) return "Shell tidak bisa dimulai."
        val marker = "HXR" + System.nanoTime()
        synchronized(termBuf) { termMark = termBuf.length }
        val w = termIn ?: return "Shell tidak tersedia."
        try {
            w.write((cmd + "\necho " + marker + ":\$?\n").toByteArray())
            w.flush()
        } catch (e: Exception) {
            termProc = null
            return "Shell terputus: ${e.message} — jalankan lagi untuk memulai sesi baru."
        }
        val deadline = System.currentTimeMillis() + 25000
        while (System.currentTimeMillis() < deadline) {
            synchronized(termBuf) {
                val s = termBuf.substring(termMark)
                val idx = s.indexOf(marker + ":")
                if (idx >= 0) {
                    val out = s.substring(0, idx).trimEnd('\n')
                    return if (out.isBlank()) "(tanpa output)" else out
                }
            }
            try { Thread.sleep(60) } catch (e: Exception) {}
        }
        return "Timeout 25 dtk — perintah mungkin masih berjalan di sesi shell."
    }

    fun uiTermReset() {
        // vc200 Fondasi (keputusan atas amanah user): Reset = bunuh worker
        // saja, serve TIDAK ikut. Serve hanya di-restart via BANGKITKAN/revive.
        runOnUiThread {
            try { ProotSession.killWorkers() } catch (e: Exception) {}
            try { termProc?.destroy() } catch (e: Exception) {}
            termProc = null
            synchronized(termBuf) { termBuf.setLength(0); termMark = 0 }
            if (::termOut.isInitialized) termOut.text = "Sesi shell dimulai ulang — folder & variabel direset."
        }
    }

