    /** v3.16.0: ekspor transkrip sesi aktif ke file .md di Download. */
    fun uiExportChat() {
        Thread {
            try {
                val mdb = MemoryDb.get(this)
                val title = mdb.sessionTitle(currentSessionId)
                // vc235 M2: pemakaian historyTranscript LAMA yang SAH dan
                // dipertahankan — ekspor transkrip ke FILE (bukan prompt
                // model): butuh teks penuh tanpa header provenance dan tanpa
                // anggaran per pesan ala Vc230. Semua jalur prompt model
                // (continuation, verifikasi, ekstraksi, BgBrain) sudah pindah
                // ke historyTranscriptVc230; fungsi lama tidak dihapus karena
                // pemakai sah ini masih ada.
                val body = mdb.historyTranscript(2000, 400000, currentSessionId)
                val safe = title.replace(Regex("[^A-Za-z0-9 ]"), "").trim().replace(" ", "-").ifBlank { "sesi" }
                val f = java.io.File("/sdcard/Download/harness-chat-$safe.md")
                f.writeText("# Transkrip Harness — $title\n\n$body\n")
                runOnUiThread { addMsg("📤 Transkrip sesi diekspor ke Download/" + f.name + " (" + (f.length() / 1024) + " KB).", "meta") }
            } catch (e: Exception) {
                runOnUiThread { addMsg("📤 Ekspor gagal: " + e.message, "meta") }
            }
        }.start()
    }

    /** v4.0.0: status semua izin penting untuk wizard Full Setup. */
    internal fun permStatusJson(): JSONObject {
        val o = JSONObject()
        val cr = contentResolver
        fun st(ok: Boolean) = if (ok) "ok" else "no"
        // v4.3.0: isi default SEMUA kunci dulu — satu cek yang gagal tidak boleh
        // membuat izin lain ikut terbaca "Belum".
        for (k in listOf("notif", "notifListener", "a11y", "usage", "overlay", "battery", "files", "alarm", "assistant")) o.put(k, "no")
        o.put("autostart", "manual")
        try {
            o.put("notif", if (android.os.Build.VERSION.SDK_INT >= 33) st(checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS) == android.content.pm.PackageManager.PERMISSION_GRANTED) else "ok")
            val nl = android.provider.Settings.Secure.getString(cr, "enabled_notification_listeners") ?: ""
            o.put("notifListener", st(nl.contains(packageName)))
            val a11yOn = android.provider.Settings.Secure.getInt(cr, android.provider.Settings.Secure.ACCESSIBILITY_ENABLED, 0) == 1
            val a11ySvc = android.provider.Settings.Secure.getString(cr, android.provider.Settings.Secure.ENABLED_ACCESSIBILITY_SERVICES) ?: ""
            o.put("a11y", st(a11yOn && a11ySvc.contains(packageName)))
            val usageOk = try {
                val ao = getSystemService(android.content.Context.APP_OPS_SERVICE) as android.app.AppOpsManager
                @Suppress("DEPRECATION") val m = ao.checkOpNoThrow(android.app.AppOpsManager.OPSTR_GET_USAGE_STATS, android.os.Process.myUid(), packageName)
                m == android.app.AppOpsManager.MODE_ALLOWED
            } catch (e: Exception) { false }
            o.put("usage", st(usageOk))
            o.put("overlay", st(android.provider.Settings.canDrawOverlays(this)))
            val pm = getSystemService(android.content.Context.POWER_SERVICE) as android.os.PowerManager
            o.put("battery", st(pm.isIgnoringBatteryOptimizations(packageName)))
            o.put("files", if (android.os.Build.VERSION.SDK_INT >= 30) st(android.os.Environment.isExternalStorageManager()) else st(checkSelfPermission(android.Manifest.permission.READ_EXTERNAL_STORAGE) == android.content.pm.PackageManager.PERMISSION_GRANTED))
            o.put("alarm", if (android.os.Build.VERSION.SDK_INT >= 31) st((getSystemService(android.content.Context.ALARM_SERVICE) as android.app.AlarmManager).canScheduleExactAlarms()) else "ok")
            val vis = android.provider.Settings.Secure.getString(cr, "voice_interaction_service") ?: ""
            o.put("assistant", st(vis.contains(packageName)))
        } catch (e: Exception) {}
        return o
    }

    /** v4.3.2: status izin untuk jalur khusus kartu Izin (lepas dari getState). */
