    /** v4.3.3: status hidup SELURUH Settings lewat satu jalur khusus —
     *  nilai kartu Bubble/Asisten/Root + badge status per tombol lanjutan. */
    fun uiSettingsStatus(): String {
        val o = JSONObject()
        try {
            val prefs = getSharedPreferences("harness", MODE_PRIVATE)
            o.put("bubbleOn", prefs.getBoolean("overlayOn", false))
            o.put("rootMode", prefs.getBoolean("rootMode", false))
            o.put("rootStatus", prefs.getString("rootStatus", "Belum dites") ?: "Belum dites")
            o.put("bubbleSize", prefs.getInt("bubbleSizeDp", 56))
            o.put("bubbleAlpha", prefs.getInt("bubbleAlphaPct", 100))
            o.put("bubbleTap", prefs.getString("bubbleTap", "panel") ?: "panel")
            o.put("voiceAuto", prefs.getBoolean("voiceAuto", true))
            o.put("panelSpeak", prefs.getBoolean("panelSpeak", true))
            o.put("shakeSummon", prefs.getBoolean("shakeSummon", false))
            o.put("apiMode", prefs.getBoolean("apiMode", false))
            o.put("wakeWordOn", prefs.getBoolean("wakeWordOn", false))
            o.put("tokIn", prefs.getLong("tokInAll", 0))
            o.put("tokOut", prefs.getLong("tokOutAll", 0))
            o.put("tokInSess", prefs.getLong("tokInSess", 0))
            o.put("tokOutSess", prefs.getLong("tokOutSess", 0))
            o.put("sessEvents", prefs.getString("dsSessEvents", "") ?: "")
            o.put("govQuietStart", prefs.getInt("govQuietStart", -1))
            o.put("govQuietEnd", prefs.getInt("govQuietEnd", -1))
            o.put("govWifiOnly", prefs.getBoolean("govWifiOnly", false))
            o.put("notifDigest", prefs.getBoolean("notifDigest", true))
            o.put("routines", prefs.getString("routines", "[]") ?: "[]")
            try {
                val skArr = org.json.JSONArray()
                for (sk in MemoryDb.get(this).skills()) {
                    val so = JSONObject()
                    so.put("id", sk.id); so.put("name", sk.name); so.put("descr", sk.descr); so.put("enabled", sk.enabled)
                    skArr.put(so)
                }
                o.put("skillsList", skArr)
            } catch (e: Exception) {}
            try {
                val sArr = org.json.JSONArray()
                for (s in MemoryDb.get(this).sessions()) {
                    val so = JSONObject()
                    so.put("id", s.id); so.put("title", s.title); so.put("pinned", s.pinned); so.put("active", s.id == currentSessionId)
                    sArr.put(so)
                }
                o.put("sessions", sArr)
            } catch (e: Exception) {}
            o.put("chatFont", prefs.getInt("chatFontPx", 16)) // vc306: default 16
            o.put("sessMsgCount", try { MemoryDb.get(this).historyCount(currentSessionId) } catch (e: Exception) { 0 })
            o.put("dsLogin", ::statusTv.isInitialized && (statusTv.text?.toString() ?: "").contains("LOGIN AKTIF"))
            o.put("connectors", try { Connectors.statusJson(this, o.optBoolean("dsLogin", false)) } catch (e: Exception) { org.json.JSONArray() })
            var agEngine = ""
            try { agEngine = Agents.active(this).engine } catch (e: Exception) {}
            o.put("ckptTask", prefs.getLong("ckptPending", 0))
            o.put("ocBusy", prefs.getLong("ocCurrentTask", 0) > 0)
            o.put("ocPending", try { OcCoord.pendingTitle(this) } catch (e: Exception) { "" })
            val perms = try { permStatusJson() } catch (e: Exception) { JSONObject() }
            fun permBadge(k: String): String = if (perms.optString(k) == "ok") "Aktif" else "Belum"
            val b = JSONObject()
            b.put("0", if (o.getBoolean("dsLogin")) "Login aktif" else "Belum login")
            b.put("1", permBadge("notifListener"))
            b.put("2", permBadge("a11y"))
            b.put("3", permBadge("usage"))
            b.put("5", permBadge("battery"))
            b.put("8", permBadge("files"))
            b.put("12", if (prefs.getBoolean("apiMode", false)) "API Internal" else "WebView")
            try { b.put("48", ScreenWatch.consentStatusText(this)) } catch (e: Exception) {}
            b.put("13", if (prefs.getBoolean("overlayOn", false)) "ON" else "OFF")
            b.put("16", permBadge("assistant"))
            b.put("23", if (prefs.getBoolean("wakeWordOn", false)) "ON" else "OFF")
            if (agEngine.isNotBlank()) b.put("39", "DeepSeek")
            if (prefs.getLong("ocCurrentTask", 0) > 0) b.put("33", "Sedang bekerja")
            b.put("44", permBadge("assistant"))
            b.put("45", if (prefs.getBoolean("rootMode", false)) "ON" else "OFF")
            b.put("46", if (prefs.getBoolean("overlayOn", false)) "ON" else "OFF")
            try {
                val agArr2 = org.json.JSONArray()
                var actId = ""
                var actName = ""
                var actAccent = ""
                try {
                    val act = Agents.active(this)
                    actId = act.id; actName = act.name; actAccent = act.accent
                    for (p in Agents.all(this)) agArr2.put(JSONObject().put("id", p.id).put("name", p.name).put("accent", p.accent).put("engine", p.engine))
                } catch (e: Exception) {}
                o.put("agents", agArr2)
                o.put("agentId", actId)
                o.put("agentName", actName)
                o.put("agentAccent", actAccent)
            } catch (e: Exception) {}
            try {
                val planArr = org.json.JSONArray()
                val planRaw2 = PlanStore.read(this, currentSessionId).toString()
                if (planRaw2.isNotBlank() && planRaw2 != "[]") {
                    val arrP2 = org.json.JSONArray(planRaw2)
                    for (i in 0 until arrP2.length()) {
                        val sP = arrP2.optString(i)
                        planArr.put(JSONObject().put("t", sP.removePrefix("☑").removePrefix("☐").trim()).put("done", sP.startsWith("☑")))
                    }
                }
                o.put("plan", planArr)
            } catch (e: Exception) { o.put("plan", org.json.JSONArray()) }
            try {
                val recArr = org.json.JSONArray()
                val c = MemoryDb.get(this).readableDatabase.rawQuery("SELECT role, text FROM history ORDER BY id DESC LIMIT 4", null)
                val tmp = ArrayList<JSONObject>()
                while (c.moveToNext()) {
                    val t = c.getString(1) ?: ""
                    tmp.add(JSONObject().put("role", c.getString(0) ?: "").put("text", if (t.length > 170) t.substring(0, 170) + "…" else t))
                }
                c.close()
                for (j in tmp.reversed()) recArr.put(j)
                o.put("recent", recArr)
            } catch (e: Exception) { o.put("recent", org.json.JSONArray()) }
            try { val tbRaw = turnPrefs().getString("teamBoard", "") ?: ""; if (tbRaw.isNotBlank()) o.put("team", JSONObject(tbRaw)) } catch (e: Exception) {}
        try { o.put("govCount", Governor.count(this)); o.put("govCap", Governor.cap(this)) } catch (e: Exception) {}
        try {
            var lt = ""
            val ckRaw = turnPrefs().getString("turnCkpt", "") ?: ""
            if (ckRaw.isNotBlank()) {
                val ck = JSONObject(ckRaw)
                if (ck.optBoolean("active", false)) {
                    val ageMin = ((System.currentTimeMillis() - ck.optLong("ts", 0)) / 60000).toInt()
                    lt = (if (ageMin <= 0) "baru saja" else "$ageMin mnt lalu") + " \u2022 " + ck.optString("user", "").take(80)
                }
            }
            o.put("liveTurn", lt)
        } catch (e: Exception) { o.put("liveTurn", "") }
        try {
            val jRaw = turnPrefs().getString("turnJournal", "") ?: ""
            if (jRaw.isNotBlank()) {
                val j = JSONObject(jRaw)
                j.put("ageSec", ((System.currentTimeMillis() - j.optLong("upd", 0)) / 1000).toInt())
                o.put("journal", j)
            }
        } catch (e: Exception) {}
        o.put("badges", b)
        } catch (e: Exception) {}
        return o.toString()
    }

    /** v4.9.5: ekor riwayat sesi aktif untuk penyembuhan tampilan Chat —
     *  baris yang tersimpan selagi UI tertutup/tidak terpasang dikirim ke
     *  React agar digabungkan ke daftar pesan (dedup di sisi React). */
    fun uiChatTail(afterId: Int): String {
        val list = ArrayList<JSONObject>()
        try {
            val db = MemoryDb.get(this).readableDatabase
            val c = if (afterId <= 0) db.rawQuery(
                "SELECT id, role, text, work FROM history WHERE session = ? ORDER BY id DESC LIMIT 40",
                arrayOf(currentSessionId.toString()))
            else db.rawQuery(
                "SELECT id, role, text, work FROM history WHERE session = ? AND id > ? ORDER BY id ASC LIMIT 80",
                arrayOf(currentSessionId.toString(), afterId.toString()))
            while (c.moveToNext()) {
                val o = JSONObject()
                o.put("id", c.getLong(0))
                o.put("role", c.getString(1) ?: "")
                o.put("text", c.getString(2) ?: "")
                val w = c.getString(3)
                if (!w.isNullOrBlank()) o.put("work", w)
                list.add(o)
            }
            c.close()
            if (afterId <= 0) list.reverse()
        } catch (e: Exception) {}
        val arr = org.json.JSONArray()
        for (o in list) arr.put(o)
        return arr.toString()
    }

    /** v4.0.0: tandai tahap flow awal (onboarding/login/setup) selesai atau reset. */
    fun uiSetFlow(key: String) {
        runOnUiThread {
            val e = getSharedPreferences("harness", MODE_PRIVATE).edit()
            when (key) {
                "onboarded" -> e.putBoolean("flowOnboarded", true)
                "login" -> e.putBoolean("flowLogin", true)
                "setup" -> e.putBoolean("flowSetup", true)
                "identity" -> e.putBoolean("flowIdentity", true)
                "reset" -> { e.putBoolean("flowOnboarded", false); e.putBoolean("flowLogin", false); e.putBoolean("flowSetup", false); if (Flavor.IS_PURE) e.putBoolean("flowIdentity", false) }
            }
            e.apply()
        }
    }

    /** v4.0.0: buka halaman izin yang tepat (stock Android & MIUI). */
    fun uiPermOpen(id: String) {
        if (id == "assistant") {
            runOnUiThread {
                val ok = try { startActivity(Intent(android.provider.Settings.ACTION_VOICE_INPUT_SETTINGS)); true } catch (e: Exception) { false }
                if (!ok) { try { startActivity(Intent(android.provider.Settings.ACTION_SETTINGS)) } catch (e: Exception) {} }
                Toast.makeText(this, "Pilih Harness sebagai Asisten digital, lalu aktifkan gestur tahan tombol power di setelan HP bila ada.", Toast.LENGTH_LONG).show()
            }
            return
        }
        runOnUiThread {
            val pkgUri = android.net.Uri.parse("package:$packageName")
            fun go(intent: Intent): Boolean = try { startActivity(intent); true } catch (e: Exception) { false }
            val done = when (id) {
                "notif" -> if (android.os.Build.VERSION.SDK_INT >= 33) { requestPermissions(arrayOf(android.Manifest.permission.POST_NOTIFICATIONS), 9911); true }
                    else go(Intent(android.provider.Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(android.provider.Settings.EXTRA_APP_PACKAGE, packageName))
                "notifListener" -> go(Intent(android.provider.Settings.ACTION_NOTIFICATION_LISTENER_SETTINGS))
                "a11y" -> go(Intent(android.provider.Settings.ACTION_ACCESSIBILITY_SETTINGS))
                "usage" -> go(Intent(android.provider.Settings.ACTION_USAGE_ACCESS_SETTINGS))
                "overlay" -> go(Intent(android.provider.Settings.ACTION_MANAGE_OVERLAY_PERMISSION, pkgUri))
                "battery" -> go(Intent(android.provider.Settings.ACTION_REQUEST_IGNORE_BATTERY_OPTIMIZATIONS, pkgUri)) || go(Intent(android.provider.Settings.ACTION_IGNORE_BATTERY_OPTIMIZATION_SETTINGS))
                "files" -> if (android.os.Build.VERSION.SDK_INT >= 30) go(Intent(android.provider.Settings.ACTION_MANAGE_APP_ALL_FILES_ACCESS_PERMISSION, pkgUri)) || go(Intent(android.provider.Settings.ACTION_MANAGE_ALL_FILES_ACCESS_PERMISSION)) else go(Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS, pkgUri))
                "alarm" -> if (android.os.Build.VERSION.SDK_INT >= 31) go(Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM, pkgUri)) else true
                "autostart" -> go(Intent().setComponent(android.content.ComponentName("com.miui.securitycenter", "com.miui.permcenter.autostart.AutoStartManagementActivity"))) || go(Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS, pkgUri))
                else -> false
            }
            if (!done) { try { startActivity(Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS, pkgUri)) } catch (e: Exception) {} }
        }
    }

