            val colP = LinearLayout(this@MainActivity).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(12), 0, 0, 0); layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f) }
            colP.addView(tv(label, 14f, when { danger -> th.errText; warn -> warnText; else -> th.text }, true))
