    internal fun thDialog(title: String, body: View, buttons: List<Triple<String, Boolean, (android.app.AlertDialog) -> Unit>>, danger: Set<String> = emptySet()): android.app.AlertDialog {
        val th = currentTheme()
        var dlgHolder: android.app.AlertDialog? = null
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(14), dp(16), dp(10)); background = rounded(th.card, ChatThemeVc306.rXl) }
        if (title.isNotBlank()) col.addView(tv(title, 16f, th.text, true).apply { setPadding(0, 0, 0, dp(10)) })
        col.addView(body)
        if (buttons.isNotEmpty()) {
            val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(12), 0, 0) }
            for ((label, accent, act) in buttons) {
                val b = thBtn(label, accent) { dlgHolder?.let(act) }
                if (label in danger) { b.background = rounded(th.errBg, 12); b.setTextColor(th.errText) }
                b.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
                row.addView(b)
            }
            col.addView(row)
        }
        val scroll = ScrollView(this).apply { addView(col) }
        val dlg = android.app.AlertDialog.Builder(this).setView(scroll).create()
        dlgHolder = dlg
        dlg.show()
        try { dlg.window?.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(Color.TRANSPARENT)) } catch (e: Exception) {}
        return dlg
    }

