        row.addView(webTile("⬇", "Login / Muat DeepSeek", true) { setBrowserMode(false); try { webView.loadUrl("https://chat.deepseek.com/") } catch (e: Exception) {} })
        row.addView(webTile("🧭", "Jelajah Agen", false) { setBrowserMode(true) })
