    private fun buildWebSlotRow(): LinearLayout {
        val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(dp(4), dp(2), dp(4), dp(4)) }
        for (slot in 1..5) {
            val cls: Class<*> = when (slot) { 1 -> SlotBrowser1::class.java; 2 -> SlotBrowser2::class.java; 3 -> SlotBrowser3::class.java; 4 -> SlotBrowser4::class.java; else -> SlotBrowser5::class.java }
            row.addView(webTile("🌐", "Browser $slot", false) { try { startActivity(Intent(this@MainActivity, cls).putExtra("slot", slot)) } catch (e: Exception) {} })
        }
        return row
    }

    private fun refreshWebChrome() {
        val th = currentTheme()
        try {
            val box = webBoxRef ?: return
            box.setBackgroundColor(th.bg)
            webTopRowRef?.let { box.removeView(it) }
            webSlotRowRef?.let { box.removeView(it) }
            val top = buildWebTopRow()
            val slots = buildWebSlotRow()
            box.addView(top, 0)
            box.addView(slots, 1)
            webTopRowRef = top
            webSlotRowRef = slots
            webBtnsRef = top
            bUrlTv?.setTextColor(th.dim)
        } catch (e: Exception) {}
    }

    private fun themeViewTree(v: View, th: ThemeColors) {
        when (v) {
            is CheckBox -> v.setTextColor(th.text)
            is Button -> { v.background = rounded(th.tileBg, 14); v.setTextColor(th.text) }
            is TextView -> v.setTextColor(if (v.text.toString() in setOf("PENGATURAN PESAN", "AKSI CEPAT", "SESI & LAINNYA")) th.dim else th.text)
            is ViewGroup -> for (i in 0 until v.childCount) themeViewTree(v.getChildAt(i), th)
        }
    }

    private fun refreshChatChrome() {
        val th = currentTheme()
        try {
            containers["Chat"]?.background = pageBackground() // vc306 (C1): gradasi Mist, bukan solid
            chatSessionBarRef?.setBackgroundColor(th.card)
            if (::sessionTitleTv.isInitialized) sessionTitleTv.setTextColor(th.text)
            chatSessionBarRef?.let { bar ->
                for (i in 0 until bar.childCount) {
                    val v = bar.getChildAt(i)
                    if (v is Button) {
                        v.background = rounded(th.tileBg, 16)
                        v.setTextColor(th.text)
                        for (d in v.compoundDrawables) d?.setTint(th.tileTint)
                    }
                }
            }
            (chatDrawerPanel as? ViewGroup)?.getChildAt(0).let { (it as? LinearLayout)?.let { panel ->
                panel.setBackgroundColor(th.card)
                themeViewTree(panel, th)
            } }
            artifactDividerRef?.setBackgroundColor(th.stroke)
            artifactPanelRoot?.setBackgroundColor(th.bg)
            // vc306 Worker B: chrome kaca + tombol composer + strip + header
            // (ganti setBackgroundColor(th.card) + loop tint lama yang
            // mengasumsikan tombol TextView "+" / mic kosong — kini semua
            // tombol composer adalah Button dengan ikon drawable).
            applyVc306Chrome()
            if (::chatInput.isInitialized) { chatInput.setTextColor(th.text); chatInput.setHintTextColor(if (isDarkTheme()) ChatThemeVc306.darkFaint else ChatThemeVc306.lightFaint) }
            replyChipTv?.setTextColor(th.tileTint)
            // vc307: tint ikon Path "back" chip balas ikut warna teks chip.
            replyChipTv?.let { for (d in it.compoundDrawables) d?.setTint(th.tileTint) }
        } catch (e: Exception) {}
    }

    internal fun refreshGroupChrome() {
        val th = currentTheme()
        try {
            groupBoxRef?.setBackgroundColor(th.bg)
            groupHeadRef?.setBackgroundColor(th.card)
            groupHead2Ref?.setBackgroundColor(th.card)
            groupDividerRef?.setBackgroundColor(th.stroke)
            groupHeadRef?.let { head ->
                for (i in 0 until head.childCount) {
                    val v = head.getChildAt(i)
                    if (v is Button) { v.background = rounded(th.tileBg, 16); v.setTextColor(th.text) }
                    // vc309 Worker B: "tanpa thinking" tetap DIM (dulu loop
                    // ini menimpanya jadi th.text — sama gelapnya dengan
                    // judul — sehingga status mode tidak lagi tersier).
                    else if (v is TextView) v.setTextColor(if (v.text.toString() == "tanpa thinking") th.dim else th.text)
                }
            }
            groupHead2Ref?.let { h2 ->
                val inner = h2.getChildAt(0) as? LinearLayout
                val rencana = inner?.getChildAt(2)
                if (rencana is Button) { rencana.background = rounded(th.tileBg, 16); rencana.setTextColor(th.text) }
            }
            groupInputRef?.setTextColor(th.text)
            // vc309 Worker B: composer grup ikut tema saat refresh — latar
            // kaca seperti composer 1-1 + hint tersier (faint), bukan dim.
            // Tanpa baris ini composer grup tetap hitam walau tema cerah
            // (latar hardcoded di build tidak pernah disentuh refresh).
            groupInputRowRef?.background = glassDrawableVc306(ChatThemeVc306.rXl, isDarkTheme())
            groupInputRef?.setHintTextColor(if (isDarkTheme()) ChatThemeVc306.darkFaint else ChatThemeVc306.lightFaint)
            if (::groupTypingTv.isInitialized) groupTypingTv.setTextColor(th.dim)
            groupReplyChipTv?.setTextColor(th.tileTint)
            refreshGroupChips()
        } catch (e: Exception) {}
    }

    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        // vc316 Worker BR (d): WebView L+ hanya menggambar porsi terlihat
        // (optimasi "intelligently choosing the portion") — wv.draw(canvas)
        // di browser_shot(_full) jadi hitam di bawah viewport pertama
        // (T-BR-23, pos-ssr.site). Matikan optimasi itu SEBELUM WebView
        // pertama dibuat (buildUi di bawah membuat WebView login).
        // Harga: draw() lebih lambat — hanya dipakai saat tangkapan layar;
        // tampilan live tidak berubah.
        try {
            if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.LOLLIPOP) {
                android.webkit.WebView.enableSlowWholeDocumentDraw()
            }
        } catch (e: Exception) {}
        CrashGuard.install(this)
        // vc196: migrasi id sesi telanjang -> namespaced, SEBELUM buildUi
        // dan SEBELUM service scheduler jalan (onCreate ini juga men-start
        // HarnessService). Sinkron by design: data kecil (JSON prefs),
        // harus selesai sebelum routing routine dipercaya.
        try { Automation.migrateSessionIds(this) } catch (e: Exception) {}
        buildUi()
        // vc309 Worker A — edge-to-edge penuh + bar ikut tema (§2 laporan):
        // apply di onCreate sesudah buildUi() supaya tiap recreate() —
        // termasuk toggle tema vc308 — otomatis menerapkan bar yang benar.
        // JANGAN panggil di call-site toggle: recreate yang ditunda saat
        // giliran berjalan akan membuat bar dan konten tidak cocok sementara.
        // Listener inset dipasang di content view (root LinearLayout
        // buildClassicUi); semua tab hidup di dalam stack di root itu
        // sehingga satu listener mencakup Beranda/Chat/Grup/Terminal/
        // Profil/Setup/Web. Gagal apply tidak pernah crash (try/catch di
        // dalam helper).
        try { SystemBarsVc309.applySystemBars(window, isDarkTheme()) } catch (e: Exception) {}
        try {
            val content = window.decorView.findViewById<View>(android.R.id.content)
            if (content != null) SystemBarsVc309.installEdgeToEdge(window, content)
        } catch (e: Exception) {}
        restoreThemeRecreateStateVc308()
        Thread {
            try {
                val rows = MemoryDb.get(this).historyForSession(currentSessionId, 40)
                if (rows.isNotEmpty()) runOnUiThread {
                    for ((role, txt) in rows) addBubble(txt, role == "user")
                }
            } catch (e: Exception) {}
        }.start()
        addBubble("Halo. Aku asisten DeepSeek-mu dengan konteks HP ini. Kalau belum login, buka tab Web dan login dulu. Contoh perintah: 'notif apa aja yang masuk hari ini?', 'app apa yang paling lama kupakai?', 'buka WhatsApp', atau 'cek baterai'.", false)
        // vc176: setupWebView() dipindah ke post pertama (ensureWeb) —
        // WebView init tidak lagi di jalur launch.
        try {
            val i = Intent(this, HarnessService::class.java)
            if (Build.VERSION.SDK_INT >= 26) startForegroundService(i) else startService(i)
        } catch (e: Exception) {}
        // vc301 SF-D6: bila proses app restart sementara server Mode ADB
        // masih hidup, binder in-memory hilang — minta server mengirim ulang
        // binder (best-effort; server pra-vc301 mengabaikan permintaan ini).
        // Tidak blokir UI; S7 di HarnessService tetap penjaga auto-start.
        Thread { try { PrivServer.rebindIfNeeded(this) } catch (e: Exception) {} }.start()
        EventDb.get(this).add("app", packageName, "Harness dibuka")
        Thread { try { RedactMigration.runOnce(this) } catch (e: Exception) {} }.start()
        Thread { try { DsSafetyMigration.runOnce(this) } catch (e: Exception) {} }.start()
        Embedder.maybeBackfill(this)
        // F2 (v4.39.0): default jam hening D2 (23:00-05:00) bila belum disetel.
        try {
            val pf = getSharedPreferences("harness", MODE_PRIVATE)
            if (!pf.getBoolean("f2QuietInit", false)) {
                val e = pf.edit()
                if (pf.getInt("govQuietStart", -1) < 0) e.putInt("govQuietStart", 23)
                if (pf.getInt("govQuietEnd", -1) < 0) e.putInt("govQuietEnd", 5)
                e.putBoolean("f2QuietInit", true).apply()
        // F2.1 (v4.39.1): grounding untuk 2 job contoh yang sudah dibuat.
        try {
            val pf2 = getSharedPreferences("harness", MODE_PRIVATE)
            if (!pf2.getBoolean("f2p1PromptFix", false)) {
                val raw = pf2.getString("routines", "[]") ?: "[]"
                val arr = try { org.json.JSONArray(raw) } catch (e: Exception) { org.json.JSONArray() }
                var changed = false
                for (i in 0 until arr.length()) {
                    val r = arr.optJSONObject(i) ?: continue
                    val id = r.optString("id", "")
                    if (id == "contoh-harian" || id == "contoh-perjam") {
                        val pr = r.optString("prompt", "")
                        if (pr.isNotBlank() && !pr.contains("HANYA angka")) {
                            r.put("prompt", pr + " Tulis HANYA angka yang benar-benar tampil di hasil tool; bila hasil tool parsial, tulis 'data parsial' dan jangan menyimpulkan total.")
                            changed = true
                        }
                    }
                }
                if (changed) pf2.edit().putString("routines", arr.toString()).apply()
                pf2.edit().putBoolean("f2p1PromptFix", true).apply()
            }
        } catch (e: Exception) {}
            }
        } catch (e: Exception) {}
        try {
            val filter = android.content.IntentFilter(TermuxBridge.ACTION)
            if (Build.VERSION.SDK_INT >= 33) {
                registerReceiver(termuxReceiver, filter, Context.RECEIVER_EXPORTED)
            } else {
                @Suppress("UnspecifiedRegisterReceiverFlag")
                registerReceiver(termuxReceiver, filter)
            }
        } catch (e: Exception) {}
        refreshSessionStatus()
        handleIncomingIntent(intent)
        try {
            if (checkSelfPermission("com.termux.permission.RUN_COMMAND") != PackageManager.PERMISSION_GRANTED) {
                requestPermissions(arrayOf("com.termux.permission.RUN_COMMAND"), 98)
            }
        } catch (e: Exception) {}
    }

    // ---------------- UI ----------------

    internal fun dp(v: Int): Int = (v * resources.displayMetrics.density).toInt()

    private fun buildUi() {
        // T6: UI React pensiun — Harness selalu UI klasik native.
        buildClassicUi()
    }

    private fun buildWebBox(): LinearLayout {
        val th = currentTheme()
        val webBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setBackgroundColor(th.bg) }
        webBoxRef = webBox
        // vc181 (mockup Web Login v4 DIKUNCI): baris atas = ubin Login/Muat
        // DeepSeek + Jelajah Agen (ikon di atas label); tanpa segmen LOGIN AI,
        // tanpa Chat Baru, tanpa Cek Sesi. Baris slot = ubin Browser 1-4.
        val topRow = buildWebTopRow()
        webBox.addView(topRow)
        webTopRowRef = topRow
        val slotBtns = buildWebSlotRow()
        webBox.addView(slotBtns)
        webSlotRowRef = slotBtns
        webBtnsRef = topRow
        webView = WebView(this).apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f) }
        webBox.addView(webView)
        // T4b1: kontainer Jelajah Agen (WebView terpisah dari login)
        val bBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; visibility = View.GONE }
        val bBar = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
        // vc316 Worker BR (b): minWidth=0 di semua tombol bar tab — lebar
        // default Button (88dp) × 4 bisa mendorong ＋ Tab keluar layar di
        // HP sempit. Hit area tetap aman (minHeight default Button 48dp).
        bBar.addView(Button(this).apply { text = "◀"; minWidth = 0; setOnClickListener { bActiveWv()?.goBack() } })
        bBar.addView(Button(this).apply { text = "▶"; minWidth = 0; setOnClickListener { bActiveWv()?.goForward() } })
        bBar.addView(Button(this).apply { text = "⟳"; minWidth = 0; setOnClickListener { bActiveWv()?.reload() } })
        // vc313: tombol ＋ Tab menghormati batas 5 tab (Spek §3.4).
        bBar.addView(Button(this).apply { text = "＋ Tab"; minWidth = 0; setOnClickListener { val wv = ensureBrowserTab(true); if (wv == null && bTabs.size >= MAX_BROWSER_TABS_VC313) Toast.makeText(this@MainActivity, "Batas 5 tab aktif", Toast.LENGTH_SHORT).show() } })
        bBox.addView(bBar)
        // vc316 Worker BR (b): URL panjang SATU baris + ellipsize — tanpa
        // ini TextView membungkus puluhan baris dan mendorong WebView
        // (weight 1) keluar layar. Label teks sendiri juga dipotong di
        // updateBrowserVisibility (AgentBrowser.tabLabelVc316).
        val uTv = TextView(this).apply {
            text = "Browser agen — belum ada tab. Agen membukanya lewat tool browser_open; atau ketuk ＋ Tab."
            textSize = 11.5f; setTextColor(DIM)
            setSingleLine(true)
            ellipsize = android.text.TextUtils.TruncateAt.END
            maxLines = 1
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        bUrlTv = uTv
        bBox.addView(uTv)
        val frame = FrameLayout(this).apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f) }
        bFrame = frame
        bBox.addView(frame)
        browserBox = bBox
        webBox.addView(bBox)
        AgentBrowser.impl = { n, a -> browserTool(n, a) }
        return webBox
    }

    private fun buildClassicUi() {
        val root = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setBackgroundColor(BG) }

        val header = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(14), dp(10), dp(14), dp(6)) }
        header.addView(TextView(this).apply { text = "Harness"; textSize = 19f; setTextColor(TEXT) })
        statusTv = TextView(this).apply { text = "Sesi DeepSeek: memeriksa…"; textSize = 12f; setTextColor(DIM) }
        header.addView(statusTv)
        // T7: header lama disembunyikan — sapaan + status pindah ke Beranda
        // ala mockup. statusTv tetap di hierarki agar semua penulis status
        // (dan pembaca seperti refreshBeranda/Wizard) tetap bekerja.
        header.visibility = View.GONE
        root.addView(header)

        // T7: bilah tab di BAWAH ala mockup (ikon + label dua baris)
        val tabBar = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT); setPadding(dp(8), dp(6), dp(8), dp(8)); setBackgroundColor(currentTheme().card) }
        for (name in listOf("Beranda", "Chat", "Terminal", "Profil", "Setup")) {
            val b = Button(this).apply {
                text = name; textSize = 10.5f
                // vc307 Worker B: ikon tab pakai sizedIconVc306 (bounds dp
                // eksplisit + skala smallest-width), BUKAN intrinsic 24dp
                // mentah — di layar kecil ikon mengecil, di tablet membesar;
                // hit area tetap >= 48dp (minHeight eksplisit, dulu 0).
                minWidth = 0; minHeight = dp(ChatThemeVc306.touchTarget)
                setMinimumHeight(dp(ChatThemeVc306.touchTarget))
                setSingleLine(true); ellipsize = android.text.TextUtils.TruncateAt.END
                val tabRes = when (name) { "Beranda" -> R.drawable.ic_home; "Chat" -> R.drawable.ic_chat; "Terminal" -> R.drawable.ic_keyboard; "Profil" -> R.drawable.ic_person; else -> R.drawable.ic_settings }
                setCompoundDrawables(null, sizedIconVc306(tabRes, DIM, chatIconSizeVc307(ChatThemeVc306.iconXl)), null, null)
                compoundDrawablePadding = dp(2)
                layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                setOnClickListener { showTab(name) }
            }
            tabBtns[name] = b
            tabBar.addView(b)
        }

        val stack = FrameLayout(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f)
            setBackgroundColor(BG)
        }

        // vc176: Web TIDAK dibangun di launch (WebView init = biaya launch
        // terbesar) — dibangun lazy via ensureWeb() (post pertama / tap Web).
        tabStack = stack

        // Chat — vc306 (C1): latar gradasi Mist via pageBackground().
        val chatBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; background = pageBackground() }
        chatScroll = ScrollView(this).apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f) }
        chatList = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(14), dp(88), dp(14), dp(12)) }
        // vc306 Worker B: padding atas 88 = header kaca mengambang
        // (margin 8 + bar 56 + fade 12) + jeda 12, agar pesan pertama
        // tidak tertutup header saat daftar di-scroll ke atas.
        chatScroll.addView(chatList)
        chatBox.addView(chatScroll)
        // T8: tombol lompat ke pesan terbaru (ada di UI lama, hilang di native)
        // vc308 Worker A (SS2): tombol ini PINDAH ke baris OTOMASI
        // (autoTopRow) — bukan lagi bar biru solid full-width mengambang di
        // atas composer. Dibangun di sini (butuh chatScroll + lb untuk
        // listener scroll di bawah), ditempel ke autoTopRow di bawah (baris
        // itu dibuat setelah blok ini). Styling ikut pill OTOMASI: latar
        // transparan (autoPillBgVc307), teks/ikon th.text, hit area 48dp.
        // Fungsi TETAP: scroll ke bawah + sembunyikan diri.
        val lb = Button(this).apply {
            text = "Pesan Terbaru"
            textSize = 12f
            typeface = android.graphics.Typeface.DEFAULT_BOLD
            background = autoPillBgVc307()
            setTextColor(currentTheme().text)
            minWidth = 0
            minHeight = dp(ChatThemeVc306.touchTarget)
            setMinimumHeight(dp(ChatThemeVc306.touchTarget))
            setPadding(dp(14), 0, dp(14), 0)
            gravity = Gravity.CENTER
            contentDescription = "Pesan Terbaru"
            setSingleLine(true)
            ellipsize = android.text.TextUtils.TruncateAt.END
            visibility = View.GONE
            setCompoundDrawables(pathIconVc306("down", currentTheme().text, chatIconSizeVc307(ChatThemeVc306.iconXs)), null, null, null)
            compoundDrawablePadding = dp(6)
            setOnClickListener { chatScroll.fullScroll(View.FOCUS_DOWN); visibility = View.GONE }
        }
        latestBtn = lb
        // TIDAK lagi chatBox.addView(lb) — ditempel ke autoTopRow di bawah.
        chatScroll.setOnScrollChangeListener { _, _, _, _, _ ->
            val nb = chatScroll.scrollY + chatScroll.height >= chatList.height - dp(300)
            lb.visibility = if (nb) View.GONE else View.VISIBLE
        }
        currentSessionId = getSharedPreferences("harness", MODE_PRIVATE).getLong("currentSession", 1L)
        val sessionBar = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            setBackgroundColor(PANEL)
            setPadding(dp(12), dp(8), dp(8), dp(8))
            // vc306 Worker B: session bar dilebur ke title pill header kaca
            // (C5) — disembunyikan, BUKAN dihapus: ref + penulis judulnya
            // (sessionTitleTv) tetap hidup agar switch/rename sesi tetap
            // jalan; aksinya pindah ke header (menu → drawer) + drawer
            // ("Sesi…", "Cari di chat…", "Grup…", "Artefak…").
            visibility = View.GONE
        }
        sessionTitleTv = TextView(this).apply {
            text = "🗂️ " + MemoryDb.get(this@MainActivity).sessionTitle(currentSessionId)
            setTextColor(TEXT); textSize = 13f; typeface = android.graphics.Typeface.DEFAULT_BOLD
            setSingleLine(true); ellipsize = android.text.TextUtils.TruncateAt.END
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        sessionBar.addView(sessionTitleTv)
        sessionBar.addView(Button(this).apply {
            // vc315 N8-M1: latar ikut tema (dulu rgb(34,34,34) hardcoded —
            // di tema terang teks #1E232E di atas #222222 kontras 1,01:1,
            // tak terbaca; kini tileBg tema: terang 13,24:1, gelap 12,30:1).
            background = rounded(currentTheme().tileBg, 16)
            minWidth = 0; minHeight = 0
            setCompoundDrawablesWithIntrinsicBounds(iconDrawable(R.drawable.ic_tune, TEXT), null, null, null)
            setOnClickListener { toggleChatDrawer() }
        }, 0)
        sessionBar.addView(Button(this).apply { text = "Sesi"; background = rounded(currentTheme().tileBg, 16); setTextColor(TEXT); minWidth = 0; minHeight = 0; setCompoundDrawablesWithIntrinsicBounds(iconDrawable(R.drawable.ic_history, TEXT), null, null, null); compoundDrawablePadding = dp(4); setOnClickListener { showSessionDialog() } })
        sessionBar.addView(Button(this).apply { text = "👥 Grup"; background = rounded(currentTheme().tileBg, 16); setTextColor(TEXT); minWidth = 0; minHeight = 0; setOnClickListener { showTab("Grup") } })
        sessionBar.addView(Button(this).apply { text = ""; background = rounded(currentTheme().tileBg, 16); minWidth = 0; minHeight = 0; setCompoundDrawablesWithIntrinsicBounds(iconDrawable(R.drawable.ic_search, TEXT), null, null, null); setOnClickListener { showChatSearch() } })
        sessionBar.addView(Button(this).apply { text = "📄"; background = rounded(currentTheme().tileBg, 16); setTextColor(TEXT); minWidth = 0; minHeight = 0; setOnClickListener { showArtifactListDialog() } })
        chatBox.addView(sessionBar, 0)
        artifactDividerRef = View(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(1))
            setBackgroundColor(Color.rgb(32, 32, 32))
        }
        chatBox.addView(artifactDividerRef, 1)
        chatSessionBarRef = sessionBar
        // T12: drawer sidebar chat — root + scrim + panel geser (kanan).
        // Dibuat di sini, diisi kontennya di bawah (ctxCheck/modeRow/chips
        // pindah induk ke drawerPanel), ditempel ke stack di akhir blok.
        val drawerRoot = FrameLayout(this).apply { visibility = View.GONE }
        val drawerScrim = View(this).apply {
            setBackgroundColor(Color.argb(150, 0, 0, 0))
            setOnClickListener { setChatDrawer(false) }
        }
        drawerRoot.addView(drawerScrim, FrameLayout.LayoutParams(
            FrameLayout.LayoutParams.MATCH_PARENT, FrameLayout.LayoutParams.MATCH_PARENT))
        // vc309 Worker B: lebar 320dp (dulu 300dp) — memberi napas 20dp
        // ekstra untuk label panjang di drawer (chip AKSI CEPAT vertikal +
        // checkbox PENGATURAN PESAN) tanpa melanggar batas drawer Material
        // (lebar layar − 56dp). setChatDrawer() memakai lebar panel aktual
        // saat menutup, jadi tidak ada konstanta 300 yang tertinggal.
        val drawerW = dp(320)
        val drawerPanel = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            // vc308 Worker C (BUG 4): dulu rgb(20,20,20) hardcoded — panel
            // drawer gelap walau tema cerah (diperbaiki juga oleh
            // refreshChatChrome saat masuk tab Chat; nilai bangun ini
