                    "fontScale=" + resources.configuration.fontScale,
                    "density=" + dm.density,
                    "screenWidthPx=" + dm.widthPixels,
                    "screenWidthDp=" + (dm.widthPixels / dm.density),
                    "hint=" + chatInput.hint
