        attachStripBoxVc212 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(dp(8), dp(2), dp(8), dp(2)); visibility = View.GONE }
        attachStripRowVc212 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
        val attachScrollVc212 = HorizontalScrollView(this).apply { addView(attachStripRowVc212!!); layoutParams = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT) }
        attachStripBoxVc212!!.addView(attachScrollVc212)
