    private fun mimeForNameVc212(name: String): String {
        return when (name.substringAfterLast('.', "").lowercase()) {
            "pdf" -> "application/pdf"
            "docx" -> "application/vnd.openxmlformats-officedocument.wordprocessingml.document"
            "doc" -> "application/msword"
            "txt" -> "text/plain"
            "md" -> "text/markdown"
            "csv" -> "text/csv"
            "json" -> "application/json"
            "jpg", "jpeg" -> "image/jpeg"
            "png" -> "image/png"
            "wav" -> "audio/x-wav"
            "mp3" -> "audio/mpeg"
            "m4a" -> "audio/mp4"
            "ogg" -> "audio/ogg"
            "aac" -> "audio/aac"
            "flac" -> "audio/flac"
            else -> "application/octet-stream"
        }
    }
    private fun sendPendingAttachesVc212(contextText: String, attaches: List<PendingAttachVc212>) {
        showTab("Chat")
        addBubble("📎 Mengirim " + attaches.size + " lampiran dengan konteks: " + contextText.take(200), true)
        Thread {
            try {
                val apiOn = try { getSharedPreferences("harness", MODE_PRIVATE).getBoolean("apiMode", false) || operatorMode() } catch (e: Exception) { false }
                if (apiOn) {
                    val files = ArrayList<Triple<ByteArray, String, String>>()
                    val failedRead = ArrayList<String>()
                    for (pa in attaches) {
                        try {
                            val bytes = contentResolver.openInputStream(pa.uri)?.readBytes() ?: throw Exception("tidak terbaca")
                            if (bytes.size > 12_000_000) throw Exception("lebih dari 12 MB")
                            files.add(Triple(bytes, pa.name, pa.mime.ifBlank { mimeForNameVc212(pa.name) }))
                        } catch (e: Exception) { failedRead.add(pa.name + " (" + (e.message ?: "gagal baca") + ")") }
                    }
                    if (files.isEmpty()) {
                        runOnUiThread { addBubble("⚠️ Semua lampiran gagal dibaca, tidak ada yang dikirim: " + failedRead.joinToString("; "), false) }
                    } else {
                    val prompt = "Konteks dari user: " + contextText + "\n\nBaca semua berkas terlampir berikut dan jawab sesuai konteks di atas. " + (if (failedRead.isNotEmpty()) "Catatan: berkas berikut GAGAL dibaca dan TIDAK ikut diunggah: " + failedRead.joinToString(", ") + ". Sebutkan kegagalan ini di jawabanmu." else "")
                    // B13: klien DeepSeek bisa belum ada (startup openai) —
                    // gagal jujur + fallback per berkas seperti jalur error.
                    val dsClientVc212 = apiClient ?: if (ensureDsClients()) apiClient else null
                    if (dsClientVc212 == null) {
                        runOnUiThread { addBubble("⚠️ Lampiran multi-file via API gagal: engine DeepSeek belum siap (otak = Models API) — fallback per berkas dengan konteks yang sama.", false) }
                        for (pa in attaches) { try { handleAttachment(pa.uri, contextText) } catch (e: Exception) {} }
                    } else dsClientVc212.uploadFilesAndAsk(files, prompt, false, { answer, failedUp ->
                        runOnUiThread {
                            val failNote = if (failedRead.isNotEmpty() || failedUp.isNotEmpty()) "\n\n⚠️ Berkas yang gagal diunggah (tidak dibaca model). Ini BUKAN karena agen tidak bisa menerima file — alasan gagal per berkas: " + (failedRead + failedUp).joinToString("; ") + ". Sampaikan alasan ini apa adanya ke user, jangan jawab 'tidak bisa menerima file'." else ""
                            sendContinuation("Hasil lampiran multi-file (jalur lampiran: upload penuh via API Internal):\n" + answer + failNote + "\n\nSampaikan hasil ini ke user dan lanjutkan tugasmu.")
                        }
                    }, { err ->
                        runOnUiThread { addBubble("⚠️ Lampiran multi-file via API gagal: $err — fallback per berkas dengan konteks yang sama.", false) }
                        for (pa in attaches) { try { handleAttachment(pa.uri, contextText) } catch (e: Exception) {} }
                    })
                    }
                } else {
                    for (pa in attaches) { try { handleAttachment(pa.uri, contextText) } catch (e: Exception) {} }
                }
            } catch (e: Exception) {
                runOnUiThread { addBubble("⚠️ Kirim lampiran gagal: ${e.message}", false) }
            }
        }.start()
    }
    private fun fallbackDocVc212(cacheF: File, name: String, ext: String, question: String) {
        try {
            if (ext == "pdf") {
                val pfd = android.os.ParcelFileDescriptor.open(cacheF, android.os.ParcelFileDescriptor.MODE_READ_ONLY)
                val renderer = android.graphics.pdf.PdfRenderer(pfd)
                val page = renderer.openPage(0)
                val bmp = android.graphics.Bitmap.createBitmap(page.width, page.height, android.graphics.Bitmap.Config.ARGB_8888)
                page.render(bmp, null, null, android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                page.close(); renderer.close(); pfd.close()
                val jpg = File(cacheDir, "pdf-page1-" + System.currentTimeMillis() + ".jpg")
                java.io.FileOutputStream(jpg).use { bmp.compress(android.graphics.Bitmap.CompressFormat.JPEG, 85, it) }
                runOnUiThread { showTab("Chat"); addBubble("📄 PDF '" + name + "' — fallback: menganalisa halaman 1 lewat vision…", false); analyzePhotoAndContinue(JSONObject().put("path", jpg.absolutePath).put("question", (question.ifBlank { "Ringkas isi halaman PDF ini." }))) }
            } else if (ext == "docx") {
                val textDoc = try {
                    val zf = java.util.zip.ZipFile(cacheF)
                    val entry = zf.getEntry("word/document.xml") ?: throw Exception("document.xml tidak ditemukan")
                    val xml = zf.getInputStream(entry).bufferedReader().readText()
                    zf.close()
                    xml.replace(Regex("<w:p[ >]"), "\n").replace(Regex("<[^>]+>"), "").replace("&lt;", "<").replace("&gt;", ">").replace("&amp;", "&").trim().let { tdVc230 -> if (tdVc230.length > 6000) tdVc230.take(30000) + "…(dipotong, sisa " + (tdVc230.length - 30000) + " char; jalur lampiran: fallback teks 30000 char — bukan upload penuh)…" else tdVc230 }
                } catch (e: Exception) { "" }
                runOnUiThread { showTab("Chat"); if (textDoc.isNotBlank()) onUserMessage("Baca file terlampir '" + name + "' ini (ekstrak teks fallback; jalur lampiran: fallback teks 30000 char — bukan upload penuh). " + (if (question.isNotBlank()) "Pertanyaanku: $question" else "Ringkas isinya dan tunjukkan hal penting di dalamnya.") + "\n\nISI FILE:\n" + textDoc) else addBubble("📎 File '" + name + "' gagal diparsing server dan ekstrak teks fallback juga gagal.", false) }
            } else {
                val rawTextVc230 = String(cacheF.readBytes(), Charsets.UTF_8)
                val text = if (rawTextVc230.length > 30000) rawTextVc230.take(30000) + "…(dipotong, sisa " + (rawTextVc230.length - 30000) + " char; jalur lampiran: fallback teks 30000 char — bukan upload penuh)…" else rawTextVc230
                runOnUiThread { showTab("Chat"); onUserMessage("Baca file terlampir '" + name + "' ini (jalur lampiran: fallback teks 30000 char — bukan upload penuh). " + (if (question.isNotBlank()) "Pertanyaanku: $question" else "Ringkas isinya dan tunjukkan hal penting di dalamnya.") + "\n\nISI FILE:\n" + text) }
            }
        } catch (e: Exception) {
            runOnUiThread { addBubble("⚠️ Fallback dokumen '" + name + "' gagal: ${e.message}", false) }
        }
    }
    private fun analyzeFramesCombinedVc212(frames: List<String>, name: String, question: String, idx: Int = 0, acc: ArrayList<String> = ArrayList()) {
        if (idx >= frames.size) {
            val combined = frames.indices.joinToString("\n\n") { i -> "Frame " + (i + 1) + ":\n" + (acc.getOrNull(i) ?: "GAGAL") }
            runOnUiThread { sendContinuation("Hasil analisa video '" + name + "' (3 frame digabung):\n" + combined + "\n\nGabungkan ketiga frame di atas jadi satu ringkasan kronologis video ini, sesuai pertanyaan user: " + question) }
            return
        }
        Thread {
            try {
                val bmp = android.graphics.BitmapFactory.decodeFile(frames[idx]) ?: throw Exception("Frame tidak terbaca: " + frames[idx])
                val scale = 1280.0 / maxOf(bmp.width, bmp.height)
                val small = if (scale < 1.0) android.graphics.Bitmap.createScaledBitmap(bmp, (bmp.width * scale).toInt(), (bmp.height * scale).toInt(), true) else bmp
                val bos = java.io.ByteArrayOutputStream()
                small.compress(android.graphics.Bitmap.CompressFormat.JPEG, 80, bos)
                val jpegBytes = bos.toByteArray()
                // B13: klien DeepSeek bisa belum ada (startup openai).
                val dsClientVc212 = apiClient ?: if (ensureDsClients()) apiClient else null
                if (dsClientVc212 == null) {
                    acc.add("GAGAL: engine DeepSeek belum siap (otak = Models API)")
                    analyzeFramesCombinedVc212(frames, name, question, idx + 1, acc)
                } else dsClientVc212.uploadFileAndAsk(jpegBytes, "frame.jpg", "image/jpeg", "Jelaskan adegan pada frame video ini secara singkat.", false, { answer ->
                    acc.add(answer)
                    analyzeFramesCombinedVc212(frames, name, question, idx + 1, acc)
                }, { err ->
                    acc.add("GAGAL: $err")
                    analyzeFramesCombinedVc212(frames, name, question, idx + 1, acc)
                })
            } catch (e: Exception) {
                acc.add("GAGAL: ${e.message}")
                analyzeFramesCombinedVc212(frames, name, question, idx + 1, acc)
            }
        }.start()
    }

    // vc241 O4: pemicu memori untuk penundaan blok graph + semantik.
    // Daftar eksplisit: kata ingatan/riwayat/keputusan, kata ganti diri +
    // kata milik, serta penyebutan kunci fakta atau judul goal yang aktif.
    // Bila TIDAK memicu, blok graph + semantik ditunda ke giliran
    // berikutnya yang memicu (bukan dihapus permanen). Daftar sengaja
    // luas: salah-memicu hanya mengirim blok seperti biasa (aman),
    // sementara salah-tunda melemahkan jawaban ingatan.
    private fun memoryTriggerVc241(text: String, mdb: MemoryDb): Boolean {
        val low = text.lowercase()
        val wordsVc241 = listOf("ingat", "pernah", "riwayat", "keputusan", "memutuskan", "putuskan", "diputuskan", "dulu", "sebelumnya", "lupa", "kenangan", "catatan", "janji", "rencana", "target", "tujuan", "goal", "preferensi", "kebiasaan", "nama", "tentang saya", "tentang aku", "siapa saya", "siapa aku", "profil saya", "data saya", "fakta", "memori", "otak", "masih ingat", "sudah pernah", "waktu itu", "kemarin", "minggu lalu", "bulan lalu", "tahun lalu", "nomor", "alamat", "tanggal lahir", "ulang tahun", "jadwal", "rutinitas", "kesepakatan", "saya biasanya", "aku biasanya", "saya selalu", "aku selalu", "saya suka", "aku suka", "saya tidak suka", "aku tidak suka", "kamu tahu", "apakah kamu tahu", "ceritakan tentang")
        if (wordsVc241.any { low.contains(it) }) return true
        try {
            for (t in mdb.factsAllWithStatus()) {
                val k = t.first
                if (k.length >= 4 && low.contains(k.lowercase())) return true
            }
        } catch (e: Exception) {}
        try {
            for (g in mdb.goals(true)) {
                if (g.title.length >= 4 && low.contains(g.title.lowercase())) return true
            }
        } catch (e: Exception) {}
        return false
    }

    // vc241 O7: sinyal fakta di jendela ekstraksi — hanya baris User:
    // yang dipindai (baris asisten/sistem bukan fakta user). Tanpa satu
    // pun sinyal, panggilan LLM ekstraksi dilewati sama sekali.
    private fun extractHasFactSignalVc241(hist: String): Boolean {
        if (hist.isBlank()) return false
        val signalsVc241 = listOf("nama", "panggil", "suka", "benci", "preferensi", "biasa", "selalu", "setiap", "rutin", "jadwal", "keputusan", "putus", "rencana", "target", "goal", "cita", "ingat", "lupa", "jangan", "aturan", "alamat", "nomor", "telepon", "tinggal", "kerja", "kantor", "toko", "anak", "istri", "suami", "keluarga", "teman", "gaji", "utang", "tabung", "nabung", "sakit", "dokter", "obat", "kota", "desa", "punya", "milik", "beli", "jual", "langganan", "hobi", "senang", "kesal", "takut", "harap", "ingin", "mau", "butuh", "perlu", "lahir", "umur", "sekolah", "kuliah", "rumah", "motor", "mobil", "bank", "rekening", "sholat", "puasa", "masak", "makan", "minum", "kopi", "bonus", "cicil", "kredit", "pacar", "mantan")
        for (ln in hist.lines()) {
            if (!ln.startsWith("User:")) continue
            val low = ln.lowercase()
            if (signalsVc241.any { low.contains(it) }) return true
        }
        return false
    }

    // VC303-P2-8 (CX-1): alasan abnormal giliran ini — SATU sumber
    // kebenaran untuk flush (onUserMessage) dan tawaran lanjut (CX-9).
    // null = giliran normal.
    private fun abnormalStopReasonVc303(): String? = when {
        turnStuckBlocked -> "kunci-putaran"
        capStopSentVc277 -> "anggaran-langkah"
        turnStoppedReason != null -> turnStoppedReason
        else -> null
    }

    // VC303-P2-8 (CX-1): flush WorkNotes yang tidak malas — diekstrak dari
    // blok onUserMessage vc301 (appendTurnNotes + saveTurnStatus lalu
    // turnWork.clear()). Idempotent: turnWork kosong = no-op (tanpa
    // menyentuh status), jadi aman dipanggil dari beberapa titik akhir
    // giliran (onUserMessage berikut, switchSession, endUserTurn,
    // clearTurnCheckpoint) tanpa baris ganda. Semantik baris vc301 tidak
    // berubah — hanya titik panggil (plus CX-6/7 di WorkNotesVc301.kt).
    private fun flushTurnWork(sessionId: Long) {
        try {
            val items = synchronized(turnWork) { turnWork.toList() }
            if (items.isEmpty()) return
            WorkNotesVc301.appendTurnNotes(this, sessionId, items, ::redactSecrets)
            WorkNotesVc301.saveTurnStatus(this, sessionId, abnormalStopReasonVc303(), lastUserText, items, planItems.toList())
            turnWork.clear()
        } catch (e: Exception) {}
    }

    // VC303-P2-14 (CX-9): tawaran "Lanjutkan tugas" — SEKALI per giliran.
    // Dipilih opsi TOMBOL (dialog, pola dialog +10 langkah vc301 SF-C5)
    // ketimbang satu giliran lanjutan otomatis: user yang memutuskan,
    // tanpa giliran siluman yang membakar cap langkah. Syarat: giliran
    // berakhir abnormal + masih ada item rencana ☐ terbuka + app di
    // depan (dialog butuh activity aktif; bila app tidak di depan,
    // tawaran dilewati — status "lanjut" tetap tersimpan oleh flush,
    // user bisa lanjut manual di giliran berikut). Ketuk "Lanjutkan" =
    // satu giliran baru via onUserMessage dengan teks lanjutan
    // deterministik (prompt = WorkNotes + status + plan sudah ditempel
    // otomatis di awal giliran: MainActivity 1-1 awal + RENCANA AKTIF).
    // Gate vc247 / cap langkah / claim-check TIDAK diubah.
    private var resumeOfferShownVc303 = false
    private fun offerResumeVc303() {
        try {
            if (resumeOfferShownVc303) return
            // vc304 B2: tawaran lanjut HANYA di sesi pemilik giliran yang
            // berhenti — jangan muncul di sesi lain. Flag TIDAK dikonsumsi
            // supaya tawaran bisa muncul lagi di akhir giliran berikut di
            // sesi pemilik.
            if (!SessionBackgroundVc304.renderAllowed(turnSessionId, currentSessionId)) return
            if (abnormalStopReasonVc303() == null) return
            if (planItems.none { it.startsWith("☐") }) return
            if (!activityResumed) return
            resumeOfferShownVc303 = true
            val openFirst = planItems.firstOrNull { it.startsWith("☐") } ?: return
            runOnUiThread {
                try {
                    // vc304 B2: dilacak agar switchSession bisa menutupnya
                    // bila user pindah sesi selagi dialog tampil.
                    resumeDialogVc304 = AlertDialog.Builder(this)
                        .setTitle("Lanjutkan tugas?")
                        .setMessage("Giliran berhenti (${abnormalStopReasonVc303()}) padahal masih ada langkah rencana terbuka. Langkah berikut: $openFirst")
                        .setPositiveButton("Lanjutkan tugas") { _, _ ->
                            resumeDialogVc304 = null
                            onUserMessage("Lanjutkan tugas yang tertunda: kerjakan langkah rencana ☐ yang masih terbuka dari STATUS GILIRAN TERAKHIR di atas; jangan mulai ulang dari langkah pertama.")
                        }
                        .setNegativeButton("Nanti saja") { _, _ -> resumeDialogVc304 = null }
                        .show()
                } catch (e: Exception) {}
            }
        } catch (e: Exception) {}
    }

    // vc304 B1: muat budget langkah giliran dari pref — SATU-SATUNYA tempat
    // baca maxToolSteps untuk giliran baru (onUserMessage + maybeResumeTurn).
    // Nilai & coercion sama persis seperti inline lama di onUserMessage
    // (default 50, coerce 5..200, plafon 200 sejak vc299). Sebelum vc304,
    // resume tidak memuat ulang: sesudah app mati/proses dibunuh, field
    // kembali ke init (stepBudget 10) → giliran resume kehabisan budget
    // di 10 lalu +10 sekali = 20, walau pref maxToolSteps 200.
    private fun loadStepBudgetVc304() {
        stepBudget = getSharedPreferences("harness", MODE_PRIVATE).getInt("maxToolSteps", 50).coerceIn(5, 200)
    }

    private fun onUserMessage(text: String) {
        try { ApprovalFloat.hide(applicationContext) } catch (e: Exception) {}
        if (handleCameraCommand(text)) return
        // F4 (v4.38.0): perintah lokal otak kedua — dijawab tanpa LLM.
        if (handleOtakKeduaCommand(text)) return
        // vc203 T1: DEBAT: hanya di room multi — ditolak tanpa LLM.
        if (debateQuestion(text) != null) { addBubble(text, true); addBubble("⚖️ Debat parlemen hanya di room multi (butuh 5 slot) — pesan DEBAT: tidak diproses di chat 1-1.", false); return }
        if (turnActive && !drainingFollow) { enqueueFollowUp(text); return }
        turnActive = true
        userTurnActive = true
        // vc306 Worker B: giliran baru = stop lama hangus; composer pindah
        // ke state berjalan (hint "Membuat…", tombol ■, pill otomasi ke strip).
        stopRequestedVc306 = false
        refreshComposerButtonsVc306()
        val prevTurnSessionVc234 = turnSessionId // vc234 K3: sesi giliran lama, dibaca SEBELUM turnSessionId ditimpa sesi baru
        turnSessionId = currentSessionId
        emitPhase("think")
        refreshLiveCard()
        autoContinueCount = 0
        malformedRetry = 0
        gateRetryVc249 = 0
        refusalRetryVc251 = 0
        turnSlotVc249 = -1
        pendingAskVc229 = null
        addBubble(text, true)
        requestStartMs = System.currentTimeMillis()
        agentSteps = 0
        rejectRetryCount = 0
        // v4.48.5 (P3): digest bukti giliran sebelumnya — dihitung SEBELUM turnWork.clear().
        // Cap eksplisit — jalur PoW tanpa limit token: maks 5 langkah terbaru, evidence 300 char/langkah, total 2000 char.
        // vc234 K3: digest hanya berlaku untuk sesi yang sama. Bila giliran
        // lama berasal dari sesi lain, digest DIBUANG (tidak tampil di prompt
        // sesi baru tanpa label) — turnWork tetap dibersihkan seperti biasa.
        prevTurnEvidence = synchronized(turnWork) { digestEvidence(turnWork.toList()) }
        prevTurnEvidenceTs = System.currentTimeMillis()
        prevTurnEvidenceSessionId = prevTurnSessionVc234
        if (prevTurnSessionVc234 != currentSessionId) {
            prevTurnEvidence = ""
            prevTurnEvidenceTs = 0
            prevTurnEvidenceSessionId = -1
        }
        // vc286 Fase 1: simpan resultId giliran lama SEBELUM turnWork.clear()
        // — cermin pola prevTurnEvidence di atas, tapi menyimpan ID (bukan
