        // guardMetaPostedVc228); ringkasan + semantik + suffix user masuk
        // guard dan total Monitor (lihat pass kedua + situs dispatch di bawah).
        var guardMetaPostedVc228 = false
        val histBeforeVc212 = run { val hs = prompt.indexOf(H_RIWAYAT); if (hs < 0) "" else { val cs = hs + H_RIWAYAT.length; var ce = prompt.length; for (h in PROMPT_HEADERS) { if (h == H_RIWAYAT) continue; val n = prompt.indexOf(h, cs); if (n >= 0 && n < ce) ce = n }; prompt.substring(cs, ce) } }
        run {
            val cap = TurnMetrics.promptCap(this)
            if (prompt.length > cap) {
                val (guarded, trimmed) = guardInitialPrompt(prompt, cap)
                prompt = guarded
                TurnMetrics.recordGuardTrim(trimmed)
                if (trimmed > 0 && !guardMetaPostedVc228) {
                    guardMetaPostedVc228 = true
                    try { addMsg("⚠️ Guard prompt memangkas riwayat percakapan (sekali per episode guard): sebagian riwayat lama dibuang agar prompt muat di cap — ringkasan riwayat lama dibuat terpisah bila potongannya cukup besar; jawaban giliran ini memakai riwayat yang tersisa.", "meta", turn = true) } catch (e: Exception) {}
                }
            }
            val sysLen = AgentPrompt.buildSystemPrompt(this, true, text).length
            val catLen = AgentPrompt.catalogForTask(this, text).length
            TurnMetrics.recordPrompt(initialLayersVc238(prompt, sysLen, catLen, prompt.length, 0))
            TurnMetrics.recordPromptTotal(prompt.length)
            TurnMetrics.recordExtra(AgentPrompt.personaLength(this), planItems.joinToString("\n").length, 0)
        }
        run {
            val summ = try { getSharedPreferences("harness", MODE_PRIVATE).getString("histSummary_" + currentSessionId, "") ?: "" } catch (e: Exception) { "" }
            if (summ.isNotBlank()) {
                val marker = H_RINGKASAN
                val hi = prompt.indexOf(H_RIWAYAT)
                prompt = if (hi >= 0) prompt.substring(0, hi) + marker + summ + "\n\n" + prompt.substring(hi) else prompt + "\n\n" + marker + summ
                try { addMsg("🧠 Ringkasan riwayat lama disisipkan ke prompt giliran ini — RINGKASAN BUATAN MODEL (belum terverifikasi — angka/nama di sini bisa salah; minta user mengonfirmasi bila dipakai untuk tindakan).", "meta", turn = true) } catch (e: Exception) {}
            }
        }
        var historyNotSummarizedVc228 = false
        run {
            val histAfterVc212 = run { val hs = prompt.indexOf(H_RIWAYAT); if (hs < 0) "" else { val cs = hs + H_RIWAYAT.length; var ce = prompt.length; for (h in PROMPT_HEADERS) { if (h == H_RIWAYAT) continue; val n = prompt.indexOf(h, cs); if (n >= 0 && n < ce) ce = n }; prompt.substring(cs, ce) } }
            if (histBeforeVc212.isNotBlank() && histAfterVc212.length < histBeforeVc212.length) {
                val droppedVc212 = histBeforeVc212.substring(0, (histBeforeVc212.length - histAfterVc212.length).coerceAtLeast(0))
                val hashVc228 = sha256Hex(droppedVc212)
                val oldHashVc228 = try { getSharedPreferences("harness", MODE_PRIVATE).getString("histSummaryHash_" + currentSessionId, "") ?: "" } catch (e: Exception) { "" }
                if (droppedVc212.isNotBlank() && hashVc228 != oldHashVc228) historyNotSummarizedVc228 = true
                if (droppedVc212.isNotBlank()) {
                    Thread {
                        try {
                            val prefsS = getSharedPreferences("harness", MODE_PRIVATE)
                            val hashVc212 = hashVc228
                            if (prefsS.getString("histSummaryHash_" + currentSessionId, "") != hashVc212) {
                                val summNew = try { BgBrain.summarizeOldHistory(this, droppedVc212) } catch (e: Exception) { null }
                                if (!summNew.isNullOrBlank()) {
                                    val old = prefsS.getString("histSummary_" + currentSessionId, "") ?: ""
                                    var combined = if (old.isBlank()) summNew else old + "\n" + summNew
                                    if (combined.length > 3000) combined = combined.takeLast(3000)
                                    prefsS.edit().putString("histSummary_" + currentSessionId, combined).putString("histSummaryHash_" + currentSessionId, hashVc212).apply()
                                    try { runOnUiThread { try { addMsg("🧠 Ringkasan riwayat lama dibuat dari potongan yang dipangkas guard (belum terverifikasi — angka/nama di sini bisa salah) — berlaku mulai giliran berikut.", "meta", turn = true) } catch (e: Exception) {} } } catch (e: Exception) {}
                                } else {
                                    // B11/D2 (Fase 1): meta jujur sekali per sesi bila
                                    // ringkasan gagal dibuat (provider gagal / kuota
                                    // habis) — konteks lama yang terpotong guard
                                    // tidak tersimpan.
                                    val failMetaKeyVc212 = "histSummaryFailMeta_" + currentSessionId
                                    if (!prefsS.getBoolean(failMetaKeyVc212, false)) {
                                        prefsS.edit().putBoolean(failMetaKeyVc212, true).apply()
                                        try { runOnUiThread { try { addMsg("🧠 Ringkasan riwayat lama tidak dibuat (provider gagal / kuota habis) — konteks lama yang terpotong guard tidak tersimpan.", "meta", turn = true) } catch (e: Exception) {} } } catch (e: Exception) {}
                                    }
                                }
                            }
                        } catch (e: Exception) {}
                    }.start()
                }
            }
        }
        if (historyNotSummarizedVc228) {
            prompt += "\n\n[SISTEM: riwayat lama belum diringkas — jawaban giliran ini belum memakai konteks lama. Jangan mengarang isi riwayat lama; bila user bertanya soal itu, katakan konteks lamanya belum tersedia di giliran ini.]\n"
            try { addMsg("⚠️ Riwayat lama belum diringkas — jawaban giliran ini belum memakai konteks lama (ringkasan dibuat di latar untuk giliran berikut).", "meta", turn = true) } catch (e: Exception) {}
        }
        run {
            val cap = TurnMetrics.promptCap(this)
            if (prompt.length > cap) {
                val (guarded2, trimmed2) = guardInitialPrompt(prompt, cap)
                prompt = guarded2
                TurnMetrics.recordGuardTrim(trimmed2)
                if (trimmed2 > 0 && !guardMetaPostedVc228) {
                    guardMetaPostedVc228 = true
                    try { addMsg("⚠️ Guard prompt memangkas riwayat percakapan (sekali per episode guard): sebagian riwayat lama dibuang agar prompt muat di cap.", "meta", turn = true) } catch (e: Exception) {}
                }
                // vc238 M15(c): fail-open kini BERBUNYI, bukan diam. Bila
                // prompt masih di atas cap sesudah guard pass kedua, itu
                // artinya prompt sistem saja sudah melebihi cap dan guard
                // tidak bisa memangkasnya — kirim satu bubble meta
                // peringatan di giliran ini (blok guard kedua hanya jalan
                // sekali per giliran, jadi bubble ini pun sekali).
                if (prompt.length > cap) {
                    try { addMsg("⚠️ Guard prompt gagal-terbuka: prompt sistem saja sudah melebihi cap " + cap + " char, jadi prompt giliran ini dikirim utuh tanpa pemangkasan — kurangi persona atau skill aktif bila ini sering muncul.", "meta", turn = true) } catch (e: Exception) {}
                }
            }
            val sysLen = AgentPrompt.buildSystemPrompt(this, true, text).length
            val catLen = AgentPrompt.catalogForTask(this, text).length
            TurnMetrics.recordPrompt(initialLayersVc238(prompt, sysLen, catLen, prompt.length, 0))
            TurnMetrics.recordPromptTotal(prompt.length)
            TurnMetrics.recordExtra(AgentPrompt.personaLength(this), planItems.joinToString("\n").length, 0)
        }
        if (Embedder.packDownloaded(this)) {
            val basePrompt = prompt
            if (!memTriggerVc241) {
                TurnMetrics.recordPromptTotal(basePrompt.length + 6 + agentText.length)
                dispatchTurn(basePrompt, agentText)
            } else Thread {
                // vc240 M6 + M16: semantik kosong -> fallback kata kunci
                // berlabel (kebijakan sama dengan jalur manual dan
                // recall_search); semantik difilter dari cuplikan riwayat
                // sesi ini dan dari baris yang duplikat kunci fakta.
                val mdbVc240 = MemoryDb.get(this)
                val factKeysVc240 = try { mdbVc240.factsAllWithStatus().map { it.first }.filter { it.length >= 3 } } catch (e: Exception) { emptyList() }
                val vecVc240 = try { Embedder.embedQuery(this, text) } catch (e: Exception) { null }
                var hitsVc240 = ""
                var jalurVc240 = ""
                if (vecVc240 != null) {
                    hitsVc240 = try { RedactSecrets.redact(mdbVc240.semanticSearchVc240(vecVc240, 5, 0.30, currentSessionId, factKeysVc240)) } catch (e: Exception) { "" }
                    jalurVc240 = "semantik"
                }
                if (hitsVc240.isBlank()) {
                    val kwVc240 = try { RedactSecrets.redact(mdbVc240.searchMemory(text, 5)) } catch (e: Exception) { "" }
                    if (kwVc240.isNotBlank() && !kwVc240.startsWith("Tidak ada memori") && !kwVc240.startsWith("Kata kunci")) {
                        hitsVc240 = kwVc240
                        jalurVc240 = if (vecVc240 == null) "kata kunci (embed query gagal — fallback semantik kosong)" else "kata kunci (fallback semantik kosong)"
                    }
                }
                runOnUiThread {
                    var hitLinesVc240 = if (hitsVc240.isNotBlank()) hitsVc240.lines().filter { it.isNotBlank() } else emptyList()
                    // vc241 O2: buang baris semantik yang isinya sudah ada verbatim di prompt awal (MEMORY.md/fakta/graph/riwayat).
                    hitLinesVc240 = hitLinesVc240.filter { ln -> val c = ln.substringAfter(" — ", ln).trim(); c.length < 20 || !basePrompt.lowercase().contains(c.lowercase()) }
                    val headerVc240 = if (hitLinesVc240.isNotEmpty()) "KONTEKS RELEVAN DARI MEMORI JANGKA PANJANG (jalur: $jalurVc240 — gunakan bila relevan, jangan diumumkan sebagai hasil pencarian):\n" else ""
                    var extra = if (hitLinesVc240.isNotEmpty()) headerVc240 + hitLinesVc240.joinToString("\n") + "\n\n" else ""
                    val suffixLenVc228 = 6 + agentText.length
                    val capVc228 = TurnMetrics.promptCap(this)
                    // vc240 M19: potong extra per baris dari yang paling
                    // tidak relevan (baris terakhir = skor terendah, karena
                    // urutan skor menurun) sampai muat, bukan buang semua.
                    while (basePrompt.length + extra.length + suffixLenVc228 > capVc228 && hitLinesVc240.isNotEmpty()) {
                        hitLinesVc240 = hitLinesVc240.dropLast(1)
                        extra = if (hitLinesVc240.isNotEmpty()) headerVc240 + hitLinesVc240.joinToString("\n") + "\n\n" else ""
                    }
                    if (hitLinesVc240.isEmpty() && hitsVc240.isNotBlank()) {
                        val markerVc240 = "KONTEKS SEMANTIK DILEWATI KARENA CAP (hasil semantik/kata kunci ada tapi tidak muat).\n\n"
                        extra = if (basePrompt.length + markerVc240.length + suffixLenVc228 <= capVc228) markerVc240 else ""
                    }
                    val sysLenVc238 = AgentPrompt.buildSystemPrompt(this, true, text).length
                    val catLenVc238 = AgentPrompt.catalogForTask(this, text).length
                    TurnMetrics.recordPrompt(initialLayersVc238(basePrompt + extra, sysLenVc238, catLenVc238, basePrompt.length + extra.length + suffixLenVc228, extra.length))
                    TurnMetrics.recordPromptTotal(basePrompt.length + extra.length + suffixLenVc228)
                    dispatchTurn(basePrompt + extra, agentText)
                }
            }.start()
        } else {
            // vc240 M6: tanpa paket embedding tidak ada semantik yang
            // bisa kosong — fallback kata kunci langsung di sini (query DB
            // ringan, seperti factsText di atas) dengan label jalur dan
            // potong per baris yang sama seperti cabang semantik.
            var extraVc240 = ""
            if (memTriggerVc241) run {
                val kw = try { RedactSecrets.redact(MemoryDb.get(this).searchMemory(text, 5)) } catch (e: Exception) { "" }
                if (kw.isNotBlank() && !kw.startsWith("Tidak ada memori") && !kw.startsWith("Kata kunci")) {
                    var linesVc240 = kw.lines().filter { it.isNotBlank() }
                    // vc241 O2: sama seperti cabang semantik — buang baris yang sudah ada verbatim di prompt awal.
                    linesVc240 = linesVc240.filter { ln -> val c = ln.substringAfter(" — ", ln).trim(); c.length < 20 || !prompt.lowercase().contains(c.lowercase()) }
                    val hdrVc240 = "KONTEKS RELEVAN DARI MEMORI JANGKA PANJANG (jalur: kata kunci — paket embedding belum diunduh):\n"
                    var ex = hdrVc240 + linesVc240.joinToString("\n") + "\n\n"
                    val suffixLenVc240 = 6 + agentText.length
                    val capVc240 = TurnMetrics.promptCap(this)
                    while (prompt.length + ex.length + suffixLenVc240 > capVc240 && linesVc240.isNotEmpty()) { linesVc240 = linesVc240.dropLast(1); ex = if (linesVc240.isNotEmpty()) hdrVc240 + linesVc240.joinToString("\n") + "\n\n" else "" }
                    extraVc240 = ex
                }
            }
            val sysLenVc238 = AgentPrompt.buildSystemPrompt(this, true, text).length
            val catLenVc238 = AgentPrompt.catalogForTask(this, text).length
            TurnMetrics.recordPrompt(initialLayersVc238(prompt + extraVc240, sysLenVc238, catLenVc238, prompt.length + extraVc240.length + 6 + agentText.length, extraVc240.length))
            TurnMetrics.recordPromptTotal(prompt.length + extraVc240.length + 6 + agentText.length)
            dispatchTurn(prompt + extraVc240, agentText)
        }
    }

    private fun showSessionDialog() {
        val th = currentTheme()
        val mdb = MemoryDb.get(this)
        val all = mdb.sessions().sortedByDescending { it.id }
        val sessions = all.filter { it.pinned } + all.filter { !it.pinned }
        val content = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        val active = try { Agents.active(this) } catch (e: Exception) { null }
        val apiOn = getSharedPreferences("harness", MODE_PRIVATE).getBoolean("apiMode", true)
        val info = cardBoxT()
        info.addView(tv("INFO CHAT", 12f, th.dim, true))
        info.addView(tv("Sesi aktif: " + mdb.sessionTitle(currentSessionId), 13f, th.text, true))
        info.addView(tv("Pesan di sesi ini: " + (try { mdb.historyCount(currentSessionId) } catch (e: Exception) { 0 }), 12.5f, th.text))
        info.addView(tv("Agen: " + (active?.name ?: "?") + " • Mesin: " + (active?.engine ?: "?") + " • Mode: " + (if (apiOn) "API Internal" else "WebView"), 12.5f, th.text))
        content.addView(info)
        var dlgRef: android.app.AlertDialog? = null
        content.addView(thBtn("＋ Sesi Baru") { dlgRef?.dismiss(); uiSessionNew() }.apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) })
        for (s in sessions) {
            val cnt = try { mdb.historyCount(s.id) } catch (e: Exception) { 0 }
            val rowB = LinearLayout(this).apply {
                orientation = LinearLayout.VERTICAL
                background = roundedS(th.bg, 14, th.stroke)
                setPadding(dp(12), dp(10), dp(12), dp(10))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { setMargins(0, dp(4), 0, dp(4)) }
            }
            rowB.addView(tv((if (s.pinned) "📌 " else "") + (if (s.id == currentSessionId) "● " else "○ ") + s.title, 13.5f, th.text, true))
            rowB.addView(tv(cnt.toString() + " pesan", 11.5f, th.dim))
            val btns = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(6), 0, 0) }
            if (s.id != currentSessionId) btns.addView(thSmallBtn("Buka") { dlgRef?.dismiss(); uiSessionSwitch(s.id) })
            btns.addView(thSmallBtn("✏️ Nama") { dlgRef?.dismiss(); inputDialog("Ganti Nama Sesi", "judul sesi", s.title) { v -> if (v.isNotBlank()) { uiSessionRename(s.id, v); android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({ showSessionDialog() }, 350) } } })
            btns.addView(thSmallBtn(if (s.pinned) "Lepas Pin" else "📌 Pin") { dlgRef?.dismiss(); uiSessionPin(s.id, !s.pinned); android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({ showSessionDialog() }, 350) } )
            btns.addView(thSmallBtn("🗑") {
                dlgRef?.dismiss()
                val msg = TextView(this).apply { text = "\"" + s.title + "\" beserta seluruh isinya akan dihapus permanen. Memori jangka panjang tidak ikut terhapus."; textSize = 14f; setTextColor(th.text) }
                thDialog("Hapus sesi?", msg, listOf(
                    Triple("Hapus", false) { d: android.app.AlertDialog ->
                        val target = mdb.deleteSession(s.id)
                        if (s.id == currentSessionId) switchSession(target)
                        d.dismiss()
                        android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({ showSessionDialog() }, 350)
                    },
                    Triple("Batal", false) { d: android.app.AlertDialog -> d.dismiss() }
                ), danger = setOf("Hapus"))
            })
            rowB.addView(btns)
            content.addView(rowB)
        }
        dlgRef = thDialog("🗂 Sesi Percakapan", content, listOf(Triple("Tutup", false) { d: android.app.AlertDialog -> d.dismiss() }))
    }

    private fun confirmDeleteSession() {
        val title = MemoryDb.get(this).sessionTitle(currentSessionId)
        AlertDialog.Builder(this)
            .setTitle("Hapus sesi ini?")
            .setMessage("Sesi \"$title\" beserta SELURUH isi percakapannya akan dihapus permanen. Fakta memori jangka panjang tidak ikut terhapus.")
            .setPositiveButton("Hapus") { _, _ -> doDeleteCurrentSession() }
            .setNegativeButton("Batal", null)
            .show()
    }

    /** Hapus sesi aktif + isi chat-nya, lalu pindah ke sesi tersisa. Return ringkasan hasil. */
    private fun doDeleteCurrentSession(): String {
        val mdb = MemoryDb.get(this)
        val deletedId = currentSessionId
        val oldTitle = mdb.sessionTitle(deletedId)
        val target = mdb.deleteSession(deletedId)
        switchSession(target)
        val msg = if (target == deletedId)
            "Sesi \"$oldTitle\" adalah satu-satunya sesi, jadi isinya dikosongkan dan judulnya direset ke \"Utama\" (sesi terakhir tidak bisa dihapus total)."
        else
            "Sesi \"$oldTitle\" beserta seluruh isinya sudah dihapus. Sekarang kamu berada di sesi \"${mdb.sessionTitle(target)}\"."
        addBubble("🗑️ $msg", false)
        return msg
    }

    private fun switchSession(id: Long) {
        // VC303-P2-8 (CX-1): flush dulu SEBELUM turnWork.clear() di bawah
        // — pindah sesi tidak lagi membuang catatan kerja giliran lama.
        flushTurnWork(currentSessionId)
        // vc226: sesi lama berakhir -> approval pending-nya kedaluwarsa.
        if (id != currentSessionId) {
            // vc229 R-04(f): pindah sesi mengkedaluwarsakan approval pending
            // DAN mandat chat sesi lama (tidak hidup kembali saat sesi lama dibuka lagi).
            try { ApprovalPanelStore.expireSession(this, currentSessionId); ApprovalPanelStore.expireMandatesForSession(this, currentSessionId) } catch (e: Exception) {}
            // vc246 GELOMBANG 5 (UI-m4): batalkan dialog persetujuan yang
            // sedang tampil + popup melayang agar tidak dieksekusi di
            // bawah sesi baru.
            try { activeToolDialogVc246?.dismiss() } catch (e: Exception) {}
            // vc304 B2: dialog persetujuan yang sedang tampil ikut parkir —
            // keputusannya menunggu user kembali ke sesi pemilik (bukan
            // hilang bersama dialog). approvalParkedVc304 diset saat dialog
            // dibuat di proceedTool dan dibersihkan saat user memutuskan.
            activeToolDialogVc246 = null
            // vc304 B2: dialog +10 yang sedang tampil ikut parkir; tawarannya
            // ditawarkan ulang saat user kembali ke sesi pemilik (di bawah).
            try { extendDialogVc304?.dismiss() } catch (e: Exception) {}
            if (extendDialogVc304 != null) extendOfferPendingVc304 = true
            extendDialogVc304 = null
            // vc304 B2: dialog tawaran-lanjut juga ditutup; tawarannya boleh
            // muncul lagi di akhir giliran berikut di sesi pemilik.
            try { resumeDialogVc304?.dismiss() } catch (e: Exception) {}
            if (resumeDialogVc304 != null) resumeOfferShownVc303 = false
            resumeDialogVc304 = null
            try { ApprovalFloat.hide(this) } catch (e: Exception) {}
        }
        currentSessionId = id
        getSharedPreferences("harness", MODE_PRIVATE).edit().putLong("currentSession", id).apply()
        if (::sessionTitleTv.isInitialized) sessionTitleTv.text = "🗂️ " + MemoryDb.get(this).sessionTitle(id)
        chatList.removeAllViews()
        synchronized(bubbleTexts) { bubbleTexts.clear() }
        // vc283: cap windowing kembali ke 150 tiap pindah sesi (kenaikan cap
        // karena "Muat …" hanya berlaku untuk sesi yang memuatnya).
        chatLiveCapVc283 = 150
        nativeHistSession = id
        // vc234 K3: pindah sesi membuang digest + sisa kerja giliran lama
        // agar tidak bocor ke sesi baru; giliran sesi baru mulai bersih.
        synchronized(turnWork) { turnWork.clear() }
        // vc302 Fix A: pindah sesi = giliran baru — reset guard baca-ulang.
        Tools.resetRereadGuardVc302()
        prevTurnEvidence = ""
        prevTurnEvidenceTs = 0
        prevTurnEvidenceSessionId = -1
        prevTurnResultIdsVc286.clear() // vc286: pindah sesi membuang jendela 2 giliran
        prevTurnResultIdsSessionVc286 = -1
        nativeOldestHistId = Long.MAX_VALUE
        Thread {
            val mdb = MemoryDb.get(this)
            val rows = mdb.historyRich(id, 80)
            val older = if (rows.isEmpty()) 0 else mdb.historyCountBefore(id, rows.first().id)
            // vc283: parse markdown 80 baris di thread latar (bukan UI thread).
            val pre = rows.map { r -> if (r.role == "asisten" || r.role == "assistant") precomputeAssistantRender(r.text) else null }
            runOnUiThread { renderHistRows(rows, older, false, pre) }
        }.start()
        // vc304 B2: kembali ke sesi pemilik giliran background — tawarkan
        // ulang keputusan yang diparkir (dialog +10 / approval tool).
        // Giliran TIDAK dihentikan saat pindah sesi; yang diparkir hanya
        // keputusannya. refreshLiveCard menampilkan progres sesi ini lagi.
        if (turnActive && turnSessionId == id) {
            if (extendOfferPendingVc304) {
                extendOfferPendingVc304 = false
                offerExtendStepsVc304()
            }
            val parkedApprovalVc304 = approvalParkedVc304
            approvalParkedVc304 = null
            if (parkedApprovalVc304 != null) proceedTool(parkedApprovalVc304.first, parkedApprovalVc304.second, true, parkedApprovalVc304.third)
        }
        refreshLiveCard()
    }






    // ===== T4b1 (migrasi native): Browser agen =====


    // ===== Perintah Cepat native (T5) =====

    private fun quickChipsList(): List<String> {
        val raw = getSharedPreferences("harness", MODE_PRIVATE).getString("quickChipsNative", null)
        if (raw != null) {
            try {
                val a = org.json.JSONArray(raw)
                val out = mutableListOf<String>()
                for (i in 0 until a.length()) { val v = a.optString(i); if (v.isNotBlank()) out.add(v) }
                if (out.isNotEmpty()) return out
            } catch (e: Exception) {}
        }
        return listOf("Cek status HP dan baterai", "Ringkasan aktivitas hari ini", "Apa tugas koordinator terakhir dan hasilnya?", "Ping Mode ADB")
    }

    private fun refreshQuickChips() {
        val row = quickChipsRow ?: return
        runOnUiThread {
            val th = currentTheme()
            row.removeAllViews()
            for (chip in quickChipsList()) {
                // vc309 Worker B: chip AKSI CEPAT vertikal, lebar penuh,
                // sentence case (isAllCaps=false — allCaps bawaan Button
                // memanjangkan "Cek status HP dan baterai" jadi
                // "CEK STATUS HP DAN BATERAI"), teks 13.5sp rata kiri,
                // maks 2 baris + ellipsize END sebagai pengaman terakhir
                // (label terpanjang membungkus dulu sebelum terpotong),
                // tinggi sentuh 48dp, warna ikut tema (dulu bg gelap
                // hardcoded + teks putih — bentrok di tema cerah).
