            // Aktivitas Terbaru: kartu putih, dot warna + waktu relatif
            box.addView(tv("Aktivitas Terbaru", 15f, th.text, true).apply { setPadding(0, dp(12), 0, dp(6)) })
            val act = LinearLayout(this).apply {
