    private fun showChatSearch() {
        val et = EditText(this).apply { hint = "Kata yang dicari di chat ini…" }
        android.app.AlertDialog.Builder(this).setTitle("🔍 Cari di Chat").setView(et)
            .setPositiveButton("Cari") { _, _ ->
                val q = et.text.toString().trim()
                if (q.isNotBlank()) {
                    val hits = synchronized(bubbleTexts) { bubbleTexts.filter { it.second.contains(q, ignoreCase = true) } }
                    if (hits.isEmpty()) {
                        android.widget.Toast.makeText(this, "Tidak ada hasil untuk \"$q\"", android.widget.Toast.LENGTH_SHORT).show()
                    } else {
                        val target = hits.last().first
                        chatScroll.post { chatScroll.scrollTo(0, maxOf(0, target.top - dp(40))) }
                        android.widget.Toast.makeText(this, hits.size.toString() + " hasil — melompat ke yang terbaru", android.widget.Toast.LENGTH_SHORT).show()
                    }
                }
            }
            .setNegativeButton("Batal", null).show()
    }

    /** Bila error bernuansa jaringan, coba jawab lokal (mode offline darurat). */
    private fun tryOfflineFallback(err: String, engineName: String): Boolean {
        val low = err.lowercase()
        val networkish = listOf("connect", "timeout", "unknown", "resolve", "ssl", "jaringan", "network", "unreachable")
            .any { low.contains(it) }
        if (!networkish) return false
        val t = lastUserText
        if (t.isBlank() || t.startsWith("Hasil tool") || t.startsWith("TUGAS LATAR") || t.startsWith("VERIFIKASI")) return false
        val local = LocalAgent.tryHandle(this, t) ?: return false
        addBubble("📴 Koneksi ke $engineName bermasalah — dijawab mode OFFLINE lokal:\n$local", false, turn = true)
        // vc304 B2: jawaban fallback offline milik giliran ini — simpan ke
        // histori sesi PEMILIK giliran (turnSessionId), bukan sesi aktif
        // saat ini (dulu: currentSessionId — bocor ke sesi lain bila
        // giliran jalan di background).
        try { MemoryDb.get(this).addHistory("asisten", local, turnSessionId) } catch (e: Exception) {}
        return true
    }

    /** Proses file dari tombol 📎 sesuai jenisnya: teks dibaca langsung, gambar/PDF/video/audio lewat vision Web. */
    private fun handleAttachment(uri: android.net.Uri, questionOverride: String? = null) {
        val question = questionOverride?.trim() ?: chatInput.text.toString().trim()
        Thread {
            try {
                val cr = contentResolver
                val mime = cr.getType(uri) ?: ""
                var name = "lampiran"
                cr.query(uri, arrayOf(android.provider.OpenableColumns.DISPLAY_NAME), null, null, null)?.use { c ->
                    if (c.moveToFirst()) name = c.getString(0) ?: name
                }
                val bytes = cr.openInputStream(uri)?.readBytes() ?: throw Exception("File tidak terbaca.")
                if (bytes.size > 12_000_000) throw Exception("File terlalu besar (${bytes.size / 1_000_000} MB > 12 MB).")
                val ext = name.substringAfterLast('.', "").lowercase()
                val cacheF = File(cacheDir, "attach-" + System.currentTimeMillis() + "." + ext.ifBlank { "bin" })
                cacheF.writeBytes(bytes)
                when {
                    mime.startsWith("image/") -> runOnUiThread {
                        showTab("Chat")
                        analyzePhotoAndContinue(JSONObject().put("path", cacheF.absolutePath)
                            .put("question", question.ifBlank { "Jelaskan isi gambar ini secara detail." }))
                    }
                    (mime == "application/pdf" || ext == "pdf" || mime == "application/vnd.openxmlformats-officedocument.wordprocessingml.document" || ext == "docx" || ext == "doc" || mime == "application/msword" || ext in listOf("txt", "md", "csv")) -> {
                        // vc212 Item 2: dokumen teks penuh lewat API; gagal -> fallback perilaku lama.
                        val qDoc = question
                        val useApiDoc = try { getSharedPreferences("harness", MODE_PRIVATE).getBoolean("apiMode", false) || operatorMode() } catch (e: Exception) { false }
                        runOnUiThread { showTab("Chat"); addBubble("📄 Dokumen '" + name + "' — mengunggah teks penuh lewat API internal… (status: mengunggah, menunggu parsing server…)", false) }
                        if (!useApiDoc) {
                            runOnUiThread { addBubble("📄 Dokumen '" + name + "' tidak lewat API (API Internal tidak aktif) — fallback ke perilaku lama.", false) }
                            fallbackDocVc212(cacheF, name, ext, qDoc)
                        } else {
                            val promptDoc = "Baca dokumen terlampir '" + name + "' SELURUHNYA. " + (if (qDoc.isNotBlank()) "Pertanyaan user: $qDoc" else "Ringkas isi dokumen ini secara lengkap dan tunjukkan hal penting di dalamnya.") + "\n\nJawab dalam Bahasa Indonesia."
                            // B13: klien DeepSeek bisa belum ada (startup openai).
                            val dsClientVc212 = apiClient ?: if (ensureDsClients()) apiClient else null
                            if (dsClientVc212 == null) {
                                runOnUiThread { addBubble("📄 Status parsing server: GAGAL (engine DeepSeek belum siap — otak = Models API) — fallback ke perilaku lama untuk '" + name + "'.", false) }
                                fallbackDocVc212(cacheF, name, ext, qDoc)
                            } else dsClientVc212.uploadFilesAndAsk(listOf(Triple(bytes, name, mime.ifBlank { mimeForNameVc212(name) })), promptDoc, false, { answer, _ ->
                                runOnUiThread { addBubble("📄 Status parsing server: SUCCESS — dokumen '" + name + "' dibaca penuh lewat API.", false); sendContinuation("Hasil baca dokumen '" + name + "' (teks penuh via API internal; jalur lampiran: upload penuh via API Internal):\n" + answer + "\n\nSampaikan hasil ini ke user dan lanjutkan tugasmu.") }
                            }, { err ->
                                runOnUiThread { addBubble("📄 Status parsing server: GAGAL (" + err + ") — fallback ke perilaku lama untuk '" + name + "'.", false) }
                                fallbackDocVc212(cacheF, name, ext, qDoc)
                            })
                        }
                    }
                    mime == "application/pdf" || ext == "pdf" -> {
                        val pfd = android.os.ParcelFileDescriptor.open(cacheF, android.os.ParcelFileDescriptor.MODE_READ_ONLY)
                        val renderer = android.graphics.pdf.PdfRenderer(pfd)
                        val pageCount = renderer.pageCount
                        val page = renderer.openPage(0)
                        val bmp = android.graphics.Bitmap.createBitmap(page.width, page.height, android.graphics.Bitmap.Config.ARGB_8888)
                        page.render(bmp, null, null, android.graphics.pdf.PdfRenderer.Page.RENDER_MODE_FOR_DISPLAY)
                        page.close(); renderer.close(); pfd.close()
                        val jpg = File(cacheDir, "pdf-page1-" + System.currentTimeMillis() + ".jpg")
                        java.io.FileOutputStream(jpg).use { bmp.compress(android.graphics.Bitmap.CompressFormat.JPEG, 85, it) }
                        runOnUiThread {
                            showTab("Chat")
                            addBubble("📄 PDF '$name' ($pageCount halaman) — menganalisa halaman 1 lewat vision…", false)
                            analyzePhotoAndContinue(JSONObject().put("path", jpg.absolutePath)
                                .put("question", (question.ifBlank { "Ringkas isi halaman PDF ini." }) + " (Ini halaman 1 dari $pageCount halaman PDF '$name'.)"))
                        }
                    }
                    mime.startsWith("text/") || ext in listOf("txt", "md", "json", "csv", "log", "xml", "html") -> {
                        val rawTextVc230 = String(bytes, Charsets.UTF_8)
                        val text = if (rawTextVc230.length > 30000) rawTextVc230.take(30000) + "…(dipotong, sisa " + (rawTextVc230.length - 30000) + " char; jalur lampiran: fallback teks 30000 char — bukan upload penuh)…" else rawTextVc230
                        runOnUiThread {
                            showTab("Chat")
                            onUserMessage("Baca file terlampir '$name' ini (jalur lampiran: fallback teks 30000 char — bukan upload penuh). " + (if (question.isNotBlank()) "Pertanyaanku: $question" else "Ringkas isinya dan tunjukkan hal penting di dalamnya.") + "\n\nISI FILE:\n$text")
                        }
                    }
                    mime.startsWith("video/") -> {
                        val res = Tools.execute(this, "transcribe_media", JSONObject().put("path", cacheF.absolutePath))
                        val framePaths = res.lines().filter { it.startsWith("Frame ") }.mapNotNull { it.substringAfter(":").trim().ifBlank { null } }
                        val framePath = framePaths.firstOrNull()
                        runOnUiThread {
                            showTab("Chat")
                            if (framePaths.size >= 2 && isVideo3FrameRequestVc212(question)) {
                                addBubble("🎬 Video '" + name + "' — mode 3 frame (awal, tengah, akhir) atas permintaan di konteks, menganalisa ketiganya lalu menggabungkan…\n" + res, false)
                                analyzeFramesCombinedVc212(framePaths, name, question.ifBlank { "Jelaskan isi video ini." })
                            } else if (framePath != null) {
                                addBubble("🎬 Video '" + name + "' — frame diekstrak, menganalisa visualnya…\n" + res, false)
                                analyzePhotoAndContinue(JSONObject().put("path", framePath)
                                    .put("question", question.ifBlank { "Jelaskan adegan pada frame video ini." }))
                            } else addBubble("🎬 $res", false)
                        }
                    }
                    mime.startsWith("audio/") -> {
                        val b64 = android.util.Base64.encodeToString(bytes, android.util.Base64.NO_WRAP)
                        runOnUiThread {
                            showTab("Web")
                            addBubble("🎵 Audio '" + name + "' — mengirim lewat Web untuk transkripsi…", false)
                            // B13: DsAgent bisa belum ada (startup openai) —
                            // ini jalan di main thread (runOnUiThread), jadi
                            // akses langsung di sini akan crash bila null.
                            val dsAgentVc212 = agent ?: if (ensureDsClients()) agent else null
                            if (dsAgentVc212 == null) {
                                endStreamBubble(); showTab("Chat")
                                addBubble("⚠️ Analisa audio lewat Web gagal: engine DeepSeek belum siap (otak = Models API)", false)
                            } else dsAgentVc212.attachFile(b64, name, mime, question.ifBlank { "Transkrip dan ringkas isi audio ini." }, { resp ->
                                endStreamBubble(); showTab("Chat")
                                addBubble("🎵 Audio '" + name + "' terkirim lewat Web — jawaban model di bawah.", false)
                                handleAgentResponse(resp)
                            }, { err ->
                                endStreamBubble(); showTab("Chat")
                                addBubble("⚠️ Analisa audio lewat Web gagal: $err", false)
                            })
                        }
                    }
                    else -> runOnUiThread {
                        addBubble("📎 File '$name' ($mime) belum didukung untuk dianalisa. Yang didukung: gambar, PDF, teks, video, audio.", false)
                    }
                }
            } catch (e: Exception) {
                runOnUiThread { addBubble("⚠️ Lampiran gagal diproses: ${e.message}", false) }
            }
        }.start()
    }

    /** v4.3.0 — Kelanjutan yang MEMBAWA KONTEKS (fix agen "tidak bisa pakai tool").
     *  Jalur API Internal membuka sesi DeepSeek BARU di tiap panggilan; kelanjutan
     *  polos membuat model buta (tanpa katalog tool, rencana, dan jejak langkah)
     *  sehingga menyimpulkan ia tidak punya akses tool. Fungsi ini merakit ulang
     *  konteks ringkas khusus jalur API; jalur WebView (sesi berkelanjutan)
     *  tetap menerima teks polos seperti sebelumnya. */

    // v4.48.6 (Butir 3): header segmen prompt awal (urutan bangun = urutan
    // di bawah; dipakai guard + pengukuran lapisan agar konsisten).
