    private fun handleAgentResponse(respRaw: String) {
        val resp = DsSafetyStrip.strip(respRaw)
        var (visible, obj) = extractTool(resp)
        // vc271 O1: tool call rusak yang berhasil diperbaiki parser tetap
        // dicatat jenis kerusakannya ke ledger (pola kerusakan model terukur).
        val repairedKindVc271 = AgentPrompt.lastRepairKind
        if (repairedKindVc271 != null) {
            try { DecisionLedger.add(this, "1-1", "parse_repair", "Tool call rusak diperbaiki otomatis (jenis: $repairedKindVc271) lalu dieksekusi — detail: " + (AgentPrompt.lastParseErrorDetail ?: "-")) } catch (e: Exception) {}
            AgentPrompt.lastRepairKind = null
        }
        // v4.13.1: panggilan tool model bisa lolos HANYA di fragmen berpikir
        // dalam format DSML (kasus 16:33 — tugas berhenti diam-diam sesudah
        // 64 tool). Selamatkan bila jawaban sendiri tidak memuat panggilan
        // dan ini bukan giliran internal/verifikasi. Eksekusinya tetap
        // lewat gerbang persetujuan yang sama seperti panggilan normal.
        if (obj == null && !internalTurn && !verifyTurn && turnThinking.isNotBlank()) {
            var rescued = AgentPrompt.extractDsmlCall(turnThinking)
            var rescueKind = "DSML"
            if (rescued == null) { rescued = AgentPrompt.extractTagCall(turnThinking)?.second; rescueKind = "tag <tool=>" }
            if (rescued != null && rescued.optString("tool").isBlank()) rescued = null
            if (rescued != null) {
                // vc229 R-05(d): rescue dari thinking HANYA untuk tool baca
                // SAFE. Tool berisiko dari thinking TIDAK dieksekusi: isi
                // thinking pemicu ditampilkan lengkap + model diminta kirim
                // ulang sebagai jawaban final bila memang dimaksud.
                val rescuedTool = rescued.optString("tool")
                if (ToolGate.level(rescuedTool) != RiskLevel.SAFE) {
                    val thinkingFull = turnThinking
                    turnThinking = ""
                    // vc316 Worker BR (a): fragmen berpikir pemicu bisa memuat
                    // markup DSML mentah — bersihkan sebelum tampil (hanya
                    // tampilan; tidak dikirim ke tool/server dari sini).
                    addBubble("🧩 Panggilan tool '$rescuedTool' ditemukan di fragmen berpikir — TIDAK dieksekusi karena tool ini berisiko (rescue vc229 hanya untuk tool baca SAFE). Isi fragmen berpikir pemicu (lengkap, markup tool mentah dibersihkan):\n" + AgentPrompt.stripRawToolMarkupForDisplay(thinkingFull), false, turn = true)
                    sendContinuation("SISTEM (rescue ditolak): panggilan tool '$rescuedTool' hanya muncul di fragmen berpikirmu, bukan di jawaban final — dan tool itu berisiko, jadi TIDAK dieksekusi. Bila kamu memang bermaksud menjalankan tool itu, kirim ulang SEKARANG sebagai blok json jawaban final (dengan argumen lengkap) dan tunggu persetujuan user; bila tidak, lanjutkan tanpa tool itu.")
                    return
                }
                obj = rescued
                visible = ""
                // vc262 H-M1 (visibilitas, BUKAN gate): teks lama mengklaim
                // rescue hanya untuk tool baca SAFE — itu sudah tidak benar
                // sejak vc247 (level() selalu SAFE, rescue apa pun jalan).
                // Eksekusi rescue kini dicatat di ledger.
                try { DecisionLedger.add(this, "1-1", "flag", "Tool '" + rescuedTool + "' dari fragmen berpikir dieksekusi via rescue (format " + rescueKind + ") — gerbang vc247 nonaktif, rescue TIDAK dibatasi tool baca SAFE.") } catch (e: Exception) {}
                addMsg("🧩 Panggilan tool model terdeteksi di fragmen berpikir (format $rescueKind) — diselamatkan & dijalankan (gerbang vc247 nonaktif: rescue TIDAK dibatasi tool baca SAFE — tercatat di ledger).", "meta", turn = true)
            }
            turnThinking = ""
        }
        // D4 (Fase 1) sabuk pengaman kedua: jawaban kosong = gagal jujur,
        // bukan giliran senyap. (Lapis pertama sudah di client Fase 0.)
        // Ditempatkan sesudah rescue thinking — tool call yang diselamatkan
        // dari fragmen berpikir tetap jalan walau respRaw kosong.
        if (respRaw.isBlank() && obj == null) {
            addBubble("⚠️ Model mengembalikan jawaban kosong — tidak ada jawaban atau tool call. Coba kirim ulang.", false, turn = true)
            endUserTurn()
            return
        }
        // vc282: pseudo tool_choice — tugas yang menuntut tool tertentu
        // (forcedToolVc282 dari pesan user) dicek di sini: bila model tidak
        // memanggilnya, SATU kali repair terarah; bila tetap tidak,
        // giliran lanjut jujur tanpa tool itu (instruksi + validasi
        // client-side, BUKAN enforcement server-side).
        if (forcedToolVc282 != null && !internalTurn && !verifyTurn) {
            val forcedVc282 = forcedToolVc282
            val parsedChoiceVc282 = ApiToolLayer.parseWithRepair(resp)
            val calledVc282 = parsedChoiceVc282.calls.map { it.optString("tool") } + listOfNotNull(obj?.optString("tool"))
            if (forcedVc282 != null && forcedVc282 in calledVc282) {
                forcedToolVc282 = null
            } else if (forcedVc282 != null && toolChoiceRepairVc282 == 0) {
                toolChoiceRepairVc282 = 1
                addMsg("🎯 Pseudo tool_choice: tugas ini menuntut tool '$forcedVc282' dulu — menyuruh model memanggilnya sekali lagi.", "meta", turn = true)
                sendContinuation(ApiToolLayer.toolChoiceRepairText(forcedVc282))
                return
            } else if (forcedVc282 != null) {
                forcedToolVc282 = null
                addMsg("🎯 Pseudo tool_choice: model tetap tidak memanggil '$forcedVc282' setelah 1 kali repair terarah — giliran lanjut jujur tanpa tool itu (instruksi + validasi client-side, bukan enforcement server-side).", "meta", turn = true)
            }
        }
        if (obj == null) {
            if (internalTurn) {
                internalTurn = false
                val propsVc228 = pendingExtractProposals.toList()
                pendingExtractProposals.clear()
                collectingExtract = false
                endUserTurn()
                if (propsVc228.isNotEmpty()) vc228ShowExtractionBatchDialog(propsVc228)
                return
            }
            if (verifyTurn) {
                verifyTurn = false
                // vc330 KATUP: sentinel "dilewati" dari klien (wadah
                // penuh, tanpa POST) BUKAN verdict — WAJIB dicek
                // SEBELUM cleanVerdict (cleanVerdict akan memetakan
                // teks ini jadi "koreksi" di cabang else). UI menampilkan
                // "dilewati", BUKAN "lolos verifikasi".
                if (visible.trim() == AgentPrompt.VERIFY_SKIPPED_VC330) {
                    addMsg("⏭️ Verifikasi diri dilewati vc330 (wadah server penuh — giliran senyap tidak boleh membuat wadah baru)", "meta", turn = true)
                } else when (val cleaned = cleanVerdict(visible)) {
                    "LULUS" -> addMsg("✓ Verifikasi diri (pemeriksaan oleh model yang sama — bukan independen): jawaban lolos verifikasi diri", "meta", turn = true)
                    null -> addMsg("🔍 Verifikasi diri (pemeriksaan oleh model yang sama — bukan independen): verifikasi tidak konklusif", "meta", turn = true)
                    else -> addBubble("🔍 Koreksi dari verifikasi diri model (bukan independen):\n$cleaned", false, turn = true)
                }
            } else if (visible.isNotEmpty()) {
                // vc251 MODE BEBAS: jawaban refusal server -> 1x retry dengan
                // reframe netral. Retry = panggilan model biasa
                // (sendContinuation -> sendToAgent, masuk kuota Governor
                // normal); jawaban kedua masuk pipeline final yang sama
                // (gate bukti, reviewer konteks-nol, double-pass,
                // claim-check) karena handleAgentResponse dipanggil lagi
                // untuk respons kedua. Tidak ada loop: sekali saja.
                if (AgentPrompt.modeBebasOn(this) && refusalRetryVc251 == 0 && AgentPrompt.isRefusalAnswer(visible)) {
                    refusalRetryVc251 = 1
                    addMsg("🔁 Mode Bebas: DeepSeek menolak topik ini — mencoba sekali lagi dengan framing netral.", "meta", turn = true)
                    sendContinuation(AgentPrompt.MODE_BEBAS_REFRAME)
                    return
                }
                // v4.18.3: jawaban "final" berisi sisa panggilan tool rusak
                // TIDAK menutup turn — pantulkan dengan koreksi format.
                    // vc271 O1: error parse SPESIFIK (bukan "kirim ulang" generik)
                    // + contoh blok benar; jenis kerusakan dicatat ke ledger.
                    val parseDetailVc271 = AgentPrompt.lastParseErrorDetail ?: "format panggilan tool tidak dikenali"
                    try { DecisionLedger.add(this, "1-1", "parse_gagal", "Tool call rusak: $parseDetailVc271 (pantulan ke-$malformedRetry dari maks 2)") } catch (e: Exception) {}
                if (malformedRetry < 2 && looksMalformedToolFragment(visible)) {
                    malformedRetry++
                    addMsg("🔁 Panggilan tool terakhir rusak (" + parseDetailVc271 + ") — sistem menyuruh agen mengulang dengan format yang benar.", "meta", turn = true)
                    sendContinuation("SISTEM (koreksi format): Jawaban terakhirmu hanya berisi panggilan tool yang RUSAK sehingga tidak bisa dijalankan dan pekerjaanmu BELUM selesai. Kerusakan parse: " + parseDetailVc271 + ". Perbaiki tepat di titik itu — contoh blok yang benar: {\"tool\":\"<nama_tool>\",\"args\":{\"arg1\":\"nilai\"}}. Panggil tool berikutnya SEKARANG memakai format itu, dengan argumen lengkap. Jangan mengakhiri sebelum pekerjaan benar-benar tuntas atau kamu memang butuh keputusan user.")
                    return
                }
                // vc232 S4: sampai di sini dengan visible masih rusak berarti batas pantulan habis.
                if (looksMalformedToolFragment(visible)) turnStoppedReason = "panggilan tool rusak berulang"
                val askPair = AgentPrompt.extractAsk(visible)
                if (askPair == null && autoContinueCount < (if (planItems.any { it.startsWith("☐") }) 2 else 1) && shouldAutoContinue(visible)) {
                    autoContinueCount++
                    addMsg("⏩ Agen berhenti sebelum tuntas — sistem menyuruhnya lanjut otomatis.", "meta", turn = true)
                    // v4.35.3 (T15): auto-lanjut membawa STATUS rencana — agen lanjutan
                    // tidak boleh buta soal apa yang sudah selesai (itu sumber pengulangan).
                    val planT15 = if (planItems.isEmpty()) "Tidak ada rencana aktif — kerjakan janji berikutnya langsung dengan tool." else "RENCANA SAAT INI (JANGAN dibuat ulang): " + planItems.mapIndexed { i, s -> "${i + 1}. $s" }.joinToString("; ") + ". Langkah ☑ SUDAH selesai & terverifikasi — JANGAN diulang, JANGAN di-restart. Lanjutkan SEKARANG dari langkah ☐ pertama; JANGAN panggil make_plan."
                    sendContinuation("SISTEM (auto-lanjut): Jawabanmu berhenti padahal pekerjaan BELUM tuntas (masih ada langkah rencana terbuka, atau kamu baru berjanji melakukan sesuatu). " + planT15 + " Jangan jawab final sebelum semua langkah rencana selesai, kecuali kamu benar-benar butuh keputusan user — kalau begitu ajukan pertanyaannya dengan jelas.")
                    return
                }
                // vc232 S4: sampai di sini dengan shouldAutoContinue masih benar berarti batas auto-lanjut habis.
                if (askPair == null && shouldAutoContinue(visible)) turnStoppedReason = "agen berhenti sebelum tuntas"
                if (askPair != null) visible = askPair.second.ifBlank { askPair.first.optString("question") }
                // vc229 R-05(e): beri tahu model (lewat riwayat) bila opsinya dipotong.
                if (askPair != null && askPair.first.optBoolean("dipotong", false)) visible += "\n(hanya 4 opsi pertama ditampilkan — model memberi lebih dari 4 opsi)"
                // vc266: FAKTA PIN penuh sekali di sini, dipakai ulang untuk
                // warning (lewat vc228ClaimWarning) + reviewer + gate bukti +
                // verifikasi diri — bukan salinan .take(4000).
                val pinnedFullVc266 = try { MemoryDb.get(this).pinnedFactsText() } catch (e: Exception) { "" }
                val allClaimsMemoryVc266 = AgentPrompt.allClaimsSupportedByMemory(AgentPrompt.splitClaims(visible), pinnedFullVc266.lines(), currentTurnUser)
                val claimWarningVc228 = vc228ClaimWarning(visible, turnWork.toList()) // vc232 S6(a): ask juga diperiksa klaimnya (pengecualian lama dihapus)
                // vc249: gate bukti — klaim faktual tanpa penanda bukti padahal pakai tool -> minta ulang SEKALI, jawaban pertama dibuang (belum tampil).
                // vc266: jawaban yang seluruh klaimnya didukung memori tidak kena gate bukti.
                if (askPair == null && claimWarningVc228 == null && gateRetryVc249 == 0 && vc228HasFactualClaim(visible) && turnUsedTools && !allClaimsMemoryVc266 && !AgentPrompt.evidenceMarkerPresent(visible)) {
                    gateRetryVc249 = 1
                    addMsg("🔁 Gate bukti: jawaban faktual belum mencantumkan bukti — sistem menyuruh agen mengulang sekali dengan format klaim → bukti.", "meta", turn = true)
                    sendContinuation(AgentPrompt.EVIDENCE_GATE_NUDGE)
                    return
                }
                // vc249: reviewer konteks-nol 1-1 — hanya klaim + bukti (jejak tool, pesan user, fakta PIN), tanpa riwayat penuh.
                // vc287: ditambah bukti giliran sebelumnya (2 giliran terakhir sesi ini, anggaran 4.000 char) — sebelumnya klaim
                // lintas-giliran yang lolos pill tetap dihapus reviewer karena buktinya hanya jejak giliran ini (Tes 1 vc286 GAGAL).
                // Dijalankan di thread
                // callback model (bukan UI thread) sehingga chatSync blokir aman. Dilewati untuk ask dan turn yang sudah dihentikan claim check.
                if (askPair == null && claimWarningVc228 == null && (vc228HasFactualClaim(visible) || turnUsedTools)) {
                    try {
                        val claimsVc249 = AgentPrompt.splitClaims(visible)
                        if (claimsVc249.isNotEmpty()) {
                            val trailVc249 = vc228FullTrailText(turnWork.toList())
                            val pinnedRevVc249 = pinnedFullVc266
                            // vc287: bukti reviewer ikut jendela 2 giliran (cermin vc286 di vc228ClaimWarning).
                            // Anggaran seksi ini maks 4.000 char agar jejak giliran ini + PESAN USER + FAKTA PIN tidak terdesak;
                            // diletakkan sesudah jejak, sebelum PESAN USER. Cap akhir .take(16000) tetap.
                            // Bila deque kosong atau sesi beda, seksi ini tidak ada (string kosong).
                            val prevEvidenceVc287 = StringBuilder()
                            if (prevTurnResultIdsSessionVc286 == turnSessionId) {
                                for (ids in prevTurnResultIdsVc286) {
                                    for (rid in ids) {
                                        try {
                                            val prevFullVc287 = ResultStore.get(this, rid)?.text ?: ""
                                            if (prevFullVc287.isNotBlank()) prevEvidenceVc287.append(if (prevFullVc287.length > 8000) prevFullVc287.take(8000) + "…(dipotong, sisa " + (prevFullVc287.length - 8000) + " char, baca via get_result[" + rid + "] untuk sisanya)…" else prevFullVc287).append(" ")
                                        } catch (e: Exception) {}
                                    }
                                }
                            }
                            val prevTextVc287 = prevEvidenceVc287.toString()
                            // vc301 SF-D8: take(3950) → take(4000) agar header
                            // "maks 4.000 char" benar, + penanda menyebut sisa
                            // char (dulu "…(dipotong)…" tanpa jumlah sisa).
                            val prevSectionVc287 = if (prevTextVc287.isBlank()) "" else "\nBUKTI GILIRAN SEBELUMNYA (hasil tool 2 giliran terakhir sesi 1-1 ini, maks 4.000 char):\n" + if (prevTextVc287.length > 4000) prevTextVc287.take(4000) + "…(dipotong, sisa " + (prevTextVc287.length - 4000) + " char)…" else prevTextVc287
                            // vc301 SF-D8: .take(16000) dulu tanpa penanda —
                            // korpus reviewer terpotong diam-diam. Kini sisa
                            // char disebut eksplisit.
                            val rawEvidenceVc301 = "JEJAK TOOL GILIRAN INI:\n" + trailVc249 + prevSectionVc287 + "\nPESAN USER:\n" + currentTurnUser + "\nFAKTA PIN:\n" + pinnedRevVc249
                            val evidenceVc249 = if (rawEvidenceVc301.length > 16000) rawEvidenceVc301.take(16000) + "…(dipotong, sisa " + (rawEvidenceVc301.length - 16000) + " char)…" else rawEvidenceVc301
                            // vc298 BAGIAN 1 (1A): reviewer WAJIB slot Browser 5
                            // (AccountPool.REVIEWER_SLOT) — tanpa fallback ke
                            // slot lain. Slot 5 kosong = reviewer dilewati
                            // dengan penanda jujur (bukan lolos diam-diam).
                            val rSlotVc249 = try { AccountPool.reviewerSlot(this) } catch (e: Exception) { null }
                            val rAuthVc249 = if (rSlotVc249 != null) try { AccountPool.slotAuth(this, rSlotVc249) } catch (e: Exception) { null } else null
                            if (rSlotVc249 == null || rAuthVc249 == null) {
                                addMsg(ReviewerVc298.SKIP_NOTE, "meta", turn = true)
                            } else if (Governor.overCapReviewer(this)) {
                                // vc277 O16(b): kuota reviewer habis — reviewer
                                // dilewati dengan penanda, bukan diam-diam lolos.
                                addMsg(Governor.reviewerOverCapText(this), "meta", turn = true)
                            } else {
                                // vc275 O11: verdict tak terparse -> retry 1x format ketat (counter govCountReviewer, bukan interaktif — chatSync reviewer=true bump reviewer + memakai sesi server TETAP reviewer slot 5 sejak vc298, bukan sesi ephemeral baru tiap review); tetap gagal -> penanda "belum terverifikasi", bukan lolos diam-diam.
                                var unsVc249: List<Int> = emptyList()
                                var concVc249 = false
                                var reviewFailVc275 = false
                                try {
                                    val (rawVc249, _) = SlotClient(this, rSlotVc249, rAuthVc249.first, rAuthVc249.second).chatSync(AgentPrompt.zeroCtxReviewPrompt(claimsVc249, evidenceVc249), false, false, reviewer = true)
                                    val (u1Vc275, c1Vc275) = AgentPrompt.parseZeroCtxReview(rawVc249)
                                    if (c1Vc275) { unsVc249 = u1Vc275; concVc249 = true } else {
                                        val (raw2Vc275, _) = SlotClient(this, rSlotVc249, rAuthVc249.first, rAuthVc249.second).chatSync(AgentPrompt.reviewerRetryPrompt(claimsVc249, evidenceVc249), false, false, reviewer = true)
                                        val (u2Vc275, c2Vc275) = AgentPrompt.parseZeroCtxReview(raw2Vc275)
                                        if (c2Vc275) { unsVc249 = u2Vc275; concVc249 = true } else reviewFailVc275 = true
                                    }
                                } catch (e: Exception) { reviewFailVc275 = true }
                                // vc275 O11(a): label jujur bila reviewer memakai slot yang sama dengan giliran agen (hanya 1 slot login).
                                val indepNoteVc275 = AgentPrompt.reviewerIndependenceNote(turnSlotVc249, rSlotVc249)
                                // vc266: klaim yang didukung memori dikeluarkan dari daftar tak didukung reviewer.
                                val unsVc249FiltVc266 = AgentPrompt.filterUnsupportedByMemory(claimsVc249, unsVc249, pinnedFullVc266.lines(), currentTurnUser)
                                // vc282: pesan sistem sebagai bukti reviewer — klaim
                                // yang mengutip peringatan sistem giliran ini
                                // (StuckDetector, kunci giliran, cap langkah)
                                // tidak dihapus filter [KLAIM DIHAPUS].
                                val unsVc249FiltVc282 = ApiToolLayer.dropSystemBackedClaims(claimsVc249, unsVc249FiltVc266, turnSystemNotesVc282.toList() + listOfNotNull(turnStoppedReason))
                                if (reviewFailVc275) addMsg(AgentPrompt.reviewerNotVerifiedNote() + indepNoteVc275, "meta", turn = true)
                                else if (unsVc249FiltVc282.isNotEmpty()) {
                                    // vc250: double-pass — jawaban yang tampil (dan tersimpan di riwayat) hanya berisi klaim yang lolos; klaim gagal diganti penanda, bukan dihapus diam-diam.
                                    visible = AgentPrompt.applyDoublePass(visible, claimsVc249, unsVc249FiltVc282)
                                    // vc288 Fase 2: footer "Yang belum diketahui" — HANYA bila double-pass benar-benar menghapus klaim.
                                    // Maks 3 baris; bagian dari jawaban yang tampil + tersimpan di riwayat (bukan bubble meta), sebelum pill.
                                    val footerVc288 = AgentPrompt.unknownFooterVc288(claimsVc249, unsVc249FiltVc282, turnWork.map { it.tool })
                                    if (footerVc288.isNotEmpty() && !visible.contains("Yang belum diketahui:")) {
                                        visible = visible.trimEnd() + "\n\n" + footerVc288
                                    }
                                    addMsg(AgentPrompt.reviewerNoteText(claimsVc249, unsVc249FiltVc282) + indepNoteVc275, "meta", turn = true)
                                } else if (indepNoteVc275.isNotBlank()) addMsg("🔍 Reviewer konteks-nol: verdict diterima" + indepNoteVc275 + ".", "meta", turn = true)
                            }
                        }
                    } catch (e: Exception) {
                        addMsg(AgentPrompt.reviewerNotVerifiedNote(), "meta", turn = true)
                    }
                }
                if (claimWarningVc228 != null) addMsg("⚠️ Peringatan sistem: klaim ini tidak didukung hasil tool di giliran ini — perbaiki atau nyatakan sebagai dugaan. Detail: $claimWarningVc228", "meta", turn = true)
                if (askPair == null && claimWarningVc228 != null) turnStoppedReason = "klaim tidak didukung hasil tool di giliran ini. Detail: $claimWarningVc228" // vc232 S4 (ask tidak dihentikan: turn menunggu user)
                // VC303-P3-20 (LP-6): sidik jari klaim gagal — simpan hash
                // kalimat klaim yang kena claim-stop per sesi; setelah 2 stop
                // BERUNTUN atas klaim yang sama, alasan berhenti meminta
                // keputusan user (bukan coba lagi). Gate claim-check sendiri
                // TIDAK diubah — hanya pencatatan + eskalasi teks. Peringatan
                // dini di giliran berikut tampil via claimFingerprintsBlockVc303
                // di awal giliran (onUserMessage).
                if (askPair == null && claimWarningVc228 != null) {
                    val repeatStopsVc303 = try { recordClaimStopVc303(visible, claimWarningVc228) } catch (e: Exception) { 0 }
                    if (repeatStopsVc303 >= 2) turnStoppedReason = (turnStoppedReason ?: "") + " — INI STOP KE-2 BERUNTUN atas klaim yang sama; JANGAN coba lagi tanpa bukti tool baru — MINTA KEPUTUSAN USER (lanjut dengan bukti / ubah klaim / batalkan tugas)."
                }
                // vc252 D-M8: jawaban kedua masih refusal — tampilkan apa
                // adanya + satu baris jujur sebagai META (addMsg "meta"),
                // BUKAN ditempel ke visible. visible disimpan ke riwayat
                // (addHistory "asisten", di bawah) — baris sistem yang
                // ditempel ke visible ikut tersimpan dan muncul lagi di
                // [RIWAYAT] giliran berikut seolah teks model. addMsg
                // "meta" hanya tampil di layar, tidak masuk riwayat.
                // JANGAN memalsukan jawaban.
                val stillRefusalVc252 = AgentPrompt.modeBebasOn(this) && refusalRetryVc251 == 1 && AgentPrompt.isRefusalAnswer(visible)
                addAnswerBubble(visible, askPair == null && claimWarningVc228 != null) // vc232 S3
                if (stillRefusalVc252) addMsg("Mode Bebas aktif, tapi DeepSeek tetap menolak topik ini.", "meta", turn = true)
                emitPhase("report")
                if (askPair != null) addMsg("❓ Agen menunggu pilihanmu — ketuk salah satu opsi di pesannya, atau ketik jawaban bebas.", "meta", turn = true)
                else if (turnStoppedReason != null) {
                    addMsg("⛔ Dihentikan: $turnStoppedReason", "meta", turn = true) // vc232 S4: satu pemilih pill akhir; S2: detail klaim dibawa di pill ini
                    addTurnEndVc306() // vc306 C8: ringkasan + footnote (durasi/langkah/sumber dipertahankan)
                } else addTurnEndVc306() // vc306 C8: menggantikan meta "✓ Selesai dalam N detik • via <sumber>" — info durasi + sumber pindah ke footnote, bukan hilang
                if (askPair == null && claimWarningVc228 != null) addMsg("🔍 Verifikasi dilewati: turn ini sudah dihentikan claim check, jadi tidak ada pill verifikasi.", "meta", turn = true) // vc232 S1: netral, sekali saja
                if (askPair != null) pendingEndReason = "ask"
                val workItemsF = turnWork.toList()
                val baseWorkF = WorkLog.turnJson(workItemsF, turnElapsedMs(workItemsF))
                var workJsonF = baseWorkF
                // v4.16.0: pertanyaan pilihan (ask) menumpang di JSON kerja
                // pesan ini — React menggambar chip opsi dari field "ask".
                if (askPair != null) {
                    try {
                        val mj = if (baseWorkF != null) JSONObject(baseWorkF) else JSONObject()
                        mj.put("ask", askPair.first)
                        workJsonF = mj.toString()
                    } catch (e: Exception) {}
                }
                if (baseWorkF != null) {
                    addMsg(WorkLog.footer(workItemsF, turnElapsedMs(workItemsF)), "meta", turn = true)
                    try { uiEvent(JSONObject(workJsonF ?: baseWorkF).put("type", "chat.work")) } catch (e: Exception) {}
                }
                try { MemoryDb.get(this).addHistory("asisten", visible, turnSessionId, workJsonF) } catch (e: Exception) {}
                // T1: di UI klasik, gambar kartu Ringkasan Kerja + kartu ask
                // dari JSON kerja yang sama (React menggambarnya dari chatTail).
                run {
                    try {
                        val hid = MemoryDb.get(this).lastHistoryId(turnSessionId)
                        if (workJsonF != null) renderWorkAndAsk(workJsonF, hid, turn = true)
                    } catch (e: Exception) {}
                    android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({ refreshLiveCard(); refreshQueueChips() }, 700)
                }
                clearTurnCheckpoint()
                // vc304 B2: giliran background yang SELESAI saat user di sesi
                // lain — hasilnya sudah di histori sesi pemilik; beri
                // notifikasi ringan (ketuk -> buka sesi pemilik) tanpa
                // mencampur tampilan sesi aktif.
                if (!activityResumed || !SessionBackgroundVc304.renderAllowed(turnSessionId, currentSessionId)) notifyTurnDone(visible)
                // vc304 B2: VO jawaban hanya dibacakan di sesi pemilik.
                if (::voiceCheck.isInitialized && voiceCheck.isChecked && SessionBackgroundVc304.renderAllowed(turnSessionId, currentSessionId)) {
                    if (askPair == null && claimWarningVc228 != null) speak("Peringatan: jawaban ini tidak didukung hasil tool. $visible") else speak(visible) // vc232 S3
                }
                if (askPair == null && claimWarningVc228 == null && !allClaimsMemoryVc266 && ::verifyCheck.isInitialized && verifyCheck.isChecked && (turnUsedTools || vc228HasFactualClaim(visible))) { // vc232 S1: turn kena claimWarning tidak diverifikasi; vc266: jawaban yang seluruh klaimnya didukung memori dilewati dari verifikasi (prompt verifikasi tidak membawa FAKTA PIN)
                    verifyTurn = true
                    emitPhase("verify")
                    // vc235 M2: verifikasi memakai transkrip Vc230 atas sesi
                    // pemilik giliran (turnSessionId), bukan sesi aktif saat ini.
                    val ctxHist = try { MemoryDb.get(this).historyTranscriptVc230(20, 20000, turnSessionId) } catch (e: Exception) { "" }
                    val trailTxt = synchronized(turnWork) { vc228FullTrailText(turnWork.toList()) }
                    val wsLineVc228 = try { WorldState.line(this) } catch (e: Exception) { "" }
                    // vc330 SESI: verifikasi kini membawa DELTA (jangkar +
                    // jejak + WorldState + jawaban final — TANPA ctxHist
                    // 20.000 char). Prompt PENUH tetap teks lama lengkap
                    // (fallback bila wadah belum primed).
                    val fullVerifyVc330 = "VERIFIKASI DIRI (pemeriksaan oleh model yang sama — bukan independen; jangan menyapa, JANGAN pakai tool): Periksa JAWABAN FINAL di bawah terhadap JEJAK TOOL PENUH & RIWAYAT di bawah ini. Klaim yang cocok dengan JEJAK TOOL = DIDUKUNG (hasil tool memang tidak selalu tercatat sebagai baris riwayat terpisah). Klaim soal kondisi HP saat ini (persentase baterai, jam) HANYA didukung bila cocok persis dengan nilai WorldState giliran ini: " + wsLineVc228 + " — bila tidak cocok, itu TIDAK didukung. Ada klaim/angka yang TIDAK didukung hasil tool?\nATURAN OUTPUT KETAT: WAJIB Bahasa Indonesia. DILARANG menulis proses berpikir, draf, analisis, atau catatan meta dalam bahasa apa pun. Output HANYA SATU baris: 'LULUS' bila semua klaim didukung, atau 'KOREKSI: <satu kalimat koreksi yang jelas untuk user>' bila ada yang menyimpang. Tidak ada teks lain.\n\nJEJAK TOOL GILIRAN INI:\n$trailTxt\n\nRIWAYAT:\n$ctxHist\n\nJAWABAN FINAL YANG DIPERIKSA:\n$visible"
                    val deltaVerifyVc330 = AgentPrompt.deltaVerifyPromptVc330(currentTurnUser, trailTxt, wsLineVc228, visible)
                    sendToAgent(fullVerifyVc330, deltaVerifyVc330)
                    return
                }
            }
            if (pendingExtract) {
                pendingExtract = false
                // vc241 O7: jendela 13 pesan (10 sejak ekstraksi terakhir + overlap 3, dulu 16); pemicu per-sesi vc235 tidak diubah. Tanpa sinyal fakta di pesan user, lewati panggilan LLM ekstraksi sama sekali.
                // vc235 M2: ekstraksi memakai transkrip Vc230 atas sesi
                // pemilik giliran (dulu: tanpa argumen sesi sehingga default
                // sesi 1, padahal sesi aktif bisa bukan 1).
                val hist = try { MemoryDb.get(this).historyTranscriptVc230(40, 40000, turnSessionId) } catch (e: Exception) { "" }
                if (!extractHasFactSignalVc241(hist)) {
                    if (pendingEndReason == null) pendingEndReason = if (turnStoppedReason?.startsWith("klaim tidak didukung") == true) "dihentikan-klaim" else if (visible.contains("?")) "pertanyaan-user" else "final"
                    endUserTurn()
                } else {
                    internalTurn = true
                    collectingExtract = true
                    pendingExtractProposals.clear()
                    // vc330 SESI: ekstraksi kini membawa DELTA (jangkar +
                    // jendela 13 pesan terakhir, cap 8.000 — BUKAN
                    // 40/40.000). Prompt PENUH tetap teks lama lengkap
                    // (40/40.000, fallback bila wadah belum primed).
                    // Gate sinyal fakta tetap memakai hist penuh (tidak
                    // berubah); jendela delta diambil dari transkrip
                    // yang sama (13 pesan terakhir).
                    val histRecentVc330 = try { MemoryDb.get(this).historyTranscriptVc230(AgentPrompt.EXTRACT_WINDOW_N_VC330, AgentPrompt.EXTRACT_WINDOW_CHARS_VC330, turnSessionId) } catch (e: Exception) { "" }
                    val fullExtractVc330 = "TUGAS LATAR (jangan menyapa user, jangan menjawab pertanyaan apa pun): Berikut riwayat percakapan terakhir user dengan asisten. Ekstrak fakta BARU tentang user yang layak disimpan permanen (nama/panggilan, preferensi, jadwal rutin, orang penting, keputusan). Untuk SETIAP fakta panggil tool remember_fact (key singkat, value jelas). Koreksi gaya/aturan pakai learn_rule. Usulanmu DIKUMPULKAN untuk persetujuan batch user sebelum tersimpan — jadi usulkan semua fakta, jangan berhenti di satu. Kalau tidak ada yang baru, jawab persis: TIDAK ADA.\n\nRIWAYAT:\n$hist"
                    sendToAgent(fullExtractVc330, AgentPrompt.deltaExtractPromptVc330(currentTurnUser, histRecentVc330))
                }
            } else {
                if (pendingEndReason == null) pendingEndReason = if (turnStoppedReason?.startsWith("klaim tidak didukung") == true) "dihentikan-klaim" else if (visible.contains("?")) "pertanyaan-user" else "final" // vc232 S5
                endUserTurn()
            }
            return
        }
        // vc232 S7: respons giliran verifikasi TIDAK BOLEH mengeksekusi tool apa pun.
        // (verifyTurn hanya bisa masih true di sini bila respons verifikasi memuat tool,
        // karena cabang verifyTurn di atas sudah mengosongkannya untuk respons bersih.)
        if (verifyTurn) {
            verifyTurn = false
            addMsg("🔍 Verifikasi diri (pemeriksaan oleh model yang sama — bukan independen): verifikasi tidak konklusif", "meta", turn = true)
            endUserTurn()
            return
        }
        // vc273 O6: >1 tool per respons di lane 1-1 DIEKSEKUSI sebagai batch
        // (maks 4 per respons; baca independen konkuren, tulis sekuensial).
        // O8 diserap O6 — tidak ada lagi perilaku transisi terpisah.
        // Batch TIDAK dipakai bila: giliran internal/verifikasi, atau batch
        // memuat tool jalur-khusus (make_plan/update_plan, analyze_photo,
        // delete_session) — untuk kombinasi itu hanya tool pertama yang
        // dijalankan lewat jalur tunggal biasa, sisanya diminta ulang.
        // Lane lain (latar/grup/tim/room) mengeksekusi batch sejak vc274 (BatchToolVc274).
        // vc282: parser lapisan API internal — strict dulu (hanya pagar
        // json kanonik), repair/lenient kemudian. Hasil sama dengan
        // extractToolCalls untuk kasus normal; perbaikan dicatat ke ledger.
        val parsedVc282 = ApiToolLayer.parseWithRepair(resp)
        val multiVc229 = parsedVc282.calls
        if (parsedVc282.repaired && multiVc229.isNotEmpty()) {
            try { DecisionLedger.add(this, "1-1", "parse_repair", "Tool call diperbaiki lapisan API vc282 (strict gagal, repair/lenient dipakai — detail strict: " + (parsedVc282.strictError ?: "-") + ") lalu dieksekusi.") } catch (e: Exception) {}
            addMsg("🔧 Format tool-call diperbaiki otomatis oleh lapisan API (strict gagal — detail: " + (parsedVc282.strictError ?: "format tidak kanonik") + ").", "meta", turn = true)
        }
        if (multiVc229.size > 1) {
            if (useBatchVc273(multiVc229)) {
                if (visible.isNotEmpty() && vc228HasFactualClaim(visible)) {
                    val warnBatchVc273 = vc228ClaimWarning(visible, turnWork.toList())
                    if (warnBatchVc273 != null) addMsg("⚠️ Peringatan sistem: klaim ini tidak didukung hasil tool di giliran ini — perbaiki atau nyatakan sebagai dugaan. Detail: $warnBatchVc273", "meta", turn = true)
                }
                if (visible.isNotEmpty()) addBubble(visible, false, turn = true)
                if (!internalTurn && !verifyTurn) {
                    AgentPrompt.extractAsk(visible)?.let { pendingAskVc229 = it.first }
                }
                execBatchAndContinueVc273(multiVc229)
                return
            }
            addMsg("🔁 Respons memuat ${multiVc229.size} panggilan tool — batch tidak dipakai untuk kombinasi ini (tool jalur-khusus atau giliran internal): hanya tool pertama yang dijalankan, kirim ulang sisanya di giliran berikutnya.", "meta", turn = true)
            // jatuh ke jalur tunggal di bawah (obj sudah = call pertama)
        }
        if (visible.isNotEmpty() && vc228HasFactualClaim(visible)) { // vc232 S6(b)
            val warnVc232 = vc228ClaimWarning(visible, turnWork.toList())
            if (warnVc232 != null) addMsg("⚠️ Peringatan sistem: klaim ini tidak didukung hasil tool di giliran ini — perbaiki atau nyatakan sebagai dugaan. Detail: $warnVc232", "meta", turn = true)
        }
        if (visible.isNotEmpty()) addBubble(visible, false, turn = true)
        val tool = obj.optString("tool")
        val args = obj.optJSONObject("args") ?: JSONObject()
        // vc272 O4: id pengikat kanonis giliran ini — id model dipakai bila
        // cocok pola dan belum dipakai giliran ini; bila tidak, app memberi
        // tc-<n> terkecil yang belum dipakai.
        val callIdVc272 = nextCallIdVc272(obj.optString("id"))
        // vc229 R-05(e): ask se-respons dengan tool — simpan, dirender setelah
        // tool dieksekusi (renderPendingAskVc229 di execToolAndContinue).
        if (!internalTurn && tool != "make_plan" && tool != "update_plan") {
            AgentPrompt.extractAsk(visible)?.let { pendingAskVc229 = it.first }
        }
        // vc229 R-05(a): pratinjau tool non-risky pertama per giliran.
        if (!Tools.isRisky(tool) && turnWork.isEmpty()) addMsg("▶️ Akan menjalankan $tool (pratinjau: tool non-risky pertama giliran ini).", "meta", turn = true)
        if (tool == "make_plan" || tool == "update_plan") { handlePlannerTool(tool, args); return }
        if (internalTurn && collectingExtract && (tool == "remember_fact" || tool == "learn_rule")) {
            val kVc228 = if (tool == "remember_fact") args.optString("key").trim() else "aturan:" + args.optString("rule").trim().hashCode()
            val vVc228 = if (tool == "remember_fact") args.optString("value").trim() else args.optString("rule").trim()
            if (kVc228.isNotBlank() && vVc228.isNotBlank()) pendingExtractProposals.add(kVc228 to vVc228)
            if (pendingExtractProposals.size >= 40) {
                internalTurn = false
                val propsVc228 = pendingExtractProposals.toList()
                pendingExtractProposals.clear()
                collectingExtract = false
                endUserTurn()
                vc228ShowExtractionBatchDialog(propsVc228)
                return
            }
            sendContinuation("Proposal fakta dicatat untuk persetujuan batch (BELUM tersimpan): $kVc228 = $vVc228. Lanjutkan mengusulkan fakta berikutnya dari riwayat, atau jawab persis TIDAK ADA bila tidak ada lagi.")
            return
        }
        if (internalTurn && Tools.isRisky(tool)) {
            internalTurn = false
            val propsVc228 = pendingExtractProposals.toList()
            pendingExtractProposals.clear()
            collectingExtract = false
            addBubble("🧠 Ekstraksi fakta latar selesai.", false, turn = true)
            endUserTurn()
            if (propsVc228.isNotEmpty()) vc228ShowExtractionBatchDialog(propsVc228)
            return
        }
        // vc262 H-M4 (visibilitas, BUKAN gate): giliran ekstraksi internal
        // bisa mengeksekusi tool non-memori — cabang penahan isRisky mati
        // sejak vc247. Dicatat di ledger, eksekusi tetap jalan.
        if (internalTurn && tool != "remember_fact" && tool != "learn_rule") {
            try { DecisionLedger.add(this, "1-1-ekstraksi", "flag", "Giliran ekstraksi internal mengeksekusi tool non-memori '" + tool + "' (cabang penahan isRisky mati sejak vc247).") } catch (e: Exception) {}
        }
        proceedTool(tool, args, false, callIdVc272)
    }

    /** vc229 R-05(e): render ask yang tadi se-respons dengan tool, SETELAH
     *  tool dieksekusi. Dipanggil dari execToolAndContinue (semua jalur). */
    private fun renderPendingAskVc229() {
        val ask = pendingAskVc229 ?: return
        pendingAskVc229 = null
        val q = ask.optString("question")
        val arr = ask.optJSONArray("options")
        val optsTxt = if (arr != null) (0 until arr.length()).joinToString("\n") { "${it + 1}. ${arr.optString(it)}" } else ""
        addBubble("❓ $q" + (if (optsTxt.isNotBlank()) "\n$optsTxt" else ""), false, turn = true)
        addMsg("❓ Agen bertanya (lihat pesan di atas) — jawab dengan ketik bebas.", "meta", turn = true) // vc232 S8 opsi (b): opsi pending-ask tidak bisa diketuk, pill-nya dibuat jujur
    }

    /** vc229 R-04(g): dialog konfirmasi kedua dalam-app untuk tool HIGH yang
     *  disetujui dari parkir notifikasi. Argumen lengkap (scrollable) + PIN
     *  bila PIN diset. Dipanggil dari onResume bila ada bgSecondConfirm. */
    private fun showBgSecondConfirmVc229() {
        if (bgSecondConfirmShownVc229) return
        val prefsSc = getSharedPreferences("harness", MODE_PRIVATE)
        val raw = prefsSc.getString("bgSecondConfirm", "") ?: ""
        if (raw.isBlank()) return
        val o = try { JSONObject(raw) } catch (e: Exception) { return }
        if (System.currentTimeMillis() - o.optLong("ts", 0) > 15 * 60_000L) {
            prefsSc.edit().remove("bgSecondConfirm").apply()
            return
        }
        // vc305 H-K1: dialog konfirmasi kedua HANYA bila status durable
        // masih PROCESSING. Slot tanpa pid (legacy pra-vc305) atau baris
        // yang sudah diputuskan / kedaluwarsa -> hapus slot + batalkan
        // notif 7704, JANGAN tampilkan dialog (tidak ada yang bisa
        // dikonfirmasi). Pemilik tunggal penulisan decision adalah
        // BgBrain.resumeSecondConfirm — di sini hanya membaca status.
        val pidVc305 = o.optString("pid", "")
        if (pidVc305.isBlank()) {
            prefsSc.edit().remove("bgSecondConfirm").apply()
            try { (getSystemService(NOTIFICATION_SERVICE) as android.app.NotificationManager).cancel(7704) } catch (e: Exception) {}
            return
        }
        try {
            val rowVc305 = ParkedApprovalStoreVc305.get(this).get(pidVc305)
            if (rowVc305 == null || rowVc305.status != "PROCESSING") {
                prefsSc.edit().remove("bgSecondConfirm").apply()
                try { (getSystemService(NOTIFICATION_SERVICE) as android.app.NotificationManager).cancel(7704) } catch (e: Exception) {}
                return
            }
            if (ParkedApprovalMachineVc305.isExpired(rowVc305.createdAtMs, rowVc305.risk, System.currentTimeMillis()) ||
                ParkedApprovalMachineVc305.isClaimExpired(rowVc305.toState(), System.currentTimeMillis())) {
                ParkedApprovalStoreVc305.get(this).markExpired(pidVc305, System.currentTimeMillis())
                prefsSc.edit().remove("bgSecondConfirm").apply()
                try { (getSystemService(NOTIFICATION_SERVICE) as android.app.NotificationManager).cancel(7704) } catch (e: Exception) {}
                return
            }
        } catch (e: Exception) {
            // Store tidak bisa dibaca -> fail-closed: jangan tampilkan dialog.
            prefsSc.edit().remove("bgSecondConfirm").apply()
            return
        }
        val tool = o.optString("tool")
        val argsStr = o.optString("args")
        val pinHash = prefsSc.getString("pinHash", "") ?: ""
        val th = currentTheme()
        val box = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(8), dp(16), dp(4)) }
        box.addView(tv("Konfirmasi kedua (dari parkir notifikasi) — tool HIGH:", 13f, th.text, true))
        box.addView(tv("Tool: $tool", 13f, th.text))
        box.addView(tv("Argumen lengkap:\n$argsStr", 12.5f, th.text))
        box.addView(tv("Tugas: " + o.optString("task").take(300), 12f, th.dim))
        var pinField: EditText? = null
        if (pinHash.isNotBlank()) {
            pinField = EditText(this).apply {
                hint = "PIN aksi sensitif"
                inputType = android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD
                setTextColor(TEXT); setHintTextColor(DIM)
            }
            box.addView(pinField)
        }
        val scroll = ScrollView(this).apply { addView(box) }
        bgSecondConfirmShownVc229 = true
        fun finishVc229(approved: Boolean) {
            bgSecondConfirmShownVc229 = false
            prefsSc.edit().remove("bgSecondConfirm").apply()
            // vc305 H-K1: cancel/dismiss -> resumeSecondConfirm menulis
            // status=REJECTED set-once di store durable (pemilik tunggal
            // decision) + menghapus kartu; di sini batalkan juga notif 7704.
            try { (getSystemService(NOTIFICATION_SERVICE) as android.app.NotificationManager).cancel(7704) } catch (e: Exception) {}
            BgBrain.resumeSecondConfirm(this, approved, o)
        }
        AlertDialog.Builder(this).setTitle("🛡️ Konfirmasi kedua — izinkan?")
            .setView(scroll)
            .setPositiveButton("Izinkan") { _, _ ->
                val pinTyped = pinField?.text?.toString() ?: ""
                if (pinField != null && pinTyped.isBlank()) {
                    Toast.makeText(this, "PIN belum diisi — aksi belum jalan.", Toast.LENGTH_LONG).show()
                    finishVc229(false)
                } else if (pinField != null && sha256Hex(pinTyped) != pinHash) {
                    Toast.makeText(this, "PIN salah — aksi dibatalkan.", Toast.LENGTH_LONG).show()
                    finishVc229(false)
                } else finishVc229(true)
            }
            .setNegativeButton("Tolak") { _, _ -> finishVc229(false) }
            .setOnCancelListener { finishVc229(false) }
            .show()
    }

    /** Gerbang langkah + risiko untuk satu panggilan tool. Batas langkah FLEKSIBEL
     *  (pref maxToolSteps, default 50, plafon 200 sejak vc299): saat tercapai dan
     *  askExtendSteps aktif, user ditanya dulu — setuju: anggaran +10 dan tool
     *  tertunda dijalankan; tolak: giliran berhenti dengan pesan batas yang jujur.
     *  vc301 SF-C5 (Gas user 12 Nov ~14:58): dialog tanya-tambah ini adalah
     *  perpanjangan BUDGET langkah, BUKAN approval per-tool — syaratnya HANYA
     *  prefs askExtendSteps, dipisah dari ToolGate.GATES_DISABLED (vc247 menghapus
     *  checkpoint approval per-tool, bukan dialog budget; dialog ini sempat mati
     *  total karena syarat lamanya `!GATES_DISABLED && askExtendSteps`). TIDAK
     *  ada gate approval yang dihidupkan kembali di sini. */
    // vc272 O4: id pengikat kanonis untuk satu tool call giliran ini.
    private fun nextCallIdVc272(modelId: String): String {
        val used = synchronized(turnWork) { turnWork.mapNotNull { it.callId.takeIf { c -> c.isNotBlank() } }.toSet() }
        if (AgentPrompt.isValidCallId(modelId) && modelId !in used) return modelId
        var n = used.size + 1
        while ("tc-$n" in used) n++
        return "tc-$n"
    }

    // vc304 B2: tawaran perpanjangan +10 langkah (dialog / popup melayang).
    // Diekstrak dari proceedTool supaya switchSession bisa menawarkannya
    // ULANG saat user kembali ke sesi pemilik giliran background — tanpa
    // itu giliran yang diparkir menunggu selamanya (pendingTool diset,
    // tidak ada kelanjutan). Dipanggil hanya bila sesi pemilik aktif
    // (parkir ditangani pemanggil proceedTool), TAPI callback float tetap
    // dijaga: float bisa diketuk SESUDAH user pindah sesi.
    private fun offerExtendStepsVc304() {
        runOnUiThread {
            var floatHandledS = false
            if (!activityResumed) {
                val shownS = ApprovalFloat.show(applicationContext, "Batas langkah tercapai",
                    "Batas $stepBudget langkah tool untuk perintah ini habis, tapi tugas kelihatannya belum selesai. Tambah 10 langkah lagi? (perpanjangan ${extendCountVc303 + 1} dari maks ${AgentPrompt.MAX_EXTEND_VC303})",
                    "Tambah 10 langkah", "Berhenti", false,
                    onApprove = {
                        // vc304 B2: float bisa diketuk SESUDAH user pindah sesi —
                        // keputusan +10 hanya berlaku di sesi pemilik; bila sesi
                        // sudah beda, parkir lagi (ditawarkan ulang saat kembali).
                        if (!SessionBackgroundVc304.renderAllowed(turnSessionId, currentSessionId)) {
                            extendOfferPendingVc304 = true
                        } else {
                            // VC303-P3-16: catat perpanjangan + progres saat ini.
                            extendCountVc303++
                            extendOkMarkVc303 = okCountVc303()
                            stepBudget += 10
                            val p = pendingTool; pendingTool = null; val cVc272 = pendingCallIdVc272; pendingCallIdVc272 = ""
                            if (p != null) proceedTool(p.first, p.second, true, cVc272)
                        }
                    },
                    onReject = {
                        // vc304 B2: sama seperti onApprove — tolak dari sesi lain
                        // bukan keputusan atas giliran ini; parkir lagi.
                        if (!SessionBackgroundVc304.renderAllowed(turnSessionId, currentSessionId)) {
                            extendOfferPendingVc304 = true
                        } else {
                            pendingTool = null
                            addBubble("⛔ Dihentikan: batas $stepBudget langkah (pilihan user dari popup melayang). Hasil sementara ada di kartu-kartu tool di atas.", false, turn = true)
                            TurnMetrics.finish(this, "anggaran-langkah")
                        }
                    },
                    onOpenApp = {})
                if (shownS) {
                    floatHandledS = true
                } else {
                    pendingTool = null
                    addBubble("⛔ Dihentikan: batas $stepBudget langkah (app tidak di depan). Hasil sementara ada di kartu-kartu tool di atas. (Naikkan batasnya di Setup tombol 26.)", false, turn = true) // vc232 S5
                    TurnMetrics.finish(this, "anggaran-langkah")
                    floatHandledS = true
                }
            }
            if (!floatHandledS) {
            extendDialogVc304 = AlertDialog.Builder(this)
                .setTitle("Batas langkah tercapai")
                .setMessage("Batas $stepBudget langkah tool untuk perintah ini habis, tapi tugas kelihatannya belum selesai. Tambah 10 langkah lagi? (perpanjangan ${extendCountVc303 + 1} dari maks ${AgentPrompt.MAX_EXTEND_VC303})")
                .setPositiveButton("Tambah 10 langkah") { _, _ ->
                    extendDialogVc304 = null
                    // VC303-P3-16: catat perpanjangan + progres saat ini.
                    extendCountVc303++
                    extendOkMarkVc303 = okCountVc303()
                    stepBudget += 10
                    val p = pendingTool; pendingTool = null; val cVc272 = pendingCallIdVc272; pendingCallIdVc272 = ""
                    if (p != null) proceedTool(p.first, p.second, true, cVc272)
                }
                .setNegativeButton("Berhenti") { _, _ ->
                    extendDialogVc304 = null
                    pendingTool = null
                    addBubble("⛔ Dihentikan: batas $stepBudget langkah (pilihan user). Hasil sementara ada di kartu-kartu tool di atas.", false, turn = true)
                    TurnMetrics.finish(this, "anggaran-langkah")
                }
                .show()
            }
        }
    }

    private fun proceedTool(tool: String, args: JSONObject, counted: Boolean, callId: String = "") {
        // v4.48.3: pengunci giliran StuckDetector — detektor bukan lagi
        // sekadar tempelan teks. Begitu kunci aktif, panggilan tool
        // berikutnya di giliran ini DITOLAK tanpa dieksekusi dan tanpa
        // memakan anggaran langkah.
        if (turnStuckBlocked) {
            blockedAttempts++
            if (blockedAttempts >= 3) {
                // Model sudah 3x mengabaikan kunci: hentikan giliran
                // sepenuhnya (gelembung final sistem, tanpa kelanjutan).
                runOnUiThread {
                    addMsg("⛔ Dihentikan: StuckDetector — agent berputar tanpa progres dan mengabaikan kunci giliran 3x. Tugas berhenti di sini — hasil sementara ada di kartu-kartu tool di atas.", "meta", turn = true)
                    pendingEndReason = "kunci-putaran"
                    endUserTurn()
                }
            } else {
                sendContinuation("⛔ GILIRAN INI DIKUNCI StuckDetector: kamu sudah berputar tanpa progres. JANGAN panggil tool lagi apa pun — jawab FINAL sekarang: laporkan apa yang sudah tercapai, di mana macetnya, dan apa yang kamu butuhkan dari user.")
            }
            return
        }
        // VC303-P3-19 (LP-5a): pola yang pernah mengunci giliran di sesi ini
        // DITOLAK di 3 langkah pertama giliran ini (tanpa dieksekusi, tanpa
        // memakan langkah). Dibatasi 2 penolakan/giliran — panggilan ke-3
        // yang sama dibiarkan lewat agar StuckDetector giliran ini yang
        // menanganinya (mencegah loop penolakan tanpa ujung).
        if (agentSteps < AgentPrompt.LOCKED_PATTERN_FIRST_STEPS_VC303 && lockedRefusalsVc303 < 2 && isLockedPatternVc303(tool, args)) {
            lockedRefusalsVc303++
            sendContinuation("⛔ POLA TERKUNCI (vc303 P3): panggilan '$tool' dengan argumen ini pernah mengunci giliran sebelumnya di sesi ini — DILARANG di 3 langkah pertama giliran ini. Pakai tool/argumen/strategi yang BERBEDA, atau jawab final ke user. Jangan panggil ulang pola yang sama.")
            return
        }
        // vc272 O3: validasi skema SEBELUM anggaran langkah — penolakan
        // validasi tidak memakan langkah tool (agentSteps tidak naik di
        // sini) dan tidak dihitung StuckDetector (tanpa stuckSuffix).
        // Batas retry sama dengan penolakan REQUIRED_ARGS (maks 2x);
        // sesudah itu panggilan jatuh ke jalur normal (execute() tetap
        // memvalidasi, dan penolakan di sana mengikuti perilaku
        // REQUIRED_ARGS yang sudah ada).
        val validationVc272 = Tools.validateArgs(this, tool, args)
        if (validationVc272 != null && rejectRetryCount < 2) {
            rejectRetryCount++
            autoRetryTools.add(tool)
            consecInvalid = 0
            invalidNames.clear()
            TurnMetrics.recordStep(tool, false, prootCutOf(validationVc272), argsHash(args), true)
            sendContinuation("Hasil tool $tool" + (if (callId.isNotBlank()) " [HASIL TOOL $callId]" else "") + " DITOLAK SISTEM:\n$validationVc272\n\nPERINTAH SISTEM — WAJIB DIPATUHI PADA GILIRAN INI: keluarkan ULANG blok json tool '$tool' yang sama, kali ini dengan argumen yang sudah DIPERBAIKI sesuai pesan di atas. DILARANG menjawab dengan prosa, rencana, atau pertanyaan klarifikasi pada giliran ini.", hasToolResult = true)
            return
        }
        if (!counted) {
            agentSteps++
            if (agentSteps == 1) emitPhase("act")
            turnUsedTools = true
            if (agentSteps > stepBudget) {
                pendingTool = tool to args
                pendingCallIdVc272 = callId
                // vc301 SF-C5 (Gas user 12 Nov ~14:58): dialog "Tambah 10
                // langkah lagi?" adalah perpanjangan BUDGET langkah, bukan
                // approval per-tool — syaratnya HANYA prefs askExtendSteps
                // (dipisah dari ToolGate.GATES_DISABLED; vc247 TIDAK
                // dilanggar — tidak ada gate approval yang dihidupkan
                // kembali). Syarat lama `!GATES_DISABLED && askExtendSteps`
                // membuat dialog ini mati total sejak vc247.
                val ask = getSharedPreferences("harness", MODE_PRIVATE).getBoolean("askExtendSteps", true)
                // VC303-P3-16 (LP-2): dialog +10 maks 3x per giliran (+30)
                // + opsi keras (mayExtendVc303): hanya bila ada progres
                // sejak perpanjangan terakhir (>= 1 tool sukses). Bila
                // tidak ditawarkan, alur jatuh ke cabang else-if di bawah
                // (berhenti jujur seperti ask=false) — dialognya sendiri
                // DIPERTAHANKAN (garis SF-C5), hanya dibatasi.
                if (ask && AgentPrompt.mayExtendVc303(extendCountVc303, okCountVc303(), extendOkMarkVc303)) {
                    // vc304 B2: giliran background — JANGAN tampilkan dialog
                    // +10 / float di sesi lain; parkir tawaran sampai user
                    // kembali ke sesi pemilik (switchSession menawarkan ulang
                    // via offerExtendStepsVc304). Giliran TIDAK dihentikan.
                    if (SessionBackgroundVc304.shouldParkDecision(turnActive, turnSessionId, currentSessionId)) {
                        extendOfferPendingVc304 = true
                    } else {
                        offerExtendStepsVc304()
                    }
                } else if (!capStopSentVc277) {
                    // vc277 O15(b): berhenti yang jujur — model diminta
                    // menjawab final dengan format selesai/belum, bukan
                    // diam-diam final. Sekali saja per giliran; bila model
                    // tetap memanggil tool, panggilan itu kena cabang ini
                    // lagi dan jatuh ke addBubble + finish di bawah.
                    capStopSentVc277 = true
                    pendingTool = null
                    val taskVc277 = currentTurnUser.ifBlank { lastUserText }.take(300)
                    sendContinuation("⛔ CAP LANGKAH TERCAPAI — kamu BERHENTI DI TENGAH pada langkah $agentSteps dari $stepBudget untuk tugas: $taskVc277. Jawab FINAL sekarang dengan jujur, format persis: \"berhenti di tengah pada langkah $agentSteps dari tugas $taskVc277 — ini yang sudah selesai: …; ini yang belum: …\". Sebutkan dari kartu tool di atas apa yang sudah selesai dan apa yang belum. JANGAN panggil tool lagi — panggilan tool berikutnya akan ditolak.")
                } else {
                    pendingTool = null
                    addBubble("⛔ Dihentikan: batas $stepBudget langkah tool per perintah tercapai dan app tidak di depan. Hasil sementara ada di kartu-kartu tool di atas. (Naikkan batasnya di Setup tombol 26.)", false, turn = true)
                    TurnMetrics.finish(this, "anggaran-langkah")
                }
                return
            }
        }
        // vc316 N9-B1/C1: konfirmasi KHUSUS op Concat yang merusak — cek
        // di sini, SEBELUM early-return gerbang mati di bawah, supaya
        // berlaku SELAGI GATES_DISABLED=true (bila gerbang hidup, WRITE
        // Concat sudah REVIEW lewat jalur normal di bawah, jadi tidak
        // ditanya dua kali). Ini BUKAN gerbang (tetap mati) dan BUKAN
        // HIGH+PIN: dialog Ya/Batal sekali per panggilan; tanpa
        // konfirmasi, tool TIDAK dieksekusi (fail-closed).
        if (ToolGate.GATES_DISABLED && ConcatTools.requiresSpecialConfirmVc316(tool, args)) {
            askConcatDestructiveConfirmVc316(tool, args, callId)
            return
        }
        // vc247: gate dimatikan — lewati seluruh cabang persetujuan di
        // bawah (autoAllow, mandat, dialog/PIN, parkir notifikasi).
        if (ToolGate.GATES_DISABLED) { execToolAndContinue(tool, args, callId); return }
        if (Tools.isRisky(tool, args)) {
            val prefsR = getSharedPreferences("harness", MODE_PRIVATE)
            val autoAllow = prefsR.getStringSet("autoAllowTools", emptySet()) ?: emptySet()
            // vc229 R-04(a)(b): autoAllow dicek SEBELUM mandat, tapi kini lewat
            // gerbang yang sama dengan kunci vc227 (kelas terkunci diblokir,
            // TTL 24 jam, ikatan sesi). Entri tak valid di-pruning diam-diam.
            // vc304 B2: ikatan sesi approval/mandat adalah SESI PEMILIK
            // giliran (turnSessionId), bukan sesi aktif saat ini — giliran
            // background tidak boleh jalan lewat autoAllow/mandat sesi lain.
            if (tool in autoAllow) {
                if (ApprovalPanelStore.autoAllowValid(this, tool, turnSessionId)) { execToolAndContinue(tool, args); return }
                try { val pruned = HashSet(autoAllow); pruned.remove(tool); prefsR.edit().putStringSet("autoAllowTools", pruned).apply(); ApprovalPanelStore.revokeAutoAllow(this, tool) } catch (e: Exception) {}
            }
            // vc226 Panel Approval: mandat aktif (jalur chat tidak punya roomId,
            // scope utama = sessionId) -> jalan tanpa dialog, tanpa posting chat.
            // vc229 R-04(e): mandat dicek sadar tool + argumen (kolom syarat).
            if (ApprovalPanelStore.hasActiveMandateForTool(this, "", turnSessionId, tool, args)) { execToolAndContinue(tool, args); return }
            // vc304 B2: giliran background yang butuh approval HARUS parkir —
            // jangan daftarkan panel/dialog di sesi lain, jangan auto-approve,
            // jangan eksekusi HIGH tanpa PIN (lubang H-K1). Menunggu user
            // kembali ke sesi pemilik (switchSession memanggil ulang
            // proceedTool dengan tool/args yang diparkir). Cabang ini mati
            // selama ToolGate.GATES_DISABLED = true — gerbang ini pertahanan
            // bila gate dihidupkan lagi.
            if (SessionBackgroundVc304.shouldParkDecision(turnActive, turnSessionId, currentSessionId)) {
                approvalParkedVc304 = Triple(tool, args, callId)
                return
            }
            runOnUiThread {
                val pinHash = prefsR.getString("pinHash", "") ?: ""
                // vc226: daftarkan ke Panel Approval (tanpa posting pesan chat).
                // Callback hanya dipakai panel; dialog/float menjalankan
                // kelanjutannya sendiri + markResolved (tidak ganda).
                val panelReq = ToolGate.describe(tool, args, this@MainActivity)
                val panelSummary = (if (panelReq.preview.isNotBlank()) panelReq.preview else tool).take(140)
                val panelId = ApprovalPanelStore.register(this, "", turnSessionId, "DeepSeek", tool,
                    panelSummary, if (tool == "create_skill") panelReq.explanation + "\n" + Tools.skillUpdateDiff(this, args).take(400) else panelReq.explanation, argsFull = args.toString()) { approved ->
                    if (approved) execToolAndContinue(tool, args, callId)
                    else { addMsg("⏹️ $tool tidak dijalankan (ditolak user).", "meta", turn = true); sendContinuation("User MENOLAK aksi tool $tool. Jangan coba lagi aksi itu; jawab user dengan penjelasan / alternatif.") } // vc232 S9 tahap 1
                }
                var floatHandled = false
                if (!activityResumed) {
                    // v4.10.4 IZIN MELAYANG: app tidak di depan — dialog activity
                    // tampil tak terlihat & menggantung (kasus user 2026-10-23:
                    // persetujuan go_back menunggu 26 menit). Popup melayang
                    // global mengambil alih; PIN tetap hanya di dalam app.
                    val reqF = ToolGate.describe(tool, args, this@MainActivity)
                    val pinNeededF = ToolGate.needsPin(tool, pinHash.isNotBlank(), args, this@MainActivity)
                    val shownF = ApprovalFloat.show(applicationContext, "Izinkan aksi?",
                        "DeepSeek ingin menjalankan: $tool\n" + ToolGate.label(reqF.risk) + (if (reqF.preview.isNotBlank()) "\nPratinjau: ${reqF.preview}" else "") + "\n" + reqF.explanation + (if (reqF.affected.isNotEmpty()) "\nSasaran: ${reqF.affected.joinToString(", ")}" else "") + "\nArgumen: $args" + (if (tool == "create_skill") "\n\nDIFF vs skill aktif lama:\n" + Tools.skillUpdateDiff(this, args) else ""),
                        "Izinkan", "Tolak", pinNeededF,
                        // vc304 B2: float bisa diketuk SESUDAH user pindah sesi —
                        // persetujuan hanya berlaku di sesi pemilik; bila sesi
                        // sudah beda, parkir lagi (bukan eksekusi / tolak dari
                        // sesi lain — HIGH tanpa PIN dilarang, lubang H-K1).
                        onApprove = { if (!SessionBackgroundVc304.renderAllowed(turnSessionId, currentSessionId)) approvalParkedVc304 = Triple(tool, args, callId) else { ApprovalPanelStore.markResolved(this, panelId, true, "popup melayang"); execToolAndContinue(tool, args) } },
                        onReject = { if (!SessionBackgroundVc304.renderAllowed(turnSessionId, currentSessionId)) approvalParkedVc304 = Triple(tool, args, callId) else { ApprovalPanelStore.markResolved(this, panelId, false, "popup melayang"); addMsg("⏹️ $tool tidak dijalankan (ditolak user).", "meta", turn = true); sendContinuation("User MENOLAK aksi tool $tool (dari popup persetujuan melayang). Jangan coba lagi aksi itu; jawab user dengan penjelasan / alternatif.") } }, // vc232 S9 tahap 1
                        onOpenApp = {
                            try { startActivity(Intent(this@MainActivity, MainActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) } catch (e: Exception) {}
                            android.os.Handler(android.os.Looper.getMainLooper()).postDelayed({ try { proceedTool(tool, args, true, callId) } catch (e: Exception) {} }, 700)
                        })
                    if (shownF) {
                        floatHandled = true
                    } else {
                        try {
                            val parkedVc242 = BgBrain.parkExternal(this, currentTurnUser, "User: " + currentTurnUser, tool, args)
                            if (parkedVc242) {
                                // vc226: approval pindah ke jalur parkir notifikasi
                                // (bukan panel) -> tarik dari panel agar tidak menggantung.
                                ApprovalPanelStore.withdraw(this, panelId, "diparkir ke notifikasi (app tidak di depan, overlay tidak tersedia)")
                                sendContinuation("Tool $tool butuh persetujuan, tetapi app sedang tidak di depan dan popup melayang tidak tersedia (izin overlay mati). Permintaan sudah DIPARKIR ke notifikasi persetujuan Otak Latar (Setujui/Tolak) dan panel melayang; tugas dilanjutkan dari sana setelah user memutuskan. Sampaikan ini singkat ke user dan akhiri giliran ini.")
                            } else {
                                sendContinuation("Tool $tool butuh persetujuan, tetapi antrean persetujuan Otak Latar PENUH (maks 8) — tugas TIDAK diparkir dan tool tidak dijalankan. Kurangi antrean (setujui/tolak parkir yang menggantung) lalu picu ulang tugasnya.")
                            }
                        } catch (e: Exception) {}
                        floatHandled = true
                    }
                }
                if (!floatHandled) {
                val box = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(8), dp(16), dp(4)) }
                val req = ToolGate.describe(tool, args, this@MainActivity)
                val skillDiffVc228 = if (tool == "create_skill") Tools.skillUpdateDiff(this, args) else ""
                box.addView(TextView(this).apply { text = "DeepSeek ingin menjalankan: $tool\n" + ToolGate.label(req.risk) + (if (req.preview.isNotBlank()) "\nPratinjau: ${req.preview}" else "") + "\n" + req.explanation + (if (req.affected.isNotEmpty()) "\nSasaran: ${req.affected.joinToString(", ")}" else "") + "\nArgumen: $args" + (if (skillDiffVc228.isNotBlank()) "\n\nDIFF vs skill aktif lama:\n" + skillDiffVc228 else ""); setTextColor(TEXT) })
                var pinField: EditText? = null
                if (ToolGate.needsPin(tool, pinHash.isNotBlank(), args, this@MainActivity)) {
                    pinField = EditText(this).apply {
                        hint = "PIN aksi sensitif"
                        inputType = android.text.InputType.TYPE_CLASS_NUMBER or android.text.InputType.TYPE_NUMBER_VARIATION_PASSWORD
                        setTextColor(TEXT); setHintTextColor(DIM)
                    }
                    box.addView(pinField)
                }
                val alwaysBox = CheckBox(this).apply { text = "Selalu izinkan tool ini (jangan tanya lagi)"; setTextColor(DIM); textSize = 12f }
                box.addView(alwaysBox)
                val approvalDlg = AlertDialog.Builder(this)
                    .setTitle("Izinkan aksi?")
                    .setView(ScrollView(this).apply { addView(box) })
                    .setPositiveButton("Izinkan") { _, _ ->
                        // vc304 B2: user memutuskan di sini — tawaran parkir
                        // tidak berlaku lagi (giliran lanjut dari keputusan ini).
                        approvalParkedVc304 = null
                        val pinTyped = pinField?.text?.toString() ?: ""
                        if (pinField != null && pinTyped.isBlank()) {
                            // Kasus nyata 2026-10-22: user menekan Izinkan tanpa
                            // mengisi PIN, model lalu mengarang narasi "PIN salah".
                            Toast.makeText(this, "PIN belum diisi — aksi belum jalan.", Toast.LENGTH_LONG).show()
