                    }
                    .setNegativeButton("Tolak") { _, _ ->
                        // vc304 B2: user memutuskan di sini (lihat positif).
                        approvalParkedVc304 = null
                        ApprovalPanelStore.markResolved(this, panelId, false, "dialog dalam app")
                        addMsg("⏹️ $tool tidak dijalankan (ditolak user).", "meta", turn = true) // vc232 S9 tahap 1
                        sendContinuation("User MENOLAK aksi tool $tool. Jangan coba lagi aksi itu; jawab user dengan penjelasan / alternatif.")
                    }
                    .create()
                // vc304 B2: catat tawaran yang sedang tampil — bila user
                // pindah sesi selagi dialog tampil, switchSession menutup
                // dialognya DAN tawaran tetap diparkir (ditawarkan ulang
                // saat kembali ke sesi pemilik); tombol di atas yang
                // memutuskan akan membersihkannya lebih dulu.
                approvalParkedVc304 = Triple(tool, args, callId)
                activeToolDialogVc246 = approvalDlg
                try {
                    if (isFinishing || isDestroyed) throw IllegalStateException("activity tidak aktif")
                    approvalDlg.show()
                } catch (e: Exception) {
                    // vc304 B2: dialog tidak tampil — keputusan pindah ke
                    // jalur parkir notifikasi (di bawah), bukan ke dialog.
                    approvalParkedVc304 = null
                    try {
                        val parkedVc242 = BgBrain.parkExternal(this, currentTurnUser, "User: " + currentTurnUser, tool, args)
                        if (parkedVc242) {
                            // vc226: sama seperti jalur float gagal — tarik dari panel.
                            ApprovalPanelStore.withdraw(this, panelId, "diparkir ke notifikasi (dialog tidak bisa tampil)")
                            sendContinuation("Tool $tool butuh persetujuan, tetapi app sedang tidak di depan sehingga dialog persetujuan tidak bisa tampil. Permintaan sudah DIPARKIR ke notifikasi persetujuan Otak Latar (Setujui/Tolak) dan panel melayang; tugas dilanjutkan dari sana setelah user memutuskan. Sampaikan ini singkat ke user dan akhiri giliran ini.")
                        } else {
                            sendContinuation("Tool $tool butuh persetujuan, tetapi antrean persetujuan Otak Latar PENUH (maks 8) — tugas TIDAK diparkir dan tool tidak dijalankan. Kurangi antrean (setujui/tolak parkir yang menggantung) lalu picu ulang tugasnya.")
                        }
                    } catch (e2: Exception) {}
                }
                }
            }
        } else {
            execToolAndContinue(tool, args)
        }
    }

    private fun handlePlannerTool(tool: String, args: JSONObject) {
        // vc282: validasi skema O3 menutup celah bypass — jalur 1-1 ini
        // dipanggil SEBELUM proceedTool, jadi validateArgs di sana tidak
        // pernah menyentuh make_plan/update_plan. Penolakan tidak memakan
        // langkah; model diminta perbaiki dan panggil ulang.
        val validationVc282 = Tools.validateArgs(this, tool, args)
        if (validationVc282 != null) {
            runOnUiThread { sendContinuation("Hasil tool $tool DITOLAK SISTEM:\n$validationVc282\n\nPERINTAH SISTEM — WAJIB DIPATUHI PADA GILIRAN INI: keluarkan ULANG blok json tool '$tool' yang sama, kali ini dengan argumen yang sudah DIPERBAIKI sesuai pesan di atas. DILARANG menjawab dengan prosa, rencana, atau pertanyaan klarifikasi pada giliran ini.") }
            return
        }
        if (tool == "make_plan") {
            // v4.35.3 (T15): di giliran auto-lanjut JANGAN hapus rencana aktif.
            if (planItems.isNotEmpty() && autoContinueCount > 0) {
                val doneT15 = planItems.count { it.startsWith("☑") }
                runOnUiThread {
                    setPlanCardVc254()
                    sendContinuation("Rencana SUDAH aktif ($doneT15/${planItems.size} selesai) — JANGAN buat rencana baru. Lanjutkan dari langkah pertama yang masih ☐, dan JANGAN ulangi langkah ☑ (sudah selesai & terverifikasi).")
                }
                return
            }
            emitPhase("plan")
            planItems.clear()
            val arr = args.optJSONArray("steps")
            if (arr != null) for (i in 0 until arr.length()) planItems.add("☐ " + arr.optString(i))
            persistPlan()
            runOnUiThread {
                planCard = addActivityRow("🗺️ Rencana", planCountTextVc254(), planStepsTextVc254(), turn = true, tool = "make_plan")
                sendContinuation("Rencana tercatat (${planItems.size} langkah). Mulai langkah 1 sekarang: panggil tool yang sesuai, jangan mengulang make_plan.")
            }
        } else {
            val idx = args.optInt("index", -1)
            // vc282: index di luar rentang TIDAK BOLEH melapor "Langkah N
            // ditandai selesai" — dulu pesan itu muncul walau tidak ada
            // langkah yang ditandai (bug pesan sukses palsu).
            if (idx !in planItems.indices) {
                runOnUiThread { sendContinuation("Hasil tool update_plan DITOLAK SISTEM: index $idx di luar rencana (${planItems.size} langkah, indeks sah 0..${planItems.size - 1}). Tidak ada langkah yang ditandai. Panggil ulang update_plan dengan index yang ada di rencana aktif.") }
                return
            }
            planItems[idx] = planItems[idx].replace("☐", "☑")
            persistPlan()
            runOnUiThread {
                setPlanCardVc254()
                sendContinuation("Langkah ${idx + 1} ditandai selesai. Lanjut ke langkah berikutnya, atau jawab final bila rencana tuntas.")
            }
        }
    }

    // ---------------- J4: antrean follow-up (dari bedah Jarves) ----------------
    private fun enqueueFollowUp(text: String) {
        synchronized(followQueue) { followQueue.add(FollowUp(++followSeq, text, false)) }
        addMsg("⏳ Diantrekan (agen sedang bekerja): ${text.take(90)}", "meta")
        emitQueueEvent()
        refreshQueueChips()
    }

    /** v3.15.0: rencana persisten lintas giliran & restart app. */
    private fun persistPlan() {
        try {
            val arr = org.json.JSONArray()
            for (s in planItems) arr.put(s)
            PlanStore.write(this, currentSessionId, arr)
        } catch (e: Exception) {}
    }

    private fun restorePlan() {
        if (planItems.isNotEmpty()) return
        try {
            // vc245 GELOMBANG 4 (XL-Rencana): baca lewat PlanStore —
            // kunci sesi, fallback kunci global lama lalu kunci tool lama.
            val raw = PlanStore.read(this, currentSessionId).toString()
            if (raw.isNotBlank()) {
                val arr = org.json.JSONArray(raw)
                for (i in 0 until arr.length()) planItems.add(arr.optString(i))
            }
        } catch (e: Exception) {}
    }

    /** v3.15.0: true bila jawaban "final" ini sebenarnya berhenti di tengah pekerjaan. */
    private fun shouldAutoContinue(visible: String): Boolean {
        if (visible.contains("?")) return false
        if (planItems.any { it.startsWith("☐") }) return true
        if (!turnUsedTools) return false
        val v = visible.lowercase()
        return listOf("selanjutnya saya akan", "berikutnya saya akan", "saya akan melakukan", "akan saya lakukan", "sekarang saya akan", "saya akan melanjutkan", "langkah selanjutnya adalah").any { v.contains(it) }
    }

