    // v4.18.3: jawaban "final" yang cuma berisi sisa panggilan tool rusak.
    private fun looksMalformedToolFragment(v: String): Boolean {
        val s = v.trim()
        if (s.contains("<tool=")) return true
        if (s == "{}" || s == "{ }") return true
        if (s.contains("\"tool\"")) {
            // vc229 R-05(c): "tool" dengan kurung tak seimbang = malformed,
            // berapa pun panjangnya; JSON tool di awal jawaban final yang
            // lolos parser juga dipantulkan (bukan ditutup sebagai final).
            var depth = 0; var inStr = false; var esc = false; var sawOpen = false
            for (c in s) {
                if (esc) { esc = false; continue }
                if (c == '\\') { esc = true; continue }
                if (c == '"') { inStr = !inStr; continue }
                if (!inStr) {
                    if (c == '{') { depth++; sawOpen = true }
                    else if (c == '}') depth--
                }
            }
            if (sawOpen && depth != 0) return true
            if (s.startsWith("{")) return true
        }
        return false
    }

    /** Fase flow agentic (Brief v4): think/plan/act/verify/report ke UI React. */
    private fun emitPhase(phase: String) {
        journalPhase(phase)
        try { uiEvent(JSONObject().put("type", "chat.phase").put("phase", phase)) } catch (e: Exception) {}
    }

    private fun emitQueueEvent() {
        try {
            val arr = org.json.JSONArray()
            synchronized(followQueue) { for (f in followQueue) arr.put(JSONObject().put("id", f.id).put("text", f.text).put("steer", f.steer)) }
            uiEvent(JSONObject().put("type", "chat.queue").put("items", arr))
        } catch (e: Exception) {}
    }

    fun uiQueueSteer(id: Int) {
        runOnUiThread {
            synchronized(followQueue) { followQueue.firstOrNull { it.id == id }?.let { it.steer = !it.steer } }
            emitQueueEvent()
        }
    }

    fun uiQueueDrop(id: Int) {
        runOnUiThread {
            var removed: FollowUp? = null
            synchronized(followQueue) {
                val hit = followQueue.firstOrNull { f -> f.id == id }
                if (hit != null) { followQueue.remove(hit); removed = hit }
            }
            if (removed != null) addMsg("🗑️ Antrean dihapus: ${removed!!.text.take(60)}", "meta")
            emitQueueEvent()
        }
    }

    /** Ambil semua sisipan steer (dipanggil di titik lanjut tool kedua mesin). */
    private fun consumeSteer(): String? {
        val taken: List<FollowUp> = synchronized(followQueue) {
            val t = followQueue.filter { it.steer }
            followQueue.removeAll(t)
            t
        }
        if (taken.isEmpty()) return null
        emitQueueEvent()
        return taken.joinToString("\n") { it.text }
    }

    /** Akhir giliran user: lepas gerbang, antrean otomatis dulu, lalu follow-up. */
    private fun endUserTurn() {
        TurnMetrics.finish(this, pendingEndReason ?: "final")
        pendingEndReason = null
        // vc304 B2: giliran berakhir -> keputusan yang diparkir (bila ada)
        // tidak berlaku lagi; tawarannya tidak ditawarkan ulang.
        extendOfferPendingVc304 = false
        approvalParkedVc304 = null
        persistPlan()
        // VC303-P2-8 (CX-1): flush di akhir giliran (sesudah jawaban
        // final) — catatan tidak lagi menunggu pesan 1-1 berikut; proses
        // mati / pindah sesi sesudah ini tidak menghilangkan turnWork.
        // Idempotent: bila clearTurnCheckpoint sudah flush lebih dulu,
        // panggilan ini no-op.
        flushTurnWork(currentSessionId)
        // VC303-P2-14 (CX-9): tawaran lanjut hanya bila TIDAK ada giliran
        // antrean yang akan jalan (auto/follow-up) — dicek SEBELUM antrean
        // dikonsumsi, karena consumeAutoQueue jalan async via UI thread.
        val noQueuedVc303 = synchronized(followQueue) { followQueue.isEmpty() } && autoQueue.isEmpty()
        turnActive = false
        userTurnActive = false
        // vc306 Worker B: giliran selesai = stop hangus; composer kembali
        // ke state idle (hint asal, tombol mic, pill otomasi ke baris atas).
        stopRequestedVc306 = false
        refreshComposerButtonsVc306()
        refreshLiveCard()
        refreshQueueChips()
        consumeAutoQueue()
        if (!turnActive) drainFollowQueue()
        if (noQueuedVc303 && !turnActive) offerResumeVc303()
        // vc308 Worker C (BUG 4): ganti tema yang sempat ditunda karena
        // giliran berjalan — terapkan sekarang (dicek ulang + dijeda di
        // dalam, supaya giliran lanjutan tidak terbunuh).
        maybeApplyPendingThemeVc308()
    }

    private fun drainFollowQueue() {
        val next: FollowUp? = synchronized(followQueue) { if (followQueue.isEmpty()) null else followQueue.removeAt(0) }
        if (next == null) return
        emitQueueEvent()
        drainingFollow = true
        try { onUserMessage(next.text) } finally { drainingFollow = false }
    }

    private fun consumeAutoQueue() {
        if (autoQueue.isEmpty()) return
        val next = autoQueue.removeFirst()
        runOnUiThread {
            addBubble("▶️ Menjalankan tugas otomatis: $next", false)
            onUserMessage(next)
        }
    }

    internal fun sha256Hex(s: String): String {
        val d = java.security.MessageDigest.getInstance("SHA-256").digest(s.toByteArray(Charsets.UTF_8))
        val sb = StringBuilder()
        for (b in d) sb.append(String.format("%02x", b))
        return sb.toString()
    }

    // ---------- Kamera Vision live (vc217) ----------
    // Foreground saja: dialog preview Camera2. Tidak ada tangkapan background,
    // tidak ada tangkapan terjadwal, tidak ada live tanpa preview terlihat.
    // Agen TIDAK punya tool tangkap: tangkapan hanya dari tombol user atau
    // loop live yang dimulai user dengan preview terlihat.
    private var camDialog: android.app.Dialog? = null
    private var camVision: CameraVision? = null
    private var camTexture: android.view.TextureView? = null
    private var camLive = false
    private var camIntervalSec = 30
    private var camAnalyzing = false
    private var camFrameNo = 0
    private var camLastDesc = ""
    private var camFail = 0
    private var camLastOkVc230 = 0
    private var camBusyVc230 = 0
    private var camQuestion = ""
    private var camPendingAutoLive = false
    private var camStatusTv: TextView? = null
    private var camIntervalTv: TextView? = null
    private var camLiveBtn: Button? = null
    private var camCaptureBtn: Button? = null
    private val camHandler = Handler(Looper.getMainLooper())
    private val camLiveTick = object : Runnable {
        override fun run() {
            if (!camLive) return
            camHandler.postDelayed(this, camIntervalSec * 1000L)
            val v = camVision
            if (v == null || !v.isOpen || camAnalyzing) return
            v.captureStill({ bytes ->
                val f = CameraVision.saveCapture(bytes, "live")
                camAnalyzing = true
                analyzeLiveFrame(bytes, f)
            }, { err ->
                if (err.contains("sibuk")) { camBusyVc230 += 1; try { GraphDb.get(applicationContext).getOrCreateEpisode(currentSessionId.toString(), "observasi", "Kamera live tangkap frame: GAGAL (sibuk), tidak teramati", "camera-live") } catch (e2: Exception) {}; return@captureStill }
                addBubble("⚠️ Tangkap frame live gagal: $err", false)
            })
        }
    }

    private fun refreshCamButtons() {
        camLiveBtn?.text = if (camLive) "⏹️ Stop Live" else "▶️ Mulai Live"
        camCaptureBtn?.isEnabled = !camLive
        // vc246 GELOMBANG 5 (FT-m8): tombol jepret yang nonaktif saat live
        // kini membawa penjelasan (dulu nonaktif tanpa keterangan).
        camCaptureBtn?.contentDescription = if (camLive) "Jepret nonaktif saat live — frame live yang berjalan dipakai sebagai jepret; hentikan live dulu untuk jepret manual." else "Tangkap foto"
        camIntervalTv?.text = "Interval: ${camIntervalSec} dtk (min 10 dtk)"
    }

    private fun setCamInterval(v: Int, announce: Boolean) {
        camIntervalSec = v.coerceIn(10, 300)
        refreshCamButtons()
        if (announce) addBubble("⏱️ Interval kamera live diubah jadi ${camIntervalSec} dtk.", false)
    }

    private fun openCameraVision(autoLive: Boolean) {
        if (camDialog?.isShowing == true) {
            if (autoLive && !camLive) startLive()
            return
        }
        if (!CameraVision.hasCamera(this)) {
            addBubble("⚠️ Perangkat ini tidak punya kamera yang bisa dipakai — kamera tidak dibuka.", false)
            return
        }
        camPendingAutoLive = autoLive
        if (checkSelfPermission(android.Manifest.permission.CAMERA) != PackageManager.PERMISSION_GRANTED) {
            AlertDialog.Builder(this)
                .setTitle("Izin kamera")
                .setMessage("Harness butuh izin kamera supaya kamu bisa memotret dari chat dan memakai mode kamera live. Foto hanya diambil saat kamu menekan Tangkap atau saat live yang kamu mulai sendiri dengan preview terlihat — tidak pernah diam-diam di background.")
                .setPositiveButton("Minta Izin") { _, _ ->
                    try {
                        requestPermissions(arrayOf(android.Manifest.permission.CAMERA), 9101)
                    } catch (e: Exception) {
                        addBubble("⚠️ Gagal meminta izin kamera: ${e.message}", false)
                    }
                }
                .setNegativeButton("Batal", null)
                .show()
            return
        }
        showCameraDialog(autoLive)
    }

