            camStatusTv?.text = if (camLive) "🎥 Live aktif — preview terlihat." else "✅ Preview siap — tekan Tangkap atau Mulai Live."
            refreshCamButtons()
            if (camPendingAutoLive) {
                camPendingAutoLive = false
                startLive()
            }
        }, { err ->
            camStatusTv?.text = "⚠️ Kamera gagal: $err"
            addBubble("⚠️ Kamera tidak bisa dibuka: $err", false)
            try {
                dlg.dismiss()
            } catch (e: Exception) {
            }
        })
        refreshCamButtons()
    }

    private fun captureCameraPhoto() {
        val v = camVision
        if (v == null || !v.isOpen) {
            Toast.makeText(this, "Tunggu preview kamera siap dulu.", Toast.LENGTH_SHORT).show()
            return
        }
        if (pendingAttachesVc212.size >= 5) {
            Toast.makeText(this, "Maks 5 lampiran per kirim — kirim dulu yang ditahan.", Toast.LENGTH_LONG).show()
            return
        }
        camStatusTv?.text = "📷 Menangkap…"
        v.captureStill({ bytes ->
            val f = CameraVision.saveCapture(bytes, "cap")
            if (f == null) {
                camStatusTv?.text = "⚠️ Foto gagal disimpan."
                Toast.makeText(this, "Foto gagal disimpan.", Toast.LENGTH_SHORT).show()
                return@captureStill
            }
            camStatusTv?.text = "✅ Foto ditangkap: ${f.name}"
            camDialog?.dismiss()
            pendingAttachesVc212.add(PendingAttachVc212(android.net.Uri.fromFile(f), f.name, "image/jpeg"))
            refreshAttachStripVc212()
            refreshSendVisibilityVc212()
            showTab("Chat")
            addBubble("📷 Foto ditangkap: ${f.name} — tulis konteks, lalu tap ➤ untuk mengirim ke agen. Foto tidak dikirim tanpa konteks.", false)
            Toast.makeText(this, "Foto ditahan — tulis konteks, lalu tap ➤.", Toast.LENGTH_SHORT).show()
        }, { err ->
            camStatusTv?.text = "⚠️ Tangkap gagal: $err"
            Toast.makeText(this, "Tangkap gagal: $err", Toast.LENGTH_SHORT).show()
        })
    }

    private fun startLive() {
        if (camLive) return
        val v = camVision
        if (v == null || !v.isOpen) {
            Toast.makeText(this, "Tunggu preview kamera siap dulu.", Toast.LENGTH_SHORT).show()
            return
        }
        if (apiClient == null) {
            addBubble("⚠️ Mode live butuh tab Web yang sudah login — buka tab Web dan login DeepSeek dulu, lalu mulai lagi.", false)
            return
        }
        val apiOn = try {
            getSharedPreferences("harness", MODE_PRIVATE).getBoolean("apiMode", false)
        } catch (e: Exception) {
            false
        }
        if (!apiOn) {
            addBubble("⚠️ Mode live butuh API Internal aktif — nyalakan di Setup (Mode Chat: API Internal) dulu, lalu mulai lagi.", false)
            return
        }
        val (pct, charging) = cameraBattery()
        if (pct in 0..19 && !charging) {
            addBubble("⚠️ Live ditolak: baterai $pct% dan tidak dicas (gerbang baterai 20%, sama seperti Otak Latar) — colok charger dulu.", false)
            return
        }
        if (::chatInput.isInitialized) {
            val q = chatInput.text.toString().trim()
            if (q.isNotEmpty()) {
                camQuestion = q
                chatInput.setText("")
            } else {
                camQuestion = ""
            }
        }
        camLive = true
        camFrameNo = 0
        camFail = 0
        camLastDesc = ""
        camStatusTv?.text = "🎥 Live aktif — interval ${camIntervalSec} dtk."
        refreshCamButtons()
        addBubble("🎥 Live kamera dimulai — interval ${camIntervalSec} dtk (min 10 dtk). Tiap frame = 1 panggilan vision. Ketuk ⏹️ Stop Live atau kirim 'stop kamera live' untuk berhenti.", false)
        camHandler.post(camLiveTick)
    }

    private fun stopLive(reason: String?) {
        if (!camLive) return
        camLive = false
        camHandler.removeCallbacks(camLiveTick)
        camStatusTv?.text = "⏹️ Live berhenti."
        refreshCamButtons()
        if (reason != null) addBubble("⏹️ Live kamera berhenti. $reason", false)
    }

    private fun stopCameraVisionSilent() {
        camLive = false
        camHandler.removeCallbacks(camLiveTick)
        try {
            camDialog?.dismiss()
        } catch (e: Exception) {
        }
    }

    private fun cameraBattery(): Pair<Int, Boolean> {
        var pct = -1
        var charging = false
        try {
            val bm = getSystemService(Context.BATTERY_SERVICE) as android.os.BatteryManager
            pct = bm.getIntProperty(android.os.BatteryManager.BATTERY_PROPERTY_CAPACITY)
        } catch (e: Exception) {
        }
        try {
            val intent = registerReceiver(null, android.content.IntentFilter(android.content.Intent.ACTION_BATTERY_CHANGED))
            if (intent != null) {
                if (pct < 0) {
                    val level = intent.getIntExtra(android.os.BatteryManager.EXTRA_LEVEL, -1)
                    val scale = intent.getIntExtra(android.os.BatteryManager.EXTRA_SCALE, -1)
                    if (level >= 0 && scale > 0) pct = (level * 100 / scale)
                }
                val status = intent.getIntExtra(android.os.BatteryManager.EXTRA_STATUS, -1)
                charging = status == android.os.BatteryManager.BATTERY_STATUS_CHARGING || status == android.os.BatteryManager.BATTERY_STATUS_FULL
            }
        } catch (e: Exception) {
        }
        return Pair(pct, charging)
    }

    private fun analyzeLiveFrame(bytes: ByteArray, file: File?) {
        camFrameNo += 1
        val n = camFrameNo
        val time = java.text.SimpleDateFormat("HH:mm", java.util.Locale.US).format(java.util.Date())
        val baseQ = if (camQuestion.isNotBlank()) camQuestion else "Deskripsikan apa yang terlihat di kamera sekarang."
        val gapVc230 = if (camFail > 0) "frame sebelumnya GAGAL diamati (deskripsi sebelumnya tidak bisa dipercaya untuk frame yang gagal itu). " else ""
        val prompt = baseQ + "\n\n(Frame live kamera ke-$n, pukul $time. " + gapVc230 + "Deskripsi frame sebelumnya: " + (if (camLastDesc.isBlank()) "-" else camLastDesc.take(500)) + ". Tugas: deskripsikan apa yang terlihat sekarang secara singkat dan faktual; bila ada perubahan dari frame sebelumnya, sebutkan perubahannya dulu; bila pertanyaan di atas bersifat spesifik atau ya-tidak, jawab itu dulu. Jangan mengidentifikasi individu — deskripsikan objek dan aktivitas saja.)"
        val thinking = isDeepPhotoRequestVc212(camQuestion)
        try {
            apiClient?.uploadFileAndAsk(bytes, "live-frame.jpg", "image/jpeg", prompt, thinking, { answer ->
                runOnUiThread {
                    camAnalyzing = false
                    camFail = 0
                    camLastOkVc230 = n
                    camLastDesc = answer.take(1000)
                    addBubble("🎥 Live #$n [$time]: $answer", false)
                    try {
                        GraphDb.get(this).getOrCreateEpisode(currentSessionId.toString(), "observasi", "Kamera live frame #$n" + (if (file != null) " (file: ${file.name})" else "") + ": " + answer.take(800), "camera-live")
                    } catch (e: Exception) {
                    }
                    val (pct, charging) = cameraBattery()
                    if (pct in 0..19 && !charging) stopLive("baterai di bawah 20% dan tidak dicas")
                }
            }, { err ->
                runOnUiThread {
                    camAnalyzing = false
                    if (err.contains("masih ada jawaban")) return@runOnUiThread
                    camFail += 1
                    try { GraphDb.get(this).getOrCreateEpisode(currentSessionId.toString(), "observasi", "Kamera live frame #$n: GAGAL — $err, tidak teramati", "camera-live") } catch (e2: Exception) {}
                    addBubble("⚠️ Frame live #$n gagal: $err", false)
                    if (camFail >= 3) stopLive("3 frame gagal berturut-turut")
                }
            }, { })
        } catch (e: Exception) {
            camAnalyzing = false
            camFail += 1
            try { GraphDb.get(this).getOrCreateEpisode(currentSessionId.toString(), "observasi", "Kamera live frame #$n: GAGAL — ${e.message}, tidak teramati", "camera-live") } catch (e2: Exception) {}
            addBubble("⚠️ Frame live #$n gagal: ${e.message}", false)
        }
    }

    private fun handleCameraCommand(text: String): Boolean {
        val low = text.trim().lowercase()
        return when {
            low == "mulai kamera live" || low == "mode kamera live" || low == "buka kamera live" -> {
                addBubble(text, true)
                openCameraVision(true)
                true
            }
            low == "stop kamera live" || low == "hentikan kamera live" || low == "matikan kamera live" -> {
                addBubble(text, true)
                if (camLive) stopLive("dihentikan lewat chat") else addBubble("Kamera live sedang tidak aktif.", false)
                true
            }
            low.startsWith("interval kamera live ") -> {
                val num = low.removePrefix("interval kamera live ").removeSuffix("detik").trim().toIntOrNull()
                addBubble(text, true)
                if (!camLive) {
                    addBubble("Live belum aktif — mulai dulu lewat tombol 📷 di composer atau kirim 'mulai kamera live'.", false)
                } else if (num == null) {
                    addBubble("Format interval: 'interval kamera live 15 detik' (min 10 dtk, maks 300 dtk).", false)
                } else {
                    setCamInterval(num, true)
                }
                true
            }
            else -> false
        }
    }

    /** Analisa foto: kecilkan -> base64 -> lampirkan ke chat Web -> tanya DeepSeek. */
    // vc304 B2: param `turn = true` = dipanggil sebagai tool giliran
    // (execToolAndContinue) — baris aktivitas + bubble-nya di-gate ke sesi
    // pemilik. Jalur lampiran user (handleAttachment/fallback) memakai
    // default false: itu output UI sesi aktif, bukan output giliran.
    private fun analyzePhotoAndContinue(args: JSONObject, turn: Boolean = false) {
        // vc282: validasi skema O3 di pintu masuk — menutup celah bypass
        // (pemanggil langsung dari UI/PDF tidak lewat proceedTool).
        // Argumen app-built selalu valid, jadi perilaku lama tak berubah.
        val validationVc282 = Tools.validateArgs(this, "analyze_photo", args)
        if (validationVc282 != null) {
            runOnUiThread { sendContinuation("Hasil tool analyze_photo DITOLAK SISTEM:\n$validationVc282\n\nPERINTAH SISTEM — keluarkan ULANG blok json tool 'analyze_photo' dengan argumen yang sudah DIPERBAIKI sesuai pesan di atas.") }
            return
        }
        val path = args.optString("path")
        val wantThinkPhoto = args.optBoolean("thinking", false) || isDeepPhotoRequestVc212(args.optString("question", ""))
        val question = args.optString("question", "Jelaskan isi gambar ini secara detail.") +
            "\n\n(Format jawaban WAJIB: ringkas dan terstruktur. Pakai baris baru antar poin, daftar bernomor atau poin-poin pendek, maksimal 6 bagian. JANGAN menulis satu paragraf panjang yang menumpuk.)"
        // vc254: gelembung status "Menyiapkan foto" diganti baris
        // aktivitas analyze_photo (diperbarui di tiap titik akhir).
        val t0PhotoVc254 = System.currentTimeMillis()
        lateinit var photoRowVc254: ActivityRowHandle
        runOnUiThread { photoRowVc254 = addActivityRow(ActivityTitle.title("analyze_photo", args), "menjalankan…", "Argumen: " + ActivityTitle.shortArgs("analyze_photo", args), turn = turn, tool = "analyze_photo") }
        Thread {
            try {
                val bmp = android.graphics.BitmapFactory.decodeFile(path)
                    ?: throw Exception("File gambar tidak terbaca: $path")
                val scale = 1280.0 / maxOf(bmp.width, bmp.height)
                val small = if (scale < 1.0) android.graphics.Bitmap.createScaledBitmap(
                    bmp, (bmp.width * scale).toInt(), (bmp.height * scale).toInt(), true) else bmp
                val bos = java.io.ByteArrayOutputStream()
                small.compress(android.graphics.Bitmap.CompressFormat.JPEG, 80, bos)
                val jpegBytes = bos.toByteArray()
                val b64 = android.util.Base64.encodeToString(jpegBytes, android.util.Base64.NO_WRAP)
                // v4.10.3: foto lewat API INTERNAL (perintah user 2026-10-23 10:02)
                // — berkas diunggah lalu dibaca di SESI SERVER YANG SAMA. Jalur Web
                // lama membuka sesi chat baru sendiri ("Penjelasan Gambar Aplikasi");
                // kini jalur Web hanya cadangan bila API gagal.
                val useApi = try {
                    AgentEngines.current(this@MainActivity) == "deepseek" &&
                        getSharedPreferences("harness", MODE_PRIVATE).getBoolean("apiMode", false)
                } catch (e: Exception) { false }
                if (useApi) {
                    // B13: klien DeepSeek bisa belum ada (startup openai +
                    // alih engine saat jalan) — jatuh ke jalur Web yang
                    // gagal jujur bila klien tetap tidak ada.
                    val dsClientPhoto = apiClient ?: if (ensureDsClients()) apiClient else null
                    if (dsClientPhoto == null) {
                        runOnUiThread { webAnalyzePhoto(b64, question, photoRowVc254, t0PhotoVc254, args, turn) }
                    } else dsClientPhoto.uploadFileAndAsk(jpegBytes, "harness-photo.jpg", "image/jpeg", question, wantThinkPhoto, { answer ->
                        runOnUiThread {
                            endStreamBubble()
                            showTab("Chat")
                            renderPendingAskVc229()
                            val msPhotoVc254 = System.currentTimeMillis() - t0PhotoVc254
                            photoRowVc254.status = ActivityTitle.statusText(msPhotoVc254, true)
                            photoRowVc254.detail = "Argumen: " + ActivityTitle.shortArgs("analyze_photo", args) + "\nHasil: " + ActivityTitle.resultTail(answer, 600)
                            // VC303-P2-15 (CX-12): simpan jawaban ke ResultStore seperti
                            // tool lain — baris WorkNotes analyze_photo kini punya R-id
                            // (bukan [-]) + total char; args sudah memuat path foto
                            // (formatLine memakai path bila ada).
                            val ridPhotoVc303 = try { ResultStore.put(this@MainActivity, "analyze_photo", answer) } catch (e: Exception) { "" }
                            turnWork.add(WorkItem("analyze_photo", msPhotoVc254, true, answer.take(120), evidence = answer.take(600), args = args.toString().take(4000), resultId = ridPhotoVc303, totalChars = answer.length))
                            sendContinuation("Hasil tool analyze_photo (via API internal, sesi yang sama):\n" + answer + "\n\nSampaikan hasil analisa ini ke user dan lanjutkan tugasmu.")
                        }
                    }, { err ->
                        runOnUiThread {
                            addBubble("⚠️ Foto via API internal gagal — jatuh ke jalur Web. ($err)", false, turn = turn)
                            photoRowVc254.status = "jalur API gagal — mencoba jalur Web…"
                            webAnalyzePhoto(b64, question, photoRowVc254, t0PhotoVc254, args, turn)
                        }
                    }, { note ->
                        // v4.10.7: penanda sesi (♻️) tampil juga di giliran foto.
                        if (note.startsWith("♻️")) runOnUiThread { addBubble(note, false, turn = turn) }
                    })
                } else {
                    runOnUiThread { webAnalyzePhoto(b64, question, photoRowVc254, t0PhotoVc254, args, turn) }
                }
            } catch (e: Exception) {
                runOnUiThread {
                    addBubble("⚠️ Analisa foto gagal: ${e.message}", false, turn = turn)
                    renderPendingAskVc229()
                    val msPhotoVc254 = System.currentTimeMillis() - t0PhotoVc254
                    photoRowVc254.status = ActivityTitle.statusText(msPhotoVc254, false)
                    photoRowVc254.detail = "Argumen: " + ActivityTitle.shortArgs("analyze_photo", args) + "\nHasil: GAGAL — " + (e.message ?: "")
                    turnWork.add(WorkItem("analyze_photo", msPhotoVc254, false, "Foto gagal dianalisis", evidence = "GAGAL — " + (e.message ?: ""), args = args.toString().take(4000)))
                    try { GraphDb.get(applicationContext).getOrCreateEpisode(currentSessionId.toString(), "observasi", "analyze_photo GAGAL — ${e.message}, tidak teramati", "analyze_photo") } catch (e2: Exception) {}
                    sendContinuation("Hasil tool analyze_photo: GAGAL — ${e.message}. Beri tahu user: tulis persis 'foto belum berhasil dianalisis', jangan mendeskripsikan tebakan.")
                }
            }
        }.start()
    }

    /** v4.10.3: jalur Web lama untuk analyze_photo (lampiran via tab Web) —
     *  kini hanya cadangan bila jalur API internal gagal. */
    // vc254: baris + t0 + args foto diteruskan dari analyzePhotoAndContinue
    // agar titik akhir jalur Web juga memperbarui baris yang sama.
    private fun webAnalyzePhoto(b64: String, question: String, photoRowVc254: ActivityRowHandle?, t0PhotoVc254: Long, photoArgsVc254: JSONObject, turn: Boolean = false) {
        // B13: jalur Web butuh DsAgent — gagal jujur bila belum ada
        // (cermin blok gagal di bawah, supaya foto tidak diam-diam hilang).
        val webAgent = agent ?: if (ensureDsClients()) agent else null
        if (webAgent == null) {
            val errDs = "engine DeepSeek belum siap (otak = Models API)"
            endStreamBubble()
            showTab("Chat")
            addBubble("⚠️ Analisa foto gagal: $errDs", false, turn = turn)
            renderPendingAskVc229()
            val msPhotoVc254 = System.currentTimeMillis() - t0PhotoVc254
            photoRowVc254?.status = ActivityTitle.statusText(msPhotoVc254, false)
            photoRowVc254?.detail = "Argumen: " + ActivityTitle.shortArgs("analyze_photo", photoArgsVc254) + "\nHasil: GAGAL — $errDs"
            turnWork.add(WorkItem("analyze_photo", msPhotoVc254, false, "Foto gagal dianalisis", evidence = "GAGAL — $errDs", args = photoArgsVc254.toString().take(4000)))
            try { GraphDb.get(applicationContext).getOrCreateEpisode(currentSessionId.toString(), "observasi", "analyze_photo GAGAL — $errDs, tidak teramati", "analyze_photo") } catch (e2: Exception) {}
            sendContinuation("Hasil tool analyze_photo: GAGAL — $errDs. Beri tahu user: tulis persis 'foto belum berhasil dianalisis', jangan mendeskripsikan tebakan.")
            return
        }
        showTab("Web")
        webAgent.analyzeImage(b64, question, { resp ->
            endStreamBubble()
            showTab("Chat")
            val msPhotoVc254 = System.currentTimeMillis() - t0PhotoVc254
            photoRowVc254?.status = ActivityTitle.statusText(msPhotoVc254, true)
            photoRowVc254?.detail = "Argumen: " + ActivityTitle.shortArgs("analyze_photo", photoArgsVc254) + "\nHasil: Foto dianalisis — hasilnya ada di jawaban agen berikut."
            // VC303-P2-15 (CX-12): jalur Web juga menyimpan jawaban ke
            // ResultStore (resp = jawaban agen atas foto) supaya baris
            // WorkNotes punya R-id + evidence, seperti jalur API.
            val ridPhotoWebVc303 = try { ResultStore.put(this@MainActivity, "analyze_photo", resp) } catch (e: Exception) { "" }
            turnWork.add(WorkItem("analyze_photo", msPhotoVc254, true, "Foto dianalisis", evidence = resp.take(600), args = photoArgsVc254.toString().take(4000), resultId = ridPhotoWebVc303, totalChars = resp.length))
            handleAgentResponse(resp)
        }, { err ->
            endStreamBubble()
            showTab("Chat")
            addBubble("⚠️ Analisa foto gagal: $err", false, turn = turn)
            renderPendingAskVc229()
            val msPhotoVc254 = System.currentTimeMillis() - t0PhotoVc254
            photoRowVc254?.status = ActivityTitle.statusText(msPhotoVc254, false)
            photoRowVc254?.detail = "Argumen: " + ActivityTitle.shortArgs("analyze_photo", photoArgsVc254) + "\nHasil: GAGAL — $err"
            turnWork.add(WorkItem("analyze_photo", msPhotoVc254, false, "Foto gagal dianalisis", evidence = "GAGAL — $err", args = photoArgsVc254.toString().take(4000)))
            try { GraphDb.get(applicationContext).getOrCreateEpisode(currentSessionId.toString(), "observasi", "analyze_photo GAGAL — $err, tidak teramati", "analyze_photo") } catch (e2: Exception) {}
            sendContinuation("Hasil tool analyze_photo: GAGAL — $err. Beri tahu user dengan jujur dan tawarkan alternatif (mis. user lampirkan manual di tab Web). Tulis persis 'foto belum berhasil dianalisis', jangan mendeskripsikan tebakan.")
        })
    }

