    private fun readLockedPatternsVc303(sessionId: Long): List<Triple<String, String, String>> {
        val out = ArrayList<Triple<String, String, String>>()
        try {
            val raw = getSharedPreferences("harness", MODE_PRIVATE).getString("lockedPatternsVc303_" + sessionId, "") ?: ""
            for (line in raw.lines()) {
                if (line.isBlank()) continue
                val p = line.split("|", limit = 3)
                if (p.size < 3) continue
                out.add(Triple(p[0], p[1], p[2]))
            }
        } catch (e: Exception) {}
        return out
    }
    // VC303-P3-19 (LP-5a): simpan (tool, hash-args) yang pernah mengunci
    // giliran — dipanggil di 2 situs turnStuckBlocked = true (jalur tunggal
    // + batch 1-1). Maks 10 pola/sesi, yang terbaru dipertahankan.
    private fun recordLockedPatternVc303(tool: String, args: JSONObject) {
        try {
            val key = AgentPrompt.lockedPatternKeyVc303(tool, args)
            val hash = key.substringAfter("|", "?")
            val preview = try { AgentPrompt.normalizeArgsVc277(args).take(120) } catch (e: Exception) { "" }
            val cur = readLockedPatternsVc303(currentSessionId).filter { it.second != hash }.toMutableList()
            cur.add(Triple(tool, hash, preview.replace("|", "/").replace("\n", " ")))
            val trimmed = cur.takeLast(10)
            getSharedPreferences("harness", MODE_PRIVATE).edit().putString("lockedPatternsVc303_" + currentSessionId, trimmed.joinToString("\n") { it.first + "|" + it.second + "|" + it.third }).apply()
        } catch (e: Exception) {}
    }
    private fun isLockedPatternVc303(tool: String, args: JSONObject): Boolean {
        return try {
            val hash = AgentPrompt.lockedPatternKeyVc303(tool, args).substringAfter("|", "?")
            readLockedPatternsVc303(currentSessionId).any { it.first == tool && it.second == hash }
        } catch (e: Exception) { false }
    }
    private fun lockedPatternsBlockVc303(sessionId: Long): String {
        val entries = readLockedPatternsVc303(sessionId)
        if (entries.isEmpty()) return ""
        val sb = StringBuilder()
        sb.append("⛔ LARANGAN KERAS — POLA YANG PERNAH MENGUNCI GILIRAN (vc303 P3, lintas giliran — sesi ini):\n")
        for ((tool, _, preview) in entries.takeLast(5)) {
            sb.append("- ").append(tool).append(" ").append(preview).append("\n")
        }
        sb.append("JANGAN panggil tool+argumen di atas di ").append(AgentPrompt.LOCKED_PATTERN_FIRST_STEPS_VC303).append(" langkah pertama giliran ini — sistem akan menolaknya. Pakai tool/argumen/strategi yang BERBEDA, atau jawab final ke user.")
        return sb.toString()
    }
    private fun readClaimEntriesVc303(sessionId: Long): LinkedHashMap<String, Pair<Int, String>> {
        val out = LinkedHashMap<String, Pair<Int, String>>()
        try {
            val raw = getSharedPreferences("harness", MODE_PRIVATE).getString("claimFingerprintsVc303_" + sessionId, "") ?: ""
            for (line in raw.lines()) {
                if (line.isBlank()) continue
                val p = line.split("|", limit = 3)
                if (p.size < 3) continue
                out[p[0]] = (p[1].toIntOrNull() ?: 1) to p[2]
            }
        } catch (e: Exception) {}
        return out
    }
    // VC303-P3-20 (LP-6): sidik jari klaim yang kena claim-stop. Return
    // jumlah stop BERUNTUN atas klaim yang sama (stop dihitung beruntun
    // hanya bila klaim-stop sebelumnya — giliran mana pun — adalah klaim
    // yang sama; klaim lain di antaranya mereset ke 1). Gate claim-check
    // sendiri TIDAK diubah — fungsi ini hanya mencatat + menghitung.
    private fun recordClaimStopVc303(visible: String, warning: String?): Int {
        return try {
            val claims = AgentPrompt.splitClaims(visible).take(5)
            if (claims.isEmpty()) return 0
            val fps = claims.map { AgentPrompt.claimFingerprintVc303(it) to it }
            val prefs = getSharedPreferences("harness", MODE_PRIVATE)
            val stored = readClaimEntriesVc303(currentSessionId)
            val lastHash = prefs.getString("lastClaimStopHashVc303_" + currentSessionId, "") ?: ""
            val nums = warning?.let { Regex("[0-9][0-9,.]*").findAll(it).map { m -> m.value }.toList() } ?: emptyList()
            val pick = fps.firstOrNull { (_, c) -> nums.any { n -> c.contains(n) } }
                ?: fps.firstOrNull { (h, _) -> h in stored }
                ?: fps.first()
            val (hash, preview) = pick
            val prevStops = stored[hash]?.first ?: 0
            val stops = if (hash == lastHash && prevStops > 0) prevStops + 1 else 1
            stored.remove(hash)
            stored[hash] = stops to preview.take(120).replace("|", "/").replace("\n", " ")
            val trimmed = LinkedHashMap<String, Pair<Int, String>>()
            stored.entries.toList().takeLast(10).forEach { trimmed[it.key] = it.value }
            val text = trimmed.entries.joinToString("\n") { (h, v) -> h + "|" + v.first + "|" + v.second }
            prefs.edit().putString("claimFingerprintsVc303_" + currentSessionId, text).putString("lastClaimStopHashVc303_" + currentSessionId, hash).apply()
            stops
        } catch (e: Exception) { 0 }
    }
    private fun claimFingerprintsBlockVc303(sessionId: Long): String {
        val entries = readClaimEntriesVc303(sessionId)
        if (entries.isEmpty()) return ""
        val sb = StringBuilder()
        sb.append("⚠️ KLAIM YANG PERNAH KENA CLAIM-STOP (vc303 P3, lintas giliran — sesi ini):\n")
        for ((_, v) in entries.entries.toList().takeLast(5)) {
            sb.append("- \"").append(v.second).append("\" (stop ").append(v.first).append("x)\n")
        }
        sb.append("Bila klaim yang sama muncul lagi TANPA hasil tool pendukung baru, WAJIB sertakan bukti (nama tool + hasil/R-id) atau nyatakan sebagai dugaan — jangan ulangi klaim itu apa adanya. Setelah 2 stop beruntun atas klaim yang sama, MINTA KEPUTUSAN USER sebelum mencoba lagi.")
        return sb.toString()
    }
    // VC303-P3-19 (LP-5b): jejak baca per agen room + pola terkunci room.
    private fun roomAgentKeyVc303(roomId: String, effSess: String, agentName: String): String = roomId + "|" + effSess + "|" + agentName
    private fun noteRoomReadVc303(roomId: String, effSess: String, agentName: String, tool: String, args: JSONObject, result: String) {
        try {
            if (!AgentPrompt.isRereadSuccessVc279(tool, result)) return
            val key = roomAgentKeyVc303(roomId, effSess, agentName)
            val list = roomReadTraceVc303.getOrPut(key) { ArrayList() }
            val sig = tool + "|" + AgentPrompt.normalizeArgsVc277(args).take(100)
            if (sig !in list) list.add(sig)
            while (list.size > 20) list.removeAt(0)
        } catch (e: Exception) {}
    }
    private fun roomReadTraceBlockVc303(roomId: String, sessId: String, agentName: String): String {
        val list = roomReadTraceVc303[roomAgentKeyVc303(roomId, sessId, agentName)] ?: return ""
        if (list.isEmpty()) return ""
        return "JEJAK BACA RONDE INI — agen " + agentName + " (vc303 P3, per agen, bukan global):\n" + list.takeLast(10).joinToString("\n") { "- sudah dibaca: $it" } + "\nYang sudah dibaca agen ini di ronde ini JANGAN dibaca ulang — pakai hasil yang sudah ada di konteks ronde ini."
    }
    private fun recordRoomLockedPatternVc303(roomId: String, effSess: String, agentName: String, tool: String, args: JSONObject) {
        try {
            val key = AgentPrompt.lockedPatternKeyVc303(tool, args)
            val hash = key.substringAfter("|", "?")
            val preview = try { AgentPrompt.normalizeArgsVc277(args).take(120) } catch (e: Exception) { "" }
            val pkey = "lockedPatternsVc303_room_" + roomId + "_" + effSess + "_" + agentName
            val prefs = getSharedPreferences("harness", MODE_PRIVATE)
            val cur = ArrayList<Triple<String, String, String>>()
            val raw = prefs.getString(pkey, "") ?: ""
            for (line in raw.lines()) {
                if (line.isBlank()) continue
                val p = line.split("|", limit = 3)
                if (p.size < 3) continue
                cur.add(Triple(p[0], p[1], p[2]))
            }
            val kept = cur.filter { it.second != hash }.toMutableList()
            kept.add(Triple(tool, hash, preview.replace("|", "/").replace("\n", " ")))
            prefs.edit().putString(pkey, kept.takeLast(10).joinToString("\n") { it.first + "|" + it.second + "|" + it.third }).apply()
        } catch (e: Exception) {}
    }
    private fun isRoomLockedPatternVc303(roomId: String, effSess: String, agentName: String, tool: String, args: JSONObject): Boolean {
        return try {
            val hash = AgentPrompt.lockedPatternKeyVc303(tool, args).substringAfter("|", "?")
            val pkey = "lockedPatternsVc303_room_" + roomId + "_" + effSess + "_" + agentName
            val raw = getSharedPreferences("harness", MODE_PRIVATE).getString(pkey, "") ?: ""
            raw.lines().any { line -> val p = line.split("|", limit = 3); p.size >= 2 && p[0] == tool && p[1] == hash }
        } catch (e: Exception) { false }
    }
    private fun roomLockedPatternsBlockVc303(roomId: String, effSess: String, agentName: String): String {
        return try {
            val pkey = "lockedPatternsVc303_room_" + roomId + "_" + effSess + "_" + agentName
            val raw = getSharedPreferences("harness", MODE_PRIVATE).getString(pkey, "") ?: ""
            val lines = raw.lines().filter { it.isNotBlank() }.takeLast(5)
            if (lines.isEmpty()) return ""
            "⛔ LARANGAN KERAS — POLA ROOM YANG PERNAH MENGUNCI (vc303 P3, agen " + agentName + ", sesi ini):\n" + lines.joinToString("\n") { "- " + it.substringBefore("|") + " " + it.substringAfter("|").substringAfter("|", "") } + "\nJANGAN panggil pola di atas di 3 langkah pertama ronde ini — pakai pendekatan berbeda."
        } catch (e: Exception) { "" }
    }

    // v4.48.3: pengunci giliran — StuckDetector kini menegakkan, bukan menempel teks.
    private var turnStuckBlocked = false
    private var capStopSentVc277 = false // vc277 O15(b): jawaban jujur cap langkah sudah diminta sekali giliran ini
    private var unknownToolCount = 0
    private var blockedAttempts = 0
    private fun stuckSuffix(tool: String, args: JSONObject, result: String, countIdent: Boolean = true, skipStuckVc278: Boolean = false): String {
        // vc278 O18(a): pembatalan timeout TIDAK dihitung StuckDetector
        // (bukan hasil identik, bukan gagal berulang) — giliran yang
        // kehabisan waktu bukan putaran.
        if (skipStuckVc278) return ""
        // vc277 O17: tool polling yang sah dikecualikan dari detektor
        // putaran (pola + hasil identik).
        if (AgentPrompt.isPollingExemptVc277(tool)) return ""
        // vc279 O20(c): baca-ulang sukses TIDAK dihitung (pola +
        // hasil identik) — lihat AgentPrompt.isRereadSuccessVc279.
        if (AgentPrompt.isRereadSuccessVc279(tool, result)) return ""
        // vc285 Fase 0: hasil idempotent memori (duplicate / forget
        // idempotent) TIDAK dihitung — lihat AgentPrompt
        // .isIdempotentMemoryResultVc285. Ambang 3/4/5 TETAP.
        if (AgentPrompt.isIdempotentMemoryResultVc285(tool, result)) return ""
        // VC303-P3-18 (LP-4): penghitung error IDENTIK yang dikecualikan —
        // cermin StuckWatch.observe: eksplorasi bervariasi tetap bebas,
        // error identik (args + teks error sama persis) dikunci di ke-3.
        if (AgentPrompt.isPagingErrorVc301(tool, result) || AgentPrompt.isSearchNotFoundVc301(tool, result)) {
            val errSigVc303 = try { AgentPrompt.normalizeArgsVc277(args) } catch (e: Exception) { "" }
            val errKeyVc303 = "ERRIDENT|$tool|" + AgentPrompt.hash64Vc277(errSigVc303) + "|" + AgentPrompt.hash64Vc277(result.lowercase().replace(Regex("\\s+"), " ").trim())
            val enVc303 = (stuckMap[errKeyVc303] ?: 0) + 1
            stuckMap[errKeyVc303] = enVc303
            if (enVc303 >= 3) return "\n\n🛑 SISTEM (StuckDetector): panggilan '$tool' dengan argumen yang sama sudah menghasilkan error yang sama $enVc303 kali — TIDAK ADA PROGRES. BERHENTI mengulang panggilan ini sekarang juga. Jawab final ke user: laporkan apa yang sudah tercapai, di mana macetnya, dan apa yang kamu butuhkan dari user. Jangan panggil tool lagi untuk pendekatan yang sama. [VC303-P3-18]"
            return ""
        }
        // vc301 SF-C1(a): hasil error paging BUKAN putaran — lihat
        // AgentPrompt.isPagingErrorVc301. Ambang 3/4/5 TETAP.
        // (Kini hanya tercapai bila LP-4 di atas tidak mengembalikan —
        // yakni error paging/not-found yang TIDAK identik dengan
        // sebelumnya; perilaku bebas-nya tidak berubah.)
        if (AgentPrompt.isPagingErrorVc301(tool, result)) return ""
        // vc301 SF-C4: pencarian "tidak ditemukan" adalah progres — lihat
        // AgentPrompt.isSearchNotFoundVc301. Ambang 3/4/5 TETAP.
        if (AgentPrompt.isSearchNotFoundVc301(tool, result)) return ""
        // vc277 O17: kunci pola pakai HASH ARGS PENUH (bukan 48 char
        // pertama) + normalisasi (lowercase, spasi ganda jadi satu).
        val sig = try { AgentPrompt.normalizeArgsVc277(args) } catch (e: Exception) { "" }
        var loopPart = ""
        // vc302 Fix E: teks peringatan/kunci panggilan IDENTIK (diisi di
        // blok pola di bawah; "" bila bukan pengulangan identik).
        var identCallPartVc302 = ""
        if (sig.length >= 8) {
            val lk = "LOOP|$tool|" + AgentPrompt.hash64Vc277(sig)
            val ln = (stuckMap[lk] ?: 0) + 1
            stuckMap[lk] = ln
            val shellHint = if (tool == "run_terminal") " Ingat: tiap panggilan terminal adalah shell BARU — export/cd/variabel TIDAK tersimpan antar-panggilan; gabungkan setup+eksekusi dalam SATU command." else ""
            // vc302 Fix E: panggilan tool+argumen IDENTIK dikunci LEBIH
            // CEPAT — peringatan di ke-2, kunci di ke-3. Kunci LOOP di atas
            // SUDAH menghitung panggilan identik (tool + hash args penuh
            // ternormalisasi `normalizeArgsVc277` — definisi IDENTIK Vc302,
            // selaras guard Fix A worker A), jadi tidak ada penghitung
            // baru. Ambang hasil identik/mirip (3/4) dan cabang LOOP lama
            // (peringatan 3 / stop 5) TIDAK diubah. Pengecualian SF-C1
            // (error paging) tetap mendahului penghitungan (return "" di
            // atas), jadi error paging tidak pernah memicu aturan ini.
            identCallPartVc302 = when {
                ln >= 3 -> "\n\n🛑 SISTEM (StuckDetector): panggilan '$tool' dengan argumen IDENTIK sudah terulang $ln kali — TIDAK ADA PROGRES. BERHENTI mengulang panggilan ini sekarang juga. Jawab final ke user: laporkan apa yang sudah tercapai, di mana macetnya, dan apa yang kamu butuhkan dari user. Jangan panggil tool lagi untuk pendekatan yang sama. [Vc302]"
                ln == 2 -> "\n\n⚠️ SISTEM (StuckDetector): panggilan '$tool' dengan argumen IDENTIK sudah terulang 2 kali — argumen: ${sig.take(200)} — kamu mengulang panggilan yang persis sama. GANTI argumen/tool/strategi sekarang, jangan panggil ulang yang sama. [Vc302]"
                else -> ""
            }
            if (identCallPartVc302.contains("🛑")) return identCallPartVc302
            loopPart = when {
                ln >= 5 -> "\n\n🛑 SISTEM (Detektor Putaran): '$tool' dengan pola argumen serupa ini sudah dipanggil $ln kali — kamu BERPUTAR tanpa progres. BERHENTI mengulang pola ini. Pakai jalur yang sama sekali lain (tool/mode berbeda) atau jawab final ke user: apa yang sudah tercapai, di mana macetnya, dan apa yang dibutuhkan." + shellHint
                ln == 3 -> "\n\n⚠️ SISTEM (Detektor Putaran): '$tool' dengan pola argumen serupa sudah dipanggil 3 kali — indikasi berputar. GANTI pendekatan secara mendasar sekarang; jangan variasi kecil dari perintah yang sama." + shellHint
                else -> ""
            }
            if (loopPart.contains("🛑")) return loopPart
        }
        // VC303-P3-17 (LP-3): kunci kemiripan argumen level-2 — cermin
        // StuckWatch.observe (Jaccard token >= 0,8; peringatan ke-3,
        // kunci ke-4). Berjalan juga bila countIdent=false (hasil
        // unknown-tool tidak dihitung, tapi pola argumen tetap jalan).
        var fuzzyPartVc303 = ""
        run {
            val toksVc303 = AgentPrompt.fuzzyTokenSetVc303(args)
            if (toksVc303.size >= 2) {
                val setsVc303 = stuckFuzzySetsVc303.getOrPut(tool) { ArrayList() }
                var clusterVc303: String? = null
                for (sVc303 in setsVc303) {
                    if (AgentPrompt.jaccardVc303(toksVc303, sVc303) >= 0.8) {
                        clusterVc303 = "FUZZY|$tool|" + AgentPrompt.hash64Vc277(sVc303.sorted().joinToString(" "))
                        break
                    }
                }
                if (clusterVc303 != null) {
                    val cnVc303 = (stuckMap[clusterVc303] ?: 0) + 1
                    stuckMap[clusterVc303] = cnVc303
                    fuzzyPartVc303 = when {
                        cnVc303 >= 4 -> "\n\n🛑 SISTEM (StuckDetector): panggilan '$tool' dengan argumen MIRIP sudah terulang $cnVc303 kali (hanya berbeda 1-2 kata/angka) — TIDAK ADA PROGRES. BERHENTI mengulang pendekatan ini sekarang juga. Jawab final ke user: laporkan apa yang sudah tercapai, di mana macetnya, dan apa yang kamu butuhkan dari user. Jangan panggil tool lagi untuk pendekatan yang sama. [VC303-P3-17]"
                        cnVc303 == 3 -> "\n\n⚠️ SISTEM (StuckDetector): panggilan '$tool' dengan argumen MIRIP sudah terulang 3 kali (hanya berbeda 1-2 kata/angka) — indikasi berputar. GANTI pendekatan secara mendasar sekarang; jangan variasi kecil dari perintah yang sama."
                        else -> ""
                    }
                } else {
                    setsVc303.add(toksVc303)
                    // Klaster baru dihitung 1 sejak panggilan pertama
                    // (cermin penghitung LOOP) — tanpa ini peringatan
                    // baru muncul di panggilan ke-4, bukan ke-3.
                    stuckMap["FUZZY|$tool|" + AgentPrompt.hash64Vc277(toksVc303.sorted().joinToString(" "))] = 1
                    while (setsVc303.size > 8) setsVc303.removeAt(0)
                }
            }
        }
        if (fuzzyPartVc303.contains("🛑")) return fuzzyPartVc303
        // v4.48.6 (Butir 1): hasil "Tool tidak dikenal" TIDAK dihitung di
        // penghitung hasil-identik (countIdent=false dari pemanggil) —
        // penghitung putaran (loop) di atas tetap jalan.
        if (!countIdent) return loopPart + identCallPartVc302 + fuzzyPartVc303
        if (result.length < 8) return loopPart + identCallPartVc302 + fuzzyPartVc303
        val key = tool + "|" + AgentPrompt.hash64Vc277(result)
        val n = (stuckMap[key] ?: 0) + 1
        stuckMap[key] = n
        // vc277 O17: deteksi "mirip" — hasil yang hanya berbeda
        // angka/timestamp dihitung SAMA (bandingkan setelah angka dihapus).
        // vc301 SF-C1(b): angka offset/total/panjang/sisa DIAWETKAN
        // (stripNumbersKeepOffsetVc301) — lihat AgentPrompt.
        val simKey = tool + "|SIM|" + AgentPrompt.hash64Vc277(AgentPrompt.stripNumbersKeepOffsetVc301(result))
        val ns = (stuckMap[simKey] ?: 0) + 1
        stuckMap[simKey] = ns
        val identPart = when {
            // F1.1: stop hasil identik diperketat 5->4 (peringatan tetap di 3).
            n >= 4 -> "\n\n🛑 SISTEM (StuckDetector): panggilan '$tool' dengan hasil IDENTIK ini sudah terulang $n kali — TIDAK ADA PROGRES. BERHENTI mengulang pendekatan ini sekarang juga. Jawab final ke user: laporkan apa yang sudah tercapai, di mana macetnya, dan apa yang kamu butuhkan dari user. Jangan panggil tool lagi untuk pendekatan yang sama."
            ns >= 4 -> "\n\n🛑 SISTEM (StuckDetector): panggilan '$tool' dengan hasil MIRIP ini sudah terulang $ns kali (hanya berbeda angka/timestamp) — TIDAK ADA PROGRES. BERHENTI mengulang pendekatan ini sekarang juga. Jawab final ke user: laporkan apa yang sudah tercapai, di mana macetnya, dan apa yang kamu butuhkan dari user. Jangan panggil tool lagi untuk pendekatan yang sama."
            n == 3 -> "\n\n⚠️ SISTEM (StuckDetector): panggilan '$tool' dengan hasil identik sudah terulang 3 kali — indikasi berputar. GANTI strategi sekarang (tool lain, jalur lain, sumber lain) atau jelaskan ke user kenapa macet."
            ns == 3 -> "\n\n⚠️ SISTEM (StuckDetector): panggilan '$tool' dengan hasil mirip sudah terulang 3 kali (hanya berbeda angka/timestamp) — indikasi berputar. GANTI strategi sekarang (tool lain, jalur lain, sumber lain) atau jelaskan ke user kenapa macet."
            else -> ""
        }
        return loopPart + identCallPartVc302 + identPart + fuzzyPartVc303
    }

    // vc273 O6: batch hanya untuk giliran 1-1 biasa. Tool jalur-khusus
    // (planner, foto, hapus sesi) punya eksekutor sendiri di jalur tunggal
    // dan tidak boleh masuk batch.
    private fun useBatchVc273(calls: List<JSONObject>): Boolean {
        if (internalTurn || verifyTurn) return false
        val special = setOf("make_plan", "update_plan", "analyze_photo", "delete_session")
        if (calls.any { it.optString("tool") in special }) return false
        if (calls.any { it.optString("tool").isBlank() }) return false
        // vc316 N9-B1/C1: batch 1-1 TIDAK dipakai bila berisi op Concat
        // yang butuh konfirmasi khusus — batch mengeksekusi langsung
        // tanpa lewat proceedTool, jadi dialog konfirmasi akan dilewati
        // diam-diam. Batch seperti itu jatuh ke jalur tunggal (hanya call
        // pertama yang dieksekusi, sisanya diminta ulang).
        if (calls.any { ConcatTools.requiresSpecialConfirmVc316(it.optString("tool"), it.optJSONObject("args") ?: JSONObject()) }) return false
        return true
    }

    // vc273 O6+O7: hasil satu call di dalam batch.
    // kind: ok / failed / unknown / rejected (validasi O3) / deferred (O7:
    // prasyarat belum punya id hasil) / skipped (batas langkah / batch dihentikan).
    private data class BatchOutcomeVc273(
        val tool: String,
        val args: JSONObject,
        val callId: String,
        val result: String,
        val resultId: String?,
        val resultTotal: Int,
        val ok: Boolean,
        val kind: String,
        val stuckText: String,
        val prereqFailed: Boolean,
        val ms: Long
    )

    // vc273 O6+O7: eksekusi batch multi-tool lane 1-1.
    // Aturan yang dipakai di sini (dari rencana pasal 3 O6/O7):
    // - maks 4 call per respons; lebih dari itu hanya 4 pertama dieksekusi.
    // - tiap call = 1 langkah (cap 50 tetap bermakna); StuckDetector per call.
    // - hitungan Governor tidak berubah (per panggilan model, bukan per tool).
    // - READ independen yang berurutan dieksekusi KONKUREN (pool maks 4);
    //   tulis/efek (RISKY + MEMORY_WRITE) SEQUENSIAL sesuai urutan dan
    //   berhenti di kegagalan pertama; call dependen tidak pernah paralel.
    // - hasil digabung dalam SATU pesan continuation, satu blok per call
    //   dengan ID pengikat tc-<n>, sebelum teks apa pun.
    // - budget JEJAK 12.000 char dibagi per call: tiap blok hasil di pesan
    //   gabungan dipotong di 3.000 char (hasil utuh via get_result).
    // - batch TIDAK auto-retry per call (berbeda dari jalur tunggal):
    //   kegagalan dilaporkan di blok gabungan dan model yang memutuskan
    //   strategi berikutnya — retry di dalam batch akan mengacaukan urutan.
    private fun execBatchAndContinueVc273(calls: List<JSONObject>) {
        // vc306 Worker B: stop dari tombol ■ composer (lihat
        // execToolAndContinue) — batch tidak jalan bila stop diminta.
        if (stopRequestedVc306) {
            stopRequestedVc306 = false
            runOnUiThread { addMsg("⛔ Dihentikan: dihentikan user dari composer", "meta", turn = true) }
            pendingEndReason = "user-stop"
            turnStoppedReason = "dihentikan user dari composer"
            sendContinuation("⛔ STOP DIMINTA oleh user dari composer. HENTIKAN tugas ini sekarang juga: jangan panggil tool lain apa pun, langsung jawab final bahwa tugas dihentikan oleh user.")
            refreshComposerButtonsVc306()
            return
        }
        // F1.0: kill switch — sama seperti execToolAndContinue.
        if (getSharedPreferences("harness", MODE_PRIVATE).getBoolean("f1Off", false)) {
            runOnUiThread { addMsg("⛔ Dihentikan: kill switch F1 dimatikan oleh user — tugas dihentikan.", "meta", turn = true) }
            pendingEndReason = "kill-switch"
            turnStoppedReason = "kill switch F1 dimatikan user"
            sendContinuation("⛔ F1 DIMATIKAN oleh user (kill switch). HENTIKAN tugas ini sekarang juga: jangan panggil tool lain apa pun, langsung jawab final bahwa tugas dihentikan oleh kill switch F1. Sampaikan ke user: untuk melanjutkan tugas ini nanti, ia harus mengaktifkan lagi F1 lewat Profil > Kill Switch F1 (mematikan kill switch), lalu mengulang perintahnya.")
            return
        }
        // Kunci StuckDetector aktif: serahkan ke proceedTool (cabang kunci
        // di sana menolak tanpa eksekusi dan tanpa memakan langkah).
        if (turnStuckBlocked) {
            val first = calls[0]
            proceedTool(first.optString("tool"), first.optJSONObject("args") ?: JSONObject(), false, nextCallIdVc272(first.optString("id")))
            return
        }
        val totalCalls = calls.size
        val batch = calls.take(AgentPrompt.MAX_BATCH_CALLS_VC273)
        val leftover = totalCalls - batch.size
        val callIds = batch.map { nextCallIdVc272(it.optString("id")) }
        // Satu baris aktivitas untuk seluruh batch (vc254).
        lateinit var rowBatchVc273: ActivityRowHandle
        runOnUiThread {
            rowBatchVc273 = addActivityRow("Batch tool (${batch.size} panggilan)", "menjalankan…", "Argumen: " + batch.mapIndexed { i, o -> callIds[i] + " " + o.optString("tool") }.joinToString(", "), turn = true)
        }
        Thread {
            val outcomes = ArrayList<BatchOutcomeVc273>()
            val writtenPaths = HashSet<String>()
            val priorIds = ArrayList<String>()
            var stopBatch = false
            var stopReason = ""
            var unknownStop = false
            var i = 0
            while (i < batch.size) {
                if (stopBatch) {
                    val o = batch[i]
                    outcomes.add(BatchOutcomeVc273(o.optString("tool"), o.optJSONObject("args") ?: JSONObject(), callIds[i], "Tidak dieksekusi — batch dihentikan: $stopReason", null, 0, false, "skipped", "", false, 0))
                    i++
                    continue
                }
                if (agentSteps >= stepBudget) {
                    val o = batch[i]
                    outcomes.add(BatchOutcomeVc273(o.optString("tool"), o.optJSONObject("args") ?: JSONObject(), callIds[i], "Tidak dieksekusi — batas $stepBudget langkah tool tercapai.", null, 0, false, "skipped", "", false, 0))
                    i++
                    continue
                }
                val tool = batch[i].optString("tool")
                val args = batch[i].optJSONObject("args") ?: JSONObject()
                val callId = callIds[i]
                val depReason = AgentPrompt.batchDependencyReason(args, priorIds, writtenPaths)
                val isRead = tool in Tools.READ_TOOLS
                if (isRead && depReason == null) {
                    // Kelompok baca independen berurutan -> konkuren (maks 4).
                    val group = ArrayList<Int>()
                    var j = i
                    while (j < batch.size && group.size < AgentPrompt.MAX_BATCH_CALLS_VC273) {
                        val tj = batch[j].optString("tool")
                        val aj = batch[j].optJSONObject("args") ?: JSONObject()
                        if (tj !in Tools.READ_TOOLS) break
                        if (AgentPrompt.batchDependencyReason(aj, priorIds + group.map { callIds[it] }, writtenPaths) != null) break
                        if (agentSteps + group.size >= stepBudget) break
                        group.add(j)
                        j++
                    }
                    val groupOutcomes = runReadGroupVc273(group.map { batch[it] to callIds[it] })
                    for (oc in groupOutcomes) {
                        val rec = recordBatchOutcomeVc273(oc)
                        outcomes.add(rec)
                        priorIds.add(rec.callId)
                        val wp = AgentPrompt.writtenPathOf(rec.tool, rec.args)
                        if (wp.isNotBlank()) writtenPaths.add(wp)
                        if (rec.kind == "unknown" && consecInvalid >= unknownStopAt) { unknownStop = true; stopBatch = true; stopReason = "3x tool tidak dikenal berturut-turut" }
                        if (turnStuckBlocked) { stopBatch = true; stopReason = "StuckDetector mengunci giliran" }
                    }
                    i = j
                    continue
                }
                // Jalur sekuensial: call tulis, atau call baca yang dependen.
                val (effArgs, deferredReason) = resolveBatchArgsVc273(tool, args, outcomes)
                if (deferredReason != null) {
                    outcomes.add(BatchOutcomeVc273(tool, args, callId, "Ditunda — $deferredReason. Hasil prasyarat sudah ada di atas; kirim ulang call ini di giliran berikutnya dengan argumen lengkap.", null, 0, false, "deferred", "", false, 0))
                    priorIds.add(callId)
                    i++
                    continue
                }
                val oc = runSingleBatchCallVc273(tool, effArgs, callId, depReason)
                val rec = recordBatchOutcomeVc273(oc)
                outcomes.add(rec)
                priorIds.add(rec.callId)
                val wp = AgentPrompt.writtenPathOf(tool, effArgs)
                if (wp.isNotBlank()) writtenPaths.add(wp)
                if (rec.kind == "unknown" && consecInvalid >= unknownStopAt) { unknownStop = true; stopBatch = true; stopReason = "3x tool tidak dikenal berturut-turut" }
                if (turnStuckBlocked) { stopBatch = true; stopReason = "StuckDetector mengunci giliran" }
                if (!isRead && (rec.kind == "failed" || rec.kind == "rejected")) {
                    stopBatch = true
                    stopReason = "tool tulis $tool " + if (rec.kind == "failed") "GAGAL" else "DITOLAK SISTEM"
                }
                i++
            }
            // Gabungkan hasil dalam SATU pesan continuation (pola Anthropic:
            // semua tool_result dalam satu pesan, sebelum teks apa pun).
            val sb = StringBuilder()
            sb.append("Hasil batch — ${outcomes.size} panggilan tool dalam satu respons (lane 1-1, vc273 O6). Satu blok hasil per call, dengan ID pengikat tc-<n>:\n")
            for (oc in outcomes) {
                val disp = RedactSecrets.redact(oc.result)
                val cap = AgentPrompt.BATCH_RESULT_CAP_VC273
                val capped = if (disp.length > cap) disp.take(cap) + "…(dipotong, sisa " + (disp.length - cap) + " char" + (if ((oc.resultId ?: "").isNotBlank()) ", pakai get_result[" + oc.resultId + "] untuk sisanya" else "") + ")…" else disp
                sb.append("\nHasil tool ${oc.tool} " + ApiToolLayer.statusTag(ApiToolLayer.classifyResult(oc.result)) + " [HASIL TOOL ${oc.callId}]" + (if (oc.resultId != null) " [id=${oc.resultId}, total ${oc.resultTotal} char]" else "") + ":\n$capped\n")
                if (oc.kind == "rejected") sb.append("PERINTAH SISTEM: keluarkan ULANG blok json tool '${oc.tool}' dengan argumen yang sudah DIPERBAIKI sesuai pesan di atas.\n")
                if (oc.kind == "failed") sb.append("WAJIB: coba strategi atau tool LAIN untuk tujuan yang sama — jangan ulangi panggilan yang persis sama.\n")
                if (oc.prereqFailed) sb.append("ERROR PRASYARAT: call ini bergantung pada hasil call sebelumnya yang gagal atau belum selesai — prasyarat belum selesai, kirim ulang setelah prasyarat selesai.\n")
                if (oc.stuckText.isNotBlank()) sb.append(oc.stuckText).append("\n")
            }
            if (leftover > 0) sb.append("\nSisa $leftover panggilan tool dari respons ini BELUM dieksekusi (batas batch maks ${AgentPrompt.MAX_BATCH_CALLS_VC273} per respons) — kirim ulang di giliran berikutnya.\n")
            if (outcomes.any { it.kind == "skipped" }) sb.append("\n⛔ CAP LANGKAH TERCAPAI di tengah batch ini (ada call yang tidak dieksekusi karena batas $stepBudget langkah). Bila tidak ada langkah tersisa, jawab FINAL dengan jujur: \"berhenti di tengah pada langkah $agentSteps dari tugas — ini yang sudah selesai: …; ini yang belum: …\". Jangan panggil tool lagi bila cap sudah habis.\n")
            sb.append("\nLanjutkan untuk user: bila butuh tool lain keluarkan blok json lagi (gabungkan hanya call yang independen, maks 4 per respons), bila selesai jawab final tanpa blok json.")
            val combinedVc273 = sb.toString()
            runOnUiThread {
                try { rowBatchVc273.status = "selesai" } catch (e: Exception) {}
                renderPendingAskVc229()
                if (unknownStop) {
                    val tried = invalidNames.joinToString(", ")
                    pendingEndReason = "berhenti-invalid-ke-3"
                    addBubble("⛔ Dihentikan: 3x tool tidak dikenal berturut-turut (nama yang dicoba: $tried). Tidak ada tool yang dieksekusi untuk nama-nama itu; bukti kerja sebelumnya tetap ada di kartu-kartu tool di atas. Ulangi perintah dengan nama tool dari katalog (mis. run_terminal, get_screen, read_file) atau jelaskan tugasnya dengan kata-kata biasa.", false, turn = true)
                    endUserTurn()
                    return@runOnUiThread
                }
                val steerTxt = consumeSteer()
                sendContinuation(combinedVc273 + if (steerTxt != null) "\n\n[ARAHAN SISIPAN USER — user mengirim arahan ini SAAT kamu sedang bekerja; prioritaskan arahan terbaru ini]:\n$steerTxt" else "", hasToolResult = true)
            }
        }.start()
    }

    // vc273 O7: call dependen yang memakai id pengikat call sebelumnya
    // sebagai id get_result/grep_result — ganti id itu dengan resultId nyata
    // yang dihasilkan call tersebut (bila ada); bila call itu tidak
    // menghasilkan id hasil, call ini DITUNDA (bukan dieksekusi dengan id
    // yang salah). Argumen lain tidak diubah.
    private fun resolveBatchArgsVc273(tool: String, args: JSONObject, priorOutcomes: List<BatchOutcomeVc273>): Pair<JSONObject, String?> {
        // Hanya get_result/grep_result yang memakai id hasil — argumen id
        // tool lain tidak boleh di-resolve ke resultId.
        if (tool != "get_result" && tool != "grep_result") return Pair(args, null)
        if (args.optString("id").isBlank()) return Pair(args, null)
        val idArg = args.optString("id")
        if (!AgentPrompt.isValidCallId(idArg)) return Pair(args, null)
        val prior = priorOutcomes.firstOrNull { it.callId == idArg } ?: return Pair(args, null)
        val rid = prior.resultId
        if (rid.isNullOrBlank()) return Pair(args, "prasyarat $idArg (${prior.tool}) tidak menghasilkan id hasil — call ini butuh id hasil itu")
        return try {
            val copy = JSONObject(args.toString())
            copy.put("id", rid)
            Pair(copy, null)
        } catch (e: Exception) { Pair(args, null) }
    }

    // vc273 O6: eksekusi satu call batch (dipakai jalur sekuensial dan tiap
    // worker pool konkuren). Validasi O3 dulu — penolakan validasi TIDAK
    // memakan langkah dan TIDAK dihitung StuckDetector (dicatat di
    // recordBatchOutcomeVc273, bukan di sini).
    private fun runSingleBatchCallVc273(tool: String, args: JSONObject, callId: String, depReason: String?): BatchOutcomeVc273 {
        val t0 = System.currentTimeMillis()
        val validation = Tools.validateArgs(this, tool, args)
        if (validation != null) {
            return BatchOutcomeVc273(tool, args, callId, "⚠️ PANGGILAN TOOL DITOLAK SISTEM:\n" + validation, null, 0, false, "rejected", "", false, System.currentTimeMillis() - t0)
        }
        // vc282: timeout batch — call sekuensial batch kini lewat
        // pengeksekusi timeout vc278 yang sama dengan jalur tunggal, jadi
        // satu call yang menggantung tidak menggantung batch. Status
        // terstruktur (classify) menggantikan isFailed di sini.
        // Catatan: executeToolWithTimeoutVc278 tidak meneruskan callId ke
        // Tools.execute, jadi prefix [tc-n] di ledger hilang untuk call
        // batch ini — callId tetap ada di WorkItem + continuation.
        val outcomeVc282 = executeToolWithTimeoutVc278(tool, args)
        val result = outcomeVc282.result
        val resultId = outcomeVc282.resultId
        val resultTotal = outcomeVc282.resultTotal
        val ok = ApiToolLayer.classifyResult(result) == ApiToolLayer.ToolStatus.OK
        val kind = when {
            result.startsWith("Tool tidak dikenal") -> "unknown"
            outcomeVc282.timedOut -> "failed"
            !ok -> "failed"
            else -> "ok"
        }
        // vc273 O7(c): call dependen yang gagal karena prasyarat bukan
        // pengulangan model — jangan dihitung StuckDetector.
        val prereqFailed = depReason != null && !ok
        return BatchOutcomeVc273(tool, args, callId, result, resultId, resultTotal, ok, kind, "", prereqFailed, System.currentTimeMillis() - t0)
    }

    // vc273 O6: kelompok baca independen dieksekusi KONKUREN (pool maks 4).
    // Aman: Tools.execute memakai ThreadLocal untuk lastResultId /
    // lastFullLength, jadi tiap worker membaca id hasilnya sendiri.
    private fun runReadGroupVc273(pairs: List<Pair<JSONObject, String>>): List<BatchOutcomeVc273> {
        val pool = java.util.concurrent.Executors.newFixedThreadPool(minOf(4, pairs.size))
        try {
            val futures = pairs.map { (obj, callId) ->
                pool.submit(java.util.concurrent.Callable {
                    val tool = obj.optString("tool")
                    val args = obj.optJSONObject("args") ?: JSONObject()
                    runSingleBatchCallVc273(tool, args, callId, null)
                })
            }
            return futures.mapIndexed { idx, f ->
                try {
                    // vc282: timeout batch — kelompok baca tidak boleh
                    // menggantung selamanya bila satu call macet.
                    // vc284 N4-M1: batas luar TIDAK BOLEH lebih kecil dari
                    // batas eksekusi dalam (toolTimeoutSecVc278) — kalau
                    // tidak, delegate_wait di kelompok baca tetap
                    // terpotong 120 dtk oleh Future.get ini walau
                    // eksekutor dalamnya sudah memberi timeout_sec + 30.
                    // maxOf menjaga keduanya konsisten; tool lain tetap
                    // 120 dtk karena kedua tabel sama untuk mereka.
                    val toVc282 = maxOf(ApiToolLayer.batchTimeoutSec(pairs[idx].first.optString("tool"), pairs[idx].first.optJSONObject("args") ?: JSONObject()), toolTimeoutSecVc278(pairs[idx].first.optString("tool"), pairs[idx].first.optJSONObject("args") ?: JSONObject()))
                    f.get(toVc282.toLong(), java.util.concurrent.TimeUnit.SECONDS)
                } catch (e: java.util.concurrent.TimeoutException) {
                    val obj = pairs[idx].first
                    val tool = obj.optString("tool")
                    val args = obj.optJSONObject("args") ?: JSONObject()
                    try { f.cancel(true) } catch (e2: Exception) {}
                    val toVc282 = maxOf(ApiToolLayer.batchTimeoutSec(tool, args), toolTimeoutSecVc278(tool, args))
                    BatchOutcomeVc273(tool, args, pairs[idx].second, "ERROR: tool " + tool + " melewati batas " + toVc282 + " dtk — dibatalkan. Giliran tidak menunggu lagi; eksekusi di latar mungkin masih berjalan sampai batas internalnya. Jangan kirim ulang perintah yang sama persis — pakai pola background + file hasil bila memang butuh lama, atau pecah tugasnya. Putuskan: lanjut dengan cara lain, atau berhenti dan beri tahu user.", null, 0, false, "failed", "", false, 0)
                } catch (e: Exception) {
                    val obj = pairs[idx].first
                    val tool = obj.optString("tool")
                    val args = obj.optJSONObject("args") ?: JSONObject()
                    BatchOutcomeVc273(tool, args, pairs[idx].second, "Gagal: ${e.message}", null, 0, false, "failed", "", false, 0)
                }
            }
        } finally {
            pool.shutdown()
        }
    }

    // vc273 O6: pembukuan per call batch — cerminan jalur tunggal
    // (execToolAndContinue) untuk WorkItem, TurnMetrics, StuckDetector,
    // dan eskalasi unknown-tool. Penolakan validasi / call yang dilewati /
    // call yang ditunda TIDAK memakan langkah dan TIDAK dihitung StuckDetector.
    // Dipanggil dari thread koordinator batch (single-flight: tidak ada jalur
    // tool lain yang berjalan bersamaan, jadi akses stuckMap aman di sini).
    private fun recordBatchOutcomeVc273(oc: BatchOutcomeVc273): BatchOutcomeVc273 {
        if (oc.kind == "rejected" || oc.kind == "skipped" || oc.kind == "deferred") return oc
        agentSteps++
        if (agentSteps == 1) emitPhase("act")
        turnUsedTools = true
        val displayResult = RedactSecrets.redact(oc.result)
        val evidence = if (displayResult.length > 4000) displayResult.take(4000) + "…(dipotong, sisa " + (displayResult.length - 4000) + " char" + (if ((oc.resultId ?: "").isNotBlank()) ", pakai get_result[" + oc.resultId + "] untuk sisanya" else "") + ")…" else displayResult
        turnWork.add(WorkItem(oc.tool, oc.ms, oc.ok, displayResult.take(120), evidence = evidence, args = oc.args.toString().take(4000), resultId = oc.resultId ?: "", callId = oc.callId, totalChars = oc.resultTotal)) // VC303-P2-12 (CX-6): total char dibawa ke baris WorkNotes
        EventDb.get(this).add("tool", packageName, oc.tool + " -> " + displayResult.take(200))
        val isUnknown = oc.result.startsWith("Tool tidak dikenal")
        // vc282: pembatalan timeout BUKAN putaran — tidak dihitung
        // StuckDetector (prinsip O18 jalur tunggal). Teks peringatan
        // sistem dikumpulkan sebagai bukti reviewer (prioritas 6).
        val stuck = if (oc.prereqFailed) "" else stuckSuffix(oc.tool, oc.args, oc.result, countIdent = !isUnknown, skipStuckVc278 = ApiToolLayer.isTimeoutResult(oc.result))
        if (stuck.isNotBlank()) turnSystemNotesVc282.add(stuck)
        if (stuck.contains("🛑")) turnStuckBlocked = true
        // VC303-P3-19 (LP-5a): kunci giliran = pola ini disimpan lintas giliran.
        if (stuck.contains("🛑")) try { recordLockedPatternVc303(oc.tool, oc.args) } catch (e: Exception) {}
        TurnMetrics.recordStep(oc.tool, isUnknown, prootCutOf(oc.result), argsHash(oc.args), false)
        var invalidSuffix = ""
        if (isUnknown) {
            unknownToolCount++
            consecInvalid++
            invalidNames.add(oc.tool)
            val listTxt = AgentPrompt.validToolListText(this)
            val groupTxt = AgentPrompt.toolGroupSummary(this)
            invalidSuffix = unknownSuffix(consecInvalid, oc.tool, invalidNames, listTxt, groupTxt)
        } else {
            consecInvalid = 0
            invalidNames.clear()
        }
        return oc.copy(stuckText = stuck + invalidSuffix)
    }

    // vc278 O18(a): timeout per eksekusi tool di jalur 1-1.
    private data class ToolExecOutcomeVc278(
        val result: String,
        val resultId: String?,
        val resultTotal: Int,
        val timedOut: Boolean,
        val timeoutSec: Int
    )

    // vc278 O18(a): tool baca cepat (lokal, tanpa eksekusi lama) = 30 dtk;
    // tulis/shell umum = 120 dtk; run_terminal mengikuti timeout yang
    // sudah ada (proot 900 dtk, termux 90 dtk).
    // vc284 N4-M1: run_team dan delegate_wait DIKECUALIKAN dari batas
    // 120 dtk — keduanya orkestrasi sinkron yang batas internalnya memang
    // lebih lama dari 120 dtk, jadi batas lama memotongnya selalu.
    // run_team: lane paralel ditunggu maks 7 menit (latch TeamRun.run) +
    // verifikasi silang Mentor satu chatSync maks 240 dtk = 660 dtk,
    // + 60 dtk margin. delegate_wait: batas eksekusi mengikuti
    // timeout_sec yang diminta model (OcCoord.waitForTaskText coerceIn
    // 15..600, default 240) + 30 dtk margin — polling 8 dtk + baca hasil
    // akhir; tanpa ini wait default 240 dtk tidak pernah bisa selesai
    // dalam 120 dtk. Tool lain TIDAK berubah.
    private val RUN_TEAM_TIMEOUT_SEC_VC284 = 720
    private val DELEGATE_WAIT_TIMEOUT_MARGIN_SEC_VC284 = 30

    private val READ_FAST_TOOLS_VC278 = setOf(
        "read_file", "list_files", "recall_search", "otak_read",
        "storage_info", "list_tools", "get_result", "grep_result",
        "list_sessions", "list_goals", "list_rooms", "list_workers",
        "list_artifacts", "list_skills", "list_tasks"
    )

    private fun toolTimeoutSecVc278(tool: String, args: JSONObject): Int {
        if (tool == "run_terminal") {
            return if (args.optString("mode", "") == "proot") 900 else 90
        }
        if (tool == "run_team") return RUN_TEAM_TIMEOUT_SEC_VC284
        if (tool == "delegate_wait") {
            return args.optInt("timeout_sec", 240).coerceIn(15, 600) + DELEGATE_WAIT_TIMEOUT_MARGIN_SEC_VC284
        }
        return if (tool in READ_FAST_TOOLS_VC278) 30 else 120
    }

    private fun executeToolWithTimeoutVc278(tool: String, args: JSONObject): ToolExecOutcomeVc278 {
        val timeoutSec = toolTimeoutSecVc278(tool, args)
        val holder = arrayOfNulls<Any>(3)
        val t = Thread {
            try {
                val r = Tools.execute(this, tool, args)
                holder[0] = r
                holder[1] = Tools.lastResultId()
                holder[2] = Tools.lastFullLength()
            } catch (e: Exception) {
                holder[0] = "ERROR: eksekusi tool $tool gagal di dalam thread: " + (e.message ?: "")
                holder[1] = null
                holder[2] = 0
            }
        }
        t.isDaemon = true
        t.start()
        try { t.join(timeoutSec * 1000L) } catch (e: Exception) {}
        if (t.isAlive) {
            // Thread latar DIBIARKAN selesai sendiri — tidak bisa
            // diinterupsi aman (bisa merusak sesi proot/termux yang
            // sedang berjalan); hasilnya dibuang, giliran lanjut dengan
            // hasil is_error ini. Model memutuskan lanjut/berhenti.
            // vc284 N4-M1: pesan timeout delegate_wait TIDAK melarang
            // kirim ulang — polling ulang adalah pola yang
            // didokumentasikan untuk tool ini (OcCoord.waitForTaskText
            // sendiri menyuruh panggil lagi bila belum selesai).
            // Frasa "melewati batas ... dtk" dipertahankan agar hasil
            // ini tetap dikenali sebagai TIMEOUT oleh
            // ApiToolLayer.classifyResult (StuckDetector tetap
            // melewatinya seperti timeout lain). Tool lain tetap memakai
            // pesan lama yang melarang kirim ulang perintah yang sama.
            val timeoutMsgVc284 = if (tool == "delegate_wait") {
                "ERROR: tool delegate_wait melewati batas $timeoutSec dtk — dibatalkan. Tugas koordinator mungkin masih berjalan; panggil delegate_wait LAGI untuk lanjut memantau (polling sah untuk tool ini), sebaiknya dengan timeout_sec lebih kecil (mis. 60) per panggilan, atau cek delegate_status / delegate_result untuk progres tanpa menunggu."
            } else {
                "ERROR: tool $tool melewati batas $timeoutSec dtk — dibatalkan. Giliran tidak menunggu lagi; eksekusi di latar mungkin masih berjalan sampai batas internalnya. Jangan kirim ulang perintah yang sama persis — pakai pola background + file hasil bila memang butuh lama, atau pecah tugasnya. Putuskan: lanjut dengan cara lain, atau berhenti dan beri tahu user."
            }
            return ToolExecOutcomeVc278(timeoutMsgVc284, null, 0, true, timeoutSec)
        }
        return ToolExecOutcomeVc278(holder[0] as? String ?: "ERROR: tool $tool tidak mengembalikan hasil.", holder[1] as? String, (holder[2] as? Int) ?: 0, false, timeoutSec)
    }

    // vc316 N9-B1/C1: dialog KONFIRMASI KHUSUS op Concat yang merusak di
    // chat 1-1 — pola dialog REVIEW di proceedTool, tapi LEBIH SEDERHANA:
    // BUKAN gerbang (tetap mati, ToolGate tidak disentuh), BUKAN HIGH+PIN,
    // tanpa Panel Approval / autoAllow / mandat / parkir: Ya/Batal sekali
    // per panggilan, tanpa "jangan tanya lagi". Dialog tidak bisa tampil
    // (app tidak di depan) -> FAIL CLOSED: tool TIDAK dieksekusi dan model
    // diberi tahu lewat continuation (bukan diam-diam). setCancelable
    // (false) supaya selalu ada keputusan eksplisit — bila dialog bisa
    // ditutup tanpa tombol, giliran akan menggantung tanpa hasil tool.
    private fun askConcatDestructiveConfirmVc316(tool: String, args: JSONObject, callId: String = "") {
        val descVc316 = ConcatTools.describeDestructiveConcatCallVc316(tool, args)
        runOnUiThread {
            try {
                AlertDialog.Builder(this)
                    .setTitle("Jalankan perintah Concat yang merusak?")
                    .setMessage(descVc316 + "\n\nPerintah ini TIDAK BISA dibatalkan otomatis. Bila ragu, tekan Batal — agen bisa menyimpan dulu proyeknya (concat_project_save).")
                    .setPositiveButton("Ya, jalankan") { _, _ -> execToolAndContinue(tool, args, callId) }
                    .setNegativeButton("Batal") { _, _ ->
                        addMsg("⏹️ $tool tidak dijalankan (ditolak user — konfirmasi khusus Concat).", "meta", turn = true)
                        sendContinuation("User MENOLAK aksi tool $tool (konfirmasi khusus Concat: perintah ini merusak). Jangan coba lagi aksi itu; jawab user dengan penjelasan / alternatif.")
                    }
                    .setCancelable(false)
                    .create().show()
            } catch (e: Exception) {
                addMsg("⏹️ $tool tidak dijalankan (konfirmasi khusus Concat tidak bisa tampil — app tidak di depan).", "meta", turn = true)
                sendContinuation("Tool $tool TIDAK dijalankan: perintah Concat ini merusak dan butuh konfirmasi user, tetapi dialog konfirmasinya tidak bisa tampil (app sedang tidak di depan). Minta user membuka app lalu memicu ulang tugasnya; jangan ulangi panggilan ini sendiri.")
            }
        }
    }

    private fun execToolAndContinue(tool: String, args: JSONObject, callId: String = "") {
        // vc306 Worker B: stop dari tombol ■ composer — pola sama seperti
        // kill switch F1 di bawah: langkah berikutnya ditolak, model diminta
        // menutup giliran. Berlakunya di batas tool-call berikut (panggilan
        // jaringan yang sedang berjalan tidak bisa dibatalkan dari sini).
        if (stopRequestedVc306) {
            stopRequestedVc306 = false
            runOnUiThread { addMsg("⛔ Dihentikan: dihentikan user dari composer", "meta", turn = true) }
            pendingEndReason = "user-stop"
            turnStoppedReason = "dihentikan user dari composer"
            sendContinuation("⛔ STOP DIMINTA oleh user dari composer. HENTIKAN tugas ini sekarang juga: jangan panggil tool lain apa pun, langsung jawab final bahwa tugas dihentikan oleh user.")
            refreshComposerButtonsVc306()
            return
        }
        // F1.0: kill switch — langkah berikutnya ditolak, giliran berakhir.
        if (getSharedPreferences("harness", MODE_PRIVATE).getBoolean("f1Off", false)) {
            runOnUiThread { addMsg("⛔ Dihentikan: kill switch F1 dimatikan oleh user — tugas dihentikan.", "meta", turn = true) }
            pendingEndReason = "kill-switch"
            turnStoppedReason = "kill switch F1 dimatikan user" // vc232 S4: jawaban final paksa sesudahnya tidak lagi mendapat pill Selesai
            sendContinuation("⛔ F1 DIMATIKAN oleh user (kill switch). HENTIKAN tugas ini sekarang juga: jangan panggil tool lain apa pun, langsung jawab final bahwa tugas dihentikan oleh kill switch F1. Sampaikan ke user: untuk melanjutkan tugas ini nanti, ia harus mengaktifkan lagi F1 lewat Profil > Kill Switch F1 (mematikan kill switch), lalu mengulang perintahnya.")
            return
        }
        val isAutoRetry = autoRetryTools.remove(tool)
        if (tool == "analyze_photo") { analyzePhotoAndContinue(args, turn = true); return }
        if (tool == "delete_session") {
            // vc265 V-M2: hormati argumen session_id — hapus HANYA sesi
            // yang dinamai; sesi AKTIF DITOLAK (katalog AgentPrompt.kt:378),
            // tanpa penghapusan apa pun. Dulu: argumen diabaikan dan sesi
            // aktif yang sedang dipakai malah dihapus.
            runOnUiThread {
                val sid = if (args.has("session_id")) args.optLong("session_id", -1) else args.optLong("id", -1)
                renderPendingAskVc229()
                when {
                    sid <= 0 -> sendContinuation("Hasil tool delete_session" + (if (callId.isNotBlank()) " [HASIL TOOL $callId]" else "") + ":\nERROR: delete_session butuh session_id (angka, lihat list sesi di UI chat). Sesi aktif TIDAK bisa dihapus dari tool. Tidak ada yang dihapus.\n\nBeritahu user secara singkat bahwa tidak ada sesi yang dihapus karena session_id tidak diberikan.")
                    sid == currentSessionId -> sendContinuation("Hasil tool delete_session" + (if (callId.isNotBlank()) " [HASIL TOOL $callId]" else "") + ":\nERROR: delete_session DITOLAK: sesi #$sid adalah sesi aktif — hapus dari UI chat (pindah sesi dulu, lalu hapus sesi ini), bukan dari tool. Tidak ada yang dihapus.\n\nBeritahu user secara singkat bahwa sesi aktif tidak bisa dihapus dari tool dan tidak ada yang dihapus.")
                    else -> {
                        val mdb = MemoryDb.get(this)
                        val title = mdb.sessionTitle(sid)
                        val exists = try { mdb.sessions().any { it.id == sid } } catch (e: Exception) { false }
                        if (!exists) {
                            sendContinuation("Hasil tool delete_session" + (if (callId.isNotBlank()) " [HASIL TOOL $callId]" else "") + ":\nERROR: sesi #$sid tidak ditemukan — tidak ada yang dihapus.\n\nBeritahu user secara singkat bahwa sesi yang diminta tidak ada.")
                        } else {
                            mdb.deleteSession(sid)
                            sendContinuation("Hasil tool delete_session" + (if (callId.isNotBlank()) " [HASIL TOOL $callId]" else "") + ":\nSesi #$sid (\"$title\") TERHAPUS permanen beserta seluruh isi percakapannya. Sesi aktif tidak berubah.\n\nBeritahu user secara singkat bahwa sesi \"$title\" sudah dihapus sesuai permintaannya.")
                        }
                    }
                }
            }
            return
        }
        // vc254: kartu eksekusi tool mentah diganti baris aktivitas
        // (judul bahasa Indonesia, default tertutup, detail = argumen).
        lateinit var rowVc254: ActivityRowHandle
        runOnUiThread { rowVc254 = addActivityRow(ActivityTitle.title(tool, args), "menjalankan…", "Argumen: " + ActivityTitle.shortArgs(tool, args), turn = true, tool = tool) }
        Thread {
            val t0 = System.currentTimeMillis()
            val outcomeVc278 = executeToolWithTimeoutVc278(tool, args)
            val result = outcomeVc278.result
            val timedOutVc278 = outcomeVc278.timedOut
            val displayResult = RedactSecrets.redact(result)
            val resultId = outcomeVc278.resultId
            val resultTotal = outcomeVc278.resultTotal
            EventDb.get(this).add("tool", packageName, "$tool -> ${displayResult.take(200)}")
            val secs = String.format(java.util.Locale.US, "%.1f", (System.currentTimeMillis() - t0) / 1000.0).replace('.', ',')
            val durMsVc254 = System.currentTimeMillis() - t0
            turnWork.add(WorkItem(tool, System.currentTimeMillis() - t0, !WorkLog.isFailed(result), displayResult.take(120), evidence = if (displayResult.length > 4000) displayResult.take(4000) + "…(dipotong, sisa " + (displayResult.length - 4000) + " char" + (if ((resultId ?: "").isNotBlank()) ", pakai get_result[" + resultId + "] untuk sisanya" else "") + ")…" else displayResult, args = args.toString().take(4000), resultId = resultId ?: "", callId = callId, totalChars = resultTotal)) // VC303-P2-12 (CX-6): total char dibawa ke baris WorkNotes; v4.48.5 (P2): evidence 800 char/langkah + penanda vc230 R-07(a) — cap eksplisit — jalur PoW tanpa limit token; summary tetap 120 untuk UI/footer.
        if (tool == "use_skill" && result.startsWith("PROSEDUR SKILL")) {
            val nmSk = Regex("PROSEDUR SKILL '([^']+)'").find(result)?.groupValues?.get(1) ?: ""
            addMsg("🧩 Skill '$nmSk' dimuat — prosedurnya diikuti untuk tugas ini.", "meta", turn = true)
        }
            runOnUiThread {
                // vc254: baris aktivitas diperbarui (status + detail
                // hasil); jejak tool tetap masuk journal seperti dulu.
                rowVc254.status = ActivityTitle.statusText(durMsVc254, !WorkLog.isFailed(result))
                rowVc254.detail = "Argumen: " + ActivityTitle.shortArgs(tool, args) + "\nHasil: " + ActivityTitle.resultTail(displayResult)
                // vc267: hasil create/edit artifact membawa penanda
                // ARTIFACT:<id> — render kartu artifact di chat.
                try {
                    val artId = Regex("ARTIFACT:([A-Za-z0-9-]+)").find(displayResult)?.groupValues?.get(1)
                    if (artId != null) addArtifactCard(artId)
                } catch (e: Exception) { }
                // vc268: hasil delete_artifact membawa penanda
                // ARTIFACT_DELETED:<id> — tandai kartu di chat
                // sebagai dihapus + refresh dialog daftar bila terbuka.
                try {
                    val delId = Regex("ARTIFACT_DELETED:([A-Za-z0-9-]+)").find(displayResult)?.groupValues?.get(1)
                    if (delId != null) {
                        markArtifactCardDeleted(delId)
                        refreshArtifactListDialog()
                    }
                } catch (e: Exception) { }
                journalTrace(ActivityTitle.title(tool, args) + " — " + rowVc254.status)
                // vc229 R-05(e): tool sudah dieksekusi -> sekarang render ask yang se-respons tadi.
                renderPendingAskVc229()
                // v4.48.9.24 (vc190): tawaran jadikan room — HANYA dari chat 1-1.
                // Jalur ini (proceedTool/handleAgentResponse) tidak dipakai grup,
                // room, TeamRun, maupun BgBrain — mereka punya eksekutor sendiri.
                // Satu kali per id schedule; list_schedules tidak memicu tawaran.
                // Dialog best-effort: kegagalan tampil tidak boleh merusak giliran.
                try {
                    if (tool == "schedule_task" && result.startsWith("Tugas AI terjadwal #")) {
                        val sid = Regex("#(\\d+)").find(result)?.groupValues?.get(1)?.toLongOrNull()
                        if (sid != null && !getSharedPreferences("harness", MODE_PRIVATE).getBoolean("roomOffered_$sid", false)) {
                            showRoomOfferDialog(sid, args.optInt("hour", -1), args.optInt("minute", 0), args.optString("prompt").trim())
                        }
                    }
                } catch (e: Exception) {
                    // tawaran best-effort — kegagalan tampil tidak merusak giliran
                }
                // Penolakan argumen kosong (v3.3.1) WAJIB berujung panggilan ulang
                // berargumen lengkap — model tidak boleh lolos dengan prosa klarifikasi.
                // vc229 R-06(c): create_subroom ditolak karena parent tidak
                    // ditemukan -> pantulkan pertanyaan ask, JANGAN biarkan model beralih tool.
                val subroomBounceVc229 = tool == "create_subroom" && (displayResult.contains("tidak ditemukan") || displayResult.contains("hanya bisa dari dalam sebuah room"))
                val subroomBounceTextVc229 = "SISTEM (pantulan create_subroom): create_subroom ditolak karena room induk tidak ditemukan / tidak disebut. JANGAN beralih ke delegate_session, delegate_task, atau chain_tasks — itu BUKAN pengganti create_subroom. Ajukan pertanyaan ask SEKARANG: room induk yang mana? (satu blok ask dengan opsi judul room yang user pernah sebut, atau opsi ketik bebas). Setelah user menjawab, panggil create_subroom lagi dengan argumen parent = jawaban user."
                val rejected = result.startsWith("⚠️ PANGGILAN TOOL DITOLAK SISTEM")
                val failed = WorkLog.isFailed(result)
                if (rejected && rejectRetryCount < 2) {
                    rejectRetryCount++
                    autoRetryTools.add(tool)
                    consecInvalid = 0
                    invalidNames.clear()
                    TurnMetrics.recordStep(tool, false, prootCutOf(result), argsHash(args), isAutoRetry)
                    sendContinuation("Hasil tool $tool" + (if (callId.isNotBlank()) " [HASIL TOOL $callId]" else "") + (if (resultId != null) " [id=$resultId, total $resultTotal char]" else "") + " DITOLAK SISTEM:\n$displayResult\n\nPERINTAH SISTEM — WAJIB DIPATUHI PADA GILIRAN INI: keluarkan ULANG blok json tool '$tool' yang sama, kali ini dengan argumen TERISI LENGKAP dari perintah user terakhir (task/command/title sesuai tool-nya). DILARANG menjawab dengan prosa, rencana, atau pertanyaan klarifikasi pada giliran ini.", hasToolResult = true)
                // VC303-P1-5 (LP-8 + residual LP-10): JANGAN auto-retry
                // penolakan deterministik — hasil yang diawali nama tool +
                // "ditolak" (mis. "forge_eval_save ditolak: ...": gagal
                // selama args tidak diperbaiki, retry hanya mengulang
                // kegagalan yang sama) — dan JANGAN auto-retry
                // artifact_bundle yang GAGAL (build Vite mahal diulang).
                // Penolakan masuk cabang rejected di atas (bukan ke sini);
                // yang dicegah di sini adalah retry hasil-gagal biasa yang
                // teksnya penolakan deterministik tool.
                } else if (failed && !timedOutVc278 && !result.lowercase().startsWith(tool.lowercase() + " ditolak") && tool != "artifact_bundle" && retriedTools.add(tool) && agentSteps < stepBudget) {
                    autoRetryTools.add(tool)
                    consecInvalid = 0
                    invalidNames.clear()
                    TurnMetrics.recordStep(tool, false, prootCutOf(result), argsHash(args), isAutoRetry)
                    if (subroomBounceVc229) sendContinuation(subroomBounceTextVc229, hasToolResult = true) else sendContinuation("Hasil tool $tool" + (if (callId.isNotBlank()) " [HASIL TOOL $callId]" else "") + (if (resultId != null) " [id=$resultId, total $resultTotal char]" else "") + " GAGAL:\n$displayResult\n\nWAJIB: coba strategi atau tool LAIN untuk tujuan yang sama — jangan ulangi panggilan yang persis sama. Bila memang tidak ada jalan lain, jelaskan ke user dengan jujur.", hasToolResult = true)
                } else {
                    // v4.48.6 (Butir 1): eskalasi unknown-tool — hasil unknown
                    // TIDAK menaikkan penghitung hasil-identik, TIDAK PERNAH
                    // menyetel turnStuckBlocked; kunci 🛑 di bawah hanya dari
                    // detektor putaran (loop), yang perilakunya tidak diubah.
                    val isUnknown = result.startsWith("Tool tidak dikenal")
                    val stuck = stuckSuffix(tool, args, result, countIdent = !isUnknown, skipStuckVc278 = timedOutVc278)
                    // vc282: teks peringatan sistem dikumpulkan sebagai
                    // bukti reviewer (prioritas 6).
                    if (stuck.isNotBlank()) turnSystemNotesVc282.add(stuck)
                    if (stuck.contains("🛑")) turnStuckBlocked = true
                    // VC303-P3-19 (LP-5a): kunci giliran = pola ini disimpan lintas giliran.
                    if (stuck.contains("🛑")) try { recordLockedPatternVc303(tool, args) } catch (e: Exception) {}
                    TurnMetrics.recordStep(tool, isUnknown, prootCutOf(result), argsHash(args), isAutoRetry)
                    var invalidSuffix = ""
                    if (isUnknown) {
                        unknownToolCount++
                        consecInvalid++
                        invalidNames.add(tool)
                        val listTxt = AgentPrompt.validToolListText(this)
                        val groupTxt = AgentPrompt.toolGroupSummary(this)
                        invalidSuffix = unknownSuffix(consecInvalid, tool, invalidNames, listTxt, groupTxt)
                    } else {
                        consecInvalid = 0
                        invalidNames.clear()
                    }
                    if (isUnknown && consecInvalid >= unknownStopAt) {
                        // v4.48.6 (Butir 1): BERHENTI — gelembung laporan
                        // jujur BARU (berbeda dari gelembung kunci
                        // StuckDetector) + endUserTurn langsung, tanpa kunci.
                        val tried = invalidNames.joinToString(", ")
                        pendingEndReason = "berhenti-invalid-ke-3"
                        addBubble("⛔ Dihentikan: 3x tool tidak dikenal berturut-turut (nama yang dicoba: $tried). Tidak ada tool yang dieksekusi untuk nama-nama itu; bukti kerja sebelumnya tetap ada di kartu-kartu tool di atas. Ulangi perintah dengan nama tool dari katalog (mis. run_terminal, get_screen, read_file) atau jelaskan tugasnya dengan kata-kata biasa.", false, turn = true)
                        endUserTurn()
                    } else {
                        val steerTxt = consumeSteer()
                        if (subroomBounceVc229) sendContinuation(subroomBounceTextVc229, hasToolResult = true) else sendContinuation(("Hasil tool $tool" + (if (callId.isNotBlank()) " [HASIL TOOL $callId]" else "") + (if (resultId != null) " [id=$resultId, total $resultTotal char]" else "") + ":\n$displayResult\n\nLanjutkan untuk user: bila butuh tool lain keluarkan blok json lagi, bila selesai jawab final tanpa blok json." + if (steerTxt != null) "\n\n[ARAHAN SISIPAN USER — user mengirim arahan ini SAAT kamu sedang bekerja; prioritaskan arahan terbaru ini]:\n$steerTxt" else "") + invalidSuffix + stuck, hasToolResult = true)
                    }
                }
            }
        }.start()
    }

    // ---------------- Terminal tab ----------------

    internal lateinit var termMode: Spinner
    internal lateinit var termInput: EditText
    internal fun termInputReady(): Boolean = ::termInput.isInitialized
    internal fun termModeReady(): Boolean = ::termMode.isInitialized


