    /** v4.48.6 (Butir 2): kartu ringkasan metrik giliran terakhir untuk tab
     *  Monitor. Angka char terpotong hanya yang TERUKUR (guard + proot);
     *  char riwayat yang dibuang historyTranscript TIDAK terukur dan ditulis
     *  begitu — tidak pernah dikarang. */
    private fun dailyPrompt(): String {
        val raw = getSharedPreferences("turnMetrics", MODE_PRIVATE).getString("daily_" + java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US).format(java.util.Date()), null) ?: return "?"
        val m = Regex("\"p\":(\\d+)").find(raw)
        return m?.groupValues?.get(1) ?: "?"
    }

    private fun dailySteps(): String {
        val raw = getSharedPreferences("turnMetrics", MODE_PRIVATE).getString("daily_" + java.text.SimpleDateFormat("yyyy-MM-dd", java.util.Locale.US).format(java.util.Date()), null) ?: return "?"
        val m = Regex("\"s\":(\\d+)").find(raw)
        return m?.groupValues?.get(1) ?: "?"
    }

    private fun formatMetricsSnapshot(): String {
        val raw = TurnMetrics.loadSnapshot(this) ?: return "📊 METRIK GILIRAN TERAKHIR\n(belum ada giliran tercatat — kirim satu perintah dulu, lalu segarkan.)"
        fun num(key: String): String {
            val m = Regex(""""$key":(\d+)""").find(raw)
            return m?.groupValues?.get(1) ?: "?"
        }
        fun str(key: String): String {
            val m = Regex("\"" + key + "\":\"([^\"]*)\"").find(raw)
            return m?.groupValues?.get(1) ?: "?"
        }
        val sb = StringBuilder()
        sb.append("📊 METRIK GILIRAN TERAKHIR\n")
        sb.append("Giliran ke: ").append(num("giliran_ke")).append("\n")
        sb.append("Alasan akhir: ").append(str("alasan_akhir")).append("\n")
        sb.append("Durasi: ").append(num("durasi_ms")).append(" ms • Langkah tool: ").append(num("langkah"))
            .append(" • Eksekusi ulang (tool+args): ").append(num("eksekusi_ulang_tool_sama"))
            .append(" • Unknown-tool: ").append(num("unknown_tool")).append("\n")
        sb.append("Total prompt: ").append(num("total_prompt_char")).append(" char (cap ").append(TurnMetrics.promptCap(this)).append(")\n")
        sb.append("Lapisan — sistem-minus-katalog: ").append(num("sistem_minus_katalog"))
            .append(" • katalog: ").append(num("katalog"))
            .append(" • memori: ").append(num("memori"))
            .append(" • riwayat: ").append(num("riwayat"))
            .append(" • jejak: ").append(num("jejak"))
            .append(" • digest: ").append(num("digest"))
            .append(" • hasil tool: ").append(num("hasil_tool"))
            .append(" • semantik: ").append(num("semantik"))
            .append(" • lainnya: ").append(num("lainnya")).append("\n")
        sb.append("Lapisan baru — persona: ").append(num("persona"))
            .append(" • rencana: ").append(num("rencana"))
            .append(" • trailer: ").append(num("trailer")).append("\n")
        sb.append("Total hari ini: ").append(dailyPrompt()).append(" char prompt • ").append(dailySteps()).append(" langkah\n")
        val mig = getSharedPreferences("harness", MODE_PRIVATE).getString("redactMigrationReport", null)
        if (!mig.isNullOrBlank()) sb.append("Migrasi redaksi 4.48.8: ").append(mig).append("\n")
        sb.append("Definisi: eksekusi ulang = pasangan (tool, hash args) yang sama dalam satu giliran, retry otomatis tidak dihitung; persona adalah SUBSET dari sistem (bukan tambahan); total = panjang prompt yang benar-benar dikirim — sejak vc228, pada giliran awal total SUDAH termasuk ringkasan riwayat lama, extra semantik (bila ada), dan suffix \"User: <pesan>\"; extra semantik dibuang bila total melebihi cap; pada giliran lanjutan, total = panjang prompt penuh yang dikirim.\n")
        sb.append("Lapisan lainnya (vc238) = selisih total dikurangi semua lapisan bernama — header blok, pemisah, catatan sistem, dan suffix user — sehingga jumlah lapisan = total; semantik = extra semantik yang benar-benar dikirim (0 bila dibuang atau tiada); pada giliran lanjutan, lainnya juga mencakup perintah user, rencana, dan trailer yang tidak masuk lapisan bernama.\n")
        sb.append("Char terpotong (terukur: guard + proot): ").append(num("char_terpotong"))
            .append(" (dari proot: ").append(num("char_dipotong_proot")).append(")\n")
        sb.append("JEJAK dibuang: ").append(num("jejak_dibuang_langkah")).append(" langkah / ")
            .append(num("jejak_dibuang_char")).append(" char\n")
        sb.append("Catatan: char riwayat yang dibuang historyTranscript (cap 6000/4500) tidak terukur — tidak ditampilkan sebagai angka.")
        return sb.toString()
    }

    /** 4.48.9: Uji Mandiri — deterministik, tanpa model, tanpa jaringan.
     *  Menolak bila giliran foreground sedang berjalan (TurnMetrics begun).
     *  TIDAK PERNAH menulis TurnMetrics/EventDb/jurnal/Monitor; satu-satunya
     *  tulisan adalah log filesDir/logs/uji-mandiri-<stamp>.txt + teks
     *  setupStatusTv (transien). ThreadLocal miliknya dibersihkan di finally.
     *  Gagal satu cek TIDAK menghentikan cek lain; log mencatat semuanya. */
    // vc175 (60.): jejak ANR terakhir via ApplicationExitInfo — hanya
    // terekam bila proses MATI karena ANR (ketuk OK); ANR yang berakhir
    // dengan "Tunggu" (app selamat) TIDAK terekam di sini.
    // vc178: panel Konektor MCP — daftar server resmi + kustom, aktif/token/tes.
    private fun startHub(ctx: Context, d: McpServerDef, cid: String) {
        if (d.oauthKind == "device") {
            McpOAuth.startDevice(ctx, d, cid,
                onCode = { userCode, verifyUri ->
                    runOnUiThread {
                        AlertDialog.Builder(ctx).setTitle("Kode GitHub: $userCode")
                            .setMessage("Buka $verifyUri di browser, masukkan kode di atas, lalu tunggu — token tersimpan otomatis bila disetujui.")
                            .setPositiveButton("Buka browser") { _, _ ->
                                try { startActivity(Intent(Intent.ACTION_VIEW, Uri.parse(verifyUri))) } catch (e: Exception) { Toast.makeText(ctx, "Gagal buka browser: ${e.message}", Toast.LENGTH_LONG).show() }
                            }
                            .setNegativeButton("Batal", null).show()
                    }
                },
                onDone = { msg -> runOnUiThread { Toast.makeText(ctx, msg, Toast.LENGTH_LONG).show() } }
            )
        } else {
            McpOAuth.startLoopback(ctx, d, cid, McpServers.clientSecretFor(ctx, d.id)) { msg ->
                runOnUiThread {
                    if (msg.contains("gagal")) {
                        val tvMsg = TextView(this).apply {
                            text = msg
                            textSize = 13f
                            setTextColor(currentTheme().text)
                            setTextIsSelectable(true)
                        }
                        thDialog("Hubungkan ${d.name} gagal", tvMsg, listOf(Triple("Tutup", true) { dd: android.app.AlertDialog -> dd.dismiss() }))
                    } else {
                        Toast.makeText(ctx, msg, Toast.LENGTH_LONG).show()
                    }
                }
            }
        }
    }

