    private fun showMitmProxyView(info: String) {
        val th = currentTheme()
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(12), dp(16), dp(12)) }
        fun topBtn(label: String, fn: () -> Unit) {
            col.addView(Button(this).apply { text = label; setTextColor(th.text); setOnClickListener { fn() } })
        }
        fun act(label: String, fn: () -> String) {
            Toast.makeText(this, label, Toast.LENGTH_SHORT).show()
            Thread {
                val msg = try { fn() } catch (e: Exception) { "error: ${e.message}" }
                runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showMitmProxyDialog() }
            }.start()
        }
        topBtn("▶ Mulai Mitmproxy") { act("Memulai mitmproxy…") { MitmProxy.start(this@MainActivity) } }
        topBtn("⏹ Stop Mitmproxy") {
            android.app.AlertDialog.Builder(this).setTitle("Stop mitmproxy terkelola?")
                .setMessage("Proses mitmproxy di worker2 akan di-kill. Job yang di-stop TIDAK akan di-restart otomatis.")
                .setPositiveButton("Stop") { _, _ -> act("Men-stop mitmproxy…") { MitmProxy.stop(this@MainActivity) } }
                .setNegativeButton("Batal", null).show()
        }
        topBtn("🩺 Periksa Melayani") { act("Memeriksa apakah mitmproxy melayani…") { MitmProxy.checkServing(this@MainActivity) } }
        topBtn("🗺️ Deteksi Route") { act("Mendeteksi route aktif…") { MitmProxy.detectRoutes(this@MainActivity) } }
        topBtn("📄 Ekor Log Mitmproxy") {
            Thread {
                val job = try { MitmProxy.findJob(this@MainActivity) } catch (e: Exception) { null }
                val tail = if (job == null) "Belum ada job mitmproxy terkelola." else try { ProotJobs.logTail(this@MainActivity, job.session, job.logPath) } catch (e: Exception) { "error: ${e.message}" }
                runOnUiThread {
                    android.app.AlertDialog.Builder(this@MainActivity).setTitle("Ekor Log — mitmproxy").setMessage(tail.take(3000))
                        .setPositiveButton("OK", null)
                        .setNegativeButton("Periksa Ulang", { _, _ -> showMitmProxyDialog() }).show()
                }
            }.start()
        }
        topBtn("🧑‍🏭 Buka Panel Jobs") { showProotJobsDialog() }
        topBtn("🔌 Proxy Env: Aktifkan untuk Semua Tangan") { act("Mengaktifkan proxy env…") { MitmProxy.setProxyEnv(this@MainActivity, true) } }
        topBtn("🔌 Proxy Env: Nonaktifkan") { act("Menonaktifkan proxy env…") { MitmProxy.setProxyEnv(this@MainActivity, false) } }
        topBtn("🔄 Periksa Ulang") { showMitmProxyDialog() }
        col.addView(TextView(this).apply { text = info; setTextColor(th.text); textSize = 13f; setPadding(0, dp(10), 0, dp(2)) })
        col.addView(TextView(this).apply { text = "Catatan: tangan serve TIDAK disentuh. Route/iptables tidak diubah. Proxy env default TIDAK AKTIF karena HTTPS di proot tidak percaya CA mitm — aktifkan manual hanya bila perlu. Tailscaled tidak dinyalakan dari sini."; setTextColor(th.dim); textSize = 13f; setPadding(0, dp(8), 0, dp(8)) })
        val scroll = android.widget.ScrollView(this).apply { addView(col) }
        android.app.AlertDialog.Builder(this).setTitle("🔍 Mitmproxy Terkelola").setView(scroll)
            .setNegativeButton("Tutup", null).show()
    }

    // vc208 L1: panel Jobs supervisor proot (Setup 63, kategori koneksi).
    // Semua operasi ProotJobs bersifat blokir — selalu dari Thread, hasil
    // kembali lewat runOnUiThread (pelajaran ANR vc193). Tangan serve TIDAK
    // PERNAH disentuh dari panel ini.
    internal fun showProotJobsDialog() {
        Toast.makeText(this, "Memeriksa status jobs proot…", Toast.LENGTH_SHORT).show()
        Thread {
            try { ProotJobs.checkAll(this@MainActivity) } catch (e: Exception) {}
            val jobs = try { ProotJobs.load(this@MainActivity) } catch (e: Exception) { emptyList() }
            runOnUiThread { showProotJobsList(jobs) }
        }.start()
    }

    private fun showProotJobsList(jobs: List<ProotJobs.Job>) {
        val th = currentTheme()
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(12), dp(16), dp(12)) }
        fun topBtn(label: String, fn: () -> Unit) {
            col.addView(Button(this).apply { text = label; setTextColor(th.text); setOnClickListener { fn() } })
        }
        topBtn("🔄 Periksa Ulang") { showProotJobsDialog() }
        topBtn("▶ Mulai Job Baru") { prootJobStartFlow() }
        topBtn("➕ Daftarkan Job Lama (PID sudah jalan)") { prootJobRegisterFlow() }
        if (jobs.isEmpty()) {
            col.addView(TextView(this).apply { text = "Belum ada job terdaftar.\n\nSupervisor hanya mengelola job yang didaftarkan lewat panel ini (Mulai Job Baru / Daftarkan Job Lama). Job nohup dari run_terminal TIDAK otomatis terdaftar — daftarkan PID-nya bila ingin diawasi.\n\nTangan serve (serve:4199 + tailscaled) TIDAK dikelola di sini — milik ServeHealth/Standby."; setTextColor(th.dim); textSize = 13f; setPadding(0, dp(8), 0, dp(8)) })
        }
        for (job in jobs) {
            val info = "📌 ${job.name}\n${job.session} • PID ${job.pid} • ${ProotJobs.statusLabel(job.status)} • ${if (job.policy == "AUTO") "restart AUTO" else "restart MANUAL"}${if (job.restartCount > 0) " • restart ${job.restartCount}x" else ""}\nLog: ${job.logPath}\n${job.lastEvent}"
            col.addView(TextView(this).apply { text = info; setTextColor(th.text); textSize = 13f; setPadding(0, dp(10), 0, dp(2)) })
            val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            fun rowBtn(label: String, fn: () -> Unit) {
                row.addView(Button(this).apply { text = label; setTextColor(th.text); setOnClickListener { fn() } })
            }
            rowBtn("Ekor Log") { prootJobLogTail(job) }
            rowBtn("Restart") { prootJobRestart(job) }
            rowBtn("Stop") { prootJobStopConfirm(job) }
            rowBtn("Hapus") { prootJobDeleteConfirm(job) }
            col.addView(row)
        }
        val scroll = android.widget.ScrollView(this).apply { addView(col) }
        android.app.AlertDialog.Builder(this).setTitle("🧑‍🏭 Jobs Proot (Supervisor)").setView(scroll)
            .setNegativeButton("Tutup", null).show()
    }

    private fun prootJobLogTail(job: ProotJobs.Job) {
        Thread {
            val tail = try { ProotJobs.logTail(this@MainActivity, job.session, job.logPath) } catch (e: Exception) { "error: ${e.message}" }
            runOnUiThread {
                android.app.AlertDialog.Builder(this@MainActivity).setTitle("Ekor Log — ${job.name}").setMessage(tail.take(3000))
                    .setPositiveButton("OK", null)
                    .setNegativeButton("Periksa Ulang", { _, _ -> showProotJobsDialog() }).show()
            }
        }.start()
    }

    private fun prootJobRestart(job: ProotJobs.Job) {
        Toast.makeText(this, "Me-restart job '${job.name}'…", Toast.LENGTH_SHORT).show()
        Thread {
            val msg = try { ProotJobs.restartJob(this@MainActivity, job.id) } catch (e: Exception) { "error: ${e.message}" }
            runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showProotJobsDialog() }
        }.start()
    }

    private fun prootJobStopConfirm(job: ProotJobs.Job) {
        android.app.AlertDialog.Builder(this).setTitle("Stop job '${job.name}'?")
            .setMessage("Proses PID ${job.pid} di ${job.session} akan di-kill. Job yang di-stop TIDAK akan di-restart otomatis.")
            .setPositiveButton("Stop") { _, _ ->
                Thread {
                    val msg = try { ProotJobs.killJob(this@MainActivity, job.id) } catch (e: Exception) { "error: ${e.message}" }
                    runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showProotJobsDialog() }
                }.start()
            }
            .setNegativeButton("Batal", null).show()
    }

    private fun prootJobDeleteConfirm(job: ProotJobs.Job) {
        android.app.AlertDialog.Builder(this).setTitle("Hapus catatan job '${job.name}'?")
            .setMessage("Hanya catatan yang dihapus — proses TIDAK dibunuh. Pakai Stop dulu bila prosesnya harus mati.")
            .setPositiveButton("Hapus Catatan") { _, _ ->
                try { ProotJobs.remove(this@MainActivity, job.id) } catch (e: Exception) {}
                Toast.makeText(this@MainActivity, "Catatan job '${job.name}' dihapus.", Toast.LENGTH_SHORT).show()
                showProotJobsDialog()
            }
            .setNegativeButton("Batal", null).show()
    }

    private fun prootJobPickSession(cb: (String) -> Unit) {
        android.app.AlertDialog.Builder(this).setTitle("Pilih tangan worker")
            .setItems(arrayOf("worker1", "worker2", "worker3", "worker4")) { _, which ->
                cb(arrayOf("worker1", "worker2", "worker3", "worker4")[which])
            }
            .setNegativeButton("Batal", null).show()
    }

    private fun prootJobStartFlow() {
        inputDialog("Nama job", "mis. mitmproxy-tangkap", "") { name ->
            if (name.isBlank()) { Toast.makeText(this, "Nama tidak boleh kosong.", Toast.LENGTH_SHORT).show(); return@inputDialog }
            prootJobPickSession { session ->
                inputDialog("Perintah job", "perintah shell penuh di dalam proot", "") { command ->
                    if (command.isBlank()) { Toast.makeText(this, "Perintah tidak boleh kosong.", Toast.LENGTH_SHORT).show(); return@inputDialog }
                    inputDialog("Path log (boleh kosong = default)", "/root/.harness/jobs/<nama>.log", "") { logPath ->
                        android.app.AlertDialog.Builder(this).setTitle("Kebijakan restart")
                            .setItems(arrayOf("AUTO (restart otomatis maks 3x/jam)", "MANUAL (hanya restart manual)")) { _, which ->
                                val policy = if (which == 0) "AUTO" else "MANUAL"
                                Toast.makeText(this, "Meluncurkan job '$name'…", Toast.LENGTH_SHORT).show()
                                Thread {
                                    val msg = try { ProotJobs.startJob(this@MainActivity, name, session, command, logPath, policy) } catch (e: Exception) { "error: ${e.message}" }
                                    runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showProotJobsDialog() }
                                }.start()
                            }
                            .setNegativeButton("Batal", null).show()
                    }
                }
            }
        }
    }

    private fun prootJobRegisterFlow() {
        inputDialog("Nama job", "mis. mitmproxy-tangkap", "") { name ->
            if (name.isBlank()) { Toast.makeText(this, "Nama tidak boleh kosong.", Toast.LENGTH_SHORT).show(); return@inputDialog }
            prootJobPickSession { session ->
                inputDialog("PID proses", "angka PID dari pgrep", "") { pidText ->
                    val pid = pidText.toLongOrNull()
                    if (pid == null || pid <= 0L) { Toast.makeText(this, "PID tidak valid.", Toast.LENGTH_SHORT).show(); return@inputDialog }
                    inputDialog("Path log (boleh kosong)", "/root/mitm8080", "") { logPath ->
                        inputDialog("Perintah job (boleh kosong = MANUAL)", "perintah asli, untuk restart otomatis", "") { command ->
                            val policy = if (command.isBlank()) "MANUAL" else "AUTO"
                            Thread {
                                val msg = try { ProotJobs.registerExisting(this@MainActivity, name, session, pid, logPath, command, policy) } catch (e: Exception) { "error: ${e.message}" }
                                runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showProotJobsDialog() }
                            }.start()
                        }
                    }
                }
            }
        }
    }

    // vc256 Fase 1: panel Worker (Device Server) — Setup 67, kategori koneksi.
