    internal fun showWorkerDialog() {
        Toast.makeText(this, "Memeriksa status worker…", Toast.LENGTH_SHORT).show()
        Thread {
            try { WorkerRegistry.healthCheck(this@MainActivity) } catch (e: Exception) {}
            val workers = try { WorkerRegistry.list(this@MainActivity) } catch (e: Exception) { emptyList() }
            // vc281 Fase 3 (D3): ukuran folder per worker dihitung di
            // thread latar (bukan UI thread) untuk baris kuota panel.
            val sizes = try { workers.associate { it.id to WorkerJanitor.folderSizeBytes(this@MainActivity, it.id) } } catch (e: Exception) { emptyMap<String, Long>() }
            runOnUiThread { showWorkerList(workers, sizes) }
        }.start()
    }

    private fun showWorkerList(workers: List<WorkerRegistry.Worker>, sizes: Map<String, Long> = emptyMap()) {
        val th = currentTheme()
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(12), dp(16), dp(12)) }
        fun topBtn(label: String, fn: () -> Unit) {
            col.addView(Button(this).apply { text = label; setTextColor(th.text); setOnClickListener { fn() } })
        }
        topBtn("🔄 Periksa Ulang") { showWorkerDialog() }
        topBtn("▶ Spawn Worker Baru") { workerSpawnFlow() }
        topBtn("📥 Kumpulkan Hasil Semua Worker") {
            Toast.makeText(this, "Mengumpulkan hasil worker…", Toast.LENGTH_SHORT).show()
            Thread {
                val msgs = mutableListOf<String>()
                for (w in workers) {
                    try { msgs.add(WorkerRegistry.collectResults(this@MainActivity, w.id)) } catch (e: Exception) { msgs.add("error: ${e.message}") }
                }
                runOnUiThread { Toast.makeText(this@MainActivity, msgs.joinToString("\n"), Toast.LENGTH_LONG).show(); showWorkerDialog() }
            }.start()
        }
        // vc258 Fase 2: status + kendali endpoint :4200.
        val epStatus = try { WorkerEndpoint.status(this@MainActivity) } catch (e: Exception) { "Endpoint :4200: (tidak terbaca)" }
        col.addView(TextView(this).apply { text = "🔌 $epStatus\nToken TIDAK PERNAH ditampilkan di sini — tersimpan di SecureStore; file token untuk opencode ada di proot /root/.harness/worker-endpoint-token (0600)."; setTextColor(th.dim); textSize = 12f; setPadding(0, dp(8), 0, dp(2)) })
        val epRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
        fun epBtn(label: String, fn: () -> Unit) {
            epRow.addView(Button(this).apply { text = label; setTextColor(th.text); setOnClickListener { fn() } })
        }
        epBtn("▶ Mulai Endpoint") {
            Thread {
                val msg = try { WorkerEndpoint.ensureStarted(this@MainActivity) } catch (e: Exception) { "error: ${e.message}" }
                runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showWorkerDialog() }
            }.start()
        }
        epBtn("⏹ Stop Endpoint") {
            Thread {
                val msg = try { WorkerEndpoint.stop() } catch (e: Exception) { "error: ${e.message}" }
                runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showWorkerDialog() }
            }.start()
        }
        epBtn("🔑 Putar Token") {
            android.app.AlertDialog.Builder(this).setTitle("Putar token endpoint baru?")
                .setMessage("Token lama langsung tidak berlaku. File token di proot ditulis ulang otomatis — worker opencode yang membaca file itu ikut memakai token baru. Lakukan bila token dicurigai bocor.")
                .setPositiveButton("Putar Token") { _, _ ->
                    Thread {
                        // vc261 N-M6: sukses hanya bila file proot
                        // benar-benar tertulis (rotateToken kembalikan Boolean).
                        val msg = try { val (_, synced) = WorkerEndpoint.rotateToken(this@MainActivity); if (synced) "Token endpoint baru dibuat + file token proot ditulis ulang. Token TIDAK ditampilkan di sini." else "Token endpoint baru dibuat, tapi file token proot GAGAL ditulis — tekan 'Sinkron Token' setelah proot hidup (token lama di file proot sudah tidak berlaku)." } catch (e: Exception) { "error: ${e.message}" }
                        runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showWorkerDialog() }
                    }.start()
                }
                .setNegativeButton("Batal", null).show()
        }
        epBtn("🔄 Sinkron Token") {
            Thread {
                val msg = try { WorkerEndpoint.syncTokenFile(this@MainActivity) } catch (e: Exception) { "error: ${e.message}" }
                runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show() }
            }.start()
        }
        col.addView(epRow)
        if (workers.isEmpty()) {
            col.addView(TextView(this).apply { text = "Belum ada worker.\n\nWorker = satu unit kerja yang bisa di-spawn, dimonitor, di-stop, dan di-restart (Fase 1 Device-as-Server). Jenis: Proot (perintah shell) dan Script Python. Worker stateless — file, tugas, dan hasil tersimpan di agen (filesDir/workers/<id>/) + cermin /sdcard/Harness-Workers/<id>/ (terlihat dari luar app).\n\nBatas: maks 5 worker JALAN bersamaan; TANPA batasan baterai (K4); restart hanya manual (tanpa auto-restart). Isolasi Fase 3 (vc281): tiap sesi proot HANYA meng-bind folder cermin worker yang JALAN di sesi itu — /sdcard di luar folder itu tidak terlihat dari worker. Worker yang berbagi satu sesi bisa melihat folder cermin satu sama lain (batas jujur K4: 5 worker, 4 sesi). Kuota default 1024 MB per worker bila belum di-set; janitor menghapus hasil tertua bila melewati kuota + memberi tahu lewat notifikasi (bila masih over-kuota, janitor juga menghapus file kerja lama >7 hari; antrean Operator ikut kuota 1024 MB + janitor); log worker dirotasi di 1 MB. Verifikasi tugas sisi server: POST /workers/<id>/verify-task (body berisi nama file tugas) dengan token per-worker — kunci HMAC tidak pernah keluar dari app, jadi jawaban VALID dari rute itu benar-benar bukti asal agen; verify-queue.py di proot sudah dihapus. Hasil yang ditulis worker langsung ke cermin tanpa lewat endpoint tidak bertanda tangan dan dilabeli DATA TIDAK TEPERCAYA. Tangan serve (serve:4199) TIDAK dikelola di sini."; setTextColor(th.dim); textSize = 13f; setPadding(0, dp(8), 0, dp(8)) })
        }
        for (w in workers) {
            val disp = try { WorkerRegistry.displayStatus(this@MainActivity, w) } catch (e: Exception) { w.status }
            val quotaEff = WorkerJanitorLogic.effectiveQuotaMb(w.quotaMb)
            val usedBytes = sizes[w.id] ?: 0L
            val overQuota = usedBytes >= WorkerJanitorLogic.quotaBytes(w.quotaMb)
            val quotaLine = "Kuota: ${WorkerJanitorLogic.formatBytes(usedBytes)} dari ${WorkerJanitorLogic.formatBytes(WorkerJanitorLogic.quotaBytes(w.quotaMb))} (${if (w.quotaMb > 0) "di-set ${w.quotaMb} MB" else "default 1024 MB"})" + (if (overQuota) " — MELEWATI KUOTA (janitor membersihkan hasil tertua)" else "")
            val info = "📌 ${w.name} • ${WorkerLogic.kindLabel(w.kind)}\n${w.session} • PID ${w.pid} • $disp\nPerintah: ${w.command.take(120)}\nFolder: ${w.workDir}\n$quotaLine\nSesi ${w.session} hanya meng-bind folder cermin worker yang jalan di sesi itu — worker lain di sesi yang sama bisa melihat folder ini.\n${w.lastEvent}"
            col.addView(TextView(this).apply { text = info; setTextColor(th.text); textSize = 13f; setPadding(0, dp(10), 0, dp(2)) })
            val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            fun rowBtn(label: String, fn: () -> Unit) {
                row.addView(Button(this).apply { text = label; setTextColor(th.text); setOnClickListener { fn() } })
            }
            rowBtn("Ekor Log") { workerLogTail(w) }
            rowBtn("Restart") { workerRestart(w) }
            rowBtn("Stop") { workerStopConfirm(w) }
            rowBtn("Reset") { workerResetConfirm(w) }
            rowBtn("Hapus") { workerDeleteConfirm(w) }
            col.addView(row)
            val row2 = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            fun rowBtn2(label: String, fn: () -> Unit) {
                row2.addView(Button(this).apply { text = label; setTextColor(th.text); setOnClickListener { fn() } })
            }
            rowBtn2("Kirim Tugas") { workerSendTaskFlow(w) }
            rowBtn2("Hasil & Tugas") { workerResultsFlow(w) }
            rowBtn2("Preview Hasil") { workerPreviewFlow(w) }
            col.addView(row2)
        }
        val scroll = android.widget.ScrollView(this).apply { addView(col) }
        android.app.AlertDialog.Builder(this).setTitle("👷 Worker (Device Server)").setView(scroll)
            .setNegativeButton("Tutup", null).show()
    }

    private fun workerLogTail(w: WorkerRegistry.Worker) {
        Thread {
            val tail = try { WorkerRegistry.logTail(this@MainActivity, w.id) } catch (e: Exception) { "error: ${e.message}" }
            runOnUiThread {
                android.app.AlertDialog.Builder(this@MainActivity).setTitle("Ekor Log — ${w.name}").setMessage(tail.take(3000))
                    .setPositiveButton("OK", null)
                    .setNegativeButton("Periksa Ulang", { _, _ -> showWorkerDialog() }).show()
            }
        }.start()
    }

    private fun workerRestart(w: WorkerRegistry.Worker) {
        Toast.makeText(this, "Me-restart worker '${w.name}'…", Toast.LENGTH_SHORT).show()
        Thread {
            val msg = try { WorkerRegistry.restartWorker(this@MainActivity, w.id) } catch (e: Exception) { "error: ${e.message}" }
            runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showWorkerDialog() }
        }.start()
    }

