    private fun workerSpawnFlow() {
        inputDialog("Nama worker", "mis. sleep-test / hitung-harian", "") { name ->
            if (name.isBlank()) { Toast.makeText(this, "Nama tidak boleh kosong.", Toast.LENGTH_SHORT).show(); return@inputDialog }
            android.app.AlertDialog.Builder(this).setTitle("Jenis worker")
                .setItems(arrayOf("Proot — perintah shell", "Script Python")) { _, which ->
                    prootJobPickSession { session ->
                        if (which == 0) {
                            inputDialog("Perintah worker", "perintah shell penuh di dalam proot", "") { command ->
                                if (command.isBlank()) { Toast.makeText(this, "Perintah tidak boleh kosong.", Toast.LENGTH_SHORT).show(); return@inputDialog }
                                Toast.makeText(this, "Meluncurkan worker '$name'…", Toast.LENGTH_SHORT).show()
                                Thread {
                                    val msg = try { WorkerRegistry.spawnProot(this@MainActivity, name, session, command) } catch (e: Exception) { "error: ${e.message}" }
                                    runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showWorkerDialog() }
                                }.start()
                            }
                        } else {
                            workerCodeDialog { code ->
                                if (code.isBlank()) { Toast.makeText(this, "Kode Python tidak boleh kosong.", Toast.LENGTH_SHORT).show(); return@workerCodeDialog }
                                Toast.makeText(this, "Meluncurkan worker '$name'…", Toast.LENGTH_SHORT).show()
                                Thread {
                                    val msg = try { WorkerRegistry.spawnPython(this@MainActivity, name, session, code) } catch (e: Exception) { "error: ${e.message}" }
                                    runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showWorkerDialog() }
                                }.start()
                            }
                        }
                    }
                }
                .setNegativeButton("Batal", null).show()
        }
    }

    private fun workerCodeDialog(cb: (String) -> Unit) {
        val th = currentTheme()
        val et = EditText(this).apply {
            hint = "Kode Python (boleh banyak baris — mis. print('halo worker'))"
            setTextColor(th.text); setHintTextColor(th.dim)
            inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_FLAG_MULTI_LINE
            minLines = 6
            background = roundedS(th.bg, 12, th.stroke)
            setPadding(dp(12), dp(10), dp(12), dp(10))
        }
        android.app.AlertDialog.Builder(this).setTitle("Kode Python worker").setView(et)
            .setPositiveButton("Spawn") { d, _ -> cb(et.text.toString()); d.dismiss() }
            .setNegativeButton("Batal", null).show()
    }

    // vc258 Fase 2: preview hasil worker (cap 2000 char) dari panel.
    private fun workerPreviewFlow(w: WorkerRegistry.Worker) {
        Thread {
            val preview = try { WorkerRegistry.previewResult(this@MainActivity, w.id, "", 2000) } catch (e: Exception) { "error: ${e.message}" }
            runOnUiThread {
                android.app.AlertDialog.Builder(this@MainActivity).setTitle("Preview Hasil — ${w.name}").setMessage(preview.take(3000))
                    .setPositiveButton("OK", null)
                    .setNegativeButton("Periksa Ulang", { _, _ -> showWorkerDialog() }).show()
            }
        }.start()
    }

    private fun workerSendTaskFlow(w: WorkerRegistry.Worker) {
        inputDialog("Tugas untuk '${w.name}'", "tulis tugas — masuk antrean inbox worker", "") { task ->
            if (task.isBlank()) { Toast.makeText(this, "Tugas tidak boleh kosong.", Toast.LENGTH_SHORT).show(); return@inputDialog }
            Thread {
                val msg = try { WorkerRegistry.enqueueTask(this@MainActivity, w.id, task) } catch (e: Exception) { "error: ${e.message}" }
                runOnUiThread { Toast.makeText(this@MainActivity, msg, Toast.LENGTH_LONG).show(); showWorkerDialog() }
            }.start()
        }
    }

    private fun workerResultsFlow(w: WorkerRegistry.Worker) {
        Thread {
            val collected = try { WorkerRegistry.collectResults(this@MainActivity, w.id) } catch (e: Exception) { "error: ${e.message}" }
            val pending = try { WorkerRegistry.listPending(this@MainActivity, w.id) } catch (e: Exception) { emptyList() }
            val results = try { WorkerRegistry.listResults(this@MainActivity, w.id) } catch (e: Exception) { emptyList() }
            val latest = if (results.isNotEmpty()) try { WorkerRegistry.readResult(this@MainActivity, w.id, results.last()) } catch (e: Exception) { "" } else ""
            val sb = StringBuilder()
            sb.append(collected).append("\n\nTugas menunggu: ${pending.size}")
            for (p in pending) sb.append("\n- ").append(p)
            sb.append("\n\nHasil: ${results.size}")
            for (r in results) sb.append("\n- ").append(r)
            val summary = sb.toString()
            runOnUiThread {
                android.app.AlertDialog.Builder(this@MainActivity).setTitle("Hasil & Tugas — ${w.name}").setMessage(summary.take(3000))
                    .setPositiveButton("OK", null)
                    .setNeutralButton("Baca Hasil Terbaru", { _, _ ->
                        if (latest.isBlank()) { Toast.makeText(this@MainActivity, "Belum ada hasil.", Toast.LENGTH_SHORT).show(); return@setNeutralButton }
                        android.app.AlertDialog.Builder(this@MainActivity).setTitle("Hasil terbaru — ${w.name}").setMessage(latest.take(3000))
                            .setPositiveButton("OK", null).show()
                    })
                    .setNegativeButton("Periksa Ulang", { _, _ -> showWorkerDialog() }).show()
            }
        }.start()
    }

internal fun showLlmProviderDialog() {
    val ctx = this
    val th = currentTheme()
    // D12 (Fase 1) — dialog 73 (frame FigCraft 21/22/23): daftar provider
    // tersimpan di ATAS + form tambah/edit dengan picker model auto-fetch,
    // tes koneksi, simpan-aktifkan, dan hapus. Perbaikan fungsional minimal
    // pada struktur lama — BUKAN rewrite form bersama first-run (Fase 5).
    // - Label default TIDAK LAGI "DeepSeek (API Internal / Web)" untuk id
    //   "openai" (label awal = label preset, atau "OpenAI").
    // - Tombol "Pakai DeepSeek Web" DIHAPUS (K1).
    // - Key TIDAK PERNAH tampil: field selalu kosong saat dibuka; kosong =
    //   pakai key tersimpan lama. Key juga tidak pernah masuk log/pesan.
    var listDlg: AlertDialog? = null

    // Key efektif untuk tes: key terisi -> dipakai; kosong + base URL lokal
    // (Ollama) -> placeholder "ollama" (server lokal mengabaikan header
    // auth); kosong + bukan lokal -> null (tes tidak jalan, minta isi key).
    fun testKeyFor(baseUrl: String, key: String?): String? {
        if (!key.isNullOrBlank()) return key
        return if (LlmProviders.isLocalBaseUrl(baseUrl)) "ollama" else null
    }

    // Tes koneksi satu provider tersimpan (baris daftar): hasil tampil di
    // baris status baris itu — BUKAN toast yang hilang (§5.6).
    fun testProviderRow(p: LlmProvider, statusTv: TextView) {
        val key = testKeyFor(p.baseUrl, LlmProviderStore.apiKey(ctx, p.id))
        if (key == null) {
            statusTv.text = "✕ API key belum diisi — isi key di form edit."
            return
        }
        statusTv.text = "Mengetes… (timeout 30 dtk)"
        Thread {
            try {
                OpenAiCompatClient.ask(p, key, "ping", timeoutMs = 30_000)
                runOnUiThread { statusTv.text = "✓ Terhubung — model ${p.model} menjawab" }
            } catch (e: Exception) {
                val msg = RedactSecrets.redact(e.message ?: "gagal")
                runOnUiThread { statusTv.text = "✕ $msg" }
            }
        }.apply { isDaemon = true }.start()
    }

    // Hapus provider (C3): removeCustom + store.delete — key SecureStore +
    // cache models + counter Governor ikut terhapus di delete(). Bila yang
    // dihapus adalah provider AKTIF -> aktif kembali ke provider pertama
    // yang configured; bila tidak ada -> "belum ada provider aktif" +
    // pesan setup. Engine TETAP openai (JANGAN diam-diam ke deepseek).
    fun confirmDeleteProvider(p: LlmProvider, onDone: () -> Unit) {
        val wasActive = LlmProviderStore.activeId(ctx) == p.id || LlmProviders.activeId() == p.id
        AlertDialog.Builder(ctx)
            .setTitle("Hapus provider?")
            .setMessage("Hapus provider '${p.label}' (${p.id})?\n\nAPI key, cache daftar model, dan counter kuota provider ini ikut dihapus." + if (wasActive) "\n\nProvider ini sedang AKTIF — sesudah dihapus, provider pertama yang configured akan diaktifkan. Bila tidak ada, belum ada provider aktif sampai kamu mengatur yang baru." else "")
            .setPositiveButton("Hapus") { _, _ ->
                LlmProviders.removeCustom(p.id)
                LlmProviderStore.delete(ctx, p.id)
                if (wasActive) {
                    val next = LlmProviders.all().firstOrNull { it.kind == LlmKind.OPENAI_COMPAT && it.configured }
                    if (next != null) {
                        LlmProviderStore.setActive(ctx, next.id)
                        LlmProviders.setActive(next.id)
                        AgentEngines.setCurrent(ctx, "openai")
                        Toast.makeText(ctx, "Provider '${p.id}' dihapus. Provider aktif kini '${next.label}'.", Toast.LENGTH_LONG).show()
                    } else {
                        // Registry/store jatuh ke deepseek internal (fallback
                        // registry Fase 0) — TAPI engine tetap openai, jadi
                        // chat memberi pesan "Otak belum diatur" yang jujur.
                        LlmProviderStore.setActive(ctx, LlmProviders.ID_DEEPSEEK)
                        AgentEngines.setCurrent(ctx, "openai")
                        Toast.makeText(ctx, "Provider '${p.id}' dihapus. Belum ada provider aktif — atur provider di Setup > 73.", Toast.LENGTH_LONG).show()
                    }
                } else {
                    Toast.makeText(ctx, "Provider '${p.id}' dihapus.", Toast.LENGTH_SHORT).show()
                }
                onDone()
            }
            .setNegativeButton("Batal", null)
            .show()
    }

    // ---- Form tambah/edit (dialog sendiri, di atas daftar) ----
    fun openFormDialog(existing: LlmProvider?) {
        val preset = existing?.let { LlmProviders.preset(it.id) }
        val idTaken = existing == null && LlmProviders.find("openai") != null
        val initId = existing?.id ?: if (idTaken) "" else "openai"
        val initLabel = existing?.label ?: preset?.label ?: "OpenAI"
        val initBase = existing?.baseUrl ?: preset?.baseUrl ?: "https://api.openai.com/v1"
        val initModel = existing?.model ?: preset?.model ?: "gpt-4o-mini"
        var formDlg: AlertDialog? = null

        // ---- state form ----
        val editingId: String? = existing?.id
        var testSucceeded = false
        var pickerController: ModelPickerController? = null
        var pickerState: ModelPickerState? = null
        var currentModel: String? = initModel
        var spinnerModels: List<ModelInfo> = emptyList()
        var suppressSpinnerEvent = false
        var controllerProviderId = initId
        var refreshSaveEnabledFn: (() -> Unit)? = null

        // ---- field ----
        val provIdEt = EditText(ctx).apply { hint = "id (mis. openai, openrouter, ollama)"; setText(initId); setTextColor(th.text); setHintTextColor(th.dim); setPadding(dp(16), dp(8), dp(16), dp(8)) }
        val labelEt = EditText(ctx).apply { hint = "label (mis. OpenAI)"; setText(initLabel); setTextColor(th.text); setHintTextColor(th.dim); setPadding(dp(16), dp(8), dp(16), dp(8)) }
        val baseEt = EditText(ctx).apply { hint = "base_url (https://api.openai.com/v1)"; setText(initBase); setTextColor(th.text); setHintTextColor(th.dim); setPadding(dp(16), dp(8), dp(16), dp(8)) }
        val keyEt = EditText(ctx).apply { hint = "api_key (disimpan terenkripsi, tidak pernah tampil)"; inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD; setTextColor(th.text); setHintTextColor(th.dim); setPadding(dp(16), dp(8), dp(16), dp(8)) }
        val keyHelperTv = tv(if (existing != null && LlmProviderStore.apiKey(ctx, existing.id) != null) "Key tersimpan — kosongkan bila tidak diganti." else "Ollama lokal tidak butuh key.", 12f, th.dim)
        val modelSpinner = Spinner(ctx)
        val pickerStatusTv = tv("Isi base URL dulu — daftar model akan muncul otomatis.", 12f, th.dim)
        val retryBtn = thSmallBtn("⟳ Coba lagi") {}
        val manualBtn = thSmallBtn("Isi model manual") {}
        val reloadBtn = thSmallBtn("⟳ Muat ulang") {}
        val manualEt = EditText(ctx).apply { hint = "model (mis. gpt-4o-mini)"; setText(initModel); setTextColor(th.text); setHintTextColor(th.dim); setPadding(dp(16), dp(8), dp(16), dp(8)); visibility = View.GONE }
        val capEt = EditText(ctx).apply { hint = "dailyCapUnits (kosong = pakai global)"; inputType = android.text.InputType.TYPE_CLASS_NUMBER; setText(existing?.dailyCapUnits?.toString() ?: ""); setTextColor(th.text); setHintTextColor(th.dim); setPadding(dp(16), dp(8), dp(16), dp(8)) }
        val maxPromptEt = EditText(ctx).apply { hint = "maxPromptChars (kosong = default)"; inputType = android.text.InputType.TYPE_CLASS_NUMBER; setText(existing?.maxPromptChars?.toString() ?: ""); setTextColor(th.text); setHintTextColor(th.dim); setPadding(dp(16), dp(8), dp(16), dp(8)) }
        val guardToggle = tv("Pengaturan lanjutan ▾", 12.5f, th.text, true).apply { setPadding(0, dp(8), 0, dp(4)) }
        val guardBox = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL; visibility = View.GONE }
        guardBox.addView(capEt); guardBox.addView(maxPromptEt)
        guardToggle.setOnClickListener {
            val open = guardBox.visibility != View.VISIBLE
            guardBox.visibility = if (open) View.VISIBLE else View.GONE
            guardToggle.text = if (open) "Pengaturan lanjutan ▴" else "Pengaturan lanjutan ▾"
        }
        val formStatusTv = tv("", 12.5f, th.errText).apply { visibility = View.GONE }
        val testStatusTv = tv("Belum dites", 12f, th.dim)
        val baseRow = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL }
        baseEt.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        val refreshBaseBtn = thSmallBtn("⟳") {}
        baseRow.addView(baseEt); baseRow.addView(refreshBaseBtn)

        fun visionBadge(v: VisionSupport): String = when (v) {
            VisionSupport.SUPPORTED -> "👁 Vision"
            VisionSupport.UNSUPPORTED -> "—"
            else -> "👁?"
        }

        fun setSpinnerItems(labels: List<String>, enabled: Boolean, selectedId: String? = null) {
            modelSpinner.isEnabled = enabled
            val adapter = ArrayAdapter(ctx, android.R.layout.simple_spinner_item, labels)
            adapter.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
            suppressSpinnerEvent = true
            modelSpinner.adapter = adapter
            if (selectedId != null) {
                val idx = spinnerModels.indexOfFirst { it.id == selectedId }
                if (idx >= 0) modelSpinner.setSelection(idx)
            }
        }

        // Render SATU state picker (§5.10.3). Callback controller datang dari
        // thread worker — pemanggil WAJIB post ke main thread (di bindPicker).
        fun renderPickerState(state: ModelPickerState) {
            pickerState = state
            if (state.selectedModel != null) currentModel = state.selectedModel
            when (state.kind) {
                ModelPickerKind.IDLE -> {
                    spinnerModels = emptyList()
                    setSpinnerItems(listOf(state.message ?: "Isi base URL dulu — daftar model akan muncul otomatis."), enabled = false)
                    pickerStatusTv.text = state.message ?: ""
                    pickerStatusTv.setTextColor(th.dim)
                    retryBtn.visibility = View.GONE; manualBtn.visibility = View.GONE; reloadBtn.visibility = View.GONE
                    manualEt.visibility = View.GONE
                }
                ModelPickerKind.LOADING -> {
                    spinnerModels = emptyList()
                    setSpinnerItems(listOf("Memuat daftar model…"), enabled = false)
                    pickerStatusTv.text = state.message ?: "Memuat daftar model…"
                    pickerStatusTv.setTextColor(th.dim)
                    retryBtn.visibility = View.GONE; manualBtn.visibility = View.GONE; reloadBtn.visibility = View.GONE
                    manualEt.visibility = View.GONE
                }
                ModelPickerKind.LOADED -> {
                    spinnerModels = state.models
                    setSpinnerItems(state.models.map { m -> m.id + "  " + visionBadge(m.vision) }, enabled = true, selectedId = state.selectedModel)
                    pickerStatusTv.text = state.message ?: ""
                    pickerStatusTv.setTextColor(th.dim)
                    retryBtn.visibility = View.GONE; manualBtn.visibility = View.GONE
                    reloadBtn.visibility = View.VISIBLE; reloadBtn.text = "⟳ Muat ulang"
                    manualEt.visibility = View.GONE
                }
                ModelPickerKind.ERROR -> {
                    spinnerModels = emptyList()
                    setSpinnerItems(listOf("Gagal memuat daftar model"), enabled = false)
                    pickerStatusTv.text = state.message ?: "Gagal memuat daftar model."
                    pickerStatusTv.setTextColor(th.errText)
                    retryBtn.visibility = View.VISIBLE; manualBtn.visibility = View.VISIBLE; reloadBtn.visibility = View.GONE
                    manualEt.visibility = View.GONE
                }
                ModelPickerKind.EMPTY -> {
                    spinnerModels = emptyList()
                    setSpinnerItems(listOf("Tidak ada model"), enabled = false)
                    pickerStatusTv.text = state.message ?: "Provider menjawab tapi tidak mengembalikan model apa pun."
                    pickerStatusTv.setTextColor(th.errText)
                    retryBtn.visibility = View.VISIBLE; manualBtn.visibility = View.VISIBLE; reloadBtn.visibility = View.GONE
                    manualEt.visibility = View.GONE
                }
                ModelPickerKind.MANUAL -> {
                    setSpinnerItems(listOf("Mode manual — daftar tidak dimuat."), enabled = false)
                    pickerStatusTv.text = state.message ?: "Mode manual — daftar tidak dimuat."
                    pickerStatusTv.setTextColor(th.dim)
                    retryBtn.visibility = View.GONE; manualBtn.visibility = View.GONE
                    reloadBtn.visibility = View.VISIBLE; reloadBtn.text = "⟳ Coba muat daftar"
                    manualEt.visibility = View.VISIBLE
                }
                ModelPickerKind.AUTH_NEEDED -> {
                    spinnerModels = emptyList()
                    setSpinnerItems(listOf("Butuh API key"), enabled = false)
                    pickerStatusTv.text = state.message ?: "Provider ini butuh API key untuk melihat daftar model — isi API key di bawah."
                    pickerStatusTv.setTextColor(th.errText)
                    retryBtn.visibility = View.GONE; manualBtn.visibility = View.VISIBLE; reloadBtn.visibility = View.GONE
                    manualEt.visibility = View.GONE
                    keyEt.requestFocus()
                }
            }
            refreshSaveEnabledFn?.invoke()
        }

        // (Re)ikat controller ke id provider saat ini. Key tersimpan dipakai
        // untuk fetch (tidak pernah ditampilkan); field key tetap kosong.
        fun bindPicker(providerId: String) {
            controllerProviderId = providerId
            try { pickerController?.close() } catch (e: Exception) {}
            val storedKey = LlmProviderStore.apiKey(ctx, providerId)
            val c = ModelPickerController(ctx, providerId, onStateChanged = { st -> runOnUiThread { renderPickerState(st) } })
            pickerController = c
            if (initModel.isNotBlank()) c.selectModel(initModel)
            c.onOpened(baseEt.text.toString().trim(), storedKey)
        }

        fun currentModelForSave(): String {
            return if (pickerState?.kind == ModelPickerKind.MANUAL) manualEt.text.toString().trim()
            else currentModel?.trim() ?: ""
        }

        fun formStatus(msg: String, isError: Boolean) {
            formStatusTv.text = msg
            formStatusTv.setTextColor(if (isError) th.errText else th.text)
            formStatusTv.visibility = if (msg.isBlank()) View.GONE else View.VISIBLE
        }

        // Field berubah sesudah tes sukses -> hasil tes basi, tandai belum dites.
        fun markTestStale() {
            testSucceeded = false
            testStatusTv.text = "Belum dites"
        }

        fun runConnectionTest() {
            val id = provIdEt.text.toString().trim()
            val label = labelEt.text.toString().trim()
            val base = baseEt.text.toString().trim()
            val model = currentModelForSave()
            if (id.isBlank() || label.isBlank() || base.isBlank() || model.isBlank()) {
                formStatus("id/label/base_url/model wajib diisi dulu sebelum tes.", isError = true)
                return
            }
            if (!ModelPickerController.isValidBaseUrl(base)) {
                formStatus("Base URL tidak valid — harus http(s):// + host.", isError = true)
                return
            }
            val keyRaw = keyEt.text.toString().trim()
            val keyEff = keyRaw.ifBlank { LlmProviderStore.apiKey(ctx, id) }
            val testProv = LlmProvider(id, label, LlmKind.OPENAI_COMPAT, base, keyEff, model, enabled = true)
            val testKey = testKeyFor(base, keyEff)
            if (testKey == null) {
                testStatusTv.text = "✕ API key belum diisi — isi key dulu (Ollama lokal tidak butuh key)."
                testSucceeded = false
                return
            }
            testStatusTv.text = "Mengetes… (timeout 30 dtk)"
            testSucceeded = false
            Thread {
                try {
                    OpenAiCompatClient.ask(testProv, testKey, "ping", timeoutMs = 30_000)
                    runOnUiThread {
                        testStatusTv.text = "✓ Terhubung — model $model menjawab"
                        testSucceeded = true
                    }
                } catch (e: Exception) {
                    val msg = RedactSecrets.redact(e.message ?: "gagal")
                    runOnUiThread { testStatusTv.text = "✕ $msg" }
                }
            }.apply { isDaemon = true }.start()
        }

        fun doSave(id: String, label: String, base: String, model: String) {
            val keyRaw = keyEt.text.toString().trim()
            val keyEff = keyRaw.ifBlank { LlmProviderStore.apiKey(ctx, id) }
            // Field lanjutan yang tidak diedit di dialog ini diteruskan dari
            // record asal (edit) / preset (baru) — jangan direset diam-diam.
            val orig = if (editingId == id) existing else LlmProviders.preset(id)
            val cap = capEt.text.toString().trim().toIntOrNull()
            val maxPrompt = maxPromptEt.text.toString().trim().toIntOrNull()
            val p = try {
                LlmProviders.addCustom(
                    id, label, base, keyEff, model, true,
                    cap, maxPrompt, orig?.maxOutputTokens,
                    orig?.thinkingParam ?: "", orig?.toolsSupport ?: "unknown",
                    orig?.vision ?: "unknown", orig?.toolRoleFallback ?: false
                )
            } catch (e: Exception) {
                formStatus("Gagal: ${e.message}", isError = true); return
            }
            // D10: cek Boolean save() — gagal -> pesan merah + tetap di layar.
            if (!LlmProviderStore.save(ctx, p)) {
                formStatus("⚠️ Gagal menyimpan provider: tidak bisa menulis penyimpanan. Provider belum aktif.", isError = true)
                return
            }
            if (!p.configured) {
                formStatus("⚠️ Provider tersimpan, tapi belum lengkap (cek API key / model) — belum diaktifkan.", isError = true)
                return
            }
            LlmProviderStore.setActive(ctx, p.id)
            LlmProviders.setActive(p.id)
            AgentEngines.setCurrent(ctx, "openai")
            Toast.makeText(ctx, "Provider '${p.id}' aktif. Otak = Models API.", Toast.LENGTH_LONG).show()
            formDlg?.dismiss()
            listDlg?.dismiss()
        }

        fun doSaveAfterTestCheck(id: String, label: String, base: String, model: String) {
            // Tes koneksi belum pernah sukses -> konfirmasi dulu (frame 20).
            if (!testSucceeded) {
                AlertDialog.Builder(ctx)
                    .setTitle("Simpan tanpa tes?")
                    .setMessage("Koneksi belum dites / tes terakhir gagal. Simpan tetap?")
                    .setPositiveButton("Simpan tetap") { _, _ -> doSave(id, label, base, model) }
                    .setNegativeButton("Tes dulu", null)
                    .show()
                return
            }
            doSave(id, label, base, model)
        }

        fun onSave() {
            val id = provIdEt.text.toString().trim()
            val label = labelEt.text.toString().trim()
            val base = baseEt.text.toString().trim()
            val model = currentModelForSave()
            if (id.isBlank() || label.isBlank() || base.isBlank() || model.isBlank()) {
                formStatus("id/label/base_url/model wajib diisi.", isError = true); return
            }
            if (!LlmProviders.validateId(id)) {
                formStatus("id provider tidak valid (huruf kecil/angka/underscore, tanpa spasi).", isError = true); return
            }
            if (!ModelPickerController.isValidBaseUrl(base)) {
                formStatus("Base URL tidak valid — harus http(s):// + host.", isError = true); return
            }
            // Tabrakan id: id sudah ada dengan label berbeda -> Timpa/Batal.
            val clash = LlmProviders.find(id)
            if (editingId != id && clash != null && clash.kind == LlmKind.OPENAI_COMPAT) {
                AlertDialog.Builder(ctx)
                    .setTitle("Timpa provider?")
                    .setMessage("Provider '$id' sudah ada sebagai '${clash.label}'.\n\nSimpan akan menimpa label, base URL, model, dan guard provider itu (key lama tetap dipakai bila field key kosong).")
                    .setPositiveButton("Timpa") { _, _ -> doSaveAfterTestCheck(id, label, base, model) }
                    .setNegativeButton("Batal", null)
                    .show()
                return
            }
            doSaveAfterTestCheck(id, label, base, model)
        }

        // ---- tombol form ----
        val testBtn = thBtn("🔍 Tes Koneksi", false) { runConnectionTest() }
        val saveBtn = thBtn("💾 Simpan & Aktifkan", true) { onSave() }
        refreshSaveEnabledFn = {
            val ok = provIdEt.text.toString().trim().isNotBlank() &&
                labelEt.text.toString().trim().isNotBlank() &&
                baseEt.text.toString().trim().isNotBlank() &&
                currentModelForSave().isNotBlank()
            saveBtn.isEnabled = ok
            saveBtn.alpha = if (ok) 1f else 0.5f
        }
        val btnRow1 = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(12), 0, 0) }
        for (b in listOf(testBtn, saveBtn)) b.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
        btnRow1.addView(testBtn); btnRow1.addView(saveBtn)
        val btnRow2 = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL }
        if (existing != null) {
            val deleteBtn = thBtn("🗑 Hapus provider", false) {
                confirmDeleteProvider(existing) { formDlg?.dismiss(); listDlg?.dismiss(); showLlmProviderDialog() }
            }
            deleteBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
            btnRow2.addView(deleteBtn)
        }
        val cancelBtn = thBtn("Batal", false) { formDlg?.dismiss() }
        cancelBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
        btnRow2.addView(cancelBtn)

        // ---- rakit form ----
        val pickerBtnRow = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(4), 0, 0) }
        pickerBtnRow.addView(retryBtn); pickerBtnRow.addView(manualBtn); pickerBtnRow.addView(reloadBtn)
        val formView = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL }
        formView.addView(provIdEt); formView.addView(labelEt); formView.addView(baseRow)
        formView.addView(tv("Model", 12.5f, th.dim))
        formView.addView(modelSpinner)
        formView.addView(pickerStatusTv)
        formView.addView(pickerBtnRow)
        formView.addView(manualEt)
        formView.addView(keyEt); formView.addView(keyHelperTv)
        formView.addView(guardToggle); formView.addView(guardBox)
        formView.addView(testStatusTv)
        formView.addView(formStatusTv)
        formView.addView(btnRow1); formView.addView(btnRow2)

        // ---- watcher + listener ----
        val textWatcher = { after: (String) -> Unit ->
            object : android.text.TextWatcher {
                override fun beforeTextChanged(s: CharSequence?, start: Int, count: Int, after: Int) {}
                override fun onTextChanged(s: CharSequence?, start: Int, before: Int, count: Int) {}
                override fun afterTextChanged(s: android.text.Editable?) { after(s?.toString() ?: "") }
            }
        }
        baseEt.addTextChangedListener(textWatcher { v ->
            markTestStale()
            pickerController?.onBaseUrlChanged(v)
            refreshSaveEnabledFn?.invoke()
        })
        baseEt.onFocusChangeListener = View.OnFocusChangeListener { _, hasFocus ->
            if (!hasFocus) pickerController?.onBaseUrlFocusLost(baseEt.text.toString())
        }
        keyEt.addTextChangedListener(textWatcher { v ->
            markTestStale()
            pickerController?.onApiKeyChanged(v)
        })
        provIdEt.addTextChangedListener(textWatcher {
            markTestStale()
            refreshSaveEnabledFn?.invoke()
        })
        provIdEt.onFocusChangeListener = View.OnFocusChangeListener { _, hasFocus ->
            if (!hasFocus) {
                val newId = provIdEt.text.toString().trim()
                if (newId.isNotBlank() && newId != controllerProviderId) bindPicker(newId)
                refreshSaveEnabledFn?.invoke()
            }
        }
        labelEt.addTextChangedListener(textWatcher { refreshSaveEnabledFn?.invoke() })
        manualEt.addTextChangedListener(textWatcher {
            if (pickerState?.kind == ModelPickerKind.MANUAL) {
                markTestStale()
                refreshSaveEnabledFn?.invoke()
            }
        })
        modelSpinner.onItemSelectedListener = object : android.widget.AdapterView.OnItemSelectedListener {
            override fun onItemSelected(parent: android.widget.AdapterView<*>?, view: View?, position: Int, id: Long) {
                if (suppressSpinnerEvent) { suppressSpinnerEvent = false; return }
                val picked = spinnerModels.getOrNull(position) ?: return
                if (picked.id == currentModel) return
                currentModel = picked.id
                pickerController?.selectModel(picked.id)
                markTestStale()
                refreshSaveEnabledFn?.invoke()
            }
            override fun onNothingSelected(parent: android.widget.AdapterView<*>?) {}
        }
        retryBtn.setOnClickListener { pickerController?.retry() }
        manualBtn.setOnClickListener { pickerController?.useManualModel(manualEt.text.toString().trim()) }
        reloadBtn.setOnClickListener { pickerController?.refresh() }
        refreshBaseBtn.setOnClickListener { pickerController?.refresh() }

        bindPicker(initId)
        refreshSaveEnabledFn?.invoke()
        formDlg = thDialog(if (existing == null) "＋ Tambah Provider" else "Edit Provider: ${existing.label}", formView, emptyList())
        formDlg?.setOnDismissListener { try { pickerController?.close() } catch (e: Exception) {} }
    }

    // ---- Daftar provider (frame 21) ----
    val listBody = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL }
    fun rebuildList() {
        listBody.removeAllViews()
        val skippedNow = LlmProviderStore.hydrate(ctx)
        val actId = LlmProviderStore.activeId(ctx)
        val engineOpenAi = AgentEngines.current(ctx) == "openai"
        val providers = LlmProviders.all().filter { it.kind == LlmKind.OPENAI_COMPAT }
        val activeProv = providers.firstOrNull { it.id == actId }
        listBody.addView(tv(
            if (activeProv != null && engineOpenAi) "Otak aktif: ${activeProv.label} (${activeProv.id}) — Models API"
            else if (providers.isEmpty()) "Belum ada provider — tambah satu di bawah."
            else "Belum ada provider aktif — ketuk satu untuk mengaktifkan.",
            12.5f, th.dim))
        for (sid in skippedNow) listBody.addView(tv("⚠️ $sid: konfigurasi rusak, tidak dimuat", 12.5f, th.errText))
        for (p in providers) {
            val isActive = p.id == actId && engineOpenAi
            val row = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL; background = rounded(th.tileBg, 14); setPadding(dp(12), dp(10), dp(12), dp(10)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { setMargins(0, dp(4), 0, dp(4)) } }
            val colP = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL; layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f) }
            colP.addView(tv(p.label + if (isActive) " • AKTIF" else "", 14f, th.text, true))
            colP.addView(tv(p.id + " • " + p.model + if (p.configured) "" else " • belum lengkap", 12f, th.dim))
            val rowStatus = tv("", 12f, th.dim)
            colP.addView(rowStatus)
            row.addView(colP)
            row.addView(thSmallBtn("🔍 Tes") { testProviderRow(p, rowStatus) })
            row.addView(thSmallBtn("🗑") { confirmDeleteProvider(p) { rebuildList() } })
            colP.setOnClickListener {
                if (p.configured) {
                    LlmProviderStore.setActive(ctx, p.id)
                    LlmProviders.setActive(p.id)
                    AgentEngines.setCurrent(ctx, "openai")
                    Toast.makeText(ctx, "Provider '${p.id}' aktif. Otak = Models API.", Toast.LENGTH_LONG).show()
                    listDlg?.dismiss()
                } else {
                    openFormDialog(p)
                }
            }
            listBody.addView(row)
        }
        listBody.addView(tv("Ketuk provider untuk mengaktifkan (bila sudah lengkap) atau mengedit.", 12f, th.dim))
        val btnRow = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(8), 0, 0) }
        thRowBtn(btnRow, "＋ Tambah Provider", true) { openFormDialog(null) }
        thRowBtn(btnRow, "Batal", false) { listDlg?.dismiss() }
        listBody.addView(btnRow)
    }
    rebuildList()
    listDlg = thDialog("🧠 Provider LLM", listBody, emptyList())
}

internal fun showApiTokenDialog() {
        val ctx = this
        val th = currentTheme()
        val clients = ApiClients.CLIENTS
        val lay = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL }
        val statusTv = tv("Status: —", 12.5f, th.dim)
        lay.addView(statusTv)
        val spinner = Spinner(ctx).apply {
            adapter = ArrayAdapter(ctx, android.R.layout.simple_spinner_item,
                clients.map { it.label + if (!it.enabled) " (contoh)" else "" }).apply {
                setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item)
            }
        }
        lay.addView(spinner)
        val et = EditText(ctx).apply {
            hint = "Token klien (dari sesi login sendiri — tidak pernah lewat chat)"
            inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD
            setTextColor(th.text); setHintTextColor(th.dim)
            setPadding(dp(16), dp(8), dp(16), dp(8))
        }
        lay.addView(et)
        fun sel(): ApiClientDef = clients[spinner.selectedItemPosition.coerceIn(0, clients.size - 1)]
        fun refreshStatus() {
            val d = sel()
            statusTv.text = "Klien: " + d.label + "\nStatus: " + if (ApiClients.hasToken(ctx, d.id)) "ADA (nilai tidak ditampilkan)" else "BELUM"
        }
        spinner.onItemSelectedListener = object : android.widget.AdapterView.OnItemSelectedListener {
            override fun onItemSelected(parent: android.widget.AdapterView<*>?, view: android.view.View?, position: Int, id: Long) { refreshStatus() }
            override fun onNothingSelected(parent: android.widget.AdapterView<*>?) {}
        }
        refreshStatus()
        thDialog("🔌 Token API-Buatan", lay, listOf(
            Triple("Simpan", true) { dd: android.app.AlertDialog ->
                val d = sel()
                val v = et.text.toString().trim()
                if (v.isBlank()) Toast.makeText(ctx, "Token kosong — tidak disimpan.", Toast.LENGTH_SHORT).show()
                else { ApiClients.setToken(ctx, d.id, v); Toast.makeText(ctx, "Token tersimpan (nilai tidak ditampilkan).", Toast.LENGTH_SHORT).show(); dd.dismiss() }
            },
            Triple("Hapus", false) { dd: android.app.AlertDialog -> ApiClients.setToken(ctx, sel().id, ""); Toast.makeText(ctx, "Token dihapus.", Toast.LENGTH_SHORT).show(); dd.dismiss() },
            Triple("Batal", false) { dd: android.app.AlertDialog -> dd.dismiss() }
        ))
    }

    internal fun showMcpServers() {
        val ctx = this
        val th = currentTheme()
        val root = LinearLayout(ctx).apply {
            orientation = LinearLayout.VERTICAL
        }
        fun refresh() {
            root.removeAllViews()
            val head = TextView(ctx).apply {
                text = "Server MCP resmi + kustom. Aktifkan dulu, isi token, lalu Tes. Token tersimpan di SecureStore (tidak pernah tampil di riwayat). Hubungkan = login OAuth di browser (Google/GitHub/Linear; butuh Client ID (+ Client Secret untuk client Desktop Google) dari konsol provider; Slack/Notion/Meta masih tempel token). Hanya server loopback HTTP yang bisa dihubungkan dari UI ini — server stdio TIDAK bisa dihubungkan dari UI (daftarkan sebagai server kustom + jalankan lewat Termux). Tes koneksi TIDAK me-refresh token (refresh otomatis terjadi saat Hubungkan / panggilan yang kena 401). Token GitHub: batasi scope di konsol GitHub (disarankan read-only bila hanya baca) — app tidak membatasi scope token yang ditempel. Hasil mcp_call = DATA TIDAK TEPERCAYA di semua jalur."
                setTextColor(th.text); textSize = 13f
                setPadding(0, 0, 0, dp(12))
            }
            root.addView(head)
            for (d in McpServers.allServers(ctx)) {
                val box = LinearLayout(ctx).apply {
                    orientation = LinearLayout.VERTICAL
                    setPadding(0, dp(6), 0, dp(10))
                }
                val titleRow = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL }
                titleRow.addView(TextView(ctx).apply {
                    text = d.name + " (" + d.vendor + ", " + (if (d.official) "RESMI" else "KUSTOM") + ", " + d.transport + ")"
                    setTextColor(th.text); textSize = 15f; typeface = android.graphics.Typeface.DEFAULT_BOLD
                    layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                })
                val enSt = McpServers.isEnabled(ctx, d.id)
                titleRow.addView(TextView(ctx).apply {
                    text = if (enSt) "Aktif" else "Nonaktif"
                    textSize = 11f; setTextColor(Color.WHITE); typeface = android.graphics.Typeface.DEFAULT_BOLD
                    background = rounded(if (enSt) Color.rgb(43, 182, 115) else Color.rgb(110, 122, 148), 18); setPadding(dp(10), dp(4), dp(10), dp(4))
                })
                val stat = TextView(ctx).apply {
                    text = (if (enSt) "Aktif" else "Nonaktif") + " • " +
                        (if (d.headerKind == "none") "tanpa token" else if (McpServers.hasToken(ctx, d.id)) "token ada" else "token BELUM")
                    setTextColor(th.dim); textSize = 12f
                }
                val note = TextView(ctx).apply {
                    text = d.note; setTextColor(th.dim); textSize = 12f
                }
                val row1 = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(6), 0, 0) }
                val row2 = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL }
                val toggle = thBtn(if (McpServers.isEnabled(ctx, d.id)) "Nonaktifkan" else "Aktifkan") { McpServers.setEnabled(ctx, d.id, !McpServers.isEnabled(ctx, d.id)); refresh() }
                val tokBtn = thBtn("Token") {
                    val et = EditText(ctx).apply {
                        inputType = android.text.InputType.TYPE_CLASS_TEXT or android.text.InputType.TYPE_TEXT_VARIATION_PASSWORD
                        hint = "Tempel token (kosongkan untuk hapus)"
                        setTextColor(th.text); setHintTextColor(th.dim)
                        setPadding(dp(16), dp(8), dp(16), dp(8))
                    }
                    thDialog("Token: " + d.name, et, listOf(
                        Triple("Simpan", true) { dd: android.app.AlertDialog -> McpServers.setToken(ctx, d.id, et.text.toString().trim()); refresh(); dd.dismiss() },
                        Triple("Batal", false) { dd: android.app.AlertDialog -> dd.dismiss() }
                    ))
                }
                val testBtn = thBtn("Tes") {
                    if (d.transport != "http") {
                        Toast.makeText(ctx, "Tes stdio belum didukung di panel — pakai mcp_call langsung.", Toast.LENGTH_LONG).show()
                        return@thBtn
                    }
                    if (!McpServers.isEnabled(ctx, d.id)) {
                        Toast.makeText(ctx, "Aktifkan dulu server ini.", Toast.LENGTH_SHORT).show()
                        return@thBtn
                    }
                    if (d.url.isNullOrBlank()) {
                        Toast.makeText(ctx, "URL server kosong.", Toast.LENGTH_SHORT).show()
                        return@thBtn
                    }
                    Thread {
                        val msg = try {
                            val tools = McpHttp.listTools(d.url!!, d.headerKind, McpServers.tokenFor(ctx, d.id))
                            "Tes ${d.name}: OK, ${tools.size} tool."
                        } catch (e: Exception) {
                            "Tes ${d.name} gagal: ${e.message}"
                        }
                        runOnUiThread { Toast.makeText(ctx, msg, Toast.LENGTH_LONG).show() }
                    }.start()
                }
                if (d.oauthKind != "none") {
                    val hubBtn = thBtn("Hubungkan") {
                        val cid = McpServers.clientIdFor(ctx, d.id)
                        if (cid.isNullOrBlank()) {
                            val et = EditText(ctx).apply {
                                hint = "Client ID dari konsol provider (publik, bukan secret)"
                                setTextColor(th.text); setHintTextColor(th.dim)
                                setPadding(dp(16), dp(8), dp(16), dp(8))
                            }
                            thDialog("Client ID: " + d.name, et, listOf(
                                Triple("Lanjut", true) { dd: android.app.AlertDialog ->
                                    val v = et.text.toString().trim()
                                    dd.dismiss()
                                    if (v.isBlank()) Toast.makeText(ctx, "Client ID kosong — Hubungkan dibatalkan.", Toast.LENGTH_SHORT).show()
                                    else { McpServers.setClientId(ctx, d.id, v); startHub(ctx, d, v) }
                                },
                                Triple("Batal", false) { dd: android.app.AlertDialog -> dd.dismiss() }
                            ))
                        } else startHub(ctx, d, cid)
                    }
                    val cidBtn = thBtn("Client ID") {
                        val et = EditText(ctx).apply {
                            setText(McpServers.clientIdFor(ctx, d.id) ?: "")
                            hint = "Client ID (kosongkan untuk hapus)"
                            setTextColor(th.text); setHintTextColor(th.dim)
                            setPadding(dp(16), dp(8), dp(16), dp(8))
                        }
                        thDialog("Client ID: " + d.name, et, listOf(
                            Triple("Simpan", true) { dd: android.app.AlertDialog -> McpServers.setClientId(ctx, d.id, et.text.toString().trim()); refresh(); dd.dismiss() },
                            Triple("Batal", false) { dd: android.app.AlertDialog -> dd.dismiss() }
                        ))
                    }
                    thAddW(row1, hubBtn); thAddW(row1, cidBtn)
                    // vc246 GELOMBANG 5 (FT-M8): field Secret hanya
                    // untuk server Google loopback yang benar-benar
                    // membutuhkannya (client Desktop Google, exchange +
                    // refresh). Linear loopback TIDAK membutuhkannya —
                    // dulu tampil untuk semua server loopback.
                    if (d.oauthKind == "loopback" && d.vendor == "Google") {
                        val secBtn = thBtn("Secret") {
                            val hasSec = !McpServers.clientSecretFor(ctx, d.id).isNullOrBlank()
                            val lay = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL }
                            lay.addView(tv(if (hasSec) "Status: tersimpan" else "Status: belum diisi", 12.5f, th.dim))
                            val et = EditText(ctx).apply {
                                hint = "Client Secret dari konsol provider (untuk client Desktop Google)"
                                setTextColor(th.text); setHintTextColor(th.dim)
                                setPadding(dp(16), dp(8), dp(16), dp(8))
                            }
                            lay.addView(et)
                            thDialog("Secret: " + d.name, lay, listOf(
                                Triple("Simpan", true) { dd: android.app.AlertDialog ->
                                    val v = et.text.toString().trim()
                                    if (v.isBlank()) Toast.makeText(ctx, "Secret kosong — tidak disimpan.", Toast.LENGTH_SHORT).show()
                                    else { McpServers.setClientSecret(ctx, d.id, v); refresh(); dd.dismiss() }
                                },
                                Triple("Hapus", false) { dd: android.app.AlertDialog -> McpServers.setClientSecret(ctx, d.id, ""); refresh(); dd.dismiss() },
                                Triple("Batal", false) { dd: android.app.AlertDialog -> dd.dismiss() }
                            ))
                        }
                        thAddW(row1, secBtn)
                    }
                    thAddW(row2, toggle); thAddW(row2, tokBtn); thAddW(row2, testBtn)
                } else if (!d.official) {
                    thAddW(row1, toggle); thAddW(row1, tokBtn)
                    val del = Button(ctx).apply {
                        text = "Hapus"
                        background = rounded(Color.rgb(150, 50, 50), 12); setTextColor(Color.WHITE)
                        setPadding(dp(12), dp(10), dp(12), dp(10)); minWidth = 0; minHeight = 0
                        setOnClickListener { McpServers.removeCustom(ctx, d.id); refresh() }
                    }
                    thAddW(row2, del); thAddW(row2, testBtn)
                } else {
                    thAddW(row1, toggle); thAddW(row1, tokBtn); thAddW(row1, testBtn)
                }
                box.addView(titleRow); box.addView(stat); box.addView(note); box.addView(row1)
                if (row2.childCount > 0) box.addView(row2)
                root.addView(box)
            }
            val addRow = LinearLayout(ctx).apply { orientation = LinearLayout.HORIZONTAL }
            val addHttp = thBtn("Tambah HTTP") {
                val lay = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL }
                val eName = EditText(ctx).apply { hint = "Nama (mis. Server Saya)"; setTextColor(th.text); setHintTextColor(th.dim) }
                val eUrl = EditText(ctx).apply { hint = "URL (https://…/mcp)"; setTextColor(th.text); setHintTextColor(th.dim) }
                val eHead = EditText(ctx).apply { hint = "Header: bearer / goog-api-key / none"; setText("bearer"); setTextColor(th.text); setHintTextColor(th.dim) }
                lay.addView(eName); lay.addView(eUrl); lay.addView(eHead)
                thDialog("Server MCP HTTP kustom", lay, listOf(
                    Triple("Tambah", true) { dd: android.app.AlertDialog ->
                        val nm = eName.text.toString().trim()
                        val url = eUrl.text.toString().trim()
                        val hk = eHead.text.toString().trim().lowercase()
                        if (nm.isBlank() || url.isBlank()) {
                            Toast.makeText(ctx, "Nama + URL wajib diisi.", Toast.LENGTH_SHORT).show()
                        } else {
                            val id = "custom_" + System.currentTimeMillis()
                            McpServers.addCustom(ctx, McpServerDef(id, nm, "Kustom", "http", url, null, if (hk == "goog-api-key" || hk == "none") hk else "bearer", false, "Server kustom (HTTP)."))
                            refresh()
                            dd.dismiss()
                        }
                    },
                    Triple("Batal", false) { dd: android.app.AlertDialog -> dd.dismiss() }
                ))
            }
            val addStdio = thBtn("Tambah stdio") {
                val lay = LinearLayout(ctx).apply { orientation = LinearLayout.VERTICAL }
                val eName = EditText(ctx).apply { hint = "Nama (mis. Server Lokal Saya)"; setTextColor(th.text); setHintTextColor(th.dim) }
                val eCmd = EditText(ctx).apply { hint = "Perintah (mis. npx -y paket-mcp@latest)"; setTextColor(th.text); setHintTextColor(th.dim) }
                lay.addView(eName); lay.addView(eCmd)
                thDialog("Server MCP stdio kustom", lay, listOf(
                    Triple("Tambah", true) { dd: android.app.AlertDialog ->
                        val nm = eName.text.toString().trim()
                        val cmd = eCmd.text.toString().trim()
                        if (nm.isBlank() || cmd.isBlank()) {
                            Toast.makeText(ctx, "Nama + perintah wajib diisi.", Toast.LENGTH_SHORT).show()
                        } else {
                            val id = "custom_" + System.currentTimeMillis()
                            McpServers.addCustom(ctx, McpServerDef(id, nm, "Kustom", "stdio", null, cmd, "none", false, "Server kustom (stdio via Termux)."))
                            refresh()
                            dd.dismiss()
                        }
                    },
                    Triple("Batal", false) { dd: android.app.AlertDialog -> dd.dismiss() }
                ))
            }
            thAddW(addRow, addHttp); thAddW(addRow, addStdio)
            root.addView(addRow)
        }
        refresh()
        thDialog("Konektor MCP", root, listOf(Triple("Tutup", false) { d: android.app.AlertDialog -> d.dismiss() }))
    }

    internal fun showAnrTrace() {
        if (Build.VERSION.SDK_INT < 30) {
            setupStatusTv.text = "Jejak ANR butuh Android 11+ (API 30) — HP ini API ${Build.VERSION.SDK_INT}."
            return
        }
        try {
            val am = getSystemService(Context.ACTIVITY_SERVICE) as android.app.ActivityManager
            val reasons = am.getHistoricalProcessExitReasons(packageName, 0, 20)
            val anrs = reasons.filter { it.reason == android.app.ApplicationExitInfo.REASON_ANR }
            if (anrs.isEmpty()) {
                setupStatusTv.text = "Tidak ada rekaman ANR yang mematikan proses (riwayat exit: ${reasons.size} entri). ANR yang berakhir dengan 'Tunggu' tidak terekam — untuk menangkapnya, ketuk OK saat ANR lalu buka tombol ini."
                return
            }
            val fmt = java.text.SimpleDateFormat("yyyy-MM-dd HH:mm:ss", java.util.Locale("id", "ID"))
            val head = StringBuilder()
            head.append("ANR terakhir: ${fmt.format(java.util.Date(anrs[0].timestamp))}\n")
            head.append("Total rekaman ANR: ${anrs.size}\n")
            for (r in anrs.take(5)) head.append("- ${fmt.format(java.util.Date(r.timestamp))}\n")
            head.append("\n")
            val trace = try {
                anrs[0].traceInputStream?.bufferedReader()?.use { it.readText().take(12000) } ?: "(jejak tidak tersedia)"
            } catch (e: Exception) { "(gagal baca jejak: ${e.message})" }
            val tv = TextView(this).apply { text = head.toString() + trace; setTextIsSelectable(true); setTextColor(TEXT); textSize = 11f; setPadding(dp(12), dp(12), dp(12), dp(12)) }
            val sv = ScrollView(this).apply { addView(tv) }
            android.app.AlertDialog.Builder(this).setTitle("Jejak ANR Terakhir").setView(sv).setPositiveButton("Tutup", null).show()
        } catch (e: Exception) {
            setupStatusTv.text = "Gagal baca jejak ANR: ${e.message}"
        }
    }

    internal fun runUjiMandiri() {
        if (TurnMetrics.isBegun()) {
            runOnUiThread { setupStatusTv.text = "Uji Mandiri ditolak: giliran sedang berjalan — jalankan lagi sesudah giliran selesai." }
            return
        }
        runOnUiThread { setupStatusTv.text = "Uji Mandiri berjalan… (tanpa model, tanpa jaringan)" }
        Thread {
            val stamp = java.text.SimpleDateFormat("yyyyMMdd-HHmmss", java.util.Locale.US).format(java.util.Date())
            val lines = ArrayList<String>()
            lines.add("# uji-mandiri | $stamp")
            var pass = 0; var fail = 0; var skip = 0
            fun verdict(name: String, ok: Boolean?, detail: String) {
                when (ok) {
                    true -> { pass++; lines.add("$name: LOLOS — $detail") }
                    false -> { fail++; lines.add("$name: GAGAL — $detail") }
                    null -> { skip++; lines.add("$name: SKIP — $detail") }
                }
            }
            // ---------- Cek 1: unknown tool 3x ----------
            try {
                val stuckSnap = HashMap(stuckMap)
                val blockedSnap = turnStuckBlocked
                try {
                    Tools.setSkipStore(true)
                    val fakes = listOf("tool_palsu_uji_1", "tool_palsu_uji_2", "tool_palsu_uji_3")
                    val results = fakes.map { Tools.execute(this@MainActivity, it, org.json.JSONObject()) }
                    val allUnknown = results.all { it.startsWith("Tool tidak dikenal") }
                    val listTxt = AgentPrompt.validToolListText(this@MainActivity)
                    val groupTxt = AgentPrompt.toolGroupSummary(this@MainActivity)
                    val s1 = unknownSuffix(1, fakes[0], fakes.take(1), listTxt, groupTxt)
                    val s2 = unknownSuffix(2, fakes[1], fakes.take(2), listTxt, groupTxt)
                    val s3 = unknownSuffix(3, fakes[2], fakes, listTxt, groupTxt)
                    val stopRule = 3 >= unknownStopAt
                    for (i in fakes.indices) stuckSuffix(fakes[i], org.json.JSONObject(), results[i], countIdent = false)
                    val stuckUnchanged = stuckMap == stuckSnap
                    val noLock = !turnStuckBlocked && !s1.contains("🛑") && !s2.contains("🛑")
                    val shapes = s1.contains("1/3") && s1.contains("JANGAN menebak") && s2.contains("2/3") && s2.contains(fakes.take(2).joinToString(", ")) && s3.isEmpty()
                    val ok = allUnknown && listTxt.isNotBlank() && shapes && stuckUnchanged && noLock && stopRule
                    verdict("Cek 1 (unknown tool 3x)", ok, "3 hasil prefix 'Tool tidak dikenal'=$allUnknown, daftar valid tak kosong=${listTxt.isNotBlank()} (>=50 per kontrak validToolListText), bentuk suffix 1/2/kosong=$shapes, stuckMap tak berubah=$stuckUnchanged, tanpa kunci=$noLock, ambang berhenti bersama=$stopRule (teks gelembung berhenti tidak tercakup — butuh giliran penuh)")
                } finally {
                    Tools.setSkipStore(false)
                    stuckMap.clear(); stuckMap.putAll(stuckSnap)
                    turnStuckBlocked = blockedSnap
                }
            } catch (e: Exception) { verdict("Cek 1 (unknown tool 3x)", false, "exception: ${e.message}") }
            // ---------- Cek 2: potong proot ----------
            try {
                val a = ProotSession.truncateOutput("x".repeat(8000))
                val b = ProotSession.truncateOutput("y".repeat(8001))
                val c = ProotSession.truncateOutput("z".repeat(20000))
                val d = ProotSession.truncateOutput("w".repeat(8000) + "\r\n")
                val e = "a".repeat(2999) + "😀" + "b".repeat(5000)
                val eOut = ProotSession.truncateOutput(e)
                val splitNote = if (eOut.length > 3000 && Character.isHighSurrogate(eOut[2999])) "emoji di batas kepala TERBELAH (lone surrogate) — hanya laporan" else "emoji di batas tidak terbelah"
                val ok = a.length == 8000 && b.length == 8029 && b.contains("tengah dipotong, 1 char") && c.length == 8033 && c.contains("tengah dipotong, 12000 char") && d.length == 8000
                verdict("Cek 2 (potong proot)", ok, "8000->${a.length}, 8001->${b.length}, 20000->${c.length}, CRLF-end->${d.length}; surrogate: $splitNote")
            } catch (e: Exception) { verdict("Cek 2 (potong proot)", false, "exception: ${e.message}") }
            // ---------- Cek 3: result store instans uji ----------
            try {
                val prodIdxFile = java.io.File(this@MainActivity.filesDir, "result-store/index.json")
                val prodHashBefore = if (prodIdxFile.exists()) sha16(prodIdxFile.readText(Charsets.UTF_8)) else "ABSENT"
                val prodSeqBefore = getSharedPreferences("harness", MODE_PRIVATE).getInt("resultSeq", 0)
                val backend = ResultStore.testBackend(this@MainActivity, stamp)
                try {
                    val id1 = ResultStore.putIn(backend, "uji", "halo uji")
                    val g1 = ResultStore.getIn(backend, id1)
                    val big = "q".repeat(400001)
                    val idBig = ResultStore.putIn(backend, "uji", big)
                    val gBig = ResultStore.getIn(backend, idBig)
                    val idxFile = java.io.File(backend.dir, "index.json")
                    val idx = org.json.JSONObject(idxFile.readText(Charsets.UTF_8))
                    val o1 = idx.getJSONObject(id1)
                    o1.put("ts", System.currentTimeMillis() - 49L * 3600 * 1000)
                    idxFile.writeText(idx.toString(), Charsets.UTF_8)
                    val gExpired = ResultStore.getIn(backend, id1)
                    val filler = "f".repeat(400000)
                    var lastId = ""
                    for (i in 1..27) { lastId = ResultStore.putIn(backend, "uji", filler) }
                    val gLast = ResultStore.getIn(backend, lastId)
                    val gBigAfter = ResultStore.getIn(backend, idBig)
                    var totalBytes = 0L
                    backend.dir.listFiles()?.forEach { if (it.name.endsWith(".txt")) totalBytes += it.length() }
                    val prodHashAfter = if (prodIdxFile.exists()) sha16(prodIdxFile.readText(Charsets.UTF_8)) else "ABSENT"
                    val prodSeqAfter = getSharedPreferences("harness", MODE_PRIVATE).getInt("resultSeq", 0)
                    val prodGuard = prodHashAfter == prodHashBefore && prodSeqAfter == prodSeqBefore
                    val ok = id1.isNotBlank() && g1?.text == "halo uji" && g1.total == 8 && gBig?.truncated == true && gBig.text.length == 400000 && gBig.total == 400001 && gExpired == null && gLast != null && gBigAfter == null && totalBytes <= 10L * 1024 * 1024 && prodGuard
                    verdict("Cek 3 (result store uji)", ok, "id1=$id1 get='${g1?.text}' total=${g1?.total}; big truncated=${gBig?.truncated} stored=${gBig?.text?.length} total=${gBig?.total}; TTL expired->null=${gExpired == null}; LRU lastAda=${gLast != null} bigLamaHilang=${gBigAfter == null} totalByte=$totalBytes; produksi tak berubah=$prodGuard (hash index + resultSeq)")
                } finally {
                    ResultStore.wipeBackend(backend)
                }
            } catch (e: Exception) { verdict("Cek 3 (result store uji)", false, "exception: ${e.message}") }
            // ---------- Cek 4: redaksi ----------
            try {
                val res = RedactSecrets.selfTest()
                val ok = res.size == 33 && res.all { it.endsWith("PASS") }
                verdict("Cek 4 (redaksi)", ok, res.joinToString("; "))
            } catch (e: Exception) { verdict("Cek 4 (redaksi)", false, "exception: ${e.message}") }
            // ---------- Cek 5: digest ----------
            try {
                val items = (1..7).map { i -> WorkItem(tool = "tool$i", ms = 100L, ok = i % 2 == 0, summary = "ringkas$i", evidence = "bukti$i-" + "e".repeat(500), args = "{}", resultId = "R$i") }
                val dig = digestEvidence(items)
                val present = (1..7).filter { dig.contains("tool$it") }
                val orderOk = present == present.sorted() && present.size <= 5 && present.isNotEmpty()
                val line7 = dig.lines().find { it.contains("tool7") }
                val lineOk = line7 != null && line7.length <= 340
                val block = digestBlock(dig, System.currentTimeMillis())
                val blockOk = block.contains("BUKTI GILIRAN SEBELUMNYA") && block.contains("DATA TIDAK TEPERCAYA") && block.contains("baru saja") && block.contains(dig)
                val emptyEv = digestEvidence(listOf(WorkItem(tool = "t0", ms = 0L, ok = true, summary = "SUMMARY-JATUH", evidence = "", args = "", resultId = "")))
                val summaryOk = emptyEv.contains("SUMMARY-JATUH")
                val ok = orderOk && lineOk && dig.length <= 2000 && blockOk && summaryOk
                verdict("Cek 5 (digest)", ok, "kept=$present urut=$orderOk capBukti300=$lineOk len=${dig.length} block=$blockOk summaryFallback=$summaryOk (urutan KRONOLOGIS per kode; retensi newest)")
            } catch (e: Exception) { verdict("Cek 5 (digest)", false, "exception: ${e.message}") }
            // ---------- Cek 6: lapisan + titik-kirim ----------
            try {
                val sys = "SISTEM-".repeat(200)
                val persona = sys.substring(0, 500)
                val cat = "KATALOG-".repeat(50)
                val mem = "MEMORI-".repeat(50)
                val hist = "RIWAYAT-".repeat(50)
                val trace = "JEJAK-".repeat(50)
                val dig = "DIGEST-".repeat(20)
                val res = "HASIL-".repeat(50)
                val assembled = sys + cat + mem + hist + trace + dig + res
                val total = assembled.length
                val naive = total + persona.length
                val layerOk = persona.length <= sys.length && sys.contains(persona) && naive != total
                val snap = TurnMetrics.loadSnapshot(this@MainActivity)
                val buf = synchronized(sendPoints) { sendPoints.toList() }
                val sendNote: String
                val sendOk: Boolean?
                if (buf.isEmpty() || snap == null) {
                    sendOk = null
                    sendNote = if (buf.isEmpty()) "SKIP: tidak ada kirim API tercatat (buffer kosong — kirim satu perintah API dulu)" else "SKIP: tidak ada snapshot Monitor"
                } else {
                    val snapTotal = Regex("\"total_prompt_char\":(\\d+)").find(snap)?.groupValues?.get(1)?.toIntOrNull()
                    val last = buf.last()
                    sendNote = if (snapTotal == null) "snapshot tanpa total_prompt_char" else "buffer terakhir len=${last.len} sha=${last.sha16} vs snapshot total=$snapTotal delta=${last.len - snapTotal}"
                    sendOk = if (snapTotal == null) false else last.len >= snapTotal
                }
                val ok = layerOk && sendOk != false
                verdict("Cek 6 (lapisan + titik-kirim)", ok, "persona subset=${sys.contains(persona)} total=$total naive(sum+persona)=$naive != total (naive SALAH by design); titik-kirim: $sendNote (sama persis = lanjutan; lebih besar = gap awal terdokumentasi; lebih kecil = GAGAL, kemungkinan kirim senyap internal menyela)")
            } catch (e: Exception) { verdict("Cek 6 (lapisan + titik-kirim)", false, "exception: ${e.message}") }
            // ---------- Cek 7: failover nonaktif ----------
            try {
                val prefs = getSharedPreferences("harness", MODE_PRIVATE)
                val slotBefore = AccountPool.activeSlot(this@MainActivity)
                val keysBefore = prefs.all.keys.filter { it.startsWith("dsSrvSessId_") || it.startsWith("dsDead_") }.toSet()
                val filled = AccountPool.filledSlots(this@MainActivity)
                val ret = AccountPool.failover(this@MainActivity)
                val slotAfter = AccountPool.activeSlot(this@MainActivity)
                val keysAfter = prefs.all.keys.filter { it.startsWith("dsSrvSessId_") || it.startsWith("dsDead_") }.toSet()
                val ok = !AccountPool.FAILOVER_ENABLED && !ret && slotAfter == slotBefore && keysAfter == keysBefore
                val filledNote = if (filled.any { it != slotBefore }) "slot lain terisi: $filled" else "slot lain kosong di perangkat ini — gate tetap false sebelum membaca slot (AccountPool:81), hasil valid; kondisi slot-terisi tak dapat dipenuhi tanpa menulis token palsu (ditolak)"
                verdict("Cek 7 (failover nonaktif)", ok, "FAILOVER_ENABLED=false, failover()=$ret, slot $slotBefore->$slotAfter tak berubah, kunci tak bertambah; $filledNote; non-cakupan jujur: adopsi lintas-sidik tidak diuji runtime di sini (ditutup harness H1 + audit kode)")
            } catch (e: Exception) { verdict("Cek 7 (failover nonaktif)", false, "exception: ${e.message}") }
            // ---------- Cek 8 (vc263): StuckWatch + brief sesi + alokasi ID notif ----------
            try {
                val wVc263 = AgentPrompt.StuckWatch()
                val s1Vc263 = wVc263.observe("read_file", org.json.JSONObject().put("path", "/x/a.txt"), "isi sama")
                val s2Vc263 = wVc263.observe("read_file", org.json.JSONObject().put("path", "/x/a.txt"), "isi sama")
                val s3Vc263 = wVc263.observe("read_file", org.json.JSONObject().put("path", "/x/a.txt"), "isi sama")
                val s4Vc263 = wVc263.observe("read_file", org.json.JSONObject().put("path", "/x/a.txt"), "isi sama")
                val w2Vc263 = AgentPrompt.StuckWatch()
                val sDiffVc263 = w2Vc263.observe("read_file", org.json.JSONObject().put("path", "/x/lain.txt"), "isi beda")
                val briefVc263 = AgentPrompt.compressSessionBrief("Cari file A", "[HASIL TOOL] read_file: isi file A baris 1\n[HASIL TOOL] write_file: file B ditulis\nAsisten: selesai")
                val briefLongVc263 = AgentPrompt.compressSessionBrief("Tugas panjang", (1..30).joinToString("\n") { "[HASIL TOOL] tool$it: hasil nomor $it yang cukup panjang untuk mengisi brief" })
                val regVc263 = NotifIds.all().map { it.second }.toSet()
                val allocOkVc263 = NotifIds.bgResultId("jadwal") !in regVc263 && NotifIds.bgFailId("jadwal") !in regVc263 && NotifIds.bgSummaryId("jadwal") !in regVc263 && NotifIds.GROUP_DONE !in regVc263 && NotifIds.checkDuplicates().isEmpty()
                val okVc263 = s1Vc263.isBlank() && s2Vc263.isBlank() && s3Vc263.contains("⚠️") && s4Vc263.contains("🛑") && AgentPrompt.StuckWatch.isStop(s4Vc263) && sDiffVc263.isBlank() && briefVc263.contains("Cari file A") && briefVc263.length <= 2000 && briefLongVc263.length <= 2000 && briefLongVc263.contains("dipotong") && allocOkVc263
                verdict("Cek 8 (vc263 StuckWatch + brief + ID notif)", okVc263, "s1_kosong=${s1Vc263.isBlank()} s2_kosong=${s2Vc263.isBlank()} s3_warn=${s3Vc263.contains("⚠️")} s4_stop=${s4Vc263.contains("🛑")} beda_arg_kosong=${sDiffVc263.isBlank()} brief_len=${briefVc263.length} brief_panjang_len=${briefLongVc263.length} penanda_potong=${briefLongVc263.contains("dipotong")} alokasi_tanpa_tabrakan=$allocOkVc263")
            } catch (e: Exception) { verdict("Cek 8 (vc263 StuckWatch + brief + ID notif)", false, "exception: ${e.message}") }
            val logDir = java.io.File(this@MainActivity.filesDir, "logs").apply { mkdirs() }
            val logFile = java.io.File(logDir, "uji-mandiri-$stamp.txt")
            try { logFile.writeText(lines.joinToString("\n"), Charsets.UTF_8) } catch (e: Exception) {}
            val summary = "Uji Mandiri: $pass LOLOS, $fail GAGAL, $skip SKIP — log: ${logFile.absolutePath}"
            runOnUiThread { setupStatusTv.text = summary }
        }.start()
    }

    private fun buildMonitorTab(): View {
        val box = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setBackgroundColor(BG); setPadding(dp(10), dp(8), dp(10), dp(8)) }
        box.addView(TextView(this).apply { text = "Monitor aktivitas HP (lokal)"; textSize = 16f; setTextColor(TEXT) })
        val searchRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
        val searchInput = EditText(this).apply {
            hint = "Cari di memori & riwayat…"
            setTextColor(TEXT); setHintTextColor(DIM); textSize = 13f
            layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
        }
        monitorSearchInputRef = searchInput
        searchRow.addView(searchInput)
        val searchBtn = Button(this).apply {
            text = "Cari"
            setOnClickListener {
                val q = searchInput.text.toString().trim()
                if (q.isNotEmpty()) {
                    Thread {
                        val res = MemoryDb.get(this@MainActivity).searchMemory(q)
                        runOnUiThread { if (::monitorTv.isInitialized) monitorTv.text = "🔎 Hasil cari '$q':\n\n$res" }
                    }.start()
                }
            }
        }
        monitorSearchBtnRef = searchBtn
        searchRow.addView(searchBtn)
        box.addView(searchRow)
        val refreshBtn = Button(this).apply { text = "Segarkan"; setOnClickListener { refreshMonitor() } }
        monitorRefreshBtnRef = refreshBtn
        box.addView(refreshBtn)
        val sosBtn = Button(this).apply {
            text = "🆘 DARURAT — SMS lokasi ke kontak darurat"
            setOnClickListener {
                val num = getSharedPreferences("harness", MODE_PRIVATE).getString("emergencyNumber", "") ?: ""
                if (num.isBlank()) {
                    Toast.makeText(this@MainActivity, "Atur kontak darurat dulu di Setup tombol 22.", Toast.LENGTH_LONG).show()
                } else {
                    AlertDialog.Builder(this@MainActivity)
                        .setTitle("Kirim SMS darurat?")
                        .setMessage("Kirim SMS berisi lokasi terakhir ke $num sekarang?")
                        .setPositiveButton("Kirim") { _, _ ->
                            Thread {
                                val loc = Tools.lastLocation(this@MainActivity)
                                val locTxt = if (loc != null) "https://maps.google.com/?q=${loc.latitude},${loc.longitude}" else "(lokasi tidak tersedia)"
                                try {
                                    val ownerD2 = Flavor.ownerNameOr(this@MainActivity, "Pengguna")
                                    android.telephony.SmsManager.getDefault().sendTextMessage(num, null,
                                        "[DARURAT] $ownerD2 mengirim sinyal darurat dari ${Flavor.APP_LABEL}. Lokasi terakhir: $locTxt", null, null)
                                    runOnUiThread { Toast.makeText(this@MainActivity, "SMS darurat terkirim ke $num", Toast.LENGTH_LONG).show() }
                                } catch (e: Exception) {
                                    runOnUiThread { Toast.makeText(this@MainActivity, "Gagal kirim SMS: ${e.message} (izin SEND_SMS — Setup 18)", Toast.LENGTH_LONG).show() }
                                }
                            }.start()
                        }
                        .setNegativeButton("Batal", null)
                        .show()
                }
            }
        }
        monitorSosBtnRef = sosBtn
        box.addView(sosBtn)
        val scroll = ScrollView(this).apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f) }
        monitorTv = TextView(this).apply { textSize = 12f; setTextColor(TEXT) }
        scroll.addView(monitorTv)
        box.addView(scroll)
        box.addView(TextView(this).apply { text = "📊 METRIK GILIRAN TERAKHIR (v4.48.6)"; textSize = 13f; setTextColor(TEXT) })
        val metricsTv = TextView(this).apply { textSize = 12f; setTextColor(TEXT) }
        box.addView(metricsTv)
        box.addView(Button(this).apply {
            text = "Segarkan metrik"
            setOnClickListener { metricsTv.text = formatMetricsSnapshot() }
        })
        // vc263 (NT-M4): tombol hapus log lama — retensi 30 hari (tombol
        // + pemangkasan harian otomatis di tick service; dulu fungsi
        // pruneOlderThan30d ada tapi NOL pemanggil).
        box.addView(Button(this).apply {
            text = "🗑 Hapus log lama (>30 hari)"
            setOnClickListener {
                val n = try { EventDb.get(this@MainActivity).pruneOlderThan30d() } catch (e: Exception) { -1 }
                Toast.makeText(this@MainActivity, if (n >= 0) "Log lama dihapus: $n baris (>30 hari)." else "Gagal membersihkan log.", Toast.LENGTH_LONG).show()
                refreshMonitor()
            }
        })
        metricsTv.text = formatMetricsSnapshot()
        return box
    }

    private fun refreshMonitor() {
        if (!::monitorTv.isInitialized) return
        Thread {
            val db = EventDb.get(this)
            val rows = db.latest(60)
            val sb = StringBuilder()
            val mdb = MemoryDb.get(this)
            val facts = mdb.facts()
            sb.append("🧠 MEMORI PERSISTEN (${facts.size} fakta aktif — tarik lewat forget_fact, hapus permanen via Setup 17; riwayat fakta di Setup 65a):\n")
            if (facts.isEmpty()) sb.append("(kosong — asisten bisa menyimpan fakta lewat remember_fact)\n")
            else for ((k, v) in facts) sb.append("- $k: $v\n")
            val rems = mdb.upcoming()
            sb.append("\n⏰ PENGINGAT AKTIF (${rems.size}):\n")
            if (rems.isEmpty()) sb.append("(tidak ada)\n")
            else for (r in rems) sb.append("- #${r.id} [${MemoryDb.fmtTs(r.dueTs)}] ${r.text}\n")
            val goalsTxt = mdb.goalsText()
            sb.append("\n🎯 TUJUAN AKTIF:\n")
            if (goalsTxt.isBlank()) sb.append("(tidak ada)\n") else sb.append(goalsTxt).append("\n")
            val bp = getSharedPreferences("harness", MODE_PRIVATE)
            sb.append("\n🧠 OTAK LATAR: ")
            sb.append(if (bp.getBoolean("bgSessionDead", false)) "SESI MATI — login ulang di tab Web agar tugas latar jalan lagi" else "siap (tugas terjadwal/aturan/briefing dieksekusi langsung di latar)")
            val parkedVc242 = BgBrain.parkedList(this)
            if (parkedVc242.isNotEmpty()) {
                sb.append("\n⏳ Antrean persetujuan Otak Latar (${parkedVc242.size}):\n")
                for ((pid, ptool, _) in parkedVc242) sb.append("- $ptool (id: $pid)\n")
            }
            // vc246 GELOMBANG 5 (AG-M6): antrean tugas latar di Monitor.
            val bgQueueVc246 = BgBrain.queueSnapshot(this)
            sb.append("\n📥 ANTREAN TUGAS LATAR (${bgQueueVc246.size}):\n")
            if (bgQueueVc246.isEmpty()) sb.append("(kosong)\n") else for (q in bgQueueVc246) sb.append("- $q\n")
            // vc262: panel Attention Budget — seksi visibilitas di Monitor
            // (bukan gate; dialog interaktif: showAttentionPanelVc262).
            try { sb.append("\n").append(AttentionBudget.summaryText(this)).append("\n") } catch (e: Exception) {}
            sb.append("\n")
            sb.append("\n🤖 KOORDINATOR OPENCODE:\n")
            sb.append(OcCoord.statusText(this))
            // vc246 GELOMBANG 5 (AG-M4): hasil per lane tim di UI Monitor
            // (lipat/buka tidak didukung TextView — tampil ringkas 300
            // char per lane; detail penuh di hasil gabungan koordinator).
            val teamBoardVc246 = try { TeamRun.boardText(this) } catch (e: Exception) { "" }
            if (teamBoardVc246.isNotBlank()) { sb.append("\n👥 HASIL PER LANE TIM:\n"); sb.append(teamBoardVc246) }
            sb.append("\n")
            val notifRows = try { db.latest(300, "notif") } catch (e: Exception) { emptyList() }
            val last24 = notifRows.filter { System.currentTimeMillis() - it.ts < 24 * 3600_000 }
            if (last24.isNotEmpty()) {
                val topPkgs = last24.groupingBy { it.pkg }.eachCount().entries.sortedByDescending { it.value }.take(3)
                sb.append("\n📌 USULAN TINDAKAN (triase notifikasi 24 jam terakhir):\n")
                for ((pkg, n) in topPkgs) sb.append("- $pkg: $n notifikasi — bila mengganggu, minta asisten membuat aturan (add_rule_trigger) untuk merangkum/mengabaikannya.\n")
            }
            sb.append("\nTotal event tercatat: ${db.count()}\n")
            sb.append(Tools.execute(this, "get_current_app", JSONObject())).append("\n")
            sb.append(Tools.execute(this, "get_battery", JSONObject())).append("\n\n")
            for (r in rows) {
                val t = java.text.SimpleDateFormat("dd/MM HH:mm:ss", java.util.Locale.getDefault()).format(java.util.Date(r.ts))
                sb.append("[$t] (${r.type}) ${r.text}\n")
            }
            runOnUiThread { monitorTv.text = sb.toString() }
        }.start()
    }

