    // ---------------- Suara: input (STT) + output (TTS) + intent masuk ----------------

    private fun speak(text: String) {
        try {
            if (tts == null) {
                tts = TextToSpeech(this) { status ->
                    ttsReady = status == TextToSpeech.SUCCESS
                    if (ttsReady) {
                        try { tts?.language = java.util.Locale("id", "ID") } catch (e: Exception) {}
                        try {
                            tts?.setOnUtteranceProgressListener(object : android.speech.tts.UtteranceProgressListener() {
                                override fun onStart(id: String?) {}
                                override fun onError(id: String?) {}
                                override fun onDone(id: String?) {
                                    if (voiceLoopActive) runOnUiThread { startVoiceInput() }
                                }
                            })
                        } catch (e: Exception) {}
                        speak(text)
                    }
                }
                return
            }
            if (!ttsReady) return
            val clean = text.replace(Regex("[*#_`>\\[\\](){}]"), " ").take(700)
            if (clean.isNotBlank()) tts?.speak(clean, TextToSpeech.QUEUE_FLUSH, null, "harness-tts")
        } catch (e: Exception) {}
    }

    private fun startVoiceInput() {
        try {
            val i = Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).apply {
                putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL, RecognizerIntent.LANGUAGE_MODEL_FREE_FORM)
                putExtra(RecognizerIntent.EXTRA_LANGUAGE, "id-ID")
                putExtra(RecognizerIntent.EXTRA_PROMPT, "Ngomong aja…")
            }
            startActivityForResult(i, 77)
        } catch (e: Exception) {
            Toast.makeText(this, "Input suara tidak tersedia di HP ini.", Toast.LENGTH_SHORT).show()
        }
    }

    override fun onActivityResult(requestCode: Int, resultCode: Int, data: Intent?) {
        super.onActivityResult(requestCode, resultCode, data)
        // vc313: pemilih file tab agen (WebChromeClient.onShowFileChooser).
        if (requestCode == 4101) {
            val cb = browserFileChooserCallback
            browserFileChooserCallback = null
            if (cb != null) {
                try {
                    if (resultCode == RESULT_OK && data != null) {
                        val uris = ArrayList<android.net.Uri>()
                        val clip = data.clipData
                        if (clip != null) { for (i in 0 until clip.itemCount) { clip.getItemAt(i).uri?.let { uris.add(it) } } }
                        else if (data.data != null) uris.add(data.data!!)
                        cb.onReceiveValue(if (uris.isEmpty()) null else uris.toTypedArray())
                    } else cb.onReceiveValue(null)
                } catch (e: Exception) {
                    try { cb.onReceiveValue(null) } catch (e2: Exception) {}
                }
            }
            return
        }
        if (requestCode == 77 && resultCode == RESULT_OK && data != null) {
            val results = data.getStringArrayListExtra(RecognizerIntent.EXTRA_RESULTS)
            val text = results?.firstOrNull()?.trim().orEmpty()
            if (text.isNotEmpty()) {
                val lower = text.lowercase()
                if (lower in listOf("cukup", "stop", "berhenti", "sudah", "matikan suara")) {
                    voiceLoopActive = false
                    Toast.makeText(this, "Mode ngobrol berhenti.", Toast.LENGTH_SHORT).show()
                } else {
                    voiceLoopActive = ::voiceCheck.isInitialized && voiceCheck.isChecked
                    showTab("Chat")
                    onUserMessage(text)
                }
            }
            return
        }
        if (requestCode == 77) { voiceLoopActive = false; return }
        if (requestCode == 44) {
            if (resultCode == RESULT_OK && data != null) {
                val uris = ArrayList<android.net.Uri>()
                val clip = data.clipData
                if (clip != null) { for (i in 0 until clip.itemCount) { clip.getItemAt(i).uri?.let { uris.add(it) } } }
                else if (data.data != null) uris.add(data.data!!)
                if (uris.isNotEmpty()) {
                    var added = 0
                    for (u in uris) {
                        if (pendingAttachesVc212.size >= 5) break
                        var nm = "lampiran"
                        var mm = ""
                        try {
                            mm = contentResolver.getType(u) ?: ""
                            contentResolver.query(u, arrayOf(android.provider.OpenableColumns.DISPLAY_NAME), null, null, null)?.use { c -> if (c.moveToFirst()) nm = c.getString(0) ?: nm }
                        } catch (e: Exception) {}
                        try { contentResolver.takePersistableUriPermission(u, Intent.FLAG_GRANT_READ_URI_PERMISSION) } catch (e: Exception) {}
                        pendingAttachesVc212.add(PendingAttachVc212(u, nm, mm))
                        added++
                    }
                    refreshAttachStripVc212()
                    refreshSendVisibilityVc212()
                    showTab("Chat")
                    if (added < uris.size) Toast.makeText(this, "Maks 5 lampiran per kirim — hanya 5 pertama yang ditahan. Tulis konteks, lalu tap ➤.", Toast.LENGTH_LONG).show()
                    else Toast.makeText(this, "Lampiran ditahan (" + added + " file) — tulis konteks, lalu tap ➤ untuk mengirim.", Toast.LENGTH_SHORT).show()
                }
            }
            return
        }
        handleFilePickerResult(requestCode, resultCode, data)
    }

    override fun onRequestPermissionsResult(requestCode: Int, permissions: Array<out String>, grantResults: IntArray) {
        super.onRequestPermissionsResult(requestCode, permissions, grantResults)
        if (requestCode == 9101) {
            val granted = grantResults.isNotEmpty() && grantResults[0] == PackageManager.PERMISSION_GRANTED
            if (granted) {
                showCameraDialog(camPendingAutoLive)
            } else {
                addBubble("⚠️ Izin kamera ditolak — kamera tidak bisa dibuka. Bila kamu menekan 'jangan tanya lagi', aktifkan manual di Info Aplikasi > Izin > Kamera.", false)
            }
        }
    }

    override fun onNewIntent(intent: Intent) {
        super.onNewIntent(intent)
        handleIncomingIntent(intent)
    }

    override fun onResume() {
        super.onResume()
        activityResumed = true
        // vc309 Worker A — terapkan ulang bar di onResume: mode "sistem"
        // (night mode OS berubah saat app di latar) + kembali dari activity
        // lain (SlotBrowser). Listener inset tidak dipasang ulang (tetap
        // hidup dari onCreate).
        try { SystemBarsVc309.applySystemBars(window, isDarkTheme()) } catch (e: Exception) {}
        try { showBgSecondConfirmVc229() } catch (e: Exception) {}
        try { serveF3Tick() } catch (e: Exception) {}
        if (!ckptChecked) { ckptChecked = true; try { maybeResumeTurn() } catch (e: Exception) {} }
        try {
            val drained = MemoryDb.drainPrompts(this)
            for (p in drained) if (autoQueue.size < 5) autoQueue.addLast(p)
            if (autoQueue.isNotEmpty() && agent?.busy != true && !internalTurn) consumeAutoQueue()
        } catch (e: Exception) {}
        // vc308 Worker C (BUG 4): ganti tema yang sempat ditunda — terapkan
        // bila giliran sudah selesai (pengaman bila endUserTurn terlewat
        // karena app sempat ke latar).
        maybeApplyPendingThemeVc308()
    }

    override fun onPause() {
        activityResumed = false
        try { stopCameraVisionSilent() } catch (e: Exception) {}
        // vc313 §3.5: flush cookie + simpan metadata tab saat app ke latar.
        try { CookieManager.getInstance().flush() } catch (e: Exception) {}
        try { saveBrowserTabsVc313() } catch (e: Exception) {}
        super.onPause()
    }

    override fun onStop() {
        // vc313 §3.5: flush cookie saat app berhenti (jangan duplikasi
        // flush setupWebView login DeepSeek — ini flush tambahan browser).
        try { CookieManager.getInstance().flush() } catch (e: Exception) {}
        super.onStop()
    }

    /** F3 (v4.37.0): cek + bangkit serve saat app kembali ke depan.
     *  Dijalankan di thread (ProotSession.exec memblokir). Throttle 5 menit,
     *  kecuali versi app berubah (= pasca-update: serve PASTI mati karena
     *  update membunuh sesi proot, jadi wajib cek). */
    private fun serveF3Tick() {
        val prefs = getSharedPreferences("harness", MODE_PRIVATE)
        val ver = try { packageManager.getPackageInfo(packageName, 0).versionName ?: "" } catch (e: Exception) { "" }
        val lastVer = prefs.getString("serveSeenVersion", "") ?: ""
        val lastTs = prefs.getLong("serveF3TickTs", 0)
        val now = System.currentTimeMillis()
        val versionChanged = ver.isNotBlank() && ver != lastVer
        if (!versionChanged && now - lastTs < 300_000) return
        prefs.edit().putLong("serveF3TickTs", now).putString("serveSeenVersion", ver).apply()
        Thread {
            try {
                val st = ServeHealth.ensureAlive(this)
                runOnUiThread { serveStatusTv?.text = "Serve :4199 — " + if (st.alive) "hidup • PID ${st.pid}" else "tidur"; tsStatusTv?.text = "Tailscale — " + TailscaleHealth.lastStatus(this) + " (" + TailscaleHealth.lastCheckText(this) + ")" }
                // vc246 GELOMBANG 5 (NT-M5): status serve yang butuh
                // tindakan kini juga menjadi notifikasi Android (dulu
                // hanya teks UI) — throttle 1 jam agar tidak spam.
                if (!st.alive) {
                    try {
                        val lastN = prefs.getLong("serveDownNotifTs", 0)
                        if (System.currentTimeMillis() - lastN > 3600_000) {
                            prefs.edit().putLong("serveDownNotifTs", System.currentTimeMillis()).apply()
                            val nm = getSystemService(NOTIFICATION_SERVICE) as android.app.NotificationManager
                            if (android.os.Build.VERSION.SDK_INT >= 26 && nm.getNotificationChannel("harness_auto_heal") == null) nm.createNotificationChannel(android.app.NotificationChannel("harness_auto_heal", "Automation Perlu Perhatian", android.app.NotificationManager.IMPORTANCE_DEFAULT))
                            val pi = android.app.PendingIntent.getActivity(this, 73, Intent(this, MainActivity::class.java), android.app.PendingIntent.FLAG_UPDATE_CURRENT or android.app.PendingIntent.FLAG_IMMUTABLE)
                            val nb = if (android.os.Build.VERSION.SDK_INT >= 26) android.app.Notification.Builder(this, "harness_auto_heal") else android.app.Notification.Builder(this)
                            nm.notify(7103, nb.setSmallIcon(android.R.drawable.ic_dialog_alert).setContentTitle("Serve :4199 tidur — perlu tindakan").setContentText("Buka app > Setup serve untuk menyalakan ulang serve.").setContentIntent(pi).setAutoCancel(true).build())
                        }
                    } catch (e: Exception) {}
                }
            } catch (e: Exception) {}
        }.start()
    }

    /** F1.0 (v4.41.0): dialog Kill Switch F1 — menghentikan job yang
     *  sedang jalan dalam 1 langkah berikutnya (depan + latar). Cakupan
     *  JUJUR: semua eksekusi tool agen dihentikan sampai diaktifkan lagi;
     *  balasan teks biasa tanpa tool tetap jalan. Reversibel. */
    internal fun f1Dialog() {
        val th = currentTheme()
        val prefs = getSharedPreferences("harness", MODE_PRIVATE)
        val box = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        fun refresh() {
            box.removeAllViews()
            val off = prefs.getBoolean("f1Off", false)
            box.addView(tv(if (off) "Status: F1 DIMATIKAN — semua eksekusi tool agen dihentikan di langkah berikutnya. Balasan teks biasa tetap jalan." else "Status: F1 AKTIF — agen boleh mengeksekusi perintah lintas aplikasi.", 13f, if (off) th.errText else th.text))
            box.addView(Button(this).apply {
                text = if (off) "▶ Aktifkan Lagi F1" else "⏸ Matikan F1 Sekarang (Kill Switch)"
                background = rounded(if (off) th.tileBg else th.errBg, 12)
                setTextColor(if (off) th.text else th.errText)
                setPadding(dp(12), dp(10), dp(12), dp(10))
                minWidth = 0; minHeight = 0
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
                setOnClickListener { prefs.edit().putBoolean("f1Off", !off).apply(); refresh() }
            })
            box.addView(tv("Kill switch ini menghentikan job depan dan job latar (BgBrain) dalam 1 langkah berikutnya. Saklar ini berbeda dari saklar darurat Job Latar (yang menghentikan pengajuan job terjadwal baru).", 12.5f, th.dim).apply { setPadding(0, dp(8), 0, 0) })
        }
        refresh()
        thDialog("⛔ Kill Switch F1", box, listOf(Triple("Tutup", false) { d: android.app.AlertDialog -> d.dismiss() }))
    }

    // vc226 Panel Approval "Butuh Manusia" (BRIEF-PANEL-APPROVAL, disetujui
    // user 2026-11-01). Satu inbox approval pending lintas room/sesi +
    // daftar Mandat aktif. Lokasi: kartu Beranda + pintu dari tiap room
    // (tanpa Command Center, sesuai keputusan §7). Badge Laporan vc191
    // tetap terpisah — tidak digabung ke panel ini.
    private fun showApprovalPanel(roomFilter: String?) {
        val th = currentTheme()
        val box = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        var dlg: android.app.AlertDialog? = null
        fun decide(it: ApprovalItem, approved: Boolean, always: Boolean) {
            // Pertahanan lapis kedua: kill switch mematikan tombol setujui.
            if (approved && ApprovalPanelStore.isKilled(this)) return
            if (always) ApprovalPanelStore.createMandate(this, it.roomId, it.sessionId, it.kelasAksi, "tool=" + it.tool)
            ApprovalPanelStore.resolve(this, it.id, approved, "panel")
            if (it.roomId.isNotBlank()) {
                try { Automation.logAction(this, it.roomId, it.agent, "panel approval",
                    (if (approved) "disetujui" else "ditolak") + (if (always) " + mandat 7 hari" else "") + ": ${it.tool}",
                    it.sessionId.toString()) } catch (e: Exception) {}
            }
        }
        fun refresh() {
            box.removeAllViews()
            val killed = try { ApprovalPanelStore.isKilled(this) } catch (e: Exception) { false }
            if (killed) box.addView(tv("⛔ KILL SWITCH AKTIF — panel dibekukan. Tombol setujui tidak bisa dipakai sampai kill switch dinonaktifkan (Profil > Kill Switch F1).", 13f, th.errText, true).apply { setPadding(0, 0, 0, dp(10)) })
            if (roomFilter != null) {
                box.addView(tv("Filter: room $roomFilter", 12.5f, th.dim, true))
                box.addView(thBtn("Tampilkan semua approval") { dlg?.dismiss(); showApprovalPanel(null) }.apply { setPadding(dp(12), dp(8), dp(12), dp(8)) })
            }
            val items = try { ApprovalPanelStore.pending(this, roomFilter) } catch (e: Exception) { emptyList() }
            // vc246 GELOMBANG 5 (GR-M6, pilihan pernyataan eksplisit):
            // panel ini HANYA untuk room + chat 1-1; approval grup TIDAK
            // pernah didaftarkan ke panel (grup memakai dialog listener
            // langsung) — dinyatakan di UI, bukan dibiarkan ambigu.
            box.addView(tv("Panel ini hanya untuk approval room + chat 1-1. Approval grup tidak masuk panel — diputuskan lewat dialog grup langsung.", 12f, th.dim).apply { setPadding(0, 0, 0, dp(6)) })
            box.addView(tv("Menunggu keputusan (${items.size})", 14f, th.text, true).apply { setPadding(0, dp(10), 0, dp(6)) })
            if (items.isEmpty()) {
                box.addView(tv(if (roomFilter != null) "Tidak ada approval pending untuk room ini." else "Tidak ada approval pending.", 12.5f, th.dim))
            }
            for (it in items) {
                val card = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; background = rounded(th.tileBg, 12); setPadding(dp(12), dp(10), dp(12), dp(10)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { setMargins(0, 0, 0, dp(8)) } }
                card.addView(tv(ApprovalPanelStore.riskLabel(it.risiko) + " • " + it.tool, 13f, th.text, true))
                card.addView(tv(it.ringkasan, 13f, th.text))
                if (it.alasan.isNotBlank()) card.addView(tv("Kenapa: " + it.alasan, 12f, th.dim))
                // vc229 R-04(h): argumen lengkap di kartu panel (dialog panel
                // sudah ScrollView); bila >8000 char, tombol setujui panel
                // dinonaktifkan — persetujuan wajib dari dialog dalam-app.
                if (it.argsFull.isNotBlank()) {
                    if (it.argsFull.length > 8000) card.addView(tv("⚠️ Argumen >8000 char — persetujuan dari panel ditolak; pakai dialog dalam-app saat tool diminta.", 12f, th.errText, true))
                    else card.addView(tv("Argumen lengkap: " + it.argsFull, 12f, th.text))
                }
                val scope = if (it.roomId.isNotBlank()) "Room ${it.roomId}" else "Chat • sesi ${it.sessionId}"
                card.addView(tv("$scope • ${it.agent} • ${ApprovalPanelStore.timeStr(it.dimintaPada)}", 11.5f, th.dim))
                // vc246 GELOMBANG 5 (XL-Panel): item yang callback-nya
                // hilang (app sempat restart) TIDAK mendapat tombol Setujui
                // — dulu ketukan itu menandai "disetujui" tanpa eksekusi.
                // Hanya tombol hapus dari panel + perintah picu ulang.
                val expiredVc246 = !ApprovalPanelStore.hasCallback(it.id)
                if (expiredVc246) {
                    card.addView(tv("⏳ KEDALUWARSA — picu ulang tugasnya. Persetujuan ini tidak bisa dieksekusi karena app sempat restart setelah item dibuat; giliran agen yang menunggu sudah tidak ada.", 12f, th.errText, true))
                }
                val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(8), 0, 0) }
                if (expiredVc246) {
                    val bDrop = thBtn("Hapus dari panel") { ApprovalPanelStore.withdraw(this, it.id, "kedaluwarsa vc246 — callback hilang"); refresh() }
                    bDrop.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
                    row.addView(bDrop)
                } else {
                    val bOk = thBtn("Setujui", true) { decide(it, true, false); refresh() }
                    bOk.isEnabled = !killed && it.argsFull.length <= 8000
                    bOk.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
                    row.addView(bOk)
                }
                val bNo = thBtn("Tolak") { decide(it, false, false); refresh() }
                bNo.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
                row.addView(bNo)
                // Kelas risiko tinggi + konfirmasi_manual tidak bisa dimandatkan:
                // tombol "setujui selalu" tidak tampil untuk kelas itu.
                if (ApprovalPanelStore.canMandate(it.kelasAksi)) {
                    val bAlways = thBtn("Setujui selalu") { decide(it, true, true); refresh() }
                    bAlways.isEnabled = !killed && it.argsFull.length <= 8000
                    bAlways.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
                    row.addView(bAlways)
                }
                card.addView(row)
                box.addView(card)
            }
            val mands = try { ApprovalPanelStore.activeMandates(this, roomFilter) } catch (e: Exception) { emptyList() }
            box.addView(tv("Mandat aktif (${mands.size}) — berlaku 7 hari, bisa dicabut kapan saja", 14f, th.text, true).apply { setPadding(0, dp(10), 0, dp(6)) })
            if (mands.isEmpty()) {
                box.addView(tv("Belum ada mandat.", 12.5f, th.dim))
            }
            for (m in mands) {
                val mRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL; background = rounded(th.tileBg, 12); setPadding(dp(12), dp(8), dp(12), dp(8)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { setMargins(0, 0, 0, dp(6)) } }
                val scope = if (m.roomId.isNotBlank()) "Room ${m.roomId}" else "Chat • sesi ${m.sessionId}"
                val mTv = tv("• ${m.kelasAksi}" + (if (m.syarat.isNotBlank()) " [${m.syarat}]" else " [tanpa ikatan argumen — kirim_luar tidak berlaku]") + " — $scope • sampai ${ApprovalPanelStore.timeStr(m.berlakuSampai)}", 12.5f, th.text)
                mTv.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                mRow.addView(mTv)
                mRow.addView(thBtn("Cabut") {
                    ApprovalPanelStore.revokeMandate(this, m.id)
                    if (m.roomId.isNotBlank()) {
                        try { Automation.logAction(this, m.roomId, "user", "panel approval", "mandat dicabut: ${m.kelasAksi}", m.sessionId.toString()) } catch (e: Exception) {}
                    }
                    refresh()
                })
                box.addView(mRow)
            }
            // vc229 R-04(c): daftar autoAllow aktif + tombol cabut per tool.
            val autosVc229 = try { ApprovalPanelStore.activeAutoAllow(this) } catch (e: Exception) { emptyList() }
            box.addView(tv("AutoAllow aktif (${autosVc229.size}) — berlaku 24 jam, terikat sesi, bisa dicabut per tool", 14f, th.text, true).apply { setPadding(0, dp(10), 0, dp(6)) })
            if (autosVc229.isEmpty()) {
                box.addView(tv("Belum ada autoAllow aktif.", 12.5f, th.dim))
            }
            for ((toolA, tsA, sessA) in autosVc229) {
                val aRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = Gravity.CENTER_VERTICAL; background = rounded(th.tileBg, 12); setPadding(dp(12), dp(8), dp(12), dp(8)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { setMargins(0, 0, 0, dp(6)) } }
                val aTv = tv("• $toolA — sesi $sessA • sampai ${ApprovalPanelStore.timeStr(tsA + ApprovalPanelStore.AUTALLOW_TTL_MS)}", 12.5f, th.text)
                aTv.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f)
                aRow.addView(aTv)
                aRow.addView(thBtn("Cabut") { ApprovalPanelStore.revokeAutoAllow(this, toolA); refresh() })
                box.addView(aRow)
            }
        }
        refresh()
        dlg = thDialog(if (roomFilter != null) "⏳ Butuh Manusia (room)" else "⏳ Butuh Manusia", box, listOf(Triple("Tutup", false) { d: android.app.AlertDialog -> d.dismiss() }))
    }

    /** F2 (v4.39.0): dialog kelola Job Latar — daftar rutinitas (toggle/hapus),
     *  tambah job harian/interval, 2 job contoh, saklar darurat, dan log. */
    // v4.48.9.21 (vc187): kartu Automation di Beranda. Muncul hanya bila ada
    // room aktif (pola kartu Progres Kerja). Ketuk = masuk room, sub-room
    // terakhir aktif.
    // v4.48.9.22 (vc188): seksi Automation di Beranda SELALU tampil (bug
    // 2026-10-27 13:39: tanpa room, Beranda tidak menampilkan apa pun
    // tentang automation). Tanpa room aktif = tombol Buat + Template.
    // Dengan room aktif = kartu lama + tombol Hentikan + Simpan Template.
    private fun addAutomationCard(box: LinearLayout) {
        val th = currentTheme()
        box.addView(tv("Automation", 15f, th.text, true).apply { setPadding(0, dp(12), 0, dp(6)) })
        val room = try { Automation.activeRoom(this) } catch (e: Exception) { null }
        if (room == null) {
            val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            val bCreate = thBtn("＋ Buat Automation") { showAutomationCreateDialog("") }
            bCreate.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
            row.addView(bCreate)
            val bTpl = thBtn("📋 Template") { showAutomationTemplatesDialog() }
            bTpl.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
            row.addView(bTpl)
            box.addView(row)
            return
        }
        val tasks = Automation.allSessionTasks(room)
        var doing = 0; var done = 0
        for (i in 0 until tasks.length()) {
            val s = tasks.optJSONObject(i)?.optString("status")
            if (s == "doing") doing++
            if (s == "done") done++
        }
        val msgs = try { Automation.loadMessages(this, room.optString("id")) } catch (e: Exception) { org.json.JSONArray() }
        var last = ""
        for (i in msgs.length() - 1 downTo 0) {
            val m = msgs.optJSONObject(i) ?: continue
            if (m.optString("sender") == "laporan") { last = m.optString("text").take(90); break }
        }
        val card = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; background = rounded(th.card, 18); setPadding(dp(14), dp(12), dp(14), dp(12)) }
        card.addView(tv("🤖 " + room.optString("title"), 14f, th.text, true))
        var liveSess = 0
        val sessArr = Automation.sessions(room)
        for (si in 0 until sessArr.length()) { val s = sessArr.optJSONObject(si) ?: continue; try { Automation.refreshSessionArchive(this, room, s) } catch (e: Exception) {}; if (!s.optBoolean("archived", false)) liveSess++ }
        card.addView(tv("Wadah • " + sessArr.length() + " sesi (" + liveSess + " aktif)" + (if (room.optBoolean("archived", false)) " • ROOM ARSIP" else "") + " • tugas: $doing berjalan, $done selesai", 12f, th.dim))
        if (last.isNotBlank()) card.addView(tv(last, 12f, th.dim))
        val actRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(8), 0, 0) }
        val bStop = thBtn("⏹ Hentikan") { stopAutomationFromCard(room) }
        bStop.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
        actRow.addView(bStop)
        val bSaveTpl = thBtn("💾 Simpan Template") { saveAutomationTemplate(room) }
        bSaveTpl.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
        actRow.addView(bSaveTpl)
        card.addView(actRow)
        card.setOnClickListener { showAutomationRoom(room.optString("id"), room.optString("lastSub", "solo"), room.optString("lastSessionId").takeIf { it.isNotBlank() }) }
        box.addView(card)
    }

    // v4.48.9.24 (vc190): tawaran otomatis jadikan room setelah schedule_task
    // sukses dari chat 1-1. Satu kali per id schedule (prefs roomOffered_<id>).
    // pendingRoomOfferScheduleId = id schedule yang tawaran room-nya dijawab Ya
    // dan menunggu room terbentuk; dipakai finishCreateAutomation untuk
    // menampilkan tawaran lanjutan batalkan jadwal chat.
    private var pendingRoomOfferScheduleId: Long? = null
    private var pendingRoomOfferHour: Int = -1
    private var pendingRoomOfferMinute: Int = -1

    private fun showRoomOfferDialog(sid: Long, hour: Int, minute: Int, prompt: String) {
        val pf = getSharedPreferences("harness", MODE_PRIVATE)
        pf.edit().putBoolean("roomOffered_$sid", true).apply()
        pendingRoomOfferHour = hour
        pendingRoomOfferMinute = minute
        val th = currentTheme()
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        col.addView(tv("Jadwal #$sid — tiap hari %02d:%02d".format(hour, minute), 14f, th.text, true))
        col.addView(tv("'$prompt'", 13f, th.dim))
        col.addView(tv("Jadwal chat ini tetap aktif kecuali dibatalkan — room baru tidak menggantikannya otomatis.", 12f, th.dim).apply { setPadding(0, dp(8), 0, 0) })
        thDialog("Jadikan Automation Room?", col, listOf(
            Triple("Ya, buat room", true) { d: android.app.AlertDialog ->
                pendingRoomOfferScheduleId = sid
                d.dismiss()
                showAutomationCreateDialog(prompt, null, "routine")
            },
            Triple("Tidak", false) { d: android.app.AlertDialog -> d.dismiss() }
        ))
    }

    private fun showCancelScheduleOffer(sid: Long, carriedTime: String = "") {
        val th = currentTheme()
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        col.addView(tv("Room sudah dibuat. Jadwal chat #$sid masih aktif — bila tidak dibatalkan, tugas akan berjalan 2x (dari jadwal chat dan dari routine room).", 13f, th.dim))
        if (carriedTime.isNotBlank()) col.addView(tv("Room baru sudah membawa jam jadwal ini ($carriedTime) lewat routine sesinya — membatalkan jadwal chat TIDAK menghentikan routine room.", 12f, th.dim).apply { setPadding(0, dp(8), 0, 0) })
        thDialog("Batalkan jadwal chat #$sid?", col, listOf(
            Triple("Ya, batalkan", true) { d: android.app.AlertDialog ->
                // vc237 M9: pembatalan jadwal dari UI ini dulu menghapus tanpa
                // arsip (berbeda dengan tool cancel_schedule yang mengarsip).
                // Kini mengarsip dulu dengan payload yang sama seperti tool.
                try {
                    val db = MemoryDb.get(this)
                    val oldS = db.schedules().firstOrNull { it.id == sid }
                    if (oldS != null) db.archiveDelete("schedule", "#$sid", org.json.JSONObject().put("hour", oldS.hour).put("minute", oldS.minute).put("prompt", oldS.prompt).toString())
                    db.deleteSchedule(sid)
                } catch (e: Exception) {}
                d.dismiss()
                Toast.makeText(this, "Jadwal chat #$sid dibatalkan.", Toast.LENGTH_LONG).show()
            },
            Triple("Tidak", false) { d: android.app.AlertDialog -> d.dismiss() }
        ))
    }

    // v4.48.9.22 (vc188): dialog pembuatan automation + kriteria eksplisit
    // (opsional) + prefill dari template. Agent bertanya solo vs multi —
    // jawaban dicatat di room (job interval/harian tidak ditanya ulang).
    private fun showAutomationCreateDialog(presetTask: String = "", template: org.json.JSONObject? = null, presetDurKind: String? = null) {
        val th = currentTheme()
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        col.addView(tv("TUGAS AUTOMATION", 12f, th.dim, true))
        val tplTask = template?.optString("task", "") ?: ""
        val initTask = if (tplTask.isNotBlank()) tplTask else presetTask
        val eTask = EditText(this).apply {
            setText(initTask); setTextColor(th.text); setHintTextColor(th.dim)
            hint = "Pekerjaan yang mau diotomasi…"
            background = roundedS(th.bg, 12, th.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); minLines = 2
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        col.addView(eTask)
        col.addView(tv("KRITERIA SELESAI (opsional — bila kosong, diturunkan dari tugas)", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, 0) })
        val tplCrit = template?.optString("criteria", "") ?: ""
        val eCrit = EditText(this).apply {
            setText(tplCrit); setTextColor(th.text); setHintTextColor(th.dim)
            hint = "mis. Laporan harian terkirim + ringkasan tampil di room"
            background = roundedS(th.bg, 12, th.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); minLines = 2
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        col.addView(eCrit)
        col.addView(tv("DURASI SESI AWAL (berlaku untuk sesi pertama; tiap sesi bisa diubah lewat ✎ Sesi)", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, 0) })
        var durKind = presetDurKind?.takeIf { it == "days" || it == "routine" || it == "full24" } ?: template?.optString("durKind", "days") ?: "days"
        if (durKind != "days" && durKind != "routine" && durKind != "full24") durKind = "days"
        val durNote = tv(when (durKind) {
            "routine" -> "Dipilih: Rutinitas (sesi awal terbuka; laporan job F2 mengalir sesuai mode tiap job)."
            "full24" -> "Dipilih: Fullwork 24 jam (sesi awal aktif 24 jam, lalu jadi arsip)."
            else -> "Dipilih: N hari (sesi awal aktif N hari ke depan, lalu jadi arsip)."
        }, 12f, th.dim)
        val durRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
        durRow.addView(thBtn("N hari") { durKind = "days"; durNote.text = "Dipilih: N hari (sesi awal aktif N hari ke depan, lalu jadi arsip)." })
        durRow.addView(thBtn("Rutin") { durKind = "routine"; durNote.text = "Dipilih: Rutinitas (sesi awal terbuka; laporan job F2 mengalir sesuai mode tiap job)." })
        durRow.addView(thBtn("24 jam") { durKind = "full24"; durNote.text = "Dipilih: Fullwork 24 jam (sesi awal aktif 24 jam, lalu jadi arsip)." })
        col.addView(durRow)
        col.addView(durNote)
        col.addView(tv("JUMLAH HARI (bila N hari)", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, 0) })
        val initDays = template?.optInt("nDays", 3) ?: 3
        val eDays = EditText(this).apply {
            setText((if (initDays > 0) initDays else 3).toString()); setTextColor(th.text); setHintTextColor(th.dim)
            inputType = android.text.InputType.TYPE_CLASS_NUMBER
            background = roundedS(th.bg, 12, th.stroke); setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        col.addView(eDays)
        col.addView(tv("BATASAN (opsional — nama tool yang dilarang, pisah koma)", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, 0) })
        val tplBlock = StringBuilder()
        val tbl = template?.optJSONArray("blocklist")
        if (tbl != null) {
            for (i in 0 until tbl.length()) {
                if (tplBlock.isNotEmpty()) tplBlock.append(", ")
                tplBlock.append(tbl.optString(i))
            }
        }
        val eBlock = EditText(this).apply {
            setText(tplBlock.toString()); setTextColor(th.text); setHintTextColor(th.dim); hint = "mis. send_sms, run_terminal"
            background = roundedS(th.bg, 12, th.stroke); setPadding(dp(12), dp(10), dp(12), dp(10))
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        col.addView(eBlock)
        col.addView(tv("Agent bertanya: pekerjaan ini dikerjakan SOLO atau diskusi MULTI-AGEN?", 12f, th.dim).apply { setPadding(0, dp(10), 0, 0) })
        val createDlg = thDialog("🤖 Buat Automation", col, listOf(
            Triple("Solo", true) { d: android.app.AlertDialog -> finishCreateAutomation(eTask.text.toString().trim(), durKind, eDays.text.toString().trim().toIntOrNull() ?: 3, eBlock.text.toString(), eCrit.text.toString().trim(), "solo", template); d.dismiss() },
            Triple("Multi-Agen", true) { d: android.app.AlertDialog -> finishCreateAutomation(eTask.text.toString().trim(), durKind, eDays.text.toString().trim().toIntOrNull() ?: 3, eBlock.text.toString(), eCrit.text.toString().trim(), "multi", template); d.dismiss() },
            Triple("Batal", false) { d: android.app.AlertDialog -> pendingRoomOfferScheduleId = null; pendingRoomOfferHour = -1; pendingRoomOfferMinute = -1; d.dismiss() }
        ))
        // vc190: bila dialog ditutup tanpa membuat room (tombol kembali /
        // sentuh luar), tawaran batalkan jadwal tidak boleh muncul belakangan.
        // finishCreateAutomation sudah mengosongkan pending bila room terbentuk,
        // sehingga listener ini hanya membersihkan sisa tawaran yang batal.
        createDlg.setOnDismissListener { if (pendingRoomOfferScheduleId != null) { pendingRoomOfferScheduleId = null; pendingRoomOfferHour = -1; pendingRoomOfferMinute = -1 } }
    }

    private fun finishCreateAutomation(task: String, durKind: String, nDays: Int, blockText: String, criteria: String, firstMode: String, template: org.json.JSONObject? = null) {
        if (task.isBlank()) { Toast.makeText(this, "Tugas kosong — dibatalkan.", Toast.LENGTH_LONG).show(); return }
        val blocklist = blockText.split(",").map { it.trim() }.filter { it.isNotBlank() }
        val room = Automation.createRoom(this, task.take(60), task, durKind, nDays, blocklist, criteria)
        room.put("lastSub", firstMode); Automation.updateRoom(this, room)
        val soloAgent = Agents.active(this).id
        Automation.ensureSessions(this, room)
        val divDef = getSharedPreferences("harness", Context.MODE_PRIVATE).getString("sessDefDivMode", "bebas") ?: "bebas"
        val sess = Automation.createSession(this, room, firstMode, task.take(60), if (firstMode == "multi") "" else soloAgent, if (firstMode == "multi") listOf("asisten", "mandor", "mentor", "agen4") else emptyList(), if (firstMode == "multi") divDef else "bebas", if (firstMode == "multi") "mandor" else soloAgent, emptyList(), durKind, nDays, "", 0)
        Automation.addSessionTask(this, room, sess, task, if (firstMode == "multi") "mandor" else soloAgent, criteria)
        // vc263 (FT-M7): pulihkan isi template ke room/sesi baru — jadwal
        // (via syncSessionSchedule), rerank, digest 07:00, member + divMode
        // multi. Room lama tanpa field ini mendapat nilai default yang jujur
        // (jadwal kosong, rerank mati, digest mati, member default).
        if (template != null) {
            try {
                if (template.optBoolean("rerank", false)) { room.put("rerank", true); Automation.updateRoom(this, room) }
                val tplMembersVc263 = template.optJSONArray("members")
                if (firstMode == "multi" && tplMembersVc263 != null && tplMembersVc263.length() > 0) {
                    sess.put("members", tplMembersVc263)
                    val tplDivVc263 = template.optString("divMode", "")
                    if (tplDivVc263.isNotBlank()) sess.put("divMode", tplDivVc263)
                    Automation.updateSession(this, room, sess)
                }
                val tplSchedVc263 = template.optString("schedTime", "")
                val tplIntVc263 = template.optInt("schedIntervalMin", 0)
                if (tplSchedVc263.isNotBlank() || tplIntVc263 > 0) {
                    sess.put("schedTime", tplSchedVc263)
                    sess.put("schedIntervalMin", tplIntVc263)
                    Automation.syncSessionSchedule(this, room, sess)
                }
                if (template.optBoolean("digest", false)) {
                    val spVc263 = getSharedPreferences("harness", Context.MODE_PRIVATE)
                    val arrVc263 = org.json.JSONArray(spVc263.getString("routines", "[]") ?: "[]")
                    var hasDigestVc263 = false
                    for (i in 0 until arrVc263.length()) { val r = arrVc263.optJSONObject(i) ?: continue; if (r.optString("kind") == "digest" && r.optString("digestRoomId") == room.optString("id")) hasDigestVc263 = true }
                    if (!hasDigestVc263) {
                        val oVc263 = org.json.JSONObject()
                        oVc263.put("id", "digest_" + room.optString("id"))
                        oVc263.put("kind", "digest")
                        oVc263.put("digestRoomId", room.optString("id"))
                        oVc263.put("sessionId", sess.optString("id"))
                        oVc263.put("time", template.optString("digestTime", "07:00"))
                        oVc263.put("prompt", "Digest harian room " + room.optString("title"))
                        oVc263.put("enabled", true)
                        oVc263.put("mode", sess.optString("mode"))
                        arrVc263.put(oVc263)
                        spVc263.edit().putString("routines", arrVc263.toString()).apply()
                    }
                }
            } catch (e: Exception) { }
        }
        // vc245 GELOMBANG 4 (XL-JadwalRoom, pilihan teruskan jam): room
        // dari tawaran jadwal membawa jam/menit jadwal asal ke schedTime
        // sesi baru lewat syncSessionSchedule — sebelum ini schedTime=""
        // dan sync tidak pernah dipanggil, sehingga pembatalan jadwal chat
        // menghilangkan penjadwalan tugas itu total.
        var carriedTimeVc245 = ""
        if (pendingRoomOfferScheduleId != null && pendingRoomOfferHour in 0..23 && pendingRoomOfferMinute in 0..59) {
            carriedTimeVc245 = "%02d:%02d".format(pendingRoomOfferHour, pendingRoomOfferMinute)
            sess.put("schedTime", carriedTimeVc245)
            Automation.syncSessionSchedule(this, room, sess)
        }
        room.put("lastSessionId", sess.optString("id"))
        Automation.updateRoom(this, room)
        Automation.appendMessage(this, room.optString("id"), firstMode, "sistem", "Room automation dibuat. Sesi awal: " + sess.optString("title") + " (durasi sesi: $durKind, mode: $firstMode).", sess.optString("id"))
        Automation.logAction(this, room.optString("id"), "sistem", "buat room", "mode: $firstMode, durasi sesi: $durKind", sess.optString("id"))
        refreshBeranda()
        showAutomationRoom(room.optString("id"), firstMode, sess.optString("id"))
        // vc190: room terbentuk dari tawaran jadwal chat — tampilkan tawaran
        // lanjutan batalkan jadwal (satu ketuk, tanpa pembatalan diam-diam).
        pendingRoomOfferScheduleId?.let { sid ->
            pendingRoomOfferScheduleId = null
            pendingRoomOfferHour = -1
            pendingRoomOfferMinute = -1
            showCancelScheduleOffer(sid, carriedTimeVc245)
        }
    }

    // v4.48.9.22 (vc188): daftar template — satu ketuk membuat room baru
    // dari template (dialog pembuatan terisi dari template).
    private fun showAutomationTemplatesDialog() {
        val th = currentTheme()
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        col.addView(tv("TEMPLATE AUTOMATION", 12f, th.dim, true))
        val templates = try { Automation.loadTemplates(this) } catch (e: Exception) { org.json.JSONArray() }
        // vc263 (FT-M7): template KINI menyimpan jadwal sesi, rerank,
        // digest, dan daftar member multi — semuanya dipulihkan saat room
        // dibuat dari template (lihat finishCreateAutomation).
        col.addView(tv("Template menyimpan: jadwal sesi, rerank, digest, daftar member multi. Semuanya dipulihkan saat room dibuat dari template.", 12f, th.dim).apply { setPadding(0, 0, 0, dp(8)) })
        val buttons = ArrayList<Triple<String, Boolean, (android.app.AlertDialog) -> Unit>>()
        if (templates.length() == 0) {
            col.addView(tv("Belum ada template. Simpan dari room (💾 Template) atau dari kartu Beranda.", 13f, th.dim))
        }
        for (i in 0 until templates.length()) {
            val t = templates.optJSONObject(i) ?: continue
            val label = "📋 " + t.optString("name") + " • " + (if (t.optString("mode") == "multi") "Multi" else "Solo") + " • " + Automation.durationText(t)
            buttons.add(Triple(label, false) { d: android.app.AlertDialog -> d.dismiss(); showAutomationCreateDialog("", t) })
        }
        // vc246 GELOMBANG 5 (FT-m14): hapus template (dulu saveTemplate ada,
        // deleteTemplate tidak ada di UI sama sekali).
        if (templates.length() > 0) {
            buttons.add(Triple("🗑 Hapus template…", false) { d: android.app.AlertDialog ->
                d.dismiss()
                val colDel = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
                val delBtns = ArrayList<Triple<String, Boolean, (android.app.AlertDialog) -> Unit>>()
                for (i in 0 until templates.length()) {
                    val t = templates.optJSONObject(i) ?: continue
                    val nm = t.optString("name")
                    delBtns.add(Triple("Hapus: $nm", false) { dd: android.app.AlertDialog -> Automation.deleteTemplate(this, nm); dd.dismiss(); Toast.makeText(this, "Template dihapus: $nm", Toast.LENGTH_SHORT).show() })
                }
                delBtns.add(Triple("Batal", false) { dd: android.app.AlertDialog -> dd.dismiss() })
                thDialog("🗑 Hapus Template", colDel, delBtns)
            })
        }
        buttons.add(Triple("Tutup", false) { d: android.app.AlertDialog -> d.dismiss() })
        thDialog("📋 Template Automation", col, buttons)
    }

    private fun saveAutomationTemplate(room: org.json.JSONObject) {
        inputDialog("Nama template", "mis. Briefing pagi", room.optString("title")) { name ->
            val nm = name.trim()
            if (nm.isBlank()) {
                Toast.makeText(this, "Nama kosong — dibatalkan.", Toast.LENGTH_LONG).show()
            } else if (Automation.saveTemplate(this, nm, room)) {
                Toast.makeText(this, "Template tersimpan: $nm", Toast.LENGTH_LONG).show()
            } else {
                Toast.makeText(this, "Gagal menyimpan template.", Toast.LENGTH_LONG).show()
            }
        }
    }

    private fun stopAutomationFromCard(room: org.json.JSONObject) {
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        col.addView(tv("Room \"" + room.optString("title") + "\" akan diarsipkan (read-only). Tidak ada lagi job/balasan baru. Peluncuran ulang lewat template.", 13f, currentTheme().text))
        thDialog("⏹ Hentikan Automation", col, listOf(
            Triple("⏹ Hentikan", true) { d: android.app.AlertDialog -> Automation.stopRoom(this, room); d.dismiss(); refreshBeranda(); Toast.makeText(this, "Automation dihentikan dan diarsipkan.", Toast.LENGTH_LONG).show() },
            Triple("Batal", false) { d: android.app.AlertDialog -> d.dismiss() }
        ), danger = setOf("⏹ Hentikan"))
    }

    private fun showAutomationLogDialog(roomId: String, sessId: String = "") {
        val th = currentTheme()
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        col.addView(tv("LOG AKSI ROOM", 12f, th.dim, true))
        // vc243 GELOMBANG 2 (GR-M5): daftar laporan gagal-route — satu tempat
        // yang bisa ditemukan, bukan hanya notifikasi yang hilang.
        try {
            val und = Automation.undeliveredReports(this)
            if (und.length() > 0) {
                col.addView(tv("⚠️ LAPORAN GAGAL ROUTE (" + und.length() + ")", 12f, th.dim, true))
                val fmtU = java.text.SimpleDateFormat("dd/MM HH:mm", java.util.Locale("id", "ID"))
                for (i in 0 until und.length()) {
                    val u = und.optJSONObject(i) ?: continue
                    val tsU = try { fmtU.format(java.util.Date(u.optLong("ts", 0))) } catch (ex: Exception) { "" }
                    col.addView(tv("[" + tsU + "] " + u.optString("origin") + " (" + u.optString("job") + "): " + u.optString("reason") + " — " + u.optString("answer").take(120), 12f, th.text).apply { setPadding(0, 0, 0, dp(4)) })
                }
            }
        } catch (e: Exception) {}
        val logRaw = try { Automation.loadLog(this, roomId) } catch (e: Exception) { org.json.JSONArray() }
        val log = org.json.JSONArray()
        for (li in 0 until logRaw.length()) {
            val le = logRaw.optJSONObject(li) ?: continue
            val ls = le.optString("sess", "")
            if (sessId.isNotBlank() && ls.isNotBlank() && ls != sessId) continue
            log.put(le)
        }
        if (log.length() == 0) {
            col.addView(tv("Belum ada aksi tercatat.", 13f, th.dim))
        } else {
            val fmt = java.text.SimpleDateFormat("HH:mm", java.util.Locale("id", "ID"))
            val start = if (log.length() > 50) log.length() - 50 else 0
            for (i in log.length() - 1 downTo start) {
                val e = log.optJSONObject(i) ?: continue
                val ts = try { fmt.format(java.util.Date(e.optLong("ts", 0))) } catch (ex: Exception) { "" }
                // vc246 GELOMBANG 5 (RM-m1): entri lama tanpa sess
                // dilabeli "sebelum sesi" — dulu ikut tampil di semua sesi
                // tanpa penanda sehingga tampak seperti aksi sesi itu.
                col.addView(tv("[" + ts + "] " + (if (e.optString("sess", "").isBlank()) "[sebelum sesi] " else "") + e.optString("agent") + " • " + e.optString("action") + " → " + e.optString("result"), 12f, th.text).apply { setPadding(0, 0, 0, dp(4)) })
            }
        }
        thDialog("📋 Log Room", col, listOf(
            Triple("Tutup", false) { d: android.app.AlertDialog -> d.dismiss() }
        ))
    }

    internal fun showGroupSessionsPanel() {
        val th = currentTheme()
        var dlgHolder: android.app.AlertDialog? = null
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        col.addView(tv("SESI", 12f, th.dim, true))
        val rooms = Automation.loadRooms(this)
        // vc211: kumpulkan baris per seksi dulu, urutan asli dipertahankan.
        val activeRows = ArrayList<LinearLayout>()
        val archivedRows = ArrayList<LinearLayout>()
        var any = false
        for (i in 0 until rooms.length()) {
            val r = rooms.optJSONObject(i) ?: continue
            var liveSess = 0
            val sessArr = Automation.sessions(r)
            for (si in 0 until sessArr.length()) { val s = sessArr.optJSONObject(si) ?: continue; try { Automation.refreshSessionArchive(this, r, s) } catch (e: Exception) {}; if (!s.optBoolean("archived", false)) liveSess++ }
            val info = sessArr.length().toString() + " sesi • " + liveSess + " aktif" + (if (r.optBoolean("archived", false)) " • ARSIP" else "")
            val rid = r.optString("id")
            val roomTitle = r.optString("title")
            val lastSub = r.optString("lastSub", "solo")
            val lastSid = r.optString("lastSessionId").takeIf { it.isNotBlank() }
            val row = LinearLayout(this).apply {
                orientation = LinearLayout.HORIZONTAL
                gravity = Gravity.CENTER_VERTICAL
                background = rounded(th.tileBg, 14)
                setPadding(dp(12), dp(12), dp(12), dp(12))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { setMargins(0, 0, 0, dp(8)) }
            }
            row.addView(TextView(this).apply { text = "🤖"; textSize = 19f; gravity = Gravity.CENTER; layoutParams = LinearLayout.LayoutParams(dp(38), dp(38)) })
            val txtCol = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(12), 0, 0, 0); layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f) }
            txtCol.addView(tv(roomTitle, 14f, th.text, true).apply { maxLines = 2; ellipsize = android.text.TextUtils.TruncateAt.END })
            txtCol.addView(tv(info, 12f, th.dim).apply { maxLines = 1; ellipsize = android.text.TextUtils.TruncateAt.END })
            row.addView(txtCol)
            // vc211: tombol hapus grup. Button menelan sentuhannya sendiri
            // sehingga klik baris (buka room) tidak ikut terpicu.
            val delBtn = thSmallBtn("🗑") {
                // vc245 GELOMBANG 4 (GR-M1): konfirmasi menyebut jumlah anak
                // yang ikut terhapus (rekursif, sama seperti deleteRoom).
                val kidsVc245 = try { Automation.descendantRooms(this, rid) } catch (e: Exception) { emptyList() }
                val kidTxtVc245 = if (kidsVc245.isEmpty()) "" else " Termasuk " + kidsVc245.size + " sub-room anak yang ikut terhapus" + (if (kidsVc245.size <= 5) " (" + kidsVc245.joinToString(", ") { it.optString("title") } + ")" else "") + "."
                val msg = TextView(this).apply { text = "\"" + roomTitle + "\" beserta seluruh sesi, tugas, laporan, dan jadwal routine di dalamnya akan dihapus permanen dan tidak bisa dibatalkan." + kidTxtVc245; textSize = 14f; setTextColor(th.text) }
                thDialog("Hapus grup ini?", msg, listOf(
                    Triple("Hapus", false) { d: android.app.AlertDialog ->
                        d.dismiss()
                        dlgHolder?.dismiss()
                        Automation.deleteRoom(this, rid)
                        Toast.makeText(this, "Grup " + roomTitle + " beserta semua sesinya sudah dihapus.", Toast.LENGTH_SHORT).show()
                        showGroupSessionsPanel()
                    },
                    Triple("Batal", false) { d: android.app.AlertDialog -> d.dismiss() }
                ), danger = setOf("Hapus"))
            }
            row.addView(delBtn)
            row.addView(tv("›", 16f, th.dim, true).apply { setPadding(dp(8), 0, 0, 0) })
            row.setOnClickListener { dlgHolder?.dismiss(); showAutomationRoom(rid, lastSub, lastSid) }
            if (r.optBoolean("archived", false) || liveSess == 0) archivedRows.add(row) else activeRows.add(row)
            any = true
        }
        if (!any) {
            col.addView(tv("Belum ada room automation. Buat dari tombol 🤖 di chat 1-1.", 13f, th.dim))
        } else {
            if (activeRows.isNotEmpty()) {
                col.addView(tv("AKTIF", 12f, th.dim, true).apply { setPadding(0, dp(4), 0, dp(6)) })
                for (rw in activeRows) col.addView(rw)
            }
            if (archivedRows.isNotEmpty()) {
                col.addView(tv("ARSIP", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, dp(6)) })
                for (rw in archivedRows) col.addView(rw)
            }
        }
        val closeBtn = thBtn("Tutup") { dlgHolder?.dismiss() }
        closeBtn.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { setMargins(0, dp(12), 0, 0) }
        col.addView(closeBtn)
        val dialogCol = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(14), dp(16), dp(10)); background = rounded(th.card, 18) }
        dialogCol.addView(tv("☰ Sesi Grup", 16f, th.text, true).apply { setPadding(0, 0, 0, dp(10)) })
        dialogCol.addView(col)
        val scroll = ScrollView(this).apply { addView(dialogCol) }
        val dlg = android.app.AlertDialog.Builder(this).setView(scroll).create()
        dlgHolder = dlg
        dlg.show()
        try { dlg.window?.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(Color.TRANSPARENT)) } catch (e: Exception) {}
    }

    // v4.48.9.21 (vc187): room automation (Solo / Multi). Paralel TANPA
    // running guard: pesan user langsung masuk, tidak pernah ditahan.
    // Multi: tiap agen jalan independen lewat SlotClient sendiri (pola lane
    // TeamRun, tanpa kunci round); typing per-agen; round cap 1 balasan
    // per agen per pemicu; Mandor koordinator bagi tugas + papan tugas.
    private fun showAutomationRoom(roomId: String, initialSub: String, initialSessionId: String? = null) {
        val th = currentTheme()
        val room = Automation.refreshArchive(this, Automation.roomById(this, roomId) ?: return)
        var sub = if (initialSub == "multi") "multi" else "solo"
        Automation.ensureSessions(this, room)
        var curSess: org.json.JSONObject = initialSessionId?.let { Automation.sessionById(room, it) } ?: Automation.sessionById(room, room.optString("lastSessionId")) ?: Automation.sessionsOfMode(room, sub).firstOrNull() ?: Automation.sessions(room).optJSONObject(0) ?: org.json.JSONObject()
        sub = curSess.optString("mode", sub)
        val archived = room.optBoolean("archived", false)
        val blocklist = ArrayList<String>()
        val bl = room.optJSONArray("blocklist") ?: org.json.JSONArray()
        for (i in 0 until bl.length()) blocklist.add(bl.optString(i))

        // vc292: `col` kini wadah HEADER (pinned, tidak ikut scroll).
        // Background kartu pindah ke rootColVc292 (lihat ujung fungsi).
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(14), dp(16), dp(4)) }
        val roomTitleTv = tv("🤖 Automation: " + room.optString("title"), 16f, th.text, true)
        col.addView(roomTitleTv)
        col.addView(tv("Wadah • " + Automation.sessions(room).length() + " sesi" + (if (archived) " • ROOM ARSIP" else "") + " • Batasan: " + (if (blocklist.isEmpty()) "tidak ada" else blocklist.joinToString(", ")), 12f, th.dim))

        val toggleRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(8), 0, dp(4)) }
        val bSolo = thBtn("Solo", sub == "solo") {}
        val bMulti = thBtn("Multi-Agen", sub == "multi") {}
        toggleRow.addView(bSolo)
        toggleRow.addView(bMulti)
        col.addView(toggleRow)
        val sessScroll = HorizontalScrollView(this).apply {
            layoutParams = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT)
            isHorizontalScrollBarEnabled = false
        }
        val sessRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
        sessScroll.addView(sessRow)
        col.addView(sessScroll)
        val sessActRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT)
        }
        val sessAddBtn = thBtn("＋ Sesi") {}
        val sessEditBtn = thBtn("✎ Sesi") {}
        val sessStopBtn = thBtn("⏹ Sesi") {}
        sessActRow.addView(sessAddBtn, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
        sessActRow.addView(sessEditBtn, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
        sessActRow.addView(sessStopBtn, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
        col.addView(sessActRow)
        val sessSetRow = LinearLayout(this).apply {
            orientation = LinearLayout.HORIZONTAL
            layoutParams = LinearLayout.LayoutParams(LinearLayout.LayoutParams.MATCH_PARENT, LinearLayout.LayoutParams.WRAP_CONTENT)
        }
        val sessSettingBtn = thBtn("⚙ Setting") {}
        val sessDigestBtn = thBtn("📰 Digest") {}
        sessSetRow.addView(sessSettingBtn, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
        sessSetRow.addView(sessDigestBtn, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
        col.addView(sessSetRow)
        val sessInfoLine = tv("", 11.5f, th.dim)
        col.addView(sessInfoLine)
        val divBoardBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; visibility = View.GONE }
        col.addView(divBoardBox)

        var roomSection = "diskusi"
        var chipDiskusi: Button? = null
        var chipTugas: Button? = null
        var chipLaporan: Button? = null
        var chipPanel: Button? = null
        val sectionRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(8), 0, dp(4)) }
        col.addView(sectionRow)

        // vc292: wadah konten (satu-satunya area scroll) + wadah composer
        // (pinned bawah). State grup laporan hidup selama dialog terbuka.
        val midColVc292 = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(4), dp(16), dp(8)) }
        val footColVc292 = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL; setPadding(dp(16), dp(8), dp(16), dp(12)) }
        var laporanTailVc292 = 60
        val expandedDaysVc292 = HashSet<String>()
        val papanHeader = tv("PAPAN TUGAS (todo → doing → done)", 12f, th.dim, true).apply { setPadding(0, dp(8), 0, 0) }
        midColVc292.addView(papanHeader)
        val boardBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        midColVc292.addView(boardBox)

        val diskusiHeader = tv("DISKUSI", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, 0) }
        midColVc292.addView(diskusiHeader)
        val msgBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        midColVc292.addView(msgBox)
        val typingBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        midColVc292.addView(typingBox)

        val eMsg = EditText(this).apply {
            setTextColor(th.text); setHintTextColor(th.dim); hint = "Tulis pesan / arah untuk agen…"
            background = roundedS(th.bg, 12, th.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); minLines = 2
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
        }
        val kirimBtn = thBtn("Kirim") {}
        val addTaskBtn = thBtn("＋ Tugas") {}
        val konsolBtn = thBtn("🧠 Konsolidasi") {}
        val petaBtn = thBtn("🗺️ PETA") {}
        val tutupBtn = thBtn("Tutup") {}
        val archiveNote = tv("Sesi arsip — pesan dan tugas tidak bisa ditambah.", 12f, th.dim).apply { setPadding(0, dp(8), 0, 0); visibility = View.GONE }
        footColVc292.addView(archiveNote)
        footColVc292.addView(eMsg)
        val inputRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(6), 0, 0) }
        inputRow.addView(kirimBtn)
        inputRow.addView(addTaskBtn)
        inputRow.addView(konsolBtn)
        inputRow.addView(petaBtn)
        footColVc292.addView(inputRow)
        fun sessArchivedNow(): Boolean {
            return try { Automation.refreshSessionArchive(this, room, curSess).optBoolean("archived", false) } catch (e: Exception) { curSess.optBoolean("archived", false) }
        }
        fun refreshArchivedViews() {
            val a = sessArchivedNow()
            eMsg.visibility = if (a) View.GONE else View.VISIBLE
            inputRow.visibility = if (a) View.GONE else View.VISIBLE
            archiveNote.visibility = if (a) View.VISIBLE else View.GONE
        }
        val actionRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(8), 0, 0) }
        val logBtn = thBtn("📋 Log") {}
        logBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
        actionRow.addView(logBtn)
        val tplBtn = thBtn("💾 Template") {}
        tplBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
        actionRow.addView(tplBtn)
        val stopBtn = thBtn("⏹ Hentikan") {}
        if (!archived) {
            stopBtn.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }
            actionRow.addView(stopBtn)
        }
        footColVc292.addView(actionRow)
        val closeRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(8), 0, 0) }
        closeRow.addView(tutupBtn)
        footColVc292.addView(closeRow)

        var scrollHolder: ScrollView? = null
        val typingViews = HashMap<String, TextView>()

        fun scrollBottom() { scrollHolder?.post { scrollHolder?.fullScroll(View.FOCUS_DOWN) } }

        fun refreshSectionChips() {
            val unread = Automation.reportUnreadFor(this, room.optString("id"), curSess.optString("id"))
            chipDiskusi?.let { it.text = "💬 Diskusi"; it.background = rounded(if (roomSection == "diskusi") ACCENT else th.tileBg, 12); it.setTextColor(if (roomSection == "diskusi") android.graphics.Color.WHITE else th.text) }
            chipTugas?.let { it.text = "☑ Tugas"; it.background = rounded(if (roomSection == "tugas") ACCENT else th.tileBg, 12); it.setTextColor(if (roomSection == "tugas") android.graphics.Color.WHITE else th.text) }
            chipLaporan?.let { it.text = if (unread > 0) "📋 Laporan ($unread)" else "📋 Laporan"; it.background = rounded(if (roomSection == "laporan") ACCENT else th.tileBg, 12); it.setTextColor(if (roomSection == "laporan") android.graphics.Color.WHITE else th.text) }
            // vc226: pintu Panel Approval dari dalam room (filter room ini).
            // Badge Laporan vc191 tetap terpisah — tidak digabung ke sini.
            // vc246 GELOMBANG 5 (UI-m3): badge dipisah room vs 1-1 —
            // dulu item 1-1 (roomId="") tidak terhitung di badge room mana
            // pun sehingga menggantung tanpa terlihat dari room.
            chipPanel?.let { val n = try { ApprovalPanelStore.pendingCount(this, room.optString("id")) } catch (e: Exception) { 0 }; val n11 = try { ApprovalPanelStore.pending(this, "").size } catch (e: Exception) { 0 }; it.text = if (n > 0 || n11 > 0) "⏳ Butuh Manusia (room $n · 1-1 $n11)" else "⏳ Butuh Manusia"; it.background = rounded(th.tileBg, 12); it.setTextColor(th.text) }
        }

        // vc246 perbaikan pasca-patch: fungsi lokal Kotlin tidak bisa
        // forward-reference — renderMessages (di atas) tidak bisa memanggil
        // sendRoomMessage (di bawah). Jalur dikirim lewat holder ini yang
        // diisi tepat setelah definisi sendRoomMessage, sebelum interaksi
        // user apa pun (semua pemanggilan renderMessages sebelumnya ada di
        // dalam callback, bukan eksekusi setup).
        var sendRoomFnVc246: ((String) -> Unit)? = null
        fun renderMessages() {
            msgBox.removeAllViews()
            if (roomSection == "laporan") Automation.clearReportUnreadFor(this, room.optString("id"), curSess.optString("id"))
            val msgs = Automation.loadMessages(this, room.optString("id"))
            val show = ArrayList<org.json.JSONObject>()
            for (i in 0 until msgs.length()) {
                val m = msgs.optJSONObject(i) ?: continue
                if (m.optString("sub") != sub) continue
                val mSess = m.optString("sess", "")
                val curId = curSess.optString("id")
                if (mSess.isNotBlank() && mSess != curId) continue
                if (mSess.isBlank() && !Automation.isFirstSession(room, curSess)) continue
                val mSender = m.optString("sender")
                val mText = m.optString("text")
                if (roomSection == "laporan") {
                    if (mSender != "laporan") continue
                } else {
                    if (mSender == "laporan") continue
                    if (mSender == "sistem" && (mText.startsWith("Verifikasi GAGAL") || mText.startsWith("Tugas selesai") || mText.startsWith("Memverifikasi tugas"))) continue
                }
                show.add(m)
            }
            val tail = if (show.size > laporanTailVc292) show.subList(show.size - laporanTailVc292, show.size) else show
            // vc292: tab LAPORAN dikelompokkan per hari (dari ts) — collapsed
            // default kecuali hari terbaru. Di luar laporan, render lama.
            if (roomSection == "laporan") {
                val fmtDayVc292 = java.text.SimpleDateFormat("d MMM yyyy", java.util.Locale("id", "ID"))
                val fmtTimeVc292 = java.text.SimpleDateFormat("HH:mm", java.util.Locale("id", "ID"))
                val groupsVc292 = LinkedHashMap<String, ArrayList<org.json.JSONObject>>()
                for (m in tail) {
                    val tsVc292 = m.optLong("ts", 0)
                    val dayVc292 = if (tsVc292 > 0) fmtDayVc292.format(java.util.Date(tsVc292)) else "Tanpa tanggal"
                    groupsVc292.getOrPut(dayVc292) { ArrayList() }.add(m)
                }
                val daysVc292 = groupsVc292.keys.toList()
                if (daysVc292.isNotEmpty() && expandedDaysVc292.isEmpty()) expandedDaysVc292.add(daysVc292.last())
                for (dayVc292 in daysVc292) {
                    val listVc292 = groupsVc292[dayVc292] ?: continue
                    val openVc292 = expandedDaysVc292.contains(dayVc292)
                    val headVc292 = thBtn("📋 " + dayVc292 + " — " + listVc292.size + " laporan  " + (if (openVc292) "▾" else "▸"), openVc292) {
                        if (expandedDaysVc292.contains(dayVc292)) expandedDaysVc292.remove(dayVc292) else expandedDaysVc292.add(dayVc292)
                        renderMessages()
                    }
                    headVc292.layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT).apply { setMargins(0, 0, 0, dp(6)) }
                    msgBox.addView(headVc292)
                    if (openVc292) {
                        for (m in listVc292) {
                            val tsVc292 = m.optLong("ts", 0)
                            if (tsVc292 > 0) msgBox.addView(tv(fmtTimeVc292.format(java.util.Date(tsVc292)), 11.5f, th.dim, true))
                            msgBox.addView(tv(m.optString("text"), 13f, th.text).apply { setPadding(0, 0, 0, dp(8)) })
                        }
                    }
                }
                if (show.size > laporanTailVc292) {
                    val moreVc292 = thSmallBtn("Muat laporan lebih lama (" + (show.size - laporanTailVc292) + " laporan lebih lama)") { laporanTailVc292 += 60; renderMessages() }
                    msgBox.addView(moreVc292)
                }
            } else for (m in tail) {
                val sender = m.optString("sender")
                // vc246 GELOMBANG 5 (K-06 + UI-M1 + AG-M7): kartu opsi ask
                // dirender di sini (pesan sender="ask" dari handleRoomReply);
                // label pill kini memakai background rounded + padding pada
                // TextView-nya sendiri (dulu hanya setPadding, tampak kotak);
                // pesan sistem dirender miring agar beda dari pesan agen.
                if (sender == "ask") {
                    try {
                        val aj = org.json.JSONObject(m.optString("text"))
                        val aq = aj.optString("question")
                        val aarr = aj.optJSONArray("options")
                        msgBox.addView(tv("❓ " + aq, 13f, th.tileTint, true).apply { setPadding(0, dp(4), 0, dp(4)) })
                        if (aarr != null) for (k in 0 until aarr.length()) {
                            val opt = aarr.optString(k)
                            if (opt.isBlank()) continue
                            msgBox.addView(thSmallBtn("▸ " + opt) { val fn = sendRoomFnVc246; if (fn != null) fn(opt) else android.widget.Toast.makeText(this, "Kartu belum siap — kirim ulang lewat kolom chat.", android.widget.Toast.LENGTH_SHORT).show() })
                        }
                        msgBox.addView(tv("Ketuk salah satu opsi di atas — jawabanmu dikirim sebagai pesan ke agen sesi ini.", 11f, th.dim).apply { setPadding(0, 0, 0, dp(8)) })
                    } catch (e: Exception) {
                        msgBox.addView(tv("❓ Pertanyaan agen (gagal render kartu): " + m.optString("text"), 13f, th.text))
                    }
                    continue
                }
                // vc254: pesan sistem berformat aktivitas dirender
                // sebagai baris lipat (bukan teks sistem miring biasa).
                // Pesan lama / bukan aktivitas jatuh ke render biasa.
                if (sender == "sistem") {
                    val actVc254 = ActivityTitle.parseText(m.optString("text"))
                    if (actVc254 != null) {
                        val rowVc254 = buildActivityRow(actVc254.title, ActivityTitle.statusText(actVc254.ms, actVc254.ok), (if (actVc254.args.isNotBlank()) "Argumen: " + actVc254.args + "\n" else "") + "Hasil: " + actVc254.result, actVc254.tool)
                        msgBox.addView(rowVc254.root)
                        continue
                    }
                }
                val label = when (sender) { "user" -> "Anda"; "sistem" -> "Sistem"; "laporan" -> "📋 Laporan"; else -> sender }
                msgBox.addView(tv(label, 12f, if (sender == "user") Color.WHITE else th.dim, true).apply { background = rounded(if (sender == "user") ACCENT else th.tileBg, 12); setPadding(dp(8), dp(2), dp(8), dp(2)) })
                msgBox.addView(tv(m.optString("text"), 13f, th.text).apply { setPadding(0, 0, 0, dp(8)); if (sender == "sistem") typeface = android.graphics.Typeface.create(android.graphics.Typeface.DEFAULT, android.graphics.Typeface.ITALIC) })
            }
            // vc243 GELOMBANG 2 (GR-M3, sumber terpisah): hasil koordinator
            // tampil di tab Laporan dengan label jelas BUKAN laporan room
            // ini — sumbernya daftar coordReports, bukan pesan room.
            if (roomSection == "laporan") {
                try {
                    val coord = Automation.coordReports(this)
                    if (coord.length() > 0) {
                        msgBox.addView(tv("🤖 Laporan Koordinator — sumber terpisah (bukan laporan room ini)", 12f, th.dim, true))
                        val from = if (coord.length() > 5) coord.length() - 5 else 0
                        for (i in coord.length() - 1 downTo from) {
                            val c = coord.optJSONObject(i) ?: continue
                            val ot = c.optString("originTitle").ifBlank { "sesi #" + c.optLong("originSession") }
                            msgBox.addView(tv("Koordinator #" + c.optLong("taskId") + " (sesi asal: " + ot + ")", 12f, th.tileTint, true))
                            msgBox.addView(tv(c.optString("result").take(600), 13f, th.text).apply { setPadding(0, 0, 0, dp(8)) })
                        }
                    }
                } catch (e: Exception) {}
            }
            if (roomSection == "laporan") Automation.clearReportUnreadFor(this, room.optString("id"), curSess.optString("id"))
            refreshSectionChips()
        }

