        }

        val verifying = HashSet<Int>()

        fun renderBoard() {
            boardBox.removeAllViews()
            val tasks = Automation.sessionTasks(curSess)
            if (tasks.length() == 0) boardBox.addView(tv("Belum ada tugas — tambah lewat tombol ＋ Tugas.", 12f, th.dim))
            for (i in 0 until tasks.length()) {
                val t = tasks.optJSONObject(i) ?: continue
                val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; gravity = android.view.Gravity.CENTER_VERTICAL }
                row.addView(tv("• [" + t.optString("status") + "] " + t.optString("text") + " (" + t.optString("agent") + ")", 12f, th.text).apply { layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f) })
                // vc246 GELOMBANG 5 (rantai 2): tombol "Tandai selesai"
                // manual yang JUJUR (mengubah status papan jadi done)
                // dipisah dari "✓ Selesai" lama yang ternyata memicu
                // VERIFIKASI agen, bukan eksekusi/penanda.
                if (t.optString("status") != "done" && !sessArchivedNow()) {
                    row.addView(thSmallBtn("Tandai selesai") {
                        Automation.markSessionTaskDone(this, room, curSess, i)
                        Automation.logAction(this, room.optString("id"), "sistem", "tandai selesai manual", t.optString("text"), curSess.optString("id")); renderBoard()
                    })
                    row.addView(thSmallBtn("✓ Verifikasi") {
                        if (verifying.contains(i)) return@thSmallBtn
                        val tasks = Automation.sessionTasks(curSess)
                        val t2 = tasks.optJSONObject(i) ?: return@thSmallBtn
                        val criteria = t2.optString("criteria").ifBlank { "Tugas tuntas bila: " + t2.optString("text") }
                        if (apiClient == null) {
                            Automation.setSessionTaskVerified(this, room, curSess, i, "SEBAGIAN", "Verifikasi dilewati — engine belum siap.")
                            Automation.logAction(this, room.optString("id"), "sistem", "verifikasi tugas", "SEBAGIAN — engine belum siap: " + t2.optString("text"), curSess.optString("id")); renderBoard()
                        } else {
                            verifying.add(i); renderBoard()
                            val recent = StringBuilder()
                            val msgs = Automation.loadMessages(this, room.optString("id"))
                            var collected = 0
                            for (j in msgs.length() - 1 downTo 0) {
                                if (collected >= 8) break
                                val m = msgs.optJSONObject(j) ?: continue
                                val ms = m.optString("sess", "")
                                if (ms.isNotBlank() && ms != curSess.optString("id")) continue
                                recent.append(m.optString("sender")).append(": ").append(m.optString("text")).append("\n")
                                collected++
                            }
                            val verAgent = if (sub == "multi") "Mandor, koordinator automation" else "agen " + (Agents.all(this).firstOrNull { it.id == curSess.optString("agent") }?.name ?: "automation")
                            val prompt = "Kamu " + verAgent + " yang memeriksa hasil tugas. Tugas: " + t2.optString("text") + ". Kriteria selesai: " + criteria + ". Bukti terbaru dari room:\n" + recent.toString() + "Jawab PERSIS dua baris: baris pertama STATUS: TERVERIFIKASI atau STATUS: SEBAGIAN atau STATUS: GAGAL; baris kedua BUKTI: <satu kalimat bukti>. Jangan teks lain."
                            try {
                                apiClient?.chat(prompt, false, false, { _: String -> },
                                    { answer, _ -> runOnUiThread {
                                        verifying.remove(i)
                                        val st = when {
                                            answer.contains("TERVERIFIKASI") -> "TERVERIFIKASI"
                                            answer.contains("GAGAL") -> "GAGAL"
                                            else -> "SEBAGIAN"
                                        }
                                        val note = answer.substringAfter("BUKTI:", "").trim().take(200).ifBlank { answer.take(200) }
                                        if (st == "GAGAL") {
                                            Automation.setSessionTaskVerifyOnly(this, room, curSess, i, st, note)
                                            Automation.logAction(this, room.optString("id"), "sistem", "verifikasi tugas", "GAGAL — $note", curSess.optString("id")); renderBoard()
                                        } else {
                                            Automation.setSessionTaskVerified(this, room, curSess, i, st, note)
                                            Automation.logAction(this, room.optString("id"), "sistem", "verifikasi tugas", "$st — $note", curSess.optString("id")); renderBoard()
                                        }
                                    } },
                                    { err -> runOnUiThread {
                                        verifying.remove(i)
                                        Automation.setSessionTaskVerified(this, room, curSess, i, "SEBAGIAN", "Verifikasi gagal: $err")
                                        Automation.logAction(this, room.optString("id"), "sistem", "verifikasi tugas", "SEBAGIAN — verifikasi gagal: $err", curSess.optString("id")); renderBoard()
                                    } })
                            } catch (e: Exception) {
                                verifying.remove(i)
                                Automation.setSessionTaskVerified(this, room, curSess, i, "SEBAGIAN", "Verifikasi gagal: ${e.message}")
                                Automation.logAction(this, room.optString("id"), "sistem", "verifikasi tugas", "SEBAGIAN — verifikasi gagal: ${e.message}", curSess.optString("id"))
                                renderBoard()
                            }
                        }
                    })
                }
                boardBox.addView(row)
            val crit = t.optString("criteria")
            if (crit.isNotBlank()) {
                boardBox.addView(tv("Kriteria: " + crit, 11.5f, th.dim).apply { setPadding(dp(12), 0, 0, dp(2)) })
            }
            val vrf = t.optString("verify")
            if (vrf.isNotBlank()) {
                boardBox.addView(tv("↳ Verifikasi: " + vrf + " — " + t.optString("verifyNote"), 11.5f, th.dim).apply { setPadding(dp(12), 0, 0, dp(4)) })
            }
            if (verifying.contains(i)) {
                boardBox.addView(tv("⏳ Memverifikasi tugas ini…", 11.5f, th.dim).apply { setPadding(dp(12), 0, 0, dp(4)) })
            }
            }
        }

        fun renderDivBoard() {
            divBoardBox.removeAllViews()
            val div = Automation.loadDiv(this, room.optString("id"), curSess.optString("id"))
            if (div.length() == 0) {
                divBoardBox.addView(tv("PAPAN PEMBAGIAN LIVE — belum ada pembagian.", 12f, th.dim))
                return
            }
            divBoardBox.addView(tv("PAPAN PEMBAGIAN LIVE", 13f, th.text, true))
            for (i in 0 until div.length()) {
                val d = div.optJSONObject(i) ?: continue
                val st = d.optString("status")
                val icon = if (st == "selesai") "✓" else if (st == "gagal") "✗" else "⏳"
                divBoardBox.addView(tv("• [" + icon + "] " + d.optString("sub").take(60) + " (pekerja slot " + d.optInt("worker", 0) + "): " + d.optString("result").take(80), 12f, th.text))
            }
        }

        fun renderSection() {
            refreshArchivedViews()
            divBoardBox.visibility = if (roomSection == "diskusi" && curSess.optString("divMode") == "koordinator") View.VISIBLE else View.GONE
            if (divBoardBox.visibility == View.VISIBLE) renderDivBoard()
            if (roomSection == "laporan") Automation.clearReportUnreadFor(this, room.optString("id"), curSess.optString("id"))
            papanHeader.visibility = if (roomSection == "tugas") View.VISIBLE else View.GONE
            boardBox.visibility = if (roomSection == "tugas") View.VISIBLE else View.GONE
            diskusiHeader.visibility = if (roomSection == "tugas") View.GONE else View.VISIBLE
            diskusiHeader.text = if (roomSection == "laporan") "LAPORAN" else "DISKUSI"
            msgBox.visibility = if (roomSection == "tugas") View.GONE else View.VISIBLE
            typingBox.visibility = if (roomSection == "diskusi") View.VISIBLE else View.GONE
            renderBoard()
            renderMessages()
            refreshSectionChips()
        }

        chipDiskusi = thBtn("💬 Diskusi", true) { roomSection = "diskusi"; renderSection(); scrollBottom() }
        chipTugas = thBtn("☑ Tugas", false) { roomSection = "tugas"; renderSection(); scrollBottom() }
        chipLaporan = thBtn("📋 Laporan", false) { roomSection = "laporan"; renderSection(); scrollBottom() }
