        chipDiskusi?.let { it.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }; sectionRow.addView(it) }
        chipTugas?.let { it.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }; sectionRow.addView(it) }
        chipLaporan?.let { it.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }; sectionRow.addView(it) }
        chipPanel?.let { it.layoutParams = LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f).apply { setMargins(dp(3), dp(3), dp(3), dp(3)) }; sectionRow.addView(it) }

        fun typingAdd(name: String) {
            if (!typingViews.containsKey(name)) {
                // vc246 GELOMBANG 5 (AG-M5): indikator running room kini
                // menyebut mode (Solo vs Multi), bukan generik.
                val modeLabel = if (sub == "solo") "Solo" else "Multi"
                val v = tv("⏳ $name sedang mengetik… (mode $modeLabel)", 12f, th.dim)
                typingBox.addView(v); typingViews[name] = v
            }
        }

        fun typingRemove(name: String) {
            typingViews.remove(name)?.let { typingBox.removeView(it) }
        }

        fun buildRoomPrompt(ag: Agents.Profile, text: String, multi: Boolean, sess: org.json.JSONObject? = null, preRanked: List<Fact>? = null): String {
            val roomNow = Automation.roomById(this, roomId) ?: room
            val sb = StringBuilder()
            if (!multi) {
                // vc240 M17: Solo room TIDAK lagi memakai buildSystemPrompt
                // penuh milik agen aktif — otak per agen room via
                // promptBlocksFor (persona/behavior agen room + SOUL/AGENTS/
                // MEMORY agen room) + katalog skill + fakta/goals ber-cap
                // seperti 1-1. Cap total + guard + Monitor diterapkan di
                // akhir buildRoomPrompt (di bawah).
                sb.append(Behaviors.block(ag.pack))
                sb.append(AgentBrain.promptBlocksFor(this, ag.id))
                sb.append(AgentPrompt.CTX_LABEL_RULES).append("\n\n")
                // vc302 Fix B: aturan total paging (total dari header, jangan jumlahkan) — room solo.
                sb.append(AgentPrompt.PAGING_TOTAL_RULE_VC302).append("\n\n")
                val skillsRoomVc240 = try { RedactSecrets.redact(MemoryDb.get(this).skillsText(text)) } catch (e: Exception) { "" }
                if (skillsRoomVc240.isNotBlank()) sb.append(H_SKILL).append(skillsRoomVc240).append("\n\n")
                val pinnedRoomVc248 = try { RedactSecrets.redact(MemoryDb.get(this).pinnedFactsText()) } catch (e: Exception) { "" }
                if (pinnedRoomVc248.isNotBlank()) sb.append(H_PIN).append(pinnedRoomVc248).append("\n\n")
                val factsRoomVc240 = try { RedactSecrets.redact(MemoryDb.get(this).dedupFactsVsPinned(MemoryDb.get(this).factsText(text), MemoryDb.get(this).pinnedFactsText())) } catch (e: Exception) { "" }
                if (factsRoomVc240.isNotBlank()) sb.append(H_MEMORI).append(factsRoomVc240).append("\n\n")
                val goalsRoomVc240 = try { RedactSecrets.redact(MemoryDb.get(this).goalsText(text)) } catch (e: Exception) { "" }
                if (goalsRoomVc240.isNotBlank()) sb.append(H_TUJUAN).append(goalsRoomVc240).append("\n\n")
                // vc244 GELOMBANG 3 (K-05): Solo room kini membawa katalog
                // katalog tool yang sama seperti Multi + baris
                // format blok JSON tool. Sebelumnya Solo tanpa katalog
                // padahal handleRoomReply tetap mem-parse JSON tool.
                // Pilihan yang diambil: katalog ditambahkan (bukan opsi
                // "Solo = diskusi saja"), jadi parser dan prompt sepakat.
                sb.append("Format tool (bila perlu): ```json {\"tool\":\"NAMA\",\"args\":{}}\n```\n")
                run {
                    // vc250 (unifikasi H-M10): katalog room UTUH seperti 1-1/grup — precedence + format ask + anti-injeksi ikut, tanpa potong per baris.
                    val catFullSoloVc250 = AgentPrompt.toolCatalog(this)
                    val catCappedSoloVc244 = if (catFullSoloVc250.length > 20000) catFullSoloVc250.take(20000) + "\n…(katalog room dipotong, sisa " + (catFullSoloVc250.length - 20000) + " char)…" else catFullSoloVc250
                    sb.append("Tool yang tersedia di sesi ini (katalog tool, sama seperti chat 1-1):\n").append(catCappedSoloVc244).append("\n")
                }
                sb.append("Aturan eksekusi di room (vc247, gerbang NONAKTIF): semua tool jalan langsung tanpa dialog, PIN, atau penahanan; analyze_photo hanya dari chat 1-1; keputusan per tugas tetap di tangan user.\n")
                if (sess != null) sb.append("Kamu ").append(ag.name).append(" (").append(agentRole(ag.id, ag.engine)).append("). Kamu di Room Automation solo (sesi ").append(sess.optString("title")).append(").\n")
                sb.append("KONTEKS ROOM AUTOMATION (chat 1-1 tidak terganggu; ini room khusus):\n")
            } else {
                sb.append("Kamu ").append(ag.name).append(" (").append(agentRole(ag.id, ag.engine)).append("). Kamu di Room Automation multi-agen.\n")
                if (sess != null) sb.append("Sesi: ").append(sess.optString("title")).append(" (mode multi, pembagian: ").append(if (sess.optString("divMode") == "koordinator") "koordinator" else "paralel-bebas").append(").\n")
                sb.append("Format tool (bila perlu): ```json {\"tool\":\"NAMA\",\"args\":{}}\n```\n")
                // vc250 (unifikasi H-M10): katalog room kini UTUH seperti
                // 1-1/grup (precedence + format ask + anti-injeksi ikut),
                // bukan lagi hanya baris "- " yang dipotong per baris.
                // Cap total 20000 char dengan penanda sisa. Thinking multi
                // tetap false (routing tidak diubah).
                run {
                    // vc250 (unifikasi H-M10): katalog room UTUH seperti 1-1/grup — precedence + format ask + anti-injeksi ikut, tanpa potong per baris.
                    val catFullVc250 = AgentPrompt.toolCatalog(this)
                    val catCapped = if (catFullVc250.length > 20000) catFullVc250.take(20000) + "\n…(katalog room dipotong, sisa " + (catFullVc250.length - 20000) + " char)…" else catFullVc250
                    // vc244 GELOMBANG 3 (XL-Multi): kalimat jujur.
                    // Klaim lama "semua bisa dipakai kecuali yang diblokir"
                    // dihapus karena gerbang room menahan REVIEW/HIGH.
                    // Pilihan yang diambil: kalimat prompt diperbaiki
                    // (bukan jalur dialog baru untuk semua tier); dialog
                    // REVIEW room ditambahkan terpisah lewat RM-M1 vc244.
                    sb.append("Tool yang tersedia di sesi ini (katalog tool, sama seperti chat 1-1):\n").append(catCapped).append("\n").append("Aturan eksekusi di room (vc247, gerbang NONAKTIF): semua tool jalan langsung tanpa dialog, PIN, atau penahanan; analyze_photo hanya dari chat 1-1; keputusan per tugas tetap di tangan user.\n")
                }
                sb.append(AgentPrompt.CTX_LABEL_RULES).append("\n\n")
                // vc302 Fix B: aturan total paging (total dari header, jangan jumlahkan) — room multi.
                sb.append(AgentPrompt.PAGING_TOTAL_RULE_VC302).append("\n\n")
                sb.append("Aturan room multi: bekerja paralel dengan agen lain, tidak saling menunggu. Bila pesan ini tidak relevan dengan peran/skill-mu, balas persis dengan LEWATI (tidak ditampilkan). Bila relevan, jawab langsung.\n")
            }
            if (multi) {
                // vc244 GELOMBANG 3 (XL-Memori): multi room kini
                // membawa katalog skill ber-query + ber-cap seperti Solo.
                val skillsMultiVc244 = try { RedactSecrets.redact(MemoryDb.get(this).skillsText(text)) } catch (e: Exception) { "" }
                if (skillsMultiVc244.isNotBlank()) sb.append(H_SKILL).append(skillsMultiVc244).append("\n\n")
                val pinnedMultiVc248 = try { RedactSecrets.redact(MemoryDb.get(this).pinnedFactsText()) } catch (e: Exception) { "" }
                if (pinnedMultiVc248.isNotBlank()) sb.append(H_PIN).append(pinnedMultiVc248).append("\n\n")
                val factsMultiVc240 = try { RedactSecrets.redact(MemoryDb.get(this).dedupFactsVsPinned(MemoryDb.get(this).factsText(text), MemoryDb.get(this).pinnedFactsText())) } catch (e: Exception) { "" }
                if (factsMultiVc240.isNotBlank()) sb.append(H_MEMORI).append(factsMultiVc240).append("\n\n")
                val goalsMultiVc240 = try { RedactSecrets.redact(MemoryDb.get(this).goalsText(text)) } catch (e: Exception) { "" }
                if (goalsMultiVc240.isNotBlank()) sb.append(H_TUJUAN).append(goalsMultiVc240).append("\n\n")
            }
            sb.append("Aturan graph: konsultasi graph tools dulu sebelum menjawab dari ingatan bila pertanyaan menyangkut riwayat atau keputusan room.\n")
            sb.append("[USER — TUGAS ROOM VERBATIM]:\n").append(roomNow.optString("task")).append("\n[/USER]\n")
            val tasks = if (sess != null) Automation.sessionTasks(sess) else roomNow.optJSONArray("tasks") ?: org.json.JSONArray()
            if (tasks.length() > 0) {
                sb.append("Papan tugas:\n")
                for (i in 0 until tasks.length()) {
                    val t = tasks.optJSONObject(i) ?: continue
                    sb.append("- [").append(t.optString("status")).append("] ").append(t.optString("text")).append(" (").append(t.optString("agent")).append(")\n")
                }
            }
            val blArr = roomNow.optJSONArray("blocklist") ?: org.json.JSONArray()
            if (blArr.length() > 0) {
                val names = ArrayList<String>()
                for (i in 0 until blArr.length()) names.add(blArr.optString(i))
                sb.append("BATASAN AUTOMATION — alat berikut DILARANG dipakai di room ini, jangan pernah memanggilnya: ").append(names.joinToString(", ")).append("\n")
            }
            if (sess != null) {
                sb.append("ATURAN OUTPUT FILE (cadangan): Bila tugas ini MENGHASILKAN file/laporan DAN user tidak memberi arahan lokasi output, tulis ke ").append(Automation.outputDirFor(this, roomNow, sess)).append(" (buat folder bila belum ada). Bila user memberi arahan lokasi output, pakai lokasi itu. Bila tugas ini memodifikasi/mengoptimalkan device, aturan folder ini TIDAK berlaku — akses bebas.\n")
            }
            // vc198 Fase 3: [MEMORI] MENGGANTIKAN blok PETA MEMORI TERKAIT
            // dari subgraphFor (bukan ditumpuk). subgraphFor tetap ada di
            // GraphDb sebagai legacy, tidak lagi dipanggil prompt.
            // ORIENTASI GRAPH di bawah tetap seperti sekarang.
            // preRanked = hasil rerank LLM bila toggle Setting room aktif;
            // null = ranking FTS + traversal (default, tanpa panggilan LLM).
            val memFacts = preRanked ?: try { GraphDb.get(this).memoryCandidates(text, roomNow.optString("title")) } catch (e: Exception) { emptyList() }
            // vc241 O2: dedup graph room vs kunci fakta (sama seperti 1-1) — fakta tabel sudah tampil di blok MEMORI PERSISTEN room.
            val memFactsVc241 = try { val keysVc241 = MemoryDb.get(this).factsAllWithStatus().map { it.first.lowercase() }.filter { it.length >= 4 }; memFacts.filter { mf -> keysVc241.none { k -> mf.factText.lowercase().contains(k) } } } catch (e: Exception) { memFacts }
            val memBlockRawVc245 = try { GraphDb.get(this).memoryBlock(memFactsVc241) } catch (e: Exception) { "" }
            // vc245 GELOMBANG 4 (FT-M4): blok memori room dilabeli global
            // bila grup room belum ada (fallback memoryCandidates ke
            // seluruh graph, bukan scope room).
            val memBlock = if (memBlockRawVc245.isNotBlank() && !(try { GraphDb.get(this).groupExists(roomNow.optString("title")) } catch (e: Exception) { true })) memBlockRawVc245.replaceFirst("[MEMORI]", "[MEMORI — global (belum scope room)]") else memBlockRawVc245
            if (memBlock.isNotBlank()) sb.append(memBlock).append("\n")
            val overview = try { GraphDb.get(this).overviewText(roomNow.optString("title")) } catch (e: Exception) { "" }
            if (overview.isNotBlank()) sb.append(overview).append("\n")
            // VC303-P2-9 (CX-2): catatan kerja ROOM ini (kunci
            // ber-namespace per room+sesi) DITEMPEL SEBELUM catatan 1-1 —
            // giliran room berikut melihat hasil tool room sebelumnya
            // (termasuk votes eval), bukan hanya tail 10 pesan. Isolasi:
            // kunci room tidak dicampur ke kunci 1-1.
            run {
                val roomSessVc303 = sess?.optString("id") ?: ""
                if (roomSessVc303.isNotBlank()) {
                    val rbVc303 = WorkNotesVc301.blockForKey(this, WorkNotesVc301.roomNotesKey(room.optString("id"), roomSessVc303))
                    if (rbVc303.isNotBlank()) sb.append("[CATATAN KERJA ROOM INI]\n").append(rbVc303).append("\n\n")
                }
            }
            // vc302 Fix C: catatan kerja sesi 1-1 aktif DITEMPEL ke prompt
            // room (sebelum riwayat room). Room kini menulis catatan
            // SENDIRI (kunci ber-namespace, CX-2 vc303) — yang dibaca di
            // sini = catatan sesi 1-1 yang aktif saat room dibuka
            // (konsisten dengan room yang sudah menarik fakta/skill/goals
            // user); baris berlabel jelas "GILIRAN SEBELUMNYA" dan agen
            // boleh mengabaikan yang tidak relevan dengan tugas room ini.
            run { val wb = AgentPrompt.workNotesBlockVc302(this, currentSessionId); if (wb.isNotBlank()) sb.append(wb).append("\n\n") }
            // VC303-P3-19 (LP-5): larangan pola room yang pernah mengunci +
            // jejak baca ronde ini per agen (bukan global).
            val roomSessVc303 = sess?.optString("id").orEmpty().ifBlank { curSess.optString("id") }
            run { val rb = roomLockedPatternsBlockVc303(roomId, roomSessVc303, ag.name); if (rb.isNotBlank()) sb.append(rb).append("\n\n") }
            run { val rt = roomReadTraceBlockVc303(roomId, roomSessVc303, ag.name); if (rt.isNotBlank()) sb.append(rt).append("\n\n") }
            val msgs = Automation.loadMessages(this, room.optString("id"))
            val recent = ArrayList<org.json.JSONObject>()
            for (i in 0 until msgs.length()) {
                val m = msgs.optJSONObject(i) ?: continue
                if (m.optString("sub") != sub) continue
                val ms = m.optString("sess", "")
                val sessOk = if (sess == null) true else if (ms.isNotBlank()) ms == sess.optString("id") else Automation.isFirstSession(roomNow, sess)
                if (sessOk) recent.add(m)
            }
            val tail = if (recent.size > 10) recent.subList(recent.size - 10, recent.size) else recent
            if (tail.isNotEmpty()) {
                // vc240 M17: riwayat room seperti Vc230 — cap 800 char per
                // pesan + header provenance (menampilkan X dari Y).
                sb.append("[RIWAYAT]\nRiwayat room terbaru (menampilkan ").append(tail.size).append(" dari ").append(recent.size).append(" pesan room/sesi ini; tiap pesan dipotong maks 2000 char):\n")
                for (m in tail) sb.append(m.optString("sender")).append(": ").append(m.optString("text").take(2000)).append("\n")
            }
            sb.append("[/RIWAYAT]\n").append("Pesan user: ").append(text)
            // vc240 M17: cap total + guard + Monitor untuk prompt room
            // (sebelumnya prompt room tanpa cap/guard sama sekali). Guard
            // yang sama dengan 1-1 dipakai; bila masih di atas cap sesudah
            // guard, prompt dikirim utuh dengan catatan di Monitor (total
            // tercatat) — perilaku fail-open guard yang sudah ada.
            var roomPromptVc240 = sb.toString()
            run {
                val capRoomVc240 = TurnMetrics.promptCap(this)
                if (roomPromptVc240.length > capRoomVc240) {
                    val (guardedRoomVc240, trimmedRoomVc240) = guardInitialPrompt(roomPromptVc240, capRoomVc240)
                    roomPromptVc240 = guardedRoomVc240
                    TurnMetrics.recordGuardTrim(trimmedRoomVc240)
                }
                // vc252 D-M7: blok Mode Bebas ditempel SETELAH guard/cap
                // (bukan di tengah prompt seperti vc251) — guard memangkas
                // span header dan blok tanpa header sendiri bisa ikut
                // terpangkas diam-diam. Tempel di sini = toggle aktif pasti
                // sampai ke model. Blok ~450 char, jadi total bisa lewat
                // cap sebesar itu — disengaja, jauh lebih kecil daripada
                // risiko framing hilang tanpa penanda.
                // vc302 Fix F: aturan batching terminal (room solo+multi —
                // ekor bersama, sesudah guard/cap supaya tidak terpangkas,
                // sebelum Mode Bebas yang tetap paling akhir).
                roomPromptVc240 += AgentPrompt.BATCH_TERMINAL_RULE_VC302 + "\n\n"
                roomPromptVc240 += AgentPrompt.modeBebasBlock(this)
                TurnMetrics.recordPromptTotal(roomPromptVc240.length)
            }
            return roomPromptVc240
        }

        // v4.48.9.22 (vc188): penghitung kegagalan identik per agen (pola
        // StuckDetector: peringatan di 3, eskalasi setelah retry habis).
        val healCounts = HashMap<String, Int>()
        // vc263 (N-m21): detektor putaran per sesi+agen di room — satu
        // StuckWatch per (sesi, agen), hidup selama room view ini tampil.
        val roomStuckWatchesVc263 = HashMap<String, AgentPrompt.StuckWatch>()
        // vc277 O17(c): pengunci giliran room per (sesi, agen) — sekali 🛑,
        // tool berikutnya ditolak tanpa eksekusi dan tanpa memakan langkah.
        val roomStuckLocksVc277 = HashMap<String, Boolean>()
        // VC303-P2-9 (CX-2): jejak tool giliran room per (sesi, agen) —
        // dikumpulkan tiap eksekusi tool room, ditulis ke kunci
        // ber-namespace saat giliran room berakhir (toolObj == null).
        // Cermin pola roomStuckWatchesVc263 di atas (kunci sama).
        val roomTurnWorkVc303 = HashMap<String, ArrayList<WorkItem>>()


        // vc206 T5: persetujuan REVIEW khusus create_subroom di room.
        // Funnel room normal menahan semua tool non-SAFE (pesan ditahan),
        // jadi tanpa cabang ini tool ini tidak pernah jalan dari room.
        // Hanya tool ini yang dapat dialog di room; REVIEW/HIGH lain tetap
        // ditahan seperti sebelumnya. autoAllow (konsisten dengan funnel
        // 1-1) langsung jalan tanpa dialog. Dijalankan di main thread
        // (handleRoomReply dipanggil via runOnUiThread); bila activity
        // tidak aktif, jatuh ke pesan ditahan yang sama seperti sebelumnya.
        fun askCreateSubroomApproval(roomSub: String, agentName: String, tool: String, args: org.json.JSONObject, effSess: String, roomNow: org.json.JSONObject) {
            fun runApproved() {
                try { Tools.setRoomContext(roomNow.optString("id"), effSess) } catch (e: Exception) {}
                val t0RoomVc254 = System.currentTimeMillis()
                val res = try { Tools.execute(this, tool, args) } catch (e: Exception) { "Gagal: ${e.message}" }
                val msRoomVc254 = System.currentTimeMillis() - t0RoomVc254
                try { Tools.clearRoomContext() } catch (e: Exception) {}
                Automation.appendMessage(this, roomNow.optString("id"), roomSub, "sistem", ActivityTitle.formatText(tool, args, res, msRoomVc254, !WorkLog.isFailed(res)), effSess)
                Automation.logAction(this, roomNow.optString("id"), agentName, "eksekusi tool", tool + " → " + res.take(120), effSess)
                renderMessages(); scrollBottom()
            }
            // vc247: gate dimatikan — sub-room dibuat langsung tanpa dialog.
            if (ToolGate.GATES_DISABLED) { runApproved(); return }
            // vc242 GR-M7: autoAllow room kini lewat gerbang vc229 yang
            // sama (TTL 24 jam + kelas terkunci), bukan mentah dari set.
            if (ApprovalPanelStore.autoAllowValid(this, tool, -1L)) { runApproved(); return }
            val req = ToolGate.describe(tool, args)
            val show = {
                try {
                    AlertDialog.Builder(this)
                        .setTitle("Izinkan buat sub-room?")
                        .setMessage("DeepSeek ingin menjalankan: $tool\n" + ToolGate.label(req.risk) + (if (req.preview.isNotBlank()) "\nPratinjau: ${req.preview}" else "") + "\n" + req.explanation + "\nArgumen: $args")
                        .setPositiveButton("Izinkan") { _, _ -> runApproved() }
                        .setNegativeButton("Tolak") { _, _ ->
                            Automation.appendMessage(this, roomNow.optString("id"), roomSub, "sistem", "⏸ Tool $tool ditolak user — sub-room tidak dibuat.", effSess)
                            Automation.logAction(this, roomNow.optString("id"), agentName, "tool ditolak", tool, effSess)
                            renderMessages(); scrollBottom()
                        }
                        .create().show()
                } catch (e: Exception) {
                    Automation.appendMessage(this, roomNow.optString("id"), roomSub, "sistem", "⏸ Tool $tool butuh persetujuan — jalankan dari chat 1-1 (dialog tidak bisa tampil).", effSess)
                    Automation.logAction(this, roomNow.optString("id"), agentName, "tool ditahan", tool, effSess)
                    renderMessages(); scrollBottom()
                }
            }
            if (android.os.Looper.myLooper() == android.os.Looper.getMainLooper()) show() else runOnUiThread { show() }
        }
        // vc244 GELOMBANG 3 (RM-M1, pilihan dialog REVIEW): tool
        // REVIEW di room kini mendapat dialog persetujuan di room,
        // meniru dialog create_subroom di atas — bukan antrean panel
        // (panel tanpa callback eksekutor akan menandai "disetujui"
        // tanpa eksekusi, lihat XL-Panel). autoAllow room lewat gerbang
        // vc229 yang sama (TTL 24 jam + kelas terkunci). Tool HIGH tetap
        // ditahan dengan pesan jalankan dari chat 1-1; PIN HIGH tidak
        // dibangun di room.
        fun askRoomReviewApproval(roomSub: String, agentName: String, tool: String, args: org.json.JSONObject, effSess: String, roomNow: org.json.JSONObject) {
            fun runApproved() {
                val t0RoomVc254 = System.currentTimeMillis()
                val res = try { Tools.execute(this, tool, args) } catch (e: Exception) { "Gagal: ${e.message}" }
                val msRoomVc254 = System.currentTimeMillis() - t0RoomVc254
                // VC303-P2-9 (CX-2): jejak tool room (jalur REVIEW-disetujui).
                roomTurnWorkVc303.getOrPut(effSess + "|" + agentName) { ArrayList() }.add(WorkItem(tool, msRoomVc254, !WorkLog.isFailed(res), RedactSecrets.redact(res).take(120), evidence = res, args = args.toString().take(4000), resultId = Tools.lastResultId() ?: "", totalChars = Tools.lastFullLength(), callId = ""))
                Automation.appendMessage(this, roomNow.optString("id"), roomSub, "sistem", ActivityTitle.formatText(tool, args, res, msRoomVc254, !WorkLog.isFailed(res)), effSess)
                Automation.logAction(this, roomNow.optString("id"), agentName, "eksekusi tool", tool + " → " + res.take(120), effSess)
                renderMessages(); scrollBottom()
            }
            // vc247: gate dimatikan — tool room dieksekusi langsung tanpa dialog.
            if (ToolGate.GATES_DISABLED) { runApproved(); return }
            if (ApprovalPanelStore.autoAllowValid(this, tool, -1L)) { runApproved(); return }
            val req = ToolGate.describe(tool, args)
            val show = {
                try {
                    AlertDialog.Builder(this)
                        .setTitle("Izinkan tool di room?")
                        .setMessage("DeepSeek ingin menjalankan: $tool\n" + ToolGate.label(req.risk) + (if (req.preview.isNotBlank()) "\nPratinjau: ${req.preview}" else "") + "\n" + req.explanation + "\nArgumen lengkap (" + args.toString().length + " char): $args")
                        .setPositiveButton("Izinkan") { _, _ -> runApproved() }
                        .setNegativeButton("Tolak") { _, _ ->
                            Automation.appendMessage(this, roomNow.optString("id"), roomSub, "sistem", "⏸ Tool $tool ditolak user — tidak dieksekusi di room.", effSess)
                            Automation.logAction(this, roomNow.optString("id"), agentName, "tool ditolak", tool, effSess)
                            renderMessages(); scrollBottom()
                        }
                        .create().show()
                } catch (e: Exception) {
                    Automation.appendMessage(this, roomNow.optString("id"), roomSub, "sistem", "⏸ Tool $tool butuh persetujuan — jalankan dari chat 1-1 (dialog tidak bisa tampil).", effSess)
                    Automation.logAction(this, roomNow.optString("id"), agentName, "tool ditahan", tool, effSess)
                    renderMessages(); scrollBottom()
                }
            }
            if (android.os.Looper.myLooper() == android.os.Looper.getMainLooper()) show() else runOnUiThread { show() }
        }
        fun handleRoomReply(roomSub: String, agentName: String, answerRaw: String, sessId: String = "") {
            val answer = DsSafetyStrip.strip(answerRaw)
            val effSess = if (sessId.isNotBlank()) sessId else curSess.optString("id")
            // vc262 N-M10: kill switch F1 menjangkau room.
            if (getSharedPreferences("harness", MODE_PRIVATE).getBoolean("f1Off", false)) {
                Automation.appendMessage(this, room.optString("id"), roomSub, "sistem", "⛔ Dihentikan: kill switch F1 dimatikan user — balasan room ini tidak diproses.", effSess)
                renderMessages(); scrollBottom()
                return
            }
            // vc246 GELOMBANG 5 (K-06): extractAsk di jalur room seperti
            // jalur 1-1 — blok JSON ask di-strip dari teks tampil, lalu
            // disimpan sebagai pesan sender="ask" yang dirender renderMessages
            // sebagai kartu opsi yang bisa diketuk. Ask se-respons dengan
            // tool ikut tersimpan (kartu tampil segera, sebelum hasil tool
            // — penyimpangan kecil yang didokumentasikan: 1-1 merender ask
            // setelah tool, room merendernya langsung agar tidak hilang bila
            // tool ditahan/ditolak).
            // VC303-P3-19 (LP-5b): guard baca-ulang Fix A adalah singleton
            // GLOBAL — di-reset tiap giliran agen room BERGANTI (bukan tiap
            // pesan), supaya bacaan agen A di ronde lalu tidak memblokir
            // bacaan identik yang sah agen B di ronde ini (pesan guard lama
            // mengklaim hasil "sudah ada di konteks giliran ini" padahal
            // konteksnya beda). Dalam giliran agen yang sama guard tetap
            // mengakumulasi seperti semula. Jejak "sudah dibaca ronde ini"
            // disimpan PER AGEN di roomReadTraceVc303 (bukan global) dan
            // ditampilkan di buildRoomPrompt. Varian yang dipilih: reset per
            // giliran-agen + jejak per agen (bukan ubah pesan guard — teks
            // itu ada di GuardHeaderVc302.kt, di luar file P3).
            val roomKeyVc303 = roomAgentKeyVc303(room.optString("id"), effSess, agentName)
            if (roomLastAgentVc303 != roomKeyVc303) {
                try { Tools.resetRereadGuardVc302() } catch (e: Exception) {}
                roomLastAgentVc303 = roomKeyVc303
            }
            val askPairVc246 = try { AgentPrompt.extractAsk(answer) } catch (e: Exception) { null }
            val answerNoAskVc246 = askPairVc246?.second ?: answer
            val (visible, toolObj) = AgentPrompt.extractToolCall(answerNoAskVc246)
            val multiRoomVc249 = try { AgentPrompt.extractToolCalls(answerNoAskVc246) } catch (e: Exception) { emptyList() }
            // vc275 O12(a): jawaban faktual room DITAHAN sampai verdict reviewer kembali (double-pass SEBELUM tampil, seperti 1-1) — kecuali jawaban membawa tool (prosa sebelum tool; jawaban final menyusul di giliran berikut) atau jawaban non-faktual (tampil langsung). Pesan yang ditahan ditampilkan di akhir Thread reviewer di bawah. Kasus tepi: jawaban non-faktual padahal tool sudah dipakai di room ini tetap tampil langsung + direview async seperti dulu (didokumentasikan di BUILD-VC275.md).
            val holdRoomVc275 = visible.isNotBlank() && toolObj == null && multiRoomVc249.size <= 1 && AgentPrompt.hasFactualClaim(visible)
            if (visible.isNotBlank() && !holdRoomVc275) Automation.appendMessage(this, room.optString("id"), roomSub, agentName, visible, effSess)
            if (askPairVc246 != null) {
                try {
                    val aq = askPairVc246.first
                    val askJson = org.json.JSONObject().put("question", aq.optString("question")).put("options", aq.optJSONArray("options") ?: org.json.JSONArray())
                    Automation.appendMessage(this, room.optString("id"), roomSub, "ask", askJson.toString(), effSess)
                } catch (e: Exception) {}
            }
            // vc249: korpus bukti room = pesan sistem 🔧 di room/sesi ini.
            val corpusRoomVc249 = StringBuilder()
            val toolsRoomVc249 = ArrayList<String>()
            try {
                val msgsRoomVc249 = Automation.loadMessages(this, room.optString("id"))
                for (i in 0 until msgsRoomVc249.length()) {
                    val mmRoomVc249 = msgsRoomVc249.optJSONObject(i) ?: continue
                    if (mmRoomVc249.optString("sub") != roomSub) continue
                    if (mmRoomVc249.optString("sender") != "sistem") continue
                    val txRoomVc249 = mmRoomVc249.optString("text")
                    // vc254: format aktivitas baru ("▸ Judul — ✓ …") ikut
                    // jadi korpus — parser lama "🔧 " dipertahankan untuk
                    // pesan yang sudah tersimpan sebelum vc254.
                    val actVc254 = ActivityTitle.parseText(txRoomVc249)
                    if (actVc254 != null) {
                        corpusRoomVc249.append(txRoomVc249).append("\n")
                        if (actVc254.tool.isNotBlank()) toolsRoomVc249.add(actVc254.tool)
                        continue
                    }
                    if (!txRoomVc249.startsWith("🔧 ")) continue
                    corpusRoomVc249.append(txRoomVc249).append("\n")
                    val tnRoomVc249 = txRoomVc249.removePrefix("🔧 ").substringBefore(" →").substringBefore(" [").trim()
                    if (tnRoomVc249.isNotBlank()) toolsRoomVc249.add(tnRoomVc249)
                }
            } catch (e: Exception) {}
            // vc274 O6+O7: >1 tool per respons di lane room DIEKSEKUSI
            // sebagai batch per agen per sesi (BatchToolVc274 — aturan
            // sama seperti 1-1 vc273; tiap call = 1 langkah cap 50
            // kumulatif per sesi). Batch HANYA bila semua call SAFE
            // (level + blocklist dicek di muka — di bawah GATES_DISABLED
            // semua level SAFE, jadi cek ini hidup terutama untuk
            // blocklist dan bila gerbang dihidupkan lagi); bila tidak,
            // jatuh ke jalur tunggal di bawah (toolObj = call pertama,
            // termasuk dialog REVIEW / penahanan seperti biasa).
            // Bentuk continuation room: riwayat room adalah continuation
            // agen berikutnya — hasil batch ditempel sebagai SATU pesan
            // sistem gabungan (prefix "🔧 " agar masuk korpus bukti
            // reviewer room seperti pesan tool biasa). Reviewer ASYNC
            // room (O12, vc275) TIDAK diubah: hasil batch tetap melewati
            // jalur review async yang sudah ada.
            if (multiRoomVc249.size > 1) {
                val roomNowBatchVc274 = Automation.roomById(this, roomId) ?: room
                val blockedBatchVc274 = ArrayList<String>()
                val blArrBatchVc274 = roomNowBatchVc274.optJSONArray("blocklist") ?: org.json.JSONArray()
                for (biVc274 in 0 until blArrBatchVc274.length()) blockedBatchVc274.add(blArrBatchVc274.optString(biVc274))
                // vc316 N9-B1/C1 + N9-C2: batch room TIDAK BOLEH berisi (a)
                // op Concat yang butuh konfirmasi khusus — dialog hanya
                // ada di jalur tunggal, batch akan melewatinya diam-diam;
                // (b) tool WRITE Concat apa pun — batch mengeksekusi tulis
                // sekuensial di UI thread (BatchToolVc274.runBatch, jalur
                // sekuensial), risiko ANR yang sama seperti N9-C2; jalur
                // tunggal sudah dipindah ke worker thread. Batch seperti
                // itu jatuh ke jalur tunggal di bawah: hanya call pertama
                // yang dieksekusi (pola yang sama seperti batch berisi tool
                // non-SAFE). READ Concat tetap boleh di batch (kelompok
                // baca jalan di pool thread, bukan UI thread).
                val roomBatchHasConcatConfirmVc316 = multiRoomVc249.any { oVc274 -> ConcatTools.requiresSpecialConfirmVc316(oVc274.optString("tool"), oVc274.optJSONObject("args") ?: org.json.JSONObject()) }
                val roomBatchHasConcatWriteVc316 = multiRoomVc249.any { oVc274 -> val tVc274 = oVc274.optString("tool"); tVc274.startsWith("concat_") && tVc274 !in Tools.READ_TOOLS }
                val roomBatchOkVc274 = BatchToolVc274.useBatch(multiRoomVc249) && !roomBatchHasConcatConfirmVc316 && !roomBatchHasConcatWriteVc316 && multiRoomVc249.all { oVc274 ->
                    val tVc274 = oVc274.optString("tool")
                    tVc274 !in blockedBatchVc274 && ToolGate.level(tVc274, oVc274.optJSONObject("args") ?: org.json.JSONObject(), this) == RiskLevel.SAFE
                }
                if (roomBatchOkVc274) {
                    val roomBudgetKeyVc274 = "roomSteps_" + room.optString("id") + "_" + effSess
                    val roomWatchVc274 = roomStuckWatchesVc263.getOrPut(effSess + "|" + agentName) { AgentPrompt.StuckWatch() }
                    val usedRoomVc274 = HashSet<String>()
                    val callIdsRoomVc274 = multiRoomVc249.map { BatchToolVc274.nextCallId(it.optString("id"), usedRoomVc274).also { usedRoomVc274.add(it) } }
                    val reportRoomVc274 = BatchToolVc274.runBatch(
                        multiRoomVc249, callIdsRoomVc274,
                        stepsLeft = { 50 - getSharedPreferences("harness", MODE_PRIVATE).getInt(roomBudgetKeyVc274, 0) },
                        executeOne = { t, a, c, dep ->
                            BatchToolVc274.runOne(this, t, a, c, dep) { tt, aa, cc -> Tools.execute(this, tt, aa, cc) }
                        },
                        recordOutcome = { oc ->
                            try { val bpRoomVc274 = getSharedPreferences("harness", MODE_PRIVATE); bpRoomVc274.edit().putInt(roomBudgetKeyVc274, bpRoomVc274.getInt(roomBudgetKeyVc274, 0) + 1).apply() } catch (e: Exception) {}
                            Automation.logAction(this, room.optString("id"), agentName, "eksekusi tool", oc.tool + " → " + oc.result.take(120), effSess)
                            // VC303-P2-9 (CX-2): kumpulkan jejak tool room (jalur batch).
                            roomTurnWorkVc303.getOrPut(effSess + "|" + agentName) { ArrayList() }.add(WorkItem(oc.tool, oc.ms, oc.ok, RedactSecrets.redact(oc.result).take(120), evidence = oc.result, args = oc.args.toString().take(4000), resultId = oc.resultId ?: "", totalChars = oc.resultTotal, callId = oc.callId))
                            if (oc.result.startsWith("Gagal:")) {
                                val hkRoomVc274 = agentName + "|" + oc.tool
                                val hcRoomVc274 = (healCounts[hkRoomVc274] ?: 0) + 1; healCounts[hkRoomVc274] = hcRoomVc274
                                Automation.appendMessage(this, room.optString("id"), roomSub, "sistem", "⚠️ Self-healing: tool " + oc.tool + " gagal — agen dapat mencoba pendekatan lain pada pesan berikutnya.", effSess)
                                if (hcRoomVc274 >= 3) Automation.appendMessage(this, room.optString("id"), roomSub, "sistem", "⚠️ Self-healing: tool " + oc.tool + " sudah gagal identik " + hcRoomVc274 + " kali (pola StuckDetector) — jangan ulangi pendekatan yang sama.", effSess)
                            }
                            // VC303-P3-19 (LP-5b): jejak baca batch per agen
                            // (diletakkan SEBELUM observe — nilai balik lambda
                            // ini adalah teks stuck dari observe, jadi baris
                            // ini tidak boleh jadi ekspresi terakhir).
                            try { noteRoomReadVc303(room.optString("id"), effSess, agentName, oc.tool, oc.args, oc.result) } catch (e: Exception) {}
                            if (oc.prereqFailed) "" else roomWatchVc274.observe(oc.tool, oc.args, oc.result)
                        }
                    )
                    Automation.appendMessage(this, room.optString("id"), roomSub, "sistem", "🔧 " + BatchToolVc274.combinedMessage("room", reportRoomVc274), effSess)
                    // vc277 O17(c): 🛑 di dalam batch room mengunci giliran
                    // (sesi, agen) — tool berikutnya ditolak tanpa eksekusi.
                    if (reportRoomVc274.outcomes.any { AgentPrompt.StuckWatch.isStop(it.stuckText) }) {
