                                            val (ans2, _) = client.chatSync("Hasil tool " + tool + ": " + res.take(4000) + "\nSimpulkan jawaban akhir ringkas + bukti.", false, false)
                                            val (vis2, _) = AgentPrompt.extractToolCall(ans2)
                                            finalText = if (vis2.isNotBlank()) vis2 else ans2
                                        }
                                        else -> finalText = (if (vis1.isNotBlank()) vis1 + " " else "") + "[alat $tool butuh persetujuan — dilewati]"
                                    }
                                } else {
                                    finalText = if (vis1.isNotBlank()) vis1 else ans1
                                }
                                if (finalText.isNullOrBlank()) throw Exception("jawaban pekerja kosong")
                            } catch (e: Exception) {
                                lastErr = e.message ?: "error"
                                val next = filled.firstOrNull { it != pSlot && !tried.contains(it) }
                                if (next == null) break
                                attemptSlot = next
                            }
                        }
                        val d2 = div.optJSONObject(i)
                        if (d2 != null) {
                            if (finalText != null) { d2.put("status", "selesai"); d2.put("result", finalText.take(500)) } else { d2.put("status", "gagal"); d2.put("result", "gagal: " + lastErr.take(200)) }
                        }
                        Automation.saveDiv(this, room.optString("id"), sessId, div)
                        runOnUiThread { renderDivBoard() }
                        if (doneCount.incrementAndGet() == total) {
                            Thread {
