                                    val stampLaporan = "🕐 Waktu laporan: " + java.text.SimpleDateFormat("EEEE, dd MMM yyyy HH:mm", java.util.Locale("id", "ID")).format(java.util.Date()) + " WIB"
                                    // vc246 GELOMBANG 5 (AG-M3): label jujur
                                    // bila ada worker gagal — dulu sintesis
                                    // parsial tampil tanpa label.
                                    val gagalVc246 = (0 until div.length()).count { div.optJSONObject(it)?.optString("status") == "gagal" }
                                    val partialVc246 = if (gagalVc246 > 0) "⚠️ Sintesis parsial — $gagalVc246 worker gagal dari ${div.length()}.\n" else ""
                                    val finalMsg = partialVc246 + synthHeader + "\n" + stampLaporan + (if (synthRest.isNotBlank()) "\n" + synthRest else "") + "\n\nIndeks hasil: " + idx + " • Folder: " + Automation.outputDirFor(this, roomNow, sess)
                                    Automation.appendMessage(this, room.optString("id"), sub, primary.name, finalMsg, sessId)
