        fun rerankFactsSync(text: String, cands: List<Fact>): List<Fact>? {
            if (cands.isEmpty()) return cands
            return try {
                val numbered = StringBuilder()
                for (i in cands.indices) numbered.append(i).append(". ").append(cands[i].factText).append("\n")
                val prompt = "Urutkan fakta berikut dari paling relevan ke paling tidak relevan dengan pesan user. Kembalikan JSON SATU BARIS saja: {\"order\":[0,1,2]}. Hanya JSON, tanpa teks lain.\n\nPESAN USER:\n" + text + "\n\nFAKTA:\n" + numbered.toString()
                val latch = java.util.concurrent.CountDownLatch(1)
                val out = java.util.concurrent.atomic.AtomicReference<String?>(null)
                apiClient?.chat(prompt, false, false, { _: String -> }, { t, _ -> out.set(t); latch.countDown() }, { _ -> latch.countDown() }, bgMode = true)
                latch.await(45, java.util.concurrent.TimeUnit.SECONDS)
                val ans = out.get() ?: return null
                val start = ans.indexOf("{"); val end = ans.lastIndexOf("}")
                if (start < 0 || end <= start) return null
                val obj = org.json.JSONObject(ans.substring(start, end + 1))
                val order = obj.optJSONArray("order") ?: return null
                val seen = HashSet<Int>()
                val ranked = ArrayList<Fact>()
                for (i in 0 until order.length()) {
                    val idx = order.optInt(i, -1)
                    if (idx in cands.indices && seen.add(idx)) ranked.add(cands[idx])
                }
                for (i in cands.indices) if (seen.add(i)) ranked.add(cands[i])
                ranked
            } catch (e: Exception) { null }
        }

        fun sendRoomMessageInner(text: String, preRanked: List<Fact>?) {
            if (sessArchivedNow()) return
            // vc262 N-M10: kill switch F1 menjangkau room (pintu kirim pesan).
            if (getSharedPreferences("harness", MODE_PRIVATE).getBoolean("f1Off", false)) { appendSystem("⛔ Dihentikan: kill switch F1 dimatikan user — pesan room tidak dikirim."); return }
            val sessId = curSess.optString("id")
            if (sub == "solo") {
                val ag = Agents.all(this).firstOrNull { it.id == curSess.optString("agent") } ?: Agents.active(this)
                val prompt = buildRoomPrompt(ag, text, false, curSess, preRanked)
                Automation.appendMessage(this, room.optString("id"), sub, "user", text, sessId)
                renderMessages(); scrollBottom()
                dispatchSolo(ag, prompt, sessId, text)
            } else {
                val dq = debateQuestion(text)
                if (dq != null) {
                    if (dq.isBlank()) { appendSystem("⚖️ Pertanyaan debat kosong — tulis DEBAT: <pertanyaan>."); }
                    else {
                        val memArr = curSess.optJSONArray("members") ?: org.json.JSONArray()
                        val memIds = ArrayList<String>()
                        for (mi in 0 until memArr.length()) memIds.add(memArr.optString(mi))
                        dispatchDebate(text, dq, sessId, memIds, preRanked)
                    }
                } else if (curSess.optString("divMode") == "koordinator") dispatchCoordinator(text, sessId) else {
                    val memArr = curSess.optJSONArray("members") ?: org.json.JSONArray()
                    val memIds = ArrayList<String>()
                    for (mi in 0 until memArr.length()) memIds.add(memArr.optString(mi))
                    dispatchMulti(text, sessId, memIds, preRanked)
                }
            }
        }

        // vc198 Fase 3: rerank LLM HANYA bila toggle Setting room aktif
        // (default OFF). Klaim <300ms TIDAK berlaku bila rerank aktif —
        // ini panggilan latar hitungan detik via wadah bgMode (vc186).
        // Gagal/timeout -> fallback ranking FTS + traversal (preRanked null).
        // Sesi koordinator tidak memakai buildRoomPrompt (prompt divisinya
        // sendiri tanpa blok graph), jadi rerank tidak berlaku di sana.
        // Dideklarasi SETELAH helper-nya: fungsi lokal Kotlin tidak bisa
        // forward-reference (pelajaran vc188).
        fun sendRoomMessage(text: String) {
            if (sessArchivedNow()) return
            val roomNowR = try { Automation.roomById(this, room.optString("id")) ?: room } catch (e: Exception) { room }
            val rerankOn = roomNowR.optBoolean("rerank", false)
            if (rerankOn && apiClient != null) {
                Thread {
                    var ranked: List<Fact>? = null
                    try {
                        val cands = GraphDb.get(this).memoryCandidates(text, roomNowR.optString("title"))
                        ranked = rerankFactsSync(text, cands)
                    } catch (e: Exception) { ranked = null }
                    runOnUiThread { sendRoomMessageInner(text, ranked) }
                }.start()
            } else {
                sendRoomMessageInner(text, null)
            }
        }
        sendRoomFnVc246 = ::sendRoomMessage

        fun consolidateRoomGraph() {
            val roomNow = Automation.roomById(this, roomId) ?: room
            val roomIdStr = room.optString("id")
            val msgs = Automation.loadMessages(this, roomIdStr)
            val mark = Automation.graphMark(this, roomIdStr)
            val prevMsgCount = mark.optInt("msgCount", 0)
            val skippedMsgs = minOf(prevMsgCount, msgs.length())
            // vc198 Fase 3: pass deterministik dipakai bersama job latar
            // (Automation.consolidateDeterministic — satu implementasi).
            var detCands: List<Triple<String, Long, List<Long>>> = emptyList()
            try {
                val det = Automation.consolidateDeterministic(this, roomNow)
                detCands = det.candBatch
                appendSystem("🧠 Konsolidasi selesai: " + det.nodes + " node baru, " + det.edges + " edge baru, " + det.skipped + " dilewati (sudah diproses).")
            } catch (e: Exception) { appendSystem("Konsolidasi gagal: ${e.message}") }
            if (apiClient != null) {
                val newTail = ArrayList<String>()
                for (i in skippedMsgs until msgs.length()) {
                    val m = msgs.optJSONObject(i) ?: continue
                    newTail.add(m.optString("sender") + ": " + m.optString("text"))
                }
                if (newTail.isEmpty()) {
                    appendSystem("✨ Konsolidasi LLM dilewati (tidak ada konten baru).")
                } else {
                    val transcript = StringBuilder()
                    val tail20 = if (newTail.size > 20) newTail.subList(newTail.size - 20, newTail.size) else newTail
                    for (s in tail20) transcript.append(s).append("\n")
                    val prompt = GraphDb.get(this).relationsPrompt(transcript.toString())
                    try {
                        apiClient?.chat(prompt, false, false, { _: String -> },
                            { answer, _ ->
                                runOnUiThread {
                                    try {
                                        val start = answer.indexOf("{"); val end = answer.lastIndexOf("}")
                                        if (start >= 0 && end > start) {
                                            val g = GraphDb.get(this)
                                            val nb2 = g.countNodes(); val eb2 = g.countEdges()
                                            // vc198 Fase 3: relasi via implementasi bersama
                                            // (GraphDb.applyRelations — sama dengan job latar).
                                            // EXTRACTED tidak pernah dibuat di sini; verifier
                                            // hanya untuk edge INFERRED baru (Fase 2); kandidat
                                            // resolusi (deterministik + relasi) masuk adjudikasi.
                                            val allCands = ArrayList<Triple<String, Long, List<Long>>>(detCands)
                                            val outcome = g.applyRelations(answer, allCands)
                                            val newEdges = outcome.newEdges
                                            val amb = outcome.amb
                                            val dN = g.countNodes() - nb2; val dE = g.countEdges() - eb2
                                            val ambNote = if (amb > 0) " (" + amb + " AMBIGUOUS untuk review di PETA)" else ""
                                            appendSystem("✨ Konsolidasi LLM selesai: " + dN + " node baru, " + dE + " edge baru." + ambNote)
                                            // vc198 Fase 2: SATU panggilan verifier untuk batch ini.
                                            // Gagal/error/parse gagal -> dilewati, konsolidasi tetap jalan.
                                            if (newEdges.isNotEmpty()) {
                                                try {
                                                    val involved = newEdges.flatMap { listOf(it.fromLabel, it.toLabel) }.toSet()
                                                    val labCache = HashMap<Long, String>()
                                                    fun labOf(id: Long): String {
                                                        if (!labCache.containsKey(id)) labCache[id] = g.nodeById(id)?.label ?: ("#" + id)
                                                        return labCache[id] ?: ("#" + id)
                                                    }
                                                    val oldList = g.activeEdgesTouching(involved).joinToString("\n") { "old:" + it.id + ": " + labOf(it.from) + " | " + it.rel + " | " + labOf(it.to) }
                                                    val vPrompt = g.verifierPrompt(newEdges, oldList, transcript.toString())
                                                    apiClient?.chat(vPrompt, false, false, { _: String -> },
                                                        { vAnswer, _ ->
                                                            runOnUiThread {
                                                                try {
                                                                    val summary = GraphDb.get(this).applyVerifier(vAnswer, newEdges)
                                                                    appendSystem("✨ Verifier: " + summary)
                                                                } catch (e: Exception) { appendSystem("✨ Verifier dilewati (parse gagal).") }
                                                                renderMessages()
                                                            }
                                                        },
                                                        { vErr -> runOnUiThread { appendSystem("✨ Verifier dilewati: $vErr") } })
                                                } catch (e: Exception) { appendSystem("✨ Verifier dilewati: ${e.message}") }
                                            } else {
                                                appendSystem("✨ Verifier dilewati (tidak ada edge INFERRED baru).")
                                            }
                                            // vc198 Fase 3: SATU panggilan adjudikasi untuk batch
                                            // kandidat resolusi (deterministik + relasi). Gagal/
                                            // parse gagal -> dilewati, tanpa merusak konsolidasi.
                                            if (allCands.isNotEmpty()) {
                                                try {
                                                    val aPrompt = g.adjudicationPrompt(allCands)
                                                    apiClient?.chat(aPrompt, false, false, { _: String -> },
                                                        { aAnswer, _ ->
                                                            runOnUiThread {
                                                                try {
                                                                    val aSummary = GraphDb.get(this).applyAdjudications(aAnswer, allCands)
                                                                    appendSystem("✨ Resolusi entitas: " + aSummary)
                                                                } catch (e: Exception) { appendSystem("✨ Resolusi entitas dilewati (parse gagal).") }
                                                                renderMessages()
                                                            }
                                                        },
                                                        { aErr -> runOnUiThread { appendSystem("✨ Resolusi entitas dilewati: $aErr") } })
                                                } catch (e: Exception) { appendSystem("✨ Resolusi entitas dilewati: ${e.message}") }
                                            }
                                        } else appendSystem("✨ Konsolidasi LLM: tidak ada JSON relasi yang bisa diparse.")
                                    } catch (e: Exception) { appendSystem("✨ Konsolidasi LLM gagal parse: ${e.message}") }
                                    renderMessages()
                                }
                            },
                            { err -> runOnUiThread { appendSystem("✨ Konsolidasi LLM dilewati: $err") } })
                    } catch (e: Exception) { appendSystem("✨ Konsolidasi LLM dilewati: ${e.message}") }
                }
            } else appendSystem("✨ Konsolidasi LLM dilewati (engine belum siap).")
            renderMessages()
        }

        fun showRoomMapDialog() {
            val roomNow2 = Automation.roomById(this, roomId) ?: room
            val title2 = roomNow2.optString("title")
            Thread {
                try {
                    val g = GraphDb.get(this)
                    val d = g.mapData(title2)
                    val scopedVc245 = try { g.groupExists(title2) } catch (e: Exception) { true }
                    runOnUiThread {
                        // vc245 GELOMBANG 4 (FT-M4, status jujur): grup room
                        // belum ada = belum pernah konsolidasi -> JANGAN
                        // tampilkan peta global sebagai peta room. Hanya
                        // status + hitungan global berlabel jelas.
                        if (!scopedVc245) {
                            val col0 = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
                            col0.addView(tv("🗺️ PETA ROOM — " + title2, 14f, th.text, true).apply { setPadding(0, 0, 0, dp(6)) })
                            col0.addView(tv("⚠️ Belum ada peta room — ketuk 🧠 Konsolidasi dulu.", 13f, th.text).apply { setPadding(0, 0, 0, dp(8)) })
                            col0.addView(tv("Graf global saat ini (BUKAN peta room ini): " + d.nodes.size + " node • " + d.edges.size + " edge. Setelah konsolidasi, PETA ROOM akan menampilkan subgraph room ini saja.", 12f, th.dim))
                            val scroll0 = ScrollView(this).apply { addView(col0) }
                            thDialog("🗺️ PETA ROOM", scroll0, listOf(Triple("Tutup", false) { dlg: android.app.AlertDialog -> dlg.dismiss() }))
                            return@runOnUiThread
                        }
                        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
                        col.addView(tv("🗺️ PETA ROOM — " + title2, 14f, th.text, true).apply { setPadding(0, 0, 0, dp(6)) })
                        // vc246 GELOMBANG 5 (RM-m3): tampilkan kapan terakhir
                        // dikonsolidasi + tombol konsolidasi dari dalam PETA.
                        val markVc246 = try { Automation.graphMark(this, roomId) } catch (e: Exception) { org.json.JSONObject() }
                        val lastVc246 = markVc246.optLong("ts", 0)
                        val lastTxtVc246 = if (lastVc246 > 0) "Terakhir dikonsolidasi: " + java.text.SimpleDateFormat("dd/MM HH:mm", java.util.Locale("id", "ID")).format(java.util.Date(lastVc246)) else if (markVc246.optInt("msgCount", 0) > 0) "Terakhir dikonsolidasi: tidak tercatat (konsolidasi lama, sebelum vc246)" else "Belum pernah dikonsolidasi."
                        col.addView(tv(lastTxtVc246, 12f, th.dim).apply { setPadding(0, 0, 0, dp(4)) })
                        col.addView(thBtn("🧠 Konsolidasi sekarang") { consolidateRoomGraph() })
                        col.addView(tv("Node: " + d.nodes.size + " • Edge: " + d.edges.size + " • Komunitas: " + d.comms.size, 12f, th.dim).apply { setPadding(0, 0, 0, dp(8)) })
                        col.addView(tv("Edge expired (arsip): " + d.expired, 12f, th.dim).apply { setPadding(0, 0, 0, dp(8)) })
                        if (d.nodes.isEmpty()) {
                            col.addView(tv("Graf masih kosong — ketuk 🧠 Konsolidasi dulu.", 13f, th.text))
                        } else {
                            col.addView(tv("⭐ GOD NODES (paling terhubung):", 12f, th.dim, true))
                            if (d.gods.isEmpty()) col.addView(tv("Belum ada.", 12f, th.text)) else for ((nd, deg) in d.gods) col.addView(tv("- " + nd.label + " (" + deg + " hubungan)", 12f, th.text))
                            col.addView(tv("🧩 KOMUNITAS:", 12f, th.dim, true).apply { setPadding(0, dp(8), 0, 0) })
                            if (d.comms.isEmpty()) col.addView(tv("Belum ada.", 12f, th.text)) else for ((ci, grp) in d.comms.withIndex()) {
                                val shown = grp.take(8).joinToString(", ") { it.label }
                                val more = if (grp.size > 8) " … (+" + (grp.size - 8) + " lagi)" else ""
                                col.addView(tv("Komunitas " + (ci + 1) + " (" + grp.size + " anggota): " + shown + more, 12f, th.text))
                            }
                            col.addView(tv("✨ KONEKSI MENGEJUTKAN:", 12f, th.dim, true).apply { setPadding(0, dp(8), 0, 0) })
                            if (d.surprising.isEmpty()) col.addView(tv("Belum ada (graf terlalu kecil / satu komunitas).", 12f, th.text)) else for (s in d.surprising) col.addView(tv("- " + s.fromLabel + " --" + s.rel + "--> " + s.toLabel + ": " + s.reason, 12f, th.text))
                            col.addView(tv("❓ PERTANYAAN YANG BISA DIJAWAB GRAF INI:", 12f, th.dim, true).apply { setPadding(0, dp(8), 0, 0) })
                            if (d.questions.isEmpty()) col.addView(tv("Belum ada.", 12f, th.text)) else for (q in d.questions) col.addView(tv("- " + q, 12f, th.text))
                            col.addView(tv("🕐 GARIS WAKTU (tertua → terbaru, menurut tanggal tercatat):", 12f, th.dim, true).apply { setPadding(0, dp(8), 0, 0) })
                            val timeSorted = d.edges.sortedWith(compareBy<EdgeFull> { it.recordedAt <= 0L }.thenBy { it.recordedAt })
                            val timeShown = timeSorted.take(50)
                            if (timeShown.isEmpty()) col.addView(tv("Belum ada edge aktif.", 12f, th.text)) else {
                                val byId2 = d.nodes.associateBy { it.id }
                                val dfmt = java.text.SimpleDateFormat("dd/MM/yyyy", java.util.Locale("id", "ID"))
                                for (te in timeShown) {
                                    val fl2 = byId2[te.from]?.label ?: ("#" + te.from)
                                    val tl2 = byId2[te.to]?.label ?: ("#" + te.to)
                                    val dstr = if (te.recordedAt > 0L) dfmt.format(java.util.Date(te.recordedAt)) else "?"
                                    col.addView(tv(dstr + " • " + fl2 + " --" + te.rel + "--> " + tl2 + " [" + te.tag + "]", 12f, th.text))
                                }
                                if (timeSorted.size > 50) col.addView(tv("… (+" + (timeSorted.size - 50) + " edge lagi)", 12f, th.dim))
                            }
                            col.addView(tv("Edge yang sudah ada saat migrasi vc198 memakai tanggal migrasi — itu tanggal pencatatan massal, bukan tanggal fakta. Edge yang dicatat sesudahnya memakai tanggal catat asli.", 12f, th.dim))
                            col.addView(tv("⚠️ AMBIGUOUS (perlu review):", 12f, th.dim, true).apply { setPadding(0, dp(8), 0, 0) })
                            if (d.ambiguous.isEmpty()) col.addView(tv("Tidak ada.", 12f, th.text))
                        }
                        var petaDlg: android.app.AlertDialog? = null
                        if (d.ambiguous.isNotEmpty()) {
                            val byId = d.nodes.associateBy { it.id }
                            for (e in d.ambiguous) {
                                val fl = byId[e.from]?.label ?: ("#" + e.from)
                                val tl = byId[e.to]?.label ?: ("#" + e.to)
                                col.addView(tv("- " + fl + " --" + e.rel + "--> " + tl + " (confidence " + e.confidence + ")", 12f, th.text))
                                val rrow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
                                // vc237 M9: tombol Hapus permanen DIHAPUS dari dialog PETA.
                                // Hapusan edge dari UI kini hanya lewat soft-expire
                                // (expireEdge, arsip lunak seperti memory_forget: baris
                                // tidak dihapus, retrieval aktif memfilternya) — bukan
                                // deleteEdge permanen tanpa arsip seperti sebelumnya.
                                rrow.addView(thSmallBtn("✓ Konfirmasi") { try { GraphDb.get(this).confirmAmbiguous(e.id) } catch (ex: Exception) {}; petaDlg?.dismiss(); Toast.makeText(this, "Dikonfirmasi → EXTRACTED.", Toast.LENGTH_SHORT).show(); showRoomMapDialog() })
                                rrow.addView(thSmallBtn("⏳ Expire") { try { GraphDb.get(this).expireEdge(e.id) } catch (ex: Exception) {}; petaDlg?.dismiss(); Toast.makeText(this, "Edge di-expire (arsip).", Toast.LENGTH_SHORT).show(); showRoomMapDialog() })
                                rrow.addView(thSmallBtn("↩ Aktifkan lagi") { try { GraphDb.get(this).unexpireEdge(e.id) } catch (ex: Exception) {}; petaDlg?.dismiss(); Toast.makeText(this, "Edge diaktifkan lagi.", Toast.LENGTH_SHORT).show(); showRoomMapDialog() })
                                col.addView(rrow)
                            }
                        }
                        val scroll = ScrollView(this).apply { addView(col) }
                        petaDlg = thDialog("🗺️ PETA ROOM", scroll, listOf(
                            Triple("🔄 Rebuild penuh", true) { dlg: android.app.AlertDialog -> Automation.clearGraphMark(this, room.optString("id")); dlg.dismiss(); appendSystem("Penanda konsolidasi dihapus — Konsolidasi berikutnya memproses ulang semua.") },
                            Triple("Tutup", false) { dlg: android.app.AlertDialog -> dlg.dismiss() }
                        ))
                    }
                } catch (e: Exception) { runOnUiThread { Toast.makeText(this, "PETA gagal: ${e.message}", Toast.LENGTH_LONG).show() } }
            }.start()
        }

        fun refreshSessInfo() {
            val sp = getSharedPreferences("harness", Context.MODE_PRIVATE)
            try { Automation.refreshSessionArchive(this, room, curSess) } catch (e: Exception) {}
            val routines = try { org.json.JSONArray(sp.getString("routines", "[]") ?: "[]") } catch (e: Exception) { org.json.JSONArray() }
            val sched = ArrayList<String>()
            for (i in 0 until routines.length()) {
                val r = routines.optJSONObject(i) ?: continue
                if (r.optString("sessionId", "") == curSess.optString("id")) {
                    sched.add(if (r.optInt("interval_min", 0) > 0) "tiap " + r.optInt("interval_min", 0) + " mnt" else "harian " + r.optString("time", ""))
                }
            }
            val modeLine = if (curSess.optString("mode") == "multi") "Multi • pembagian: " + (if (curSess.optString("divMode") == "koordinator") "koordinator" else "paralel-bebas") else "Solo • agen: " + curSess.optString("agent")
            sessInfoLine.text = "Sesi: " + curSess.optString("title") + " • " + modeLine + " • " + Automation.sessionDurationText(curSess) + " • Jadwal: " + (if (sched.isEmpty()) "-" else sched.joinToString(", "))
        }

        fun refreshSessionRow() {
            sessRow.removeAllViews()
            val list = Automation.sessionsOfMode(room, sub)
            for (s in list) {
                val sid = s.optString("id")
                val unread = Automation.reportUnreadFor(this, room.optString("id"), sid)
                var label = s.optString("title").take(18)
                if (unread > 0) label += " (" + unread + ")"
                if (sid == curSess.optString("id")) label += " •"
                val chip = thBtn(label, sid == curSess.optString("id")) {}
                chip.setOnClickListener {
                    val target = Automation.sessionById(room, sid) ?: return@setOnClickListener
                    curSess = target
                    sub = target.optString("mode", sub)
                    room.put("lastSessionId", sid)
                    room.put("lastSub", sub)
                    Automation.updateRoom(this, room)
                    refreshSessionRow()
                    refreshSessInfo()
                    renderSection()
                    scrollBottom()
                }
                sessRow.addView(chip)
            }
        }

        fun refreshToggle() {
            bSolo.background = rounded(if (sub == "solo") ACCENT else th.tileBg, 12)
            bSolo.setTextColor(if (sub == "solo") android.graphics.Color.WHITE else th.text)
            bMulti.background = rounded(if (sub == "multi") ACCENT else th.tileBg, 12)
            bMulti.setTextColor(if (sub == "multi") android.graphics.Color.WHITE else th.text)
        }

        // v4.48.9.26 (vc192): dialog buat/edit sesi. Mode TIDAK bisa diubah
        // pada sesi yang sudah ada (pesan + tugas sudah terikat); judul,
        // agen, anggota, pembagian, dan pekerja bisa diubah.
        fun showSessionCreateDialog(editSess: org.json.JSONObject?) {
            val isEdit = editSess != null
            val th2 = currentTheme()
            val col2 = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            // vc246 GELOMBANG 5 (GR-M4 + RM-m2, catatan batas): di build
            // ini TIDAK ADA batas 3 sesi/room yang menolak (pemeriksaan
            // lama sudah tidak ada di createSession) dan durasi sesi baru
            // TIDAK diwarisi dari sesi pertama (durKind/nDays diisi dari
            // dialog ini, bukan dari sesi pertama) — dinyatakan di dialog
            // agar tidak ada yang mengira batas lama masih berlaku.
            col2.addView(tv("Sesi baru: tanpa batas jumlah sesi per room; durasi diatur di dialog ini (tidak diwarisi sesi pertama).", 12f, th2.dim))
            col2.addView(tv("JUDUL SESI", 12f, th2.dim, true))
            val eTitle = EditText(this).apply { setText(editSess?.optString("title", "") ?: ""); setTextColor(th2.text); setHintTextColor(th2.dim); background = roundedS(th2.bg, 12, th2.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) }
            col2.addView(eTitle)
            col2.addView(tv("TUGAS AWAL (opsional)", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            val eTask = EditText(this).apply { setText(""); setTextColor(th2.text); setHintTextColor(th2.dim); background = roundedS(th2.bg, 12, th2.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); minLines = 2; layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) }
            col2.addView(eTask)
            var mode = editSess?.optString("mode", sub) ?: sub
            val agents = Agents.all(this)
            var soloAgent = editSess?.optString("agent", "")?.takeIf { it.isNotBlank() } ?: Agents.active(this).id
            val agentBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            val agentBtns = HashMap<String, android.widget.Button>()
            for (ag in agents) {
                val b = thBtn(ag.name, ag.id == soloAgent) {}
                b.setOnClickListener { soloAgent = ag.id; for ((id, btn) in agentBtns) { btn.background = rounded(if (id == soloAgent) ACCENT else th2.tileBg, 12); btn.setTextColor(if (id == soloAgent) android.graphics.Color.WHITE else th2.text) } }
                agentBtns[ag.id] = b
                agentBox.addView(b)
            }
            val memberSet = HashSet<String>()
            if (isEdit) { val mm = editSess!!.optJSONArray("members") ?: org.json.JSONArray(); for (i in 0 until mm.length()) memberSet.add(mm.optString(i)) } else { memberSet.add("asisten"); memberSet.add("mandor"); memberSet.add("mentor"); memberSet.add("agen4") }
            val memberBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            val memberBtns = HashMap<String, android.widget.Button>()
            for (ag in agents) {
                val b = thBtn(ag.name, memberSet.contains(ag.id)) {}
                b.setOnClickListener { if (memberSet.contains(ag.id)) memberSet.remove(ag.id) else memberSet.add(ag.id); b.background = rounded(if (memberSet.contains(ag.id)) ACCENT else th2.tileBg, 12); b.setTextColor(if (memberSet.contains(ag.id)) android.graphics.Color.WHITE else th2.text) }
                memberBtns[ag.id] = b
                memberBox.addView(b)
            }
            var divMode = editSess?.optString("divMode", "bebas") ?: "bebas"
            val divNote = tv("Pembagian: " + (if (divMode == "koordinator") "Koordinator" else "Paralel-bebas"), 12f, th2.dim)
            val divRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            val bDivBebas = thBtn("Paralel-bebas", divMode == "bebas") {}
            val bDivKoord = thBtn("Koordinator", divMode == "koordinator") {}
            bDivBebas.setOnClickListener { divMode = "bebas"; divNote.text = "Pembagian: Paralel-bebas" }
            bDivKoord.setOnClickListener { divMode = "koordinator"; divNote.text = "Pembagian: Koordinator" }
            divRow.addView(bDivBebas, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
            divRow.addView(bDivKoord, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
            var primaryAgent = editSess?.optString("primaryAgent", "")?.takeIf { it.isNotBlank() } ?: "mandor"
            val primNote = tv("Agen utama: " + primaryAgent, 12f, th2.dim)
            val primBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            val primBtns = HashMap<String, android.widget.Button>()
            for (ag in agents) {
                val b = thBtn(ag.name, ag.id == primaryAgent) {}
                b.setOnClickListener { primaryAgent = ag.id; primNote.text = "Agen utama: " + primaryAgent; for ((id, btn) in primBtns) { btn.background = rounded(if (id == primaryAgent) ACCENT else th2.tileBg, 12); btn.setTextColor(if (id == primaryAgent) android.graphics.Color.WHITE else th2.text) } }
                primBtns[ag.id] = b
                primBox.addView(b)
            }
            val filledSlots = try { AccountPool.filledSlots(applicationContext) } catch (e: Exception) { emptyList() }
            val workerSet = HashSet<Int>()
            if (isEdit) { val ww = editSess!!.optJSONArray("workerSlots") ?: org.json.JSONArray(); for (i in 0 until ww.length()) workerSet.add(ww.optInt(i)) } else { for (s in filledSlots) workerSet.add(s) }
            val workerBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            if (filledSlots.isEmpty()) {
                workerBox.addView(tv("Belum ada slot login — pekerja diisi otomatis saat slot tersedia.", 12f, th2.dim))
            } else {
                for (s in filledSlots) {
                    val b = thBtn("Browser " + s, workerSet.contains(s)) {}
                    b.setOnClickListener { if (workerSet.contains(s)) workerSet.remove(s) else workerSet.add(s); b.background = rounded(if (workerSet.contains(s)) ACCENT else th2.tileBg, 12); b.setTextColor(if (workerSet.contains(s)) android.graphics.Color.WHITE else th2.text) }
                    workerBox.addView(b)
                }
            }
            val divLabel = tv("MODE PEMBAGIAN (multi)", 12f, th2.dim, true)
            val primLabel = tv("AGEN UTAMA (koordinator)", 12f, th2.dim, true)
            val workerLabel = tv("SLOT PEKERJA (koordinator)", 12f, th2.dim, true)
            val modeNote = tv("Mode: " + (if (mode == "multi") "Multi-Agen" else "Solo"), 12f, th2.dim)
            val modeRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            val bModeSolo = thBtn("Solo", mode == "solo") {}
            val bModeMulti = thBtn("Multi-Agen", mode == "multi") {}
            fun refreshPickers() {
                val isMulti = mode == "multi"
                agentBox.visibility = if (isMulti) View.GONE else View.VISIBLE
                memberBox.visibility = if (isMulti) View.VISIBLE else View.GONE
                divLabel.visibility = if (isMulti) View.VISIBLE else View.GONE
                divRow.visibility = if (isMulti) View.VISIBLE else View.GONE
                divNote.visibility = if (isMulti) View.VISIBLE else View.GONE
                primLabel.visibility = if (isMulti) View.VISIBLE else View.GONE
                primBox.visibility = if (isMulti) View.VISIBLE else View.GONE
                primNote.visibility = if (isMulti) View.VISIBLE else View.GONE
                workerLabel.visibility = if (isMulti) View.VISIBLE else View.GONE
                workerBox.visibility = if (isMulti) View.VISIBLE else View.GONE
            }
            if (!isEdit) {
                bModeSolo.setOnClickListener { mode = "solo"; modeNote.text = "Mode: Solo"; refreshPickers() }
                bModeMulti.setOnClickListener { mode = "multi"; modeNote.text = "Mode: Multi-Agen"; refreshPickers() }
            }
            modeRow.addView(bModeSolo, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
            modeRow.addView(bModeMulti, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
            col2.addView(tv("MODE", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(modeRow)
            col2.addView(modeNote)
            col2.addView(tv("AGEN SOLO (pilih di awal — sesi terikat ke agen ini)", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(agentBox)
            col2.addView(tv("ANGGOTA MULTI (pilih — default semua aktif)", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(memberBox)
            col2.addView(divLabel.apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(divRow)
            col2.addView(divNote)
            col2.addView(primLabel.apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(primBox)
            col2.addView(primNote)
            col2.addView(workerLabel.apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(workerBox)
            var sessDurKind = editSess?.optString("durKind", "")?.takeIf { it == "days" || it == "routine" || it == "full24" } ?: "days"
            var sessNDays = editSess?.optInt("nDays", 3) ?: 3
            if (sessNDays <= 0) sessNDays = 3
            val durNote2 = tv(when (sessDurKind) {
                "routine" -> "Dipilih: Rutinitas (sesi terbuka, tanpa kedaluwarsa)."
                "full24" -> "Dipilih: Fullwork 24 jam (sesi aktif 24 jam dari Simpan, lalu jadi arsip)."
                else -> "Dipilih: N hari (sesi aktif N hari dari Simpan, lalu jadi arsip)."
            }, 12f, th2.dim)
            val durBtns = HashMap<String, android.widget.Button>()
            fun refreshDurBtns() {
                for ((k, b) in durBtns) { b.background = rounded(if (k == sessDurKind) ACCENT else th2.tileBg, 12); b.setTextColor(if (k == sessDurKind) android.graphics.Color.WHITE else th2.text) }
