            val eTime2 = EditText(this).apply { setText(editSess?.optString("schedTime", "") ?: ""); setTextColor(th2.text); setHintTextColor(th2.dim); hint = "HH:MM, mis. 03:00"; background = roundedS(th2.bg, 12, th2.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) }
