            col2.addView(tv("WAKTU (jadwal sesi - kosong = tanpa jadwal)", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(eTime2)
            col2.addView(eInterval2)
