            col2.addView(tv("DURASI SESI", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(durRow2)
            col2.addView(durNote2)
            col2.addView(tv("JUMLAH HARI (bila N hari)", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(eDays2)
            col2.addView(tv("Bila durasi diubah, hitungan dimulai ulang dari saat Simpan.", 12f, th2.dim))
            col2.addView(tv(if (isEdit) "Mode tidak bisa diubah pada sesi yang sudah ada (pesan + tugas sudah terikat). Judul, agen, anggota, pembagian, pekerja, durasi, dan waktu bisa diubah." else "Durasi + waktu berlaku per sesi (room hanya wadah). Jadwal F2 tetap bisa mengikat routine ke sesi ini.", 12f, th2.dim).apply { setPadding(0, dp(8), 0, 0) })
            refreshPickers()
            val scroll = ScrollView(this).apply { addView(col2) }
            thDialog(if (isEdit) "✎ Edit Sesi" else "＋ Sesi Baru", scroll, listOf(
                Triple("Simpan", true) { d: android.app.AlertDialog ->
                    val title = eTitle.text.toString().trim()
                    val task = eTask.text.toString().trim()
                    val timeTxt = eTime2.text.toString().trim()
                    val intTxt = eInterval2.text.toString().trim()
                    val intVal = if (intTxt.isBlank()) 0 else intTxt.toIntOrNull() ?: -1
                    var timeOk = true
                    if (intVal < 0) timeOk = false
                    if (intVal in 1..4) timeOk = false
                    if (intVal == 0 && timeTxt.isNotBlank()) {
                        val pp = timeTxt.split(":")
                        val hh = pp.getOrNull(0)?.toIntOrNull()
                        val mm = pp.getOrNull(1)?.toIntOrNull()
                        if (hh == null || mm == null || hh !in 0..23 || mm !in 0..59) timeOk = false
                    }
                    // vc246 GELOMBANG 5 (FT-m12): bila Waktu DAN interval
                    // keduanya diisi, nyatakan pemenangnya (interval) —
                    // dulu salah satu menang diam-diam tanpa pemberitahuan.
                    if (timeOk && intVal > 0 && timeTxt.isNotBlank()) Toast.makeText(this, "Waktu dan interval keduanya diisi — interval dipakai, Waktu dikosongkan.", Toast.LENGTH_LONG).show()
                    if (!timeOk) {
                        Toast.makeText(this, "Waktu salah - jam pakai HH:MM, interval minimal 5 menit.", Toast.LENGTH_LONG).show()
                    } else if (isEdit && editSess!!.optBoolean("archived", false)) {
                        Toast.makeText(this, "Sesi arsip - tidak bisa diubah.", Toast.LENGTH_LONG).show()
                        d.dismiss()
                    } else if (isEdit) {
                        val s = editSess!!
                        if (title.isNotBlank()) s.put("title", title)
                        s.put("agent", soloAgent)
                        val mem = org.json.JSONArray()
                        for (m in memberSet) mem.put(m)
                        s.put("members", mem)
                        s.put("divMode", divMode)
                        s.put("primaryAgent", primaryAgent)
                        val ws = org.json.JSONArray()
                        for (w in workerSet) ws.put(w)
                        s.put("workerSlots", ws)
                        val nd = eDays2.text.toString().trim().toIntOrNull() ?: 3
                        val oldKind = s.optString("durKind", "")
                        val oldDays = s.optInt("nDays", 3)
                        s.put("durKind", sessDurKind)
                        s.put("nDays", if (sessDurKind == "days") (if (nd > 0) nd else 3) else 0)
                        if (sessDurKind != oldKind || (sessDurKind == "days" && nd != oldDays)) s.put("endAt", Automation.endAtFor(sessDurKind, nd))
                        s.put("schedTime", if (intVal > 0) "" else timeTxt)
                        s.put("schedIntervalMin", intVal)
                        Automation.updateSession(this, room, s)
                        Automation.syncSessionSchedule(this, room, s)
                        curSess = s
                        if (task.isNotBlank()) Automation.addSessionTask(this, room, s, task, Agents.active(this).id)
                        d.dismiss()
                        refreshSessionRow(); refreshSessInfo(); renderSection(); scrollBottom()
                        Toast.makeText(this, "Sesi diperbarui.", Toast.LENGTH_SHORT).show()
                    } else {
                        val nd = eDays2.text.toString().trim().toIntOrNull() ?: 3
                        val s = Automation.createSession(this, room, mode, title,
                            if (mode == "multi") "" else soloAgent,
                            if (mode == "multi") memberSet.toList() else emptyList(),
                            if (mode == "multi") divMode else "bebas",
                            if (mode == "multi") primaryAgent else soloAgent,
                            if (mode == "multi") workerSet.toList() else emptyList(),
                            sessDurKind, nd, if (intVal > 0) "" else timeTxt, intVal)
                        if (task.isNotBlank()) Automation.addSessionTask(this, room, s, task, Agents.active(this).id)
                        Automation.syncSessionSchedule(this, room, s)
                        room.put("lastSessionId", s.optString("id"))
                        room.put("lastSub", mode)
                        Automation.updateRoom(this, room)
                        curSess = s
                        sub = mode
                        d.dismiss()
                        refreshToggle(); refreshSessionRow(); refreshSessInfo(); renderSection(); scrollBottom()
                        Toast.makeText(this, "Sesi dibuat: " + s.optString("title"), Toast.LENGTH_SHORT).show()
                    }
                },
                Triple("Batal", false) { d: android.app.AlertDialog -> d.dismiss() }
            ))
        }

        // v4.48.9.26 (vc192): setting room — pembagian default sesi multi
        // baru, folder output cadangan, dan saklar digest harian 07:00.
        fun showRoomSettingDialog() {
            val th2 = currentTheme()
            val col2 = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            val sp = getSharedPreferences("harness", Context.MODE_PRIVATE)
            col2.addView(tv("NAMA ROOM", 12f, th2.dim, true))
            val eRoomTitle = EditText(this).apply { setText(room.optString("title")); setTextColor(th2.text); setHintTextColor(th2.dim); background = roundedS(th2.bg, 12, th2.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) }
            col2.addView(eRoomTitle)
            col2.addView(tv("Mengganti nama tidak mengubah sesi, tugas, laporan, atau folder output (folder sudah tersimpan per sesi).", 12f, th2.dim))
            var divDef = sp.getString("sessDefDivMode", "bebas") ?: "bebas"
            col2.addView(tv("PEMBAGIAN DEFAULT SESI MULTI BARU", 12f, th2.dim, true))
            val divNote = tv("Dipilih: " + (if (divDef == "koordinator") "Koordinator" else "Paralel-bebas"), 12f, th2.dim)
            val divRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            divRow.addView(thBtn("Paralel-bebas") { divDef = "bebas"; divNote.text = "Dipilih: Paralel-bebas" }, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
            divRow.addView(thBtn("Koordinator") { divDef = "koordinator"; divNote.text = "Dipilih: Koordinator" }, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
            col2.addView(divRow)
            col2.addView(divNote)
            col2.addView(tv("FOLDER OUTPUT (cadangan)", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            val eRoot = EditText(this).apply { setText(sp.getString("sessOutRoot", "/sdcard/Harness/") ?: "/sdcard/Harness/"); setTextColor(th2.text); setHintTextColor(th2.dim); background = roundedS(th2.bg, 12, th2.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) }
            col2.addView(eRoot)
            col2.addView(tv("Berlaku hanya bila tugas menghasilkan file/laporan DAN user tidak memberi arahan output. Arahan user selalu menang; tugas modifikasi/optimasi device bebas dari aturan ini.", 12f, th2.dim).apply { setPadding(0, dp(4), 0, 0) })
            val hasDigest = try {
                val arr = org.json.JSONArray(sp.getString("routines", "[]") ?: "[]")
                var found = false
                for (i in 0 until arr.length()) { val r = arr.optJSONObject(i) ?: continue; if (r.optString("kind") == "digest" && r.optString("digestRoomId") == room.optString("id")) found = true }
                found
            } catch (e: Exception) { false }
            col2.addView(tv("DIGEST HARIAN (07:00)", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            col2.addView(tv(if (hasDigest) "Aktif: ringkasan harian room ini dibuat tiap 07:00 dan dikirim ke sesi terikat." else "Nonaktif: tidak ada ringkasan harian otomatis untuk room ini.", 12f, th2.dim))
            // vc198 Fase 3: toggle rerank LLM (default OFF). Bila aktif,
            // [MEMORI] diurutkan ulang oleh LLM (1 panggilan latar per
            // pesan room, hitungan detik — klaim <300ms TIDAK berlaku).
            var rerankOn = room.optBoolean("rerank", false)
            col2.addView(tv("RERANK MEMORI (LLM)", 12f, th2.dim, true).apply { setPadding(0, dp(10), 0, 0) })
            val rerankNote = tv("Dipilih: " + (if (rerankOn) "Aktif (1 panggilan LLM latar per pesan room)" else "Nonaktif (ranking FTS + traversal saja)"), 12f, th2.dim)
            val rerankRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
            rerankRow.addView(thBtn("Mati") { rerankOn = false; rerankNote.text = "Dipilih: Nonaktif (ranking FTS + traversal saja)" }, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
            rerankRow.addView(thBtn("Hidup") { rerankOn = true; rerankNote.text = "Dipilih: Aktif (1 panggilan LLM latar per pesan room)" }, LinearLayout.LayoutParams(0, LinearLayout.LayoutParams.WRAP_CONTENT, 1f))
            col2.addView(rerankRow)
            col2.addView(rerankNote)
            thDialog("⚙ Setting Room", col2, listOf(
                Triple("Simpan", true) { d: android.app.AlertDialog ->
                    sp.edit().putString("sessDefDivMode", divDef).apply()
                    val root = eRoot.text.toString().trim()
                    if (root.isNotBlank()) sp.edit().putString("sessOutRoot", if (root.endsWith("/")) root else root + "/").apply()
                    val newTitle = eRoomTitle.text.toString().trim()
                    if (newTitle.isNotBlank() && newTitle != room.optString("title")) {
                        room.put("title", newTitle)
                        Automation.updateRoom(this, room)
                        roomTitleTv.text = "🤖 Automation: " + newTitle
                        Toast.makeText(this, "Nama room diubah.", Toast.LENGTH_SHORT).show()
                    }
                    if (room.optBoolean("rerank", false) != rerankOn) {
                        room.put("rerank", rerankOn)
                        Automation.updateRoom(this, room)
                    }
                    d.dismiss()
                    Toast.makeText(this, "Setting room disimpan.", Toast.LENGTH_SHORT).show()
                },
                Triple(if (hasDigest) "Matikan Digest" else "Aktifkan Digest", false) { d: android.app.AlertDialog ->
                    try {
                        val arr = org.json.JSONArray(sp.getString("routines", "[]") ?: "[]")
                        if (hasDigest) {
                            val kept = org.json.JSONArray()
                            for (i in 0 until arr.length()) { val r = arr.optJSONObject(i) ?: continue; if (!(r.optString("kind") == "digest" && r.optString("digestRoomId") == room.optString("id"))) kept.put(r) }
                            sp.edit().putString("routines", kept.toString()).apply()
                            Toast.makeText(this, "Digest harian dimatikan.", Toast.LENGTH_SHORT).show()
                        } else {
                            val o = org.json.JSONObject()
                            o.put("id", "digest_" + room.optString("id"))
                            o.put("kind", "digest")
                            o.put("digestRoomId", room.optString("id"))
                            o.put("sessionId", curSess.optString("id"))
                            o.put("time", "07:00")
                            o.put("prompt", "Digest harian room " + room.optString("title"))
                            o.put("enabled", true)
                            o.put("mode", curSess.optString("mode"))
                            arr.put(o)
                            sp.edit().putString("routines", arr.toString()).apply()
                            Toast.makeText(this, "Digest harian diaktifkan (07:00).", Toast.LENGTH_SHORT).show()
                        }
                    } catch (e: Exception) { Toast.makeText(this, "Gagal: ${e.message}", Toast.LENGTH_LONG).show() }
                    d.dismiss()
                    refreshSessInfo()
                },
                Triple("Batal", false) { d: android.app.AlertDialog -> d.dismiss() }
            ))
        }

        bSolo.setOnClickListener {
            sub = "solo"
            val target = Automation.sessionById(room, room.optString("lastSessionId"))?.takeIf { it.optString("mode") == "solo" } ?: Automation.sessionsOfMode(room, "solo").firstOrNull()
            if (target != null) { curSess = target; room.put("lastSessionId", target.optString("id")) }
            room.put("lastSub", sub)
            Automation.updateRoom(this, room)
            refreshToggle()
            refreshSessionRow()
            refreshSessInfo()
            renderSection()
            scrollBottom()
        }
        bMulti.setOnClickListener {
            sub = "multi"
            val target = Automation.sessionById(room, room.optString("lastSessionId"))?.takeIf { it.optString("mode") == "multi" } ?: Automation.sessionsOfMode(room, "multi").firstOrNull()
            if (target != null) { curSess = target; room.put("lastSessionId", target.optString("id")) }
            room.put("lastSub", sub)
            Automation.updateRoom(this, room)
            refreshToggle()
            refreshSessionRow()
            refreshSessInfo()
            renderSection()
            scrollBottom()
        }
        kirimBtn.setOnClickListener {
            val t = eMsg.text.toString().trim()
            if (t.isNotBlank()) { eMsg.setText(""); sendRoomMessage(t); roomSection = "diskusi"; renderSection() }
        }
        addTaskBtn.setOnClickListener {
            if (sessArchivedNow()) { Toast.makeText(this, "Sesi arsip — tugas tidak bisa ditambah.", Toast.LENGTH_SHORT).show(); return@setOnClickListener }
            val c2 = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            val eT = EditText(this).apply {
                hint = "Tugas…"; setTextColor(th.text); setHintTextColor(th.dim)
                background = roundedS(th.bg, 12, th.stroke); setPadding(dp(12), dp(10), dp(12), dp(10))
                layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT)
            }
            c2.addView(eT)
            thDialog("Tambah Tugas", c2, listOf(
                Triple("Simpan", true) { d2: android.app.AlertDialog -> val t = eT.text.toString().trim(); if (t.isNotBlank()) { Automation.addSessionTask(this, room, curSess, t, (Agents.all(this).firstOrNull { it.id == curSess.optString("agent") }?.id ?: Agents.active(this).id)); renderBoard(); appendSystem("Tugas ditambahkan ke papan: $t"); val c3 = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }; c3.addView(tv("Tugas sudah masuk papan sesi ini. Kirim juga ke agen sesi ini sekarang agar langsung dikerjakan, atau biarkan di papan saja?", 13f, th.text)); thDialog("Kirim ke Agen?", c3, listOf(Triple("Kirim ke agen", true) { d3: android.app.AlertDialog -> sendRoomMessage(t); roomSection = "diskusi"; renderSection(); d3.dismiss() }, Triple("Papan saja", false) { d3: android.app.AlertDialog -> roomSection = "tugas"; renderSection(); d3.dismiss() })); roomSection = "tugas"; renderSection() }; d2.dismiss() },
                Triple("Batal", false) { d2: android.app.AlertDialog -> d2.dismiss() }
            ))
        }
        // vc246 GELOMBANG 5 (RM-m2): tombol Konsolidasi dinonaktifkan
        // bila engine belum siap (dulu hanya pesan "engine belum siap"
        // setelah diketuk).
        konsolBtn.isEnabled = apiClient != null
        konsolBtn.setOnClickListener { if (apiClient == null) { Toast.makeText(this, "Engine belum siap — konsolidasi belum bisa jalan.", Toast.LENGTH_SHORT).show(); return@setOnClickListener }; consolidateRoomGraph() }
        petaBtn.setOnClickListener { showRoomMapDialog() }

        var dlgHolder: android.app.AlertDialog? = null
        tutupBtn.setOnClickListener { dlgHolder?.dismiss() }
        logBtn.setOnClickListener { showAutomationLogDialog(room.optString("id"), curSess.optString("id")) }
        sessAddBtn.setOnClickListener { if (!room.optBoolean("archived", false)) showSessionCreateDialog(null) }
        sessEditBtn.setOnClickListener { if (!sessArchivedNow()) showSessionCreateDialog(curSess) }
        sessStopBtn.setOnClickListener {
            if (sessArchivedNow()) { Toast.makeText(this, "Sesi sudah arsip.", Toast.LENGTH_SHORT).show(); return@setOnClickListener }
            val cStop = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            cStop.addView(tv("Sesi \"" + curSess.optString("title") + "\" akan diarsipkan (read-only). Pesan dan tugas tidak bisa ditambah. Sesi lain di room ini tidak terpengaruh.", 13f, th.text))
            thDialog("⏹ Hentikan Sesi", cStop, listOf(
                Triple("⏹ Hentikan", true) { dStop: android.app.AlertDialog -> Automation.stopSession(this, room, curSess); dStop.dismiss(); refreshSessionRow(); refreshSessInfo(); renderSection(); scrollBottom(); Toast.makeText(this, "Sesi dihentikan dan diarsipkan.", Toast.LENGTH_LONG).show() },
                Triple("Batal", false) { dStop: android.app.AlertDialog -> dStop.dismiss() }
            ), danger = setOf("⏹ Hentikan"))
        }
        sessSettingBtn.setOnClickListener { showRoomSettingDialog() }
        sessDigestBtn.setOnClickListener {
            // vc246 GELOMBANG 5 (FT-m13): digest ke sesi arsip ditolak
            // dengan pesan (dulu tidak dicek arsipnya, berbeda dengan
            // routine biasa yang dicek di tick).
            if (sessArchivedNow()) { Toast.makeText(this, "Sesi arsip — digest tidak dibuat untuk sesi arsip.", Toast.LENGTH_SHORT).show(); return@setOnClickListener }
            Thread {
                val digest = try { Automation.buildRoomDigest(this, room.optString("id")) } catch (e: Exception) { "Digest gagal: ${e.message}" }
                runOnUiThread {
                    Automation.appendMessage(this, room.optString("id"), sub, "laporan", "[digest harian] " + digest, curSess.optString("id"))
                    renderMessages(); scrollBottom()
                    Toast.makeText(this, "Digest dibuat — lihat di Laporan.", Toast.LENGTH_LONG).show()
                }
            }.start()
        }
        tplBtn.setOnClickListener { saveAutomationTemplate(room) }
        stopBtn.setOnClickListener {
            val cStop = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
            cStop.addView(tv("Room \"" + room.optString("title") + "\" akan diarsipkan (read-only). Tidak ada lagi job/balasan baru. Peluncuran ulang lewat template.", 13f, th.text))
            thDialog("⏹ Hentikan Automation", cStop, listOf(
                Triple("⏹ Hentikan", true) { dStop: android.app.AlertDialog -> Automation.stopRoom(this, room); dStop.dismiss(); dlgHolder?.dismiss(); refreshBeranda(); Toast.makeText(this, "Automation dihentikan dan diarsipkan.", Toast.LENGTH_LONG).show() },
                Triple("Batal", false) { dStop: android.app.AlertDialog -> dStop.dismiss() }
            ), danger = setOf("⏹ Hentikan"))
        }

        // vc292: root 3 zona — header pinned, konten scroll, composer
        // pinned. scrollHolder kini ScrollView tengah saja.
        val midScrollVc292 = ScrollView(this).apply {
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, 0, 1f)
            addView(midColVc292)
        }
        val dividerVc292 = View(this).apply {
            setBackgroundColor(th.stroke)
            layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, dp(1))
        }
        val rootColVc292 = LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            background = rounded(th.card, 18)
            addView(col, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT))
            addView(midScrollVc292)
            addView(dividerVc292)
            addView(footColVc292, LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT))
        }
        scrollHolder = midScrollVc292
        val dlg = android.app.AlertDialog.Builder(this).setView(rootColVc292).create()
        dlgHolder = dlg
        dlg.show()
        dlg.setOnDismissListener { refreshBeranda() }
        dlg.window?.setBackgroundDrawable(android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT))
        refreshToggle()
        refreshSessionRow()
        refreshSessInfo()
        renderSection()
        scrollBottom()
    }

    internal fun jobDialog() {
        val th = currentTheme()
        val prefs = getSharedPreferences("harness", MODE_PRIVATE)
        val box = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        fun loadRoutines(): org.json.JSONArray {
            return try { org.json.JSONArray(prefs.getString("routines", "[]") ?: "[]") } catch (e: Exception) { org.json.JSONArray() }
        }
        fun saveRoutines(a: org.json.JSONArray) {
            try { prefs.edit().putString("routines", a.toString()).apply() } catch (e: Exception) {}
        }
        fun fmtTs(ts: Long): String {
            return try { java.text.SimpleDateFormat("dd/MM HH:mm", java.util.Locale("id", "ID")).format(java.util.Date(ts)) } catch (e: Exception) { "" }
        }
        fun refresh() {
            box.removeAllViews()
            val off = prefs.getBoolean("jobsOff", false)
            box.addView(tv(if (off) "Status: SEMUA JOB DIMATIKAN (darurat)" else "Status: job aktif", 13f, if (off) th.errText else th.text))
            // vc246 GELOMBANG 5 (NT-m2/XL-m2): label jujur — jobsOff
            // hanya menghentikan origin jadwal/rutinitas, bukan briefing/
            // rekap/tujuan. Pilihan ubah label (bukan perluas cakupan).
            box.addView(thBtn(if (off) "▶ Nyalakan Lagi Jadwal & Rutinitas" else "⏸ Matikan Jadwal & Rutinitas (Darurat)") { prefs.edit().putBoolean("jobsOff", !off).apply(); refresh() }.apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) })
            box.addView(tv("Hanya mematikan jadwal & rutinitas. Briefing, rekap, dan langkah tujuan TIDAK ikut dimatikan.", 12f, th.dim))
            box.addView(thBtn("➕ Tambah Job Harian") {
                inputDialog("Job harian baru", "Perintah untuk agen (pakai tool baca saja bila ingin jalan tanpa approval)", "") { prompt ->
                    if (prompt.isBlank()) {
                        Toast.makeText(this@MainActivity, "Perintah kosong — dibatalkan.", Toast.LENGTH_LONG).show()
                    } else {
                        inputDialog("Jam job harian", "Format HH:MM, mis. 07:05", "07:05") { time ->
                            val parts = time.split(":")
                            val hh = parts.getOrNull(0)?.toIntOrNull()
                            val mm = parts.getOrNull(1)?.toIntOrNull()
                            if (hh == null || mm == null || hh !in 0..23 || mm !in 0..59) {
                                Toast.makeText(this@MainActivity, "Format jam salah — pakai HH:MM.", Toast.LENGTH_LONG).show()
                            } else {
                                val arr = loadRoutines()
                                val o = org.json.JSONObject()
                                o.put("id", System.currentTimeMillis().toString())
                                o.put("time", "%02d:%02d".format(hh, mm))
                                o.put("prompt", prompt)
                                o.put("enabled", true)
                                arr.put(o); saveRoutines(arr); refresh()
                            }
                        }
                    }
                }
            }.apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) })
            box.addView(thBtn("➕ Tambah Job Interval") {
                inputDialog("Job interval baru", "Perintah untuk agen (pakai tool baca saja bila ingin jalan tanpa approval)", "") { prompt ->
                    if (prompt.isBlank()) {
                        Toast.makeText(this@MainActivity, "Perintah kosong — dibatalkan.", Toast.LENGTH_LONG).show()
                    } else {
                        inputDialog("Interval job", "Tiap berapa menit? Mis. 60", "60") { mins ->
                            val m = mins.toIntOrNull()
                            if (m == null || m < 5) {
                                Toast.makeText(this@MainActivity, "Interval minimal 5 menit.", Toast.LENGTH_LONG).show()
                            } else {
                                val arr = loadRoutines()
                                val o = org.json.JSONObject()
                                o.put("id", System.currentTimeMillis().toString())
                                o.put("interval_min", m)
                                o.put("prompt", prompt)
                                o.put("enabled", true)
                                arr.put(o); saveRoutines(arr); refresh()
                            }
                        }
                    }
                }
            }.apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) })
            box.addView(thBtn("🧪 Buat 2 Job Contoh (harian 07:05 + per jam — pakai kuota LLM tiap jalan)") {
                val arr = loadRoutines()
                var changed = false
                fun has(prefix: String): Boolean {
                    for (i in 0 until arr.length()) {
                        if ((arr.optJSONObject(i)?.optString("prompt", "") ?: "").startsWith(prefix)) return true
                    }
                    return false
                }
                if (!has("Laporan kesiapan pagi")) {
                    val o = org.json.JSONObject()
                    o.put("id", "contoh-harian")
                    o.put("time", "07:05")
                    o.put("prompt", "Laporan kesiapan pagi: cek baterai, storage bebas, dan jumlah notifikasi 12 jam terakhir, lalu tulis ringkasan 3-5 baris. Hanya pakai tool baca. Tulis HANYA angka yang benar-benar tampil di hasil tool; bila hasil tool parsial, tulis 'data parsial' dan jangan menyimpulkan total.")
                    o.put("enabled", true)
                    arr.put(o); changed = true
                }
                if (!has("Cek singkat kondisi HP")) {
                    val o = org.json.JSONObject()
                    o.put("id", "contoh-perjam")
                    o.put("interval_min", 60)
                    o.put("prompt", "Cek singkat kondisi HP: baterai (persen + sedang dicas/tidak) dan waktu sekarang, jawab 1-2 kalimat. Hanya pakai tool baca. Tulis HANYA angka yang benar-benar tampil di hasil tool; bila hasil tool parsial, tulis 'data parsial' dan jangan menyimpulkan total.")
                    o.put("enabled", true)
                    arr.put(o); changed = true
                }
                if (changed) saveRoutines(arr)
                Toast.makeText(this@MainActivity, if (changed) "2 job contoh dibuat." else "2 job contoh sudah ada.", Toast.LENGTH_LONG).show()
                refresh()
            }.apply { layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) })
            val arr = loadRoutines()
            box.addView(tv("DAFTAR JOB (" + arr.length() + ")", 12f, th.dim, true))
            val sessLabels = HashMap<String, String>()
            try {
                val rooms = Automation.loadRooms(this)
                for (ri in 0 until rooms.length()) {
                    val rm = rooms.optJSONObject(ri) ?: continue
                    Automation.ensureSessions(this, rm)
                    val ss = Automation.sessions(rm)
                    for (si in 0 until ss.length()) {
                        val s = ss.optJSONObject(si) ?: continue
                        sessLabels[s.optString("id")] = rm.optString("title").take(20) + " / " + s.optString("title").take(20)
                    }
                }
            } catch (e: Exception) {}
            // vc196: label sesi room-aware — bila routine membawa roomId,
            // selesaikan lewat (roomId, sessionId), bukan map id telanjang
            // (map itu ditimpa room berikutnya bila id kembar).
            fun sessLabelForRoutine(rr: org.json.JSONObject): String {
                val sid = rr.optString("sessionId", "")
                if (sid.isBlank()) return ""
                val rid = rr.optString("roomId", "")
                if (rid.isNotBlank()) {
                    try {
                        val rm = Automation.roomById(this, rid)
                        val ss = if (rm != null) Automation.sessionById(rm, sid) else null
                        if (rm != null && ss != null) return " → Sesi: " + rm.optString("title").take(20) + " / " + ss.optString("title").take(20)
                    } catch (e: Exception) {}
                }
                return " → Sesi: " + (sessLabels[sid] ?: "?")
            }
            for (i in 0 until arr.length()) {
                val r = arr.optJSONObject(i) ?: continue
                val whenText = if (r.optInt("interval_min", 0) > 0) "tiap " + r.optInt("interval_min", 0) + " mnt" else "harian " + r.optString("time", "")
                val en = r.optBoolean("enabled", true)
                box.addView(tv("• " + whenText + " — " + r.optString("prompt", "").take(70) + sessLabelForRoutine(r) + " [" + (if (en) "AKTIF" else "NONAKTIF") + "]", 12.5f, th.text))
                val row = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL; setPadding(0, dp(4), 0, dp(6)) }
                row.addView(thSmallBtn(if (en) "Nonaktifkan" else "Aktifkan") {
                    try { r.put("enabled", !en); saveRoutines(arr) } catch (e: Exception) {}
                    refresh()
                })
                row.addView(thSmallBtn("✏️ Edit") { jobEditDialog(arr, r) { saveRoutines(arr); refresh() } })
                row.addView(thSmallBtn("Hapus") {
                    try { arr.remove(i); saveRoutines(arr) } catch (e: Exception) {}
                    refresh()
                })
                box.addView(row)
            }
            box.addView(tv("LOG TERAKHIR", 12f, th.dim, true))
            val logs = try { MemoryDb.get(this).jobHistory(15) } catch (e: Exception) { emptyList() }
            if (logs.isEmpty()) box.addView(tv("Belum ada eksekusi job tercatat.", 12.5f, th.dim))
            for (l in logs) box.addView(tv("• [" + fmtTs(l.ts) + "] " + l.job + " " + l.status + " — " + l.detail, 12f, th.dim))
        }
        refresh()
        thDialog("📋 Job Latar (F2)", box, listOf(Triple("Tutup", false) { d: android.app.AlertDialog -> d.dismiss() }))
    }

    private fun jobEditDialog(arr: org.json.JSONArray, r: org.json.JSONObject, onSaved: () -> Unit) {
        val th = currentTheme()
        val isInterval = r.optInt("interval_min", 0) > 0
        val col = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        col.addView(tv("PERINTAH", 12f, th.dim, true))
        val ePrompt = EditText(this).apply { setText(r.optString("prompt", "")); setTextColor(th.text); setHintTextColor(th.dim); background = roundedS(th.bg, 12, th.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); minLines = 3; layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) }
        col.addView(ePrompt)
        col.addView(tv(if (isInterval) "INTERVAL (MENIT)" else "JAM (HARIAN)", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, 0) })
        val eWhen = EditText(this).apply { setText(if (isInterval) r.optInt("interval_min", 60).toString() else r.optString("time", "07:05")); setTextColor(th.text); setHintTextColor(th.dim); background = roundedS(th.bg, 12, th.stroke); setPadding(dp(12), dp(10), dp(12), dp(10)); layoutParams = LinearLayout.LayoutParams(ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT) }
        col.addView(eWhen)
        col.addView(tv("MODE LAPORAN (room automation)", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, 0) })
        var jobMode = r.optString("mode", "solo")
        val modeNote = tv("Dipilih: " + (if (jobMode == "multi") "Multi-Agen" else "Solo") + " (laporan job ini masuk sesi yang dipilih di bawah; tanpa sesi = sesi #1 mode ini).", 12f, th.dim)
        val modeRow = LinearLayout(this).apply { orientation = LinearLayout.HORIZONTAL }
        modeRow.addView(thBtn("Solo") { jobMode = "solo"; modeNote.text = "Dipilih: Solo (laporan job ini masuk sesi yang dipilih di bawah; tanpa sesi = sesi #1 mode ini)." })
        modeRow.addView(thBtn("Multi") { jobMode = "multi"; modeNote.text = "Dipilih: Multi-Agen (laporan job ini masuk sesi yang dipilih di bawah; tanpa sesi = sesi #1 mode ini)." })
        col.addView(modeRow)
        col.addView(modeNote)
        col.addView(tv("SESI LAPORAN (room automation)", 12f, th.dim, true).apply { setPadding(0, dp(10), 0, 0) })
        val sessOptions = ArrayList<Triple<String, String, String>>()
        sessOptions.add(Triple("", "Default (sesi #1 mode)", ""))
        try {
            val rooms = Automation.loadRooms(this)
            for (ri in 0 until rooms.length()) {
                val rm = rooms.optJSONObject(ri) ?: continue
                Automation.ensureSessions(this, rm)
                val ss = Automation.sessions(rm)
                for (si in 0 until ss.length()) {
                    val s = ss.optJSONObject(si) ?: continue
                    sessOptions.add(Triple(s.optString("id"), rm.optString("title").take(20) + " / " + s.optString("title").take(20) + " (" + s.optString("mode") + ")", rm.optString("id")))
                }
            }
        } catch (e: Exception) {}
        // vc196: opsi membawa roomId agar pilihan tidak ambigu bila id sesi
        // kembar antar room (solo1/multi1 lama). Label dipilih lewat
        // pasangan (sessionId, roomId) bila roomId ada.
        fun sessLabelFor(id: String, roomId: String = ""): String {
            val hit = if (roomId.isNotBlank()) sessOptions.firstOrNull { it.first == id && it.third == roomId } else null
            return (hit ?: sessOptions.firstOrNull { it.first == id })?.second ?: "Default (sesi #1 mode)"
        }
        var jobSessionId = r.optString("sessionId", "")
        var jobRoomId = r.optString("roomId", "")
        val sessNote = tv("Dipilih: " + sessLabelFor(jobSessionId, jobRoomId), 12f, th.dim)
        val sessBox = LinearLayout(this).apply { orientation = LinearLayout.VERTICAL }
        for ((sid, label, sRoom) in sessOptions) {
            val b = thBtn(label, sid == jobSessionId && (jobRoomId.isBlank() || sRoom == jobRoomId)) {}
            b.setOnClickListener { jobSessionId = sid; jobRoomId = sRoom; sessNote.text = "Dipilih: " + sessLabelFor(jobSessionId, jobRoomId) }
            sessBox.addView(b)
        }
        col.addView(sessBox)
        col.addView(sessNote)
        col.addView(tv(if (isInterval) "Minimal 5 menit. Jenis job tidak bisa diubah: job interval tetap interval." else "Format HH:MM. Jenis job tidak bisa diubah: job harian tetap harian.", 12f, th.dim).apply { setPadding(0, dp(8), 0, 0) })
        thDialog("Edit Job", col, listOf(
            Triple("Simpan", true) { d: android.app.AlertDialog ->
                val prompt = ePrompt.text.toString().trim()
                var ok = true
                if (prompt.isBlank()) { Toast.makeText(this@MainActivity, "Perintah kosong — dibatalkan.", Toast.LENGTH_LONG).show(); ok = false }
                else if (isInterval) {
                    val m = eWhen.text.toString().trim().toIntOrNull()
                    if (m == null || m < 5) { Toast.makeText(this@MainActivity, "Interval minimal 5 menit.", Toast.LENGTH_LONG).show(); ok = false }
                    else { try { r.put("interval_min", m) } catch (e: Exception) {} }
                } else {
                    val parts = eWhen.text.toString().trim().split(":")
                    val hh = parts.getOrNull(0)?.toIntOrNull()
                    val mm = parts.getOrNull(1)?.toIntOrNull()
                    if (hh == null || mm == null || hh !in 0..23 || mm !in 0..59) { Toast.makeText(this@MainActivity, "Format jam salah — pakai HH:MM.", Toast.LENGTH_LONG).show(); ok = false }
                    else { try { r.put("time", "%02d:%02d".format(hh, mm)) } catch (e: Exception) {} }
                }
                if (ok) {
                    try { r.put("prompt", prompt) } catch (e: Exception) {}
                    try { r.put("mode", jobMode) } catch (e: Exception) {}
                    try { r.put("sessionId", jobSessionId) } catch (e: Exception) {}
                    try { r.put("roomId", jobRoomId) } catch (e: Exception) {}
                    onSaved()
                    d.dismiss()
                }
            },
            Triple("Batal", false) { d: android.app.AlertDialog -> d.dismiss() }
        ))
    }

    /** F3 (v4.37.0): dialog Serve Standby — toggle service persisten +
     *  panduan autostart MIUI + info batas (D3 disetujui user). */
    internal fun serveStandbyDialog() {
        val prefs = getSharedPreferences("harness", MODE_PRIVATE)
        val on = prefs.getBoolean("serveStandby", false)
        val status = ServeHealth.lastStatus(this)
        android.app.AlertDialog.Builder(this)
            .setTitle("⚡ Serve Standby (F3)")
            .setMessage("Serve proot :4199 — " + status + "\n\nAktif: service foreground persisten \"Harness standby\" menjaga proses app hidup sehingga serve ikut hidup, + percobaan bangkit otomatis pasca-reboot (Auto Start).\n\nWatchdog kini juga menjaga tailscaled + serve :4199: tiap 5 menit memastikan daemon tailscale jalan dan serve :4199 terserve (tailnet-only, tanpa funnel). Bila status \"perlu login ulang\", buka URL login dari agent — watchdog tidak bisa login sendiri.\n\nBatas jujur: MIUI tetap bisa membunuh service; bila itu terjadi, serve kembali saat app dibuka (revive pasca-update/luncur) atau lewat tombol Bangkitkan di Terminal/Profil.\n\nAgar Auto Start bekerja di MIUI: aktifkan Autostart untuk Harness di Info aplikasi (tombol di bawah), dan set Baterai = Tanpa batasan bila tersedia.")
            .setPositiveButton(if (on) "Matikan Standby" else "Aktifkan Standby") { _, _ ->
                if (on) {
                    prefs.edit().putBoolean("serveStandby", false).apply()
                    try { stopService(Intent(this, ServeStandbyService::class.java)) } catch (e: Exception) {}
                    Toast.makeText(this, "Standby dimatikan — service berhenti.", Toast.LENGTH_LONG).show()
                } else {
                    prefs.edit().putBoolean("serveStandby", true).apply()
                    try {
                        val i = Intent(this, ServeStandbyService::class.java)
                        if (android.os.Build.VERSION.SDK_INT >= 26) startForegroundService(i) else startService(i)
                    } catch (e: Exception) {}
                    Toast.makeText(this, "Standby aktif — service berjalan + serve diperiksa.", Toast.LENGTH_LONG).show()
                }
            }
            .setNeutralButton("Buka Info Aplikasi") { _, _ ->
                try { startActivity(Intent(android.provider.Settings.ACTION_APPLICATION_DETAILS_SETTINGS).apply { data = android.net.Uri.parse("package:$packageName") }) } catch (e: Exception) {}
            }
            .setNegativeButton("Tutup", null).show()
    }

    /** Intent ASSIST (panggilan asisten) + SEND (share teks dari app lain). */
    private fun handleIncomingIntent(intent: Intent?) {
        if (intent == null) return
        // vc246 GELOMBANG 5 (NT-m1/XL-m1): ketuk notif hasil latar kini
        // membawa sesi (extra bgSessionId dari BgBrain.openAppIntent) —
        // app membuka sesi itu, bukan sekadar beranda.
        try {
            val bgSess = intent.getLongExtra("bgSessionId", -1)
            if (bgSess > 0) {
                showTab("Chat")
                try { switchSession(bgSess) } catch (e: Exception) {}
            }
        } catch (e: Exception) {}
        // vc262 NT-m1: ketuk notif hasil koordinator membuka sesi asal.
        try {
            val ocSess = intent.getLongExtra("ocOriginSession", -1)
            if (ocSess > 0) {
                showTab("Chat")
                try { switchSession(ocSess) } catch (e: Exception) {}
            }
        } catch (e: Exception) {}
        // vc262 NT-m1: ketuk notif grup membuka tab Grup.
        try {
            if (intent.getBooleanExtra("openGroup", false)) showTab("Grup")
        } catch (e: Exception) {}
        if (intent.action == Intent.ACTION_ASSIST) {
            // v4.10.1: gestur/shortcut asisten = PANEL, bukan app penuh
            // (desain awal v4.2.0). Teruskan ke panel lalu tutup activity ini.
            try { startActivity(Intent(this, FloatingAgentActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)) } catch (e: Exception) {}
            // v4.11.0: JANGAN finish() — itu membunuh sesi app yang sedang
            // terbuka. Panel kini task terpisah; cukup mundurkan task app.
            try { moveTaskToBack(true) } catch (e: Exception) {}
            return
        }
        // vc176: aksi agen butuh WebView+agen (kini deferred) — bangun dulu.
        try {
            val needAgent = !intent.getStringExtra("AUTO_PROMPT").isNullOrBlank() ||
                !intent.getStringExtra("VOICE_QUERY").isNullOrBlank() ||
                intent.getBooleanExtra("AUTO_VOICE", false)
            if (needAgent) ensureWeb()
        } catch (e: Exception) {}
        try {
            val autoPrompt = intent.getStringExtra("AUTO_PROMPT")
            if (!autoPrompt.isNullOrBlank()) {
                showTab("Chat")
                addBubble("▶️ Tugas otomatis dari notifikasi: $autoPrompt", false)
                onUserMessage(autoPrompt)
                return
            }
            val voiceQuery = intent.getStringExtra("VOICE_QUERY")
            if (!voiceQuery.isNullOrBlank()) {
                showTab("Chat")
                onUserMessage(voiceQuery)
                return
            }
            if (intent.getBooleanExtra("AUTO_VOICE", false)) {
                showTab("Chat")
                startVoiceInput()
                return
            }
            if (intent.action == Intent.ACTION_SEND && intent.type == "text/plain") {
                val shared = intent.getStringExtra(Intent.EXTRA_TEXT)?.trim().orEmpty()
                if (shared.isNotEmpty() && ::chatInput.isInitialized) {
                    showTab("Chat")
                    chatInput.setText(shared)
                    chatInput.setSelection(chatInput.text.length)
                    Toast.makeText(this, "Teks dari share diterima — tekan panah kirim atau edit dulu.", Toast.LENGTH_LONG).show()
                }
            }
        } catch (e: Exception) {}
    }

    // vc268 DOUBLE GUARD EXIT (global, semua layar/lane): back pada
    // titik di mana back selama ini langsung menutup app TIDAK langsung
    // keluar — tekan pertama hanya toast, tekan kedua dalam 2000 ms baru
    // keluar (finish activity). Jeda lebih dari 2000 ms = hitungan reset.
    private var lastBackExitMs: Long = 0

    override fun onBackPressed() {
        if (isArtifactPanelOpen()) { closeArtifactPanel(); return }
        if (chatDrawerRoot?.visibility == View.VISIBLE) { setChatDrawer(false); return }
        if (webView.canGoBack() && containers["Web"]?.visibility == View.VISIBLE &&
            containers["Chat"]?.visibility != View.VISIBLE) webView.goBack()
        else {
            val now = System.currentTimeMillis()
            if (now - lastBackExitMs < 2000) {
                super.onBackPressed()
            } else {
                lastBackExitMs = now
                Toast.makeText(this, "Ketuk kembali untuk keluar dari app", Toast.LENGTH_SHORT).show()
            }
        }
    }
}

// ===== vc306 Worker C — ChatCardsVc306: logika MURNI kartu chat =====
// Objek top-level TANPA dependensi Android supaya bisa diuji JVM murni
// (TestChatCardsVc306.kt). Semua nilai visual di sini = nilai spek
// SPEC-SAMAKAN-CHAT-DSHGO.md (a.1/a.8/a.9/a.14, C6/C7/C8/C12); bila spek
// vs skill #14/#15 konflik, SKILL MENANG — penyimpangan dicatat di
// komentar masing-masing konstanta.
// - Tone tool: bg per kategori dari spek (light/dark). Teks on-container
//   (fg) TIDAK ada di spek kecuali read (#173F65/#C0DBF8) — fg lain
//   dipilih supaya kontras vs bg >= 4.5:1 (dihitung Python, rumus WCAG;
//   lihat TestChatCardsVc306.kt (a)).
// - Glyph = huruf pertama verb kategori (terminal "$" = prompt shell);
//   BUKAN ikon per tool — tidak ada data ikon per tool di Harness.
// - Pemetaan nama tool -> tone: eksplisit dari ToolRegistry.kt; nama
//   yang tidak terdaftar -> NEUTRAL (terdokumentasi, bukan ditebak).
// - Token/biaya TIDAK PERNAH dikarang: TurnMetrics hanya mencatat char
//   prompt (bukan token), DsApiClient hanya mencatat token KUMULATIF
//   per sesi (tokInSess/tokOutSess, bukan per giliran), dan tidak ada
//   data biaya/Rp di mana pun — formatFootnote menerima token/biaya
//   nullable dan menghilangkannya bila null.
object ChatCardsVc306 {
    enum class Tone { TERMINAL, READ, EDIT, SEARCH, WEB, AGENT, PLAN, NEUTRAL }

    const val GROUP_THRESHOLD = 3
    const val CODE_WELL_MAX_HEIGHT_DP = 280
    const val THINK_GLYPH_RADIUS_DP = 8 // spek 7.68 -> dibulatkan ke dp (tanpa pecahan dp di Views)

    private val TERMINAL_TOOLS = setOf("run_terminal", "run_privileged")
    private val READ_TOOLS = setOf(
        "read_file", "list_files", "storage_info", "get_screen", "get_notifications",
        "get_timeline", "get_current_app", "get_app_usage", "get_battery",
        "get_device_info", "list_apps", "get_location", "get_calendar_today",
        "get_clipboard", "read_sms", "read_call_log", "gmail_unread", "otak_read",
        "recall_facts", "recall_lessons", "list_tools", "list_skills",
        "read_skill_version", "list_skill_versions", "list_artifacts", "list_goals",
        "list_reminders", "list_schedules", "list_fact_candidates",
        "list_rule_triggers", "list_geofences", "graph_neighbors", "graph_overview",
        "graph_path", "get_result", "wait_change", "wait_for_app", "wait_confirm",
        "watch_screen", "take_screenshot", "priv_capture", "browser_tabs",
        "rote_status", "preview_worker_result"
    )
    private val EDIT_TOOLS = setOf(
        "write_file", "edit_file", "generate_document", "generate_presentation",
        "create_artifact", "edit_artifact", "delete_artifact", "artifact_bundle",
        "otak_write", "memory_add", "memory_forget", "forget_fact", "remember_fact",
        "remember_lesson", "learn_rule", "promote_fact", "propose_fact",
        "rebuild_fact_links", "make_goal", "update_goal", "set_reminder",
        "cancel_reminder", "set_alarm", "schedule_task", "cancel_schedule",
        "set_clipboard", "import_skill_file", "restore_skill_version",
        "add_geofence", "delete_geofence", "add_rule_trigger", "delete_rule_trigger",
        "add_calendar_event", "send_email", "gmail_send", "send_sms", "reply_notification"
    )
    private val SEARCH_TOOLS = setOf(
        "web_search", "search_youtube", "memory_search", "recall_search",
        "graph_search", "gmail_search", "grep_result"
    )
    private val WEB_TOOLS = setOf(
        "web_fetch", "http_request", "browser_open", "browser_tap", "browser_type",
        "browser_read", "browser_shot", "api_read", "api_write"
    )
    private val AGENT_TOOLS = setOf(
        "delegate_task", "delegate_session", "delegate_result", "delegate_wait",
        "delegate_status", "run_team", "chain_tasks", "use_skill", "create_subroom",
        "oc_checkpoint", "coord_rule", "ask_operator", "check_operator", "mcp_call",
        "mcp_list_servers", "mcp_list_tools", "mcp_setup", "judge_skill",
        "export_skill", "export_skill_version", "create_skill", "delete_skill",
        "sync_memory", "rote_run", "transcribe_media", "analyze_photo"
    )
    private val PLAN_TOOLS = setOf("make_plan", "update_plan")

    fun toneForTool(name: String): Tone = when (name.trim()) {
        in TERMINAL_TOOLS -> Tone.TERMINAL
        in READ_TOOLS -> Tone.READ
        in EDIT_TOOLS -> Tone.EDIT
        in SEARCH_TOOLS -> Tone.SEARCH
        in WEB_TOOLS -> Tone.WEB
        in AGENT_TOOLS -> Tone.AGENT
        in PLAN_TOOLS -> Tone.PLAN
        else -> Tone.NEUTRAL // nama tak dikenal / batch / generik — netral, bukan ditebak
    }

    // Fallback judul Bahasa Indonesia (ActivityTitle.title) bila nama tool
    // tidak diteruskan ke buildActivityRow — pencocokan awalan judul saja.
    fun toneForTitle(title: String): Tone {
        val t = title.trim()
        return when {
            t.contains("Rencana") || t.contains("rencana") -> Tone.PLAN
            t.startsWith("Perintah dijalankan") -> Tone.TERMINAL
            t.startsWith("Mencari") -> Tone.SEARCH
            t.startsWith("Mengambil isi") || t.startsWith("Membuka halaman") ||
                t.startsWith("Membuka ") && t.contains("http") -> Tone.WEB
            t.startsWith("Membaca") || t.startsWith("Melihat") || t.startsWith("Memeriksa") ||
                t.startsWith("Lihat ") || t.startsWith("Mengingat") -> Tone.READ
            t.startsWith("Menulis") || t.startsWith("Mengedit") || t.startsWith("Membuat") ||
                t.startsWith("Menambah") || t.startsWith("Menyimpan") || t.startsWith("Menghapus") ||
                t.startsWith("Mengubah") || t.startsWith("Mengirim") || t.startsWith("Menyalin") -> Tone.EDIT
            t.startsWith("Mendelegasikan") || t.startsWith("Menjalankan tim") ||
                t.startsWith("Memuat skill") || t.startsWith("Melempar tugas") -> Tone.AGENT
            else -> Tone.NEUTRAL
        }
    }

    // Verb spek hanya menyebut Run/Read/Edit/Thinking; kategori lain memakai
    // verb kategorinya (Search/Fetch/Agent/Plan/Tool) — didokumentasikan.
    fun verbForTone(tone: Tone): String = when (tone) {
        Tone.TERMINAL -> "Run"; Tone.READ -> "Read"; Tone.EDIT -> "Edit"
        Tone.SEARCH -> "Search"; Tone.WEB -> "Fetch"; Tone.AGENT -> "Agent"
        Tone.PLAN -> "Plan"; Tone.NEUTRAL -> "Tool"
    }

    // Glyph satu huruf dari verb ("$" = prompt shell untuk terminal).
    fun glyphForTone(tone: Tone): String = when (tone) {
        Tone.TERMINAL -> "$"; Tone.READ -> "R"; Tone.EDIT -> "E"
        Tone.SEARCH -> "S"; Tone.WEB -> "W"; Tone.AGENT -> "A"
        Tone.PLAN -> "P"; Tone.NEUTRAL -> "•"
    }

    private fun nounForTone(tone: Tone, n: Int): String {
        val singular = when (tone) {
            Tone.TERMINAL -> "command"; Tone.READ -> "file"; Tone.EDIT -> "edit"
            Tone.SEARCH -> "search"; Tone.WEB -> "fetch"; Tone.AGENT -> "agent call"
            Tone.PLAN -> "plan"; Tone.NEUTRAL -> "call"
        }
        val plural = when (tone) {
            Tone.TERMINAL -> "commands"; Tone.READ -> "files"; Tone.EDIT -> "edits"
            Tone.SEARCH -> "searches"; Tone.WEB -> "fetches"; Tone.AGENT -> "agent calls"
            Tone.PLAN -> "plans"; Tone.NEUTRAL -> "calls"
        }
        return if (n == 1) singular else plural
    }

    // --- Warna tone tool (spek a.1/C6, literal hex) ---
    // Dark: terminal #303540, read #21374E, edit #443116, search #39304B,
    // web #1D3D2D, agent #452C3D, plan #0F3D3D, neutral #32353D.
    // Light: terminal #E6EAF2, read #DAECFF, edit #FAE6CD, search #EDE5FE,
    // web #D7F1E2, agent #F9E2F0, plan #D0F1F0, neutral #E7E9EF.
    fun toneBgHex(tone: Tone, dark: Boolean): String = when (tone) {
        Tone.TERMINAL -> if (dark) "#303540" else "#E6EAF2"
        Tone.READ -> if (dark) "#21374E" else "#DAECFF"
        Tone.EDIT -> if (dark) "#443116" else "#FAE6CD"
        Tone.SEARCH -> if (dark) "#39304B" else "#EDE5FE"
        Tone.WEB -> if (dark) "#1D3D2D" else "#D7F1E2"
        Tone.AGENT -> if (dark) "#452C3D" else "#F9E2F0"
        Tone.PLAN -> if (dark) "#0F3D3D" else "#D0F1F0"
        Tone.NEUTRAL -> if (dark) "#32353D" else "#E7E9EF"
    }

    // Teks on-container: read dari spek (#173F65 light / #C0DBF8 dark);
    // sisanya dipilih agar kontras vs bg >= 4.5:1 (terukur, lihat tes (a)).
    fun toneFgHex(tone: Tone, dark: Boolean): String = when (tone) {
        Tone.TERMINAL -> if (dark) "#D5DAE6" else "#2B3345"
        Tone.READ -> if (dark) "#C0DBF8" else "#173F65"
        Tone.EDIT -> if (dark) "#F5D9A8" else "#6B4A1D"
        Tone.SEARCH -> if (dark) "#DCD2F2" else "#4A3670"
        Tone.WEB -> if (dark) "#BFE8CF" else "#1F5C38"
        Tone.AGENT -> if (dark) "#F2CBE3" else "#7A2E5E"
        Tone.PLAN -> if (dark) "#BDE8E6" else "#14524F"
        Tone.NEUTRAL -> if (dark) "#D8DBE3" else "#33363F"
    }

    // --- Warna semantik (spek a.1) ---
    // Dark (teks): success #8BCCA6, warning #E6BD7C, danger #E69089, info #8CBDE8.
    // Light (teks): success #337250, warning #936123, danger #A54743, info #2971A7.
    fun semanticTextHex(kind: String, dark: Boolean): String = when (kind) {
        "success" -> if (dark) "#8BCCA6" else "#337250"
        "warning" -> if (dark) "#E6BD7C" else "#936123"
        "danger" -> if (dark) "#E69089" else "#A54743"
        "info" -> if (dark) "#8CBDE8" else "#2971A7"
        else -> if (dark) "#B6BBC5" else "#4F5562"
    }

    // Container kartu claim-check / StuckDetector (C12).
    // Light dari spek: warning #F9E9CE, danger #FFE2E0. Dark TIDAK ada di
    // spek — dipakai container gelap hangat (#33291A warning, #33201F danger)
    // supaya teks semantik dark tetap >= 4.5:1 (terukur, lihat tes (a)).
    // PENYIMPANGAN SKILL-MENANG: teks warning light spek (#936123) di atas
    // container #F9E9CE hanya 4.42:1 (GAGAL AA) — dipakai #7A4E1B (5.99:1).
    fun claimContainerHex(dark: Boolean): String = if (dark) "#33291A" else "#F9E9CE"
    fun claimTextHex(dark: Boolean): String = if (dark) "#E6BD7C" else "#7A4E1B"
    fun stuckContainerHex(dark: Boolean): String = if (dark) "#33201F" else "#FFE2E0"
    fun stuckTextHex(dark: Boolean): String = if (dark) "#E69089" else "#A54743"

    // Surface untuk uji kontras teks semantik (spek C1: dark #1C1F28, light #F0F4FD).
    const val SURFACE_DARK_HEX = "#1C1F28"
    const val SURFACE_LIGHT_HEX = "#F0F4FD"

    fun hexToArgb(hex: String): Int {
        val h = hex.trim().removePrefix("#")
        val v = h.toLong(16).toInt()
        return (0xFF000000.toInt() or v)
    }

    fun contrastRatio(fgArgb: Int, bgArgb: Int): Double {
        fun lin(c: Int): Double {
            val s = c / 255.0
            return if (s <= 0.03928) s / 12.92 else Math.pow((s + 0.055) / 1.055, 2.4)
        }
        fun lum(argb: Int): Double {
            val r = lin((argb shr 16) and 0xFF)
            val g = lin((argb shr 8) and 0xFF)
            val b = lin(argb and 0xFF)
            return 0.2126 * r + 0.7152 * g + 0.0722 * b
        }
        val l1 = lum(fgArgb); val l2 = lum(bgArgb)
        val hi = maxOf(l1, l2); val lo = minOf(l1, l2)
        return (hi + 0.05) / (lo + 0.05)
    }

    fun shouldGroup(toolCalls: Int): Boolean = toolCalls >= GROUP_THRESHOLD

    // "Run 2 commands · Read 3 files" — urutan kategori tetap (bukan urutan
    // kemunculan) supaya ringkasan stabil; kategori 0 tidak ditampilkan.
    fun groupSummary(counts: Map<Tone, Int>): String {
        val order = listOf(Tone.TERMINAL, Tone.READ, Tone.EDIT, Tone.SEARCH, Tone.WEB, Tone.AGENT, Tone.PLAN, Tone.NEUTRAL)
        return order.mapNotNull { t ->
            val n = counts[t] ?: 0
            if (n <= 0) null else "${verbForTone(t)} $n ${nounForTone(t, n)}"
        }.joinToString(" · ")
    }

    // "Completed · N tool calls · M messages" (+ "· N thinking blocks"
    // bila HANYA thinking — turn tanpa tool dan tanpa pesan).
    fun turnSummary(toolCalls: Int, messages: Int, thinkingBlocks: Int): String {
        if (toolCalls == 0 && messages == 0 && thinkingBlocks > 0)
            return "Completed · $thinkingBlocks thinking block" + if (thinkingBlocks == 1) "" else "s"
        val tools = "$toolCalls tool call" + if (toolCalls == 1) "" else "s"
        val msgs = "$messages message" + if (messages == 1) "" else "s"
        return "Completed · $tools · $msgs"
    }

    // Format token ringkas: 34000 -> "34K"; <1000 apa adanya.
    fun formatTokens(tokens: Long): String =
        if (tokens >= 1000) "${tokens / 1000}K" else "$tokens"

    // Footnote giliran (a.14): "N sec · M steps · ~RpX · N tokens ›".
    // Dipendekkan bertahap BILA melebihi maxLen: tokens dulu, lalu langkah,
    // lalu biaya; durasi + sumber SELALU ada. Token/biaya null = tidak
    // tersedia (TIDAK dikarang) -> segmennya hilang sejak awal.
    // Durasi null/<=0 -> "? sec" (durasi selalu ada sebagai segmen).
    fun formatFootnote(durationSec: Double?, steps: Int?, tokens: Long?, costRp: Double?, source: String?, maxLen: Int = 64): String {
        val dur = if (durationSec == null || durationSec <= 0.0) "? sec"
            else String.format(java.util.Locale.US, "%.1f", durationSec).replace('.', ',') + " sec"
        var segs = mutableListOf(dur)
        if (steps != null && steps > 0) segs.add("$steps steps")
        if (costRp != null && costRp > 0) {
            val rp = String.format(java.util.Locale.US, "%,.0f", costRp).replace(',', '.')
            segs.add("~Rp$rp")
        }
        if (tokens != null && tokens > 0) segs.add("${formatTokens(tokens)} tokens")
        if (!source.isNullOrBlank()) segs.add("via $source")
        fun join(list: List<String>) = list.joinToString(" · ") + " ›"
        if (join(segs).length <= maxLen) return join(segs)
        // Tahap 1: buang tokens.
        segs = segs.filter { !it.endsWith("tokens") }.toMutableList()
        if (join(segs).length <= maxLen) return join(segs)
        // Tahap 2: buang langkah.
        segs = segs.filter { !it.endsWith("steps") }.toMutableList()
        if (join(segs).length <= maxLen) return join(segs)
        // Tahap 3: buang biaya (durasi + sumber tetap).
        segs = segs.filter { !it.startsWith("~Rp") }.toMutableList()
        return join(segs)
    }

    // Label diff edit file "+18 −4" — null bila data diff tidak tersedia
    // (WorkItem tidak membawa jumlah baris +/-; JANGAN dikarang).
    fun diffLabel(added: Int?, removed: Int?): String? {
        if (added == null || removed == null) return null
        return "+$added −$removed"
    }

    // Predikat kartu tone (C12) — dipakai addMsg supaya call-site tidak berubah.
    fun isClaimWarningText(text: String): Boolean {
        val t = text.trimStart()
        return t.startsWith("⚠️ Peringatan sistem: klaim") ||
            t.contains("JAWABAN INI TIDAK DIDUKUNG HASIL TOOL")
    }

    fun isStuckStoppedText(text: String): Boolean {
        val t = text.trimStart()
        return t.startsWith("⛔ Dihentikan:") && t.contains("StuckDetector")
    }
}
